import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../types/species-builder/species-builder";
import type {
  SpeciesItemRecord,
  SpeciesItemSystem,
  SpeciesItemTableData,
} from "../../../types/species-builder/species-item";
import { WfrpCharacteristicKey } from "../../../types/wfrp4e/characteristics";
import { assignIfPresent } from "../../../shared/assign-if-present";
import { decodeTalentChoices } from "./choices";
import { decodeCharacteristics } from "./system";
import { speciesEffectCarrierName } from "./effect-carriers";

export function speciesItemToDefinition(
  item: SpeciesItemRecord,
  tables: SpeciesItemTableData = {},
): SpeciesBuilderDefinition {
  const { system } = item;
  const talents = decodeTalentChoices(system.talents.choices);
  const definition: SpeciesBuilderDefinition = {
    key: system.keys[0] || `species${item.id.toLowerCase()}`,
    name: item.name,
    includeInExtraSpecies: true,
    skills: system.skills.list,
    talents: talents.map((grant) => grant.choices.map((choice) => choice.name).join(", ")),
  };
  if (item.effects.length) definition.traits = [speciesEffectCarrierName(item)];
  assignIfPresent(definition, "characteristics", decodeCharacteristics(system));
  assignIfPresent(definition, "careerTable", tables.careerTable);
  for (const field of ["extra", "fate", "movement", "resilience"] as const) {
    const value = system[field];
    if (value !== null) definition[field] = value;
  }
  if (system.talents.random !== null) {
    definition.randomTalents = { [tables.randomTalentKey || "talents"]: system.talents.random };
  }
  return definition;
}

export function speciesItemToSubspecies(
  item: SpeciesItemRecord,
  parent: SpeciesItemRecord,
  tables: SpeciesItemTableData,
): SpeciesBuilderSubspeciesDefinition {
  const system = inheritSpeciesSystem(item.system, parent.system);
  const full = speciesItemToDefinition({ ...item, system }, tables);
  const child: SpeciesBuilderSubspeciesDefinition = { key: full.key, name: full.name };
  for (const field of [
    "characteristics",
    "extra",
    "fate",
    "movement",
    "resilience",
    "randomTalents",
    "careerTable",
  ] as const)
    assignIfPresent(child, field, full[field]);
  const parentDefinition = speciesItemToDefinition(parent);
  // Upstream compileSpecies inherits an empty effects array; a non-empty child array replaces it.
  const traits = item.effects.length ? full.traits : parentDefinition.traits;
  Object.assign(child, listDelta("skills", parentDefinition.skills ?? [], full.skills ?? []));
  Object.assign(child, listDelta("talents", parentDefinition.talents ?? [], full.talents ?? []));
  Object.assign(child, listDelta("traits", parentDefinition.traits ?? [], traits ?? []));
  return child;
}

function inheritSpeciesSystem(
  child: SpeciesItemSystem,
  parent: SpeciesItemSystem,
): SpeciesItemSystem {
  decodeTalentChoices(child.talents.choices);
  const system = structuredClone(child);
  for (const key of Object.values(WfrpCharacteristicKey)) {
    system.characteristics[key] = {
      base: child.characteristics[key]?.base ?? parent.characteristics[key]?.base ?? null,
      dice: child.characteristics[key]?.dice ?? parent.characteristics[key]?.dice ?? null,
    };
  }
  for (const field of ["extra", "fate", "movement", "resilience"] as const)
    system[field] = child[field] ?? parent[field];
  if (!child.skills.list.length) system.skills = parent.skills;
  if (!child.talents.choices.options.length) system.talents.choices = parent.talents.choices;
  system.talents.random = child.talents.random ?? parent.talents.random;
  return system;
}

function listDelta(field: "skills" | "talents" | "traits", parent: string[], child: string[]) {
  return {
    [`${field}Added`]: child.filter((name) => !parent.includes(name)),
    [`${field}Removed`]: parent.filter((name) => !child.includes(name)),
  };
}
