import { defineStore } from "pinia";
import { computed, ref } from "vue";

import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderRandomTalentSource,
} from "../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationCatalog } from "../../types/species-builder/validation";

import { buildWfrpSpeciesConfig } from "../../functions/species-builder/species-config";
import {
  composeSpeciesBuilderEditingDefinitions,
  splitSpeciesBuilderEditingDefinitions,
} from "../../functions/species-builder/editing-definitions";
import { normalizeSpeciesBuilderSettings } from "../../functions/species-builder/species-settings-normalization";
import { snapshotSpeciesTable } from "../../functions/species-builder/world-table";
import {
  clonePlain,
  createDefinitionsWithGeneratedKeys,
  formatJson,
  getErrorMessage,
  snapshotSettings,
} from "../../functions/species-builder/editor/draft";
import { createCareerTableDropActions } from "./career-table-drop-actions";
import { createSpeciesBuilderBridgeAccess } from "./bridge-access";
import { createSpeciesBuilderDefinitionActions } from "./definition-actions";
import { createSpeciesBuilderLinkedGrantActions } from "./linked-grant-actions";
import { createSpeciesBuilderReplacementActions } from "./replacement-actions";
import { createSpeciesBuilderSaveActions } from "./save-actions";
import { createSpeciesBuilderSaveState, snapshotDefinitionSettings } from "./save-state";
import { createSpeciesTableActions } from "./species-table-actions";
import { createSpeciesBuilderSubspeciesActions } from "./subspecies-actions";
import {
  createEmptySpeciesBuilderValidationCatalog,
  createSpeciesBuilderChargenValidation,
} from "./chargen-validation";

export const useSpeciesBuilderStore = defineStore("species-builder", () => {
  const { configure, configuredBridge, requireBridge } = createSpeciesBuilderBridgeAccess();
  const definitions = ref<SpeciesBuilderEditingDefinition[]>([]);
  const runtimeDefinitions = ref<SpeciesBuilderDefinition[]>([]);
  const autoRegisterSpeciesTable = ref(false);
  const correctExistingWfrpSpecies = ref(false);
  const showGeneratedConfigTab = ref(false);
  const selectedIndex = ref(0);
  const isLoaded = ref(false);
  const isLoading = ref(true);
  const isSaving = ref(false);
  const message = ref("");
  const loadError = ref("");
  const saveError = ref("");
  const randomTalentSources = ref<SpeciesBuilderRandomTalentSource[]>([]);
  const validationCatalog = ref<SpeciesBuilderValidationCatalog>(
    createEmptySpeciesBuilderValidationCatalog(),
  );
  const savedSettingsSnapshot = ref("");
  const savedDefinitionsSnapshot = ref("");
  const savedSpeciesTableSnapshot = ref("");
  const savedCorrectExistingWfrpSpecies = ref(false);

  const selectedDefinition = computed(() => definitions.value[selectedIndex.value]);
  const definitionsWithGeneratedKeys = computed(() =>
    createDefinitionsWithGeneratedKeys(definitions.value),
  );
  const speciesTableDefinitions = computed(() =>
    definitionsWithGeneratedKeys.value.filter((definition) => !definition.runtimeUnavailable),
  );
  const persistedDefinitions = computed(() =>
    splitSpeciesBuilderEditingDefinitions(definitionsWithGeneratedKeys.value),
  );
  const draftSettings = computed(() => ({
    autoRegisterSpeciesTable: autoRegisterSpeciesTable.value,
    correctExistingWfrpSpecies: correctExistingWfrpSpecies.value,
    ...persistedDefinitions.value,
    showGeneratedConfigTab: showGeneratedConfigTab.value,
  }));
  const normalizedSettings = computed(() => normalizeSpeciesBuilderSettings(draftSettings.value));
  const generatedConfigText = computed(() =>
    formatJson(buildWfrpSpeciesConfig(normalizedSettings.value, runtimeDefinitions.value)),
  );
  const correctionSettingHasUnsavedChanges = computed(
    () => correctExistingWfrpSpecies.value !== savedCorrectExistingWfrpSpecies.value,
  );
  const speciesTableActions = createSpeciesTableActions({
    autoRegisterSpeciesTable,
    definitions: speciesTableDefinitions,
    message,
  });
  const { validationIssues } = createSpeciesBuilderChargenValidation({
    catalog: validationCatalog,
    editingDefinitions: definitionsWithGeneratedKeys,
    settings: draftSettings,
    speciesTable: speciesTableActions.preparedSpeciesTable,
  });
  const {
    blockingSpeciesTableValidationMessages,
    blockingValidationIssues,
    canSave,
    definitionsHaveUnsavedChanges,
    hasUnsavedChanges,
    requiresUnsafeSaveConfirmation,
    settingsHaveUnsavedChanges,
    speciesTableWillSave,
  } = createSpeciesBuilderSaveState({
    autoRegisterSpeciesTable,
    isLoading,
    isSaving,
    loadError,
    normalizedSettings,
    savedDefinitionsSnapshot,
    savedSettingsSnapshot,
    savedSpeciesTableSnapshot,
    speciesTable: speciesTableActions.speciesTable,
    speciesTableSnapshot: speciesTableActions.speciesTableSnapshot,
    speciesTableValidationMessages: speciesTableActions.speciesTableValidationMessages,
    validationIssues,
  });
  const { saveChanges } = createSpeciesBuilderSaveActions({
    autoRegisterSpeciesTable,
    canSave,
    correctionSettingHasUnsavedChanges,
    correctExistingWfrpSpecies,
    definitions,
    definitionsHaveUnsavedChanges,
    hydrateSpeciesTable: speciesTableActions.hydrateSpeciesTable,
    isSaving,
    loadError,
    message,
    normalizedSettings,
    preparedSpeciesTable: speciesTableActions.preparedSpeciesTable,
    requireBridge,
    requiresUnsafeSaveConfirmation,
    runtimeDefinitions,
    savedDefinitionsSnapshot,
    savedCorrectExistingWfrpSpecies,
    savedSettingsSnapshot,
    savedSpeciesTableSnapshot,
    saveError,
    selectedIndex,
    settingsHaveUnsavedChanges,
    showGeneratedConfigTab,
    speciesTableWillSave,
  });
  const definitionActions = createSpeciesBuilderDefinitionActions({
    definitions,
    message,
    selectedDefinition,
    selectedIndex,
  });
  const allSubspeciesActions = createSpeciesBuilderSubspeciesActions({
    definitions,
    message,
    selectedIndex,
  });
  const { updateDefinitionForSubspecies, ...subspeciesActions } = allSubspeciesActions;
  const { resolveDroppedItem, ...replacementActions } = createSpeciesBuilderReplacementActions({
    bridge: configuredBridge,
    definitionActions,
    loadError,
    selectedDefinition,
    subspeciesActions,
  });
  const linkedGrantActions = createSpeciesBuilderLinkedGrantActions({
    definitionActions,
    resolveDroppedItem,
    selectedDefinition,
    subspeciesActions: {
      canEditSubspecies: subspeciesActions.canEditSubspecies,
      updateDefinitionForSubspecies,
    },
  });
  const careerTableDropActions = createCareerTableDropActions({
    bridge: configuredBridge,
    definitionActions,
    loadError,
    resolveDroppedItem,
    selectedDefinition,
    subspeciesActions,
  });

  async function loadSettings(): Promise<void> {
    isLoading.value = true;
    loadError.value = "";
    saveError.value = "";
    message.value = "";

    try {
      const settings = await requireBridge().loadSettings();
      const [runtimeSpecies, talentSources, speciesTableLoad, catalog] = await Promise.all([
        requireBridge().loadRuntimeSpecies(),
        requireBridge().loadRandomTalentSources(),
        requireBridge().loadSpeciesTable(),
        requireBridge().loadValidationCatalog(settings.definitions.map(({ key }) => key)),
      ]);
      autoRegisterSpeciesTable.value = settings.autoRegisterSpeciesTable;
      correctExistingWfrpSpecies.value = settings.correctExistingWfrpSpecies;
      runtimeDefinitions.value = clonePlain(runtimeSpecies);
      definitions.value = composeSpeciesBuilderEditingDefinitions(
        settings.definitions,
        runtimeSpecies,
        settings.runtimeSpeciesExtensions,
      );
      randomTalentSources.value = talentSources;
      showGeneratedConfigTab.value = settings.showGeneratedConfigTab;
      selectedIndex.value = definitions.value.length > 0 ? 0 : -1;
      speciesTableActions.hydrateSpeciesTable(speciesTableLoad);
      validationCatalog.value = catalog;
      savedSettingsSnapshot.value = snapshotSettings(normalizedSettings.value);
      savedDefinitionsSnapshot.value = snapshotDefinitionSettings(normalizedSettings.value);
      savedCorrectExistingWfrpSpecies.value = settings.correctExistingWfrpSpecies;
      savedSpeciesTableSnapshot.value = snapshotSpeciesTable(speciesTableLoad.draft);
      isLoaded.value = true;
    } catch (error) {
      isLoaded.value = false;
      loadError.value = getErrorMessage(error);
    } finally {
      isLoading.value = false;
    }
  }

  async function ensureSettingsLoaded(): Promise<void> {
    if (!isLoaded.value) {
      await loadSettings();
    }
  }

  function updateShowGeneratedConfigTab(value: boolean): void {
    showGeneratedConfigTab.value = value;
    message.value = "";
  }

  function updateAutoRegisterSpeciesTable(value: boolean): void {
    autoRegisterSpeciesTable.value = value;
    message.value = "";
  }

  function updateCorrectExistingWfrpSpecies(value: boolean): void {
    correctExistingWfrpSpecies.value = value;
    message.value = "";
  }

  return {
    ...definitionActions,
    ...careerTableDropActions,
    ...linkedGrantActions,
    ...replacementActions,
    ...speciesTableActions,
    ...subspeciesActions,
    autoRegisterSpeciesTable,
    blockingSpeciesTableValidationMessages,
    blockingValidationIssues,
    canSave,
    configure,
    correctExistingWfrpSpecies,
    definitions,
    ensureSettingsLoaded,
    generatedConfigText,
    hasUnsavedChanges,
    isLoading,
    isLoaded,
    isSaving,
    loadError,
    loadSettings,
    message,
    randomTalentSources,
    requiresUnsafeSaveConfirmation,
    saveChanges,
    saveError,
    selectedDefinition,
    selectedIndex,
    showGeneratedConfigTab,
    updateAutoRegisterSpeciesTable,
    updateCorrectExistingWfrpSpecies,
    updateShowGeneratedConfigTab,
    validationIssues,
  };
});
