import { WfrpCharacteristicKey } from "../../../../types/wfrp4e/characteristics";
import { SPECIES_ITEM_TYPE } from "./adapter";

export function registerSpeciesItemModel(): void {
  const nativeModel = CONFIG.Item.dataModels["species"];
  if (nativeModel) {
    CONFIG.Item.dataModels[SPECIES_ITEM_TYPE] = nativeModel;
    return;
  }
  // WFRP's PsychologyModel directly extends its BaseItemModel. Inherit that base to retain
  // Warhammer Item preparation/lifecycle behavior without borrowing another Item's fields.
  const BaseItemModel = Object.getPrototypeOf(
    CONFIG.Item.dataModels["psychology"],
  ) as FoundryItemModelClass;
  if (typeof BaseItemModel?.defineSchema !== "function")
    throw new Error("WFRP BaseItemModel is unavailable for Species Items.");
  class BridgeSpeciesModel extends BaseItemModel {
    static LOCALIZATION_PREFIXES = ["WH.Models.species"];

    static override defineSchema(): Record<string, unknown> {
      const fields = foundry.data.fields;
      const optionalNumber = () => new fields.NumberField({ min: 0 });
      const reference = () => new fields.EmbeddedDataField(DocumentReferenceModel);
      return {
        ...super.defineSchema(),
        characteristics: new fields.SchemaField(
          Object.fromEntries(
            Object.values(WfrpCharacteristicKey).map((key) => [
              key,
              new fields.SchemaField({
                base: new fields.NumberField({ initial: 20, min: 0 }),
                dice: new fields.NumberField({ initial: 2, min: 0 }),
              }),
            ]),
          ),
        ),
        fate: optionalNumber(),
        resilience: optionalNumber(),
        extra: optionalNumber(),
        movement: new fields.NumberField({ initial: 4, min: 0 }),
        skills: ListModel.createListModel(new fields.StringField()),
        talents: new fields.SchemaField({
          choices: new fields.EmbeddedDataField(ChoiceModel, { restrictType: ["talent"] }),
          random: new fields.NumberField({ min: 0, integer: true }),
        }),
        size: new fields.StringField({
          choices: game.wfrp4e?.config?.["actorSizes"],
          initial: "avg",
        }),
        subspeciesOf: reference(),
        keys: new fields.ArrayField(new fields.StringField()),
        tables: new fields.SchemaField({
          talents: reference(),
          eye: reference(),
          hair: reference(),
          career: reference(),
        }),
      };
    }
  }
  CONFIG.Item.dataModels[SPECIES_ITEM_TYPE] = BridgeSpeciesModel;
}
