<script setup lang="ts">
import type { SpeciesItemSheetBridge } from "../../../types/species-builder/species-item";
import { useSpeciesItemStore } from "../../../state/species-item";
import SpeciesItemDetails from "./SpeciesItemDetails.vue";
import SpeciesItemNotes from "./SpeciesItemNotes.vue";
import SpeciesItemEffects from "./SpeciesItemEffects.vue";
const props = defineProps<{ uuid: string; editable: boolean; bridge: SpeciesItemSheetBridge }>();
const store = useSpeciesItemStore(props.uuid);
store.configure(props.bridge);
</script>

<template>
  <form
    class="app:flex app:h-full app:min-w-0 app:flex-col app:gap-3"
    @submit.prevent="store.save()"
  >
    <header class="app:flex app:items-center app:gap-3">
      <button
        type="button"
        class="dui-btn dui-btn-sm app:h-auto"
        aria-label="Choose Species image"
        :disabled="!editable || store.isSaving"
        @click="store.chooseImage()"
      >
        <div class="dui-avatar">
          <div class="app:w-14">
            <img
              :src="store.draft.img"
              alt="Species image"
              width="56"
              height="56"
              class="app:object-contain"
            />
          </div>
        </div>
      </button>
      <label class="dui-fieldset app:min-w-0 app:flex-1">
        <span class="dui-label">Name</span>
        <input
          v-model="store.draft.name"
          aria-label="Species name"
          class="dui-input dui-input-sm app:w-full"
          :disabled="!editable || !store.isLoaded || store.isSaving"
          required
        />
      </label>
    </header>
    <div v-if="store.error" class="dui-alert dui-alert-error" role="alert">{{ store.error }}</div>
    <div class="dui-tabs dui-tabs-border" role="tablist" aria-label="Species Item">
      <button
        :id="`${uuid}-description-tab`"
        type="button"
        role="tab"
        class="dui-tab"
        :class="{ 'dui-tab-active': store.tab === 'description' }"
        :aria-selected="store.tab === 'description'"
        :aria-controls="`${uuid}-description-panel`"
        @click="store.tab = 'description'"
      >
        Description
      </button>
      <button
        :id="`${uuid}-details-tab`"
        type="button"
        role="tab"
        class="dui-tab"
        :class="{ 'dui-tab-active': store.tab === 'details' }"
        :aria-selected="store.tab === 'details'"
        :aria-controls="`${uuid}-details-panel`"
        @click="store.tab = 'details'"
      >
        Details
      </button>
      <button
        :id="`${uuid}-effects-tab`"
        type="button"
        role="tab"
        class="dui-tab"
        :class="{ 'dui-tab-active': store.tab === 'effects' }"
        :aria-selected="store.tab === 'effects'"
        :aria-controls="`${uuid}-effects-panel`"
        @click="store.tab = 'effects'"
      >
        Effects
      </button>
    </div>
    <div class="app:min-h-0 app:min-w-0 app:flex-1 app:overflow-y-auto">
      <section
        v-show="store.tab === 'description'"
        :id="`${uuid}-description-panel`"
        role="tabpanel"
        :aria-labelledby="`${uuid}-description-tab`"
      >
        <SpeciesItemNotes
          v-if="store.isLoaded"
          :key="store.revision"
          :uuid="uuid"
          :editable="editable"
        />
      </section>
      <section
        v-show="store.tab === 'details'"
        :id="`${uuid}-details-panel`"
        role="tabpanel"
        :aria-labelledby="`${uuid}-details-tab`"
      >
        <SpeciesItemDetails
          :uuid="uuid"
          :editable="editable && store.isLoaded && !store.isSaving"
        />
      </section>
      <section
        v-show="store.tab === 'effects'"
        :id="`${uuid}-effects-panel`"
        role="tabpanel"
        :aria-labelledby="`${uuid}-effects-tab`"
      >
        <SpeciesItemEffects
          :uuid="uuid"
          :editable="editable && store.isLoaded && !store.isSaving"
        />
      </section>
    </div>
    <footer class="app:flex app:flex-wrap app:items-center app:gap-2">
      <button
        type="submit"
        class="dui-btn dui-btn-sm dui-btn-primary"
        :disabled="!editable || !store.isLoaded || store.isSaving"
      >
        Save Item
      </button>
      <button
        type="button"
        class="dui-btn dui-btn-sm"
        :disabled="store.isSaving"
        @click="store.reload()"
      >
        Reload Item
      </button>
      <span role="status">{{ store.dirty ? "Unsaved changes" : store.message || "Saved" }}</span>
    </footer>
  </form>
</template>
