<script setup lang="ts">
import type { WfrpCharacteristicKey } from "../../../../../../../../../types/wfrp4e/characteristics";

import { WFRP_CHARACTERISTIC_NAMES } from "../../../../../../../../../types/wfrp4e/characteristics";
import { characteristicKeys } from "../../support/field-definitions";
import {
  hasValidationErrors,
  issuesForField,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../../validation-presentation";

const props = defineProps<{
  characteristics: Partial<Record<WfrpCharacteristicKey, string>> | undefined;
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
}>();

const emit = defineEmits<{
  update: [key: WfrpCharacteristicKey, value: string];
}>();

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement ? event.target.value : "";
}

function characteristicIssues(key: WfrpCharacteristicKey): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, `characteristics.${key}`);
}

function characteristicMessages(key: WfrpCharacteristicKey): string[] {
  return uniqueIssueMessages(characteristicIssues(key));
}
</script>

<template>
  <table class="dui-table dui-table-sm">
    <thead>
      <tr>
        <th scope="col">Characteristic</th>
        <th scope="col">Starting formula</th>
      </tr>
    </thead>
    <tbody>
      <tr v-for="key in characteristicKeys" :key="key">
        <th scope="row">
          <label :for="`species-characteristic-${key}`">{{ WFRP_CHARACTERISTIC_NAMES[key] }}</label>
        </th>
        <td>
          <input
            :id="`species-characteristic-${key}`"
            :aria-describedby="
              characteristicIssues(key).length ? `species-characteristic-${key}-errors` : undefined
            "
            :aria-invalid="hasValidationErrors(characteristicIssues(key)) || undefined"
            class="dui-input dui-input-sm"
            :class="
              validationClass(characteristicIssues(key), 'dui-input-error', 'dui-input-warning')
            "
            :disabled="isDisabled"
            placeholder="2d10+20"
            :value="characteristics?.[key] ?? ''"
            type="text"
            @input="emit('update', key, inputValue($event))"
          />
          <div
            v-if="characteristicMessages(key).length"
            :id="`species-characteristic-${key}-errors`"
          >
            <p
              v-for="message in characteristicMessages(key)"
              :key="message"
              class="app:m-0 app:text-xs"
              :class="
                validationClass(characteristicIssues(key), 'app:text-error', 'app:text-warning')
              "
            >
              {{ message }}
            </p>
          </div>
        </td>
      </tr>
    </tbody>
  </table>
</template>
