<script setup lang="ts">
import { computed, onMounted, ref } from "vue";

import type { SpeciesBuilderBridge } from "../../../types/species-builder/species-builder";

import {
  createAllExampleSpeciesPackage,
  createExampleSpeciesPackage,
  EXAMPLE_SPECIES_OPTIONS,
} from "../../../functions/species-builder/example-species";
import { useSpeciesBuilderEditor } from "../../../state/species-builder/editor";
import SpeciesBuilderStatus from "../species-builder/components/SpeciesBuilderStatus.vue";
import UnsafeSaveConfirmationSubView from "../species-builder/components/UnsafeSaveConfirmationSubView.vue";
import { useSpeciesBuilderUnsafeSave } from "../species-builder/components/unsafe-save";
import SpeciesBuilderSettingsPanel from "../species-builder/tabs/settings/SpeciesBuilderSettingsPanel.vue";
import SpeciesSuiteHeader from "./components/SpeciesSuiteHeader.vue";

const props = defineProps<{
  bridge: SpeciesBuilderBridge;
  onOpenDirectory: () => void;
  onOpenSpecies: (definitionIndex: number) => void;
  onSettingsSaved?: () => void;
}>();
const editor = useSpeciesBuilderEditor(props.bridge, { onSettingsSaved: props.onSettingsSaved });
const unsafeSave = useSpeciesBuilderUnsafeSave(editor);
const selectedExampleSpeciesId = ref(EXAMPLE_SPECIES_OPTIONS[0]?.id ?? "");
const isBusy = computed(() => editor.isLoading.value || editor.isSaving.value);

onMounted(() => void editor.ensureSettingsLoaded());

function addExample(exampleId: string): void {
  const examplePackage = createExampleSpeciesPackage(exampleId);
  if (!examplePackage) return;
  editor.addExamplePackage(examplePackage);
  props.onOpenSpecies(editor.selectedIndex.value);
}

function addAllExamples(): void {
  editor.addExamplePackage(createAllExampleSpeciesPackage());
  props.onOpenSpecies(editor.selectedIndex.value);
}
</script>

<template>
  <section class="app:flex app:min-h-full app:flex-col" :aria-busy="isBusy">
    <SpeciesSuiteHeader
      :can-save="editor.canSave.value"
      context="Project settings"
      :has-unsaved-changes="editor.hasUnsavedChanges.value"
      :is-busy="isBusy"
      :show-issues="false"
      title="Configurator"
      @open-parent="onOpenDirectory"
      @reload="editor.loadSettings"
      @save="unsafeSave.requestSave"
    />

    <UnsafeSaveConfirmationSubView
      :is-open="unsafeSave.isConfirmationOpen.value"
      @close="unsafeSave.closeConfirmation"
      @confirm="unsafeSave.confirmSave"
    />

    <main class="app:flex app:flex-1 app:flex-col app:gap-3 app:p-3">
      <SpeciesBuilderStatus
        :chargen-error-count="0"
        :chargen-warning-count="0"
        :load-error="editor.loadError.value || editor.saveError.value"
        :message="editor.message.value"
        validation-message=""
      />
      <SpeciesBuilderSettingsPanel
        :auto-register-species-table="editor.autoRegisterSpeciesTable.value"
        :correct-existing-wfrp-species="editor.correctExistingWfrpSpecies.value"
        :example-species-options="EXAMPLE_SPECIES_OPTIONS"
        :is-disabled="isBusy"
        :selected-example-species-id="selectedExampleSpeciesId"
        :show-generated-config-tab="editor.showGeneratedConfigTab.value"
        :species-table="editor.speciesTable.value"
        @generate-all-example-species="addAllExamples"
        @generate-example-species="addExample"
        @update-auto-register-species-table="editor.updateAutoRegisterSpeciesTable"
        @update-correct-existing-wfrp-species="editor.updateCorrectExistingWfrpSpecies"
        @update-selected-example-species-id="selectedExampleSpeciesId = $event"
        @update-show-generated-config-tab="editor.updateShowGeneratedConfigTab"
      />
    </main>
  </section>
</template>
