import type { Component } from "vue";

import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";
import type { SpeciesBuilderEditorTab } from "../../../view/apps/species-builder/tabs/species/pages/editor/editor-tabs";
import type { SubspeciesEditorTab } from "../../../view/apps/species-builder/tabs/species/pages/editor/tabs/subspecies/subspecies-editor-tabs";
import type { RandomTableTab } from "../../../view/apps/species-builder/tabs/species/pages/editor/tabs/tables/random-table-events";

import { pinia } from "../../../state/pinia";
import { useSpeciesBuilderStore } from "../../../state/species-builder";
import SpeciesDirectoryApp from "../../../view/apps/species-builder-suite/SpeciesDirectoryApp.vue";
import { getSpeciesBuilderValidationDestination } from "../../../view/apps/species-builder/components/validation/species-builder-validation-summary";
import { MODULE_ID } from "../../constants";
import { SpeciesConfiguratorApplication } from "./SpeciesConfiguratorApplication";
import { SpeciesEditorApplication } from "./SpeciesEditorApplication";
import { SpeciesIssuesApplication } from "./SpeciesIssuesApplication";
import { SpeciesSuiteApplication } from "./SpeciesSuiteApplication";
import { SpeciesTableApplication } from "./SpeciesTableApplication";
import { SubspeciesEditorApplication } from "./SubspeciesEditorApplication";
import { WfrpConfigApplication } from "./WfrpConfigApplication";
import { WoundFormulaApplication } from "./WoundFormulaApplication";

export class SpeciesDirectoryApplication extends SpeciesSuiteApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-species-directory`,
    classes: [MODULE_ID, "wfrp4e-customizer-species-directory"],
    position: { height: 680, width: 820 },
    window: {
      icon: "fa-solid fa-people-group",
      resizable: true,
      title: "WFRP4e Species Builder",
    },
  };

  readonly #configurator: SpeciesConfiguratorApplication;
  readonly #editor: SpeciesEditorApplication;
  readonly #issues: SpeciesIssuesApplication;
  readonly #speciesTable: SpeciesTableApplication;
  readonly #subspeciesEditor: SubspeciesEditorApplication;
  readonly #wfrpConfig: WfrpConfigApplication;
  readonly #woundFormula: WoundFormulaApplication;
  #activeDefinitionIndex = -1;

  constructor() {
    super();
    this.#editor = new SpeciesEditorApplication({
      openDirectory: () => void this.render(true),
      openIssues: (definitionIndex) => void this.#issues.open(definitionIndex),
      openSubspecies: (definitionIndex, subspeciesIndex) =>
        void this.openSubspecies(definitionIndex, subspeciesIndex),
      openWoundFormula: (definitionIndex) => void this.openWoundFormula(definitionIndex, undefined),
    });
    this.#subspeciesEditor = new SubspeciesEditorApplication({
      openIssues: (definitionIndex) => void this.#issues.open(definitionIndex),
      openParent: (definitionIndex) => void this.openSpecies(definitionIndex, "subspecies"),
      openWoundFormula: (definitionIndex, subspeciesIndex) =>
        void this.openWoundFormula(definitionIndex, subspeciesIndex),
    });
    this.#configurator = new SpeciesConfiguratorApplication(
      () => void this.render(true),
      (definitionIndex) => void this.openSpecies(definitionIndex),
    );
    this.#speciesTable = new SpeciesTableApplication(
      () => void this.render(true),
      () => void this.#issues.open(),
    );
    this.#wfrpConfig = new WfrpConfigApplication(() => void this.render(true));
    this.#issues = new SpeciesIssuesApplication(
      () => void this.render(true),
      (issue) => this.openValidationIssue(issue),
    );
    this.#woundFormula = new WoundFormulaApplication((definitionIndex, subspeciesIndex) => {
      if (subspeciesIndex === undefined) {
        void this.openSpecies(definitionIndex, "wounds");
      } else {
        void this.openSubspecies(definitionIndex, subspeciesIndex, "wounds");
      }
    });
  }

  protected override getVueComponent(): Component {
    return SpeciesDirectoryApp;
  }

  protected override getApplicationProps(): Record<string, unknown> {
    return {
      onOpenConfigurator: () => this.#configurator.render(true),
      onOpenIssues: (definitionIndex?: number) => this.#issues.open(definitionIndex),
      onOpenSpecies: (definitionIndex: number) => this.openSpecies(definitionIndex),
      onOpenSpeciesTable: () => this.#speciesTable.render(true),
      onOpenWfrpConfig: () => this.#wfrpConfig.render(true),
    };
  }

  private openSpecies(
    definitionIndex: number,
    tab: SpeciesBuilderEditorTab = "details",
    tableTab: RandomTableTab = "careerTable",
  ): Promise<SpeciesEditorApplication> {
    this.selectDefinition(definitionIndex);
    return this.#editor.open(definitionIndex, tab, tableTab);
  }

  private openSubspecies(
    definitionIndex: number,
    subspeciesIndex: number,
    tab: SubspeciesEditorTab = "details",
    tableTab: RandomTableTab = "careerTable",
  ): Promise<SubspeciesEditorApplication> {
    this.selectDefinition(definitionIndex);
    void this.#editor.open(definitionIndex, "subspecies");
    return this.#subspeciesEditor.open(definitionIndex, subspeciesIndex, tab, tableTab);
  }

  private openWoundFormula(
    definitionIndex: number,
    subspeciesIndex: number | undefined,
  ): Promise<WoundFormulaApplication> {
    this.selectDefinition(definitionIndex);
    return this.#woundFormula.open(definitionIndex, subspeciesIndex);
  }

  private selectDefinition(definitionIndex: number): void {
    if (definitionIndex !== this.#activeDefinitionIndex) {
      void this.#subspeciesEditor.close();
      void this.#woundFormula.close();
    }

    this.#activeDefinitionIndex = definitionIndex;
    useSpeciesBuilderStore(pinia).selectDefinition(definitionIndex);
  }

  private openValidationIssue(issue: SpeciesBuilderValidationIssue): void {
    const destination = getSpeciesBuilderValidationDestination(issue);

    void this.#issues.close();

    if (destination.kind === "project") {
      if (destination.tab === "species-table") {
        void this.#speciesTable.render(true);
      } else {
        void this.render(true);
      }
      return;
    }

    if (destination.kind === "subspecies") {
      void this.openSubspecies(
        destination.definitionIndex,
        destination.subspeciesIndex,
        destination.subspeciesTab,
        destination.tableTab,
      );
      return;
    }

    void this.openSpecies(destination.definitionIndex, destination.editorTab, destination.tableTab);
  }
}
