import type {
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderDefinition,
  SpeciesBuilderHeightDefinition,
} from "../../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../../types/wfrp4e/characteristics";

import { clonePlain, parseTextMapField, setOptionalField } from "./draft";
import {
  normalizeCareerTableRows,
  normalizeEditableText,
  normalizeNumberInput,
  normalizeText,
  normalizeWoundFormulaInput,
  parseStringLines,
  type SpeciesBuilderArrayField,
  type SpeciesBuilderTextMapField,
} from "./field-values";

export function createBlankSpeciesDefinition(): SpeciesBuilderDefinition {
  return {
    includeInExtraSpecies: true,
    key: "",
    name: "New Species",
  };
}

export function copySpeciesDefinition(
  definition: SpeciesBuilderDefinition,
  definitions: SpeciesBuilderDefinition[],
): SpeciesBuilderDefinition {
  const copy = clonePlain(definition);

  copy.key = nextAvailableSpeciesKey(`${copy.key}-copy`, definitions);
  copy.name = `${copy.name} Copy`;

  return copy;
}

export function appendSpeciesDefinitions(
  current: SpeciesBuilderDefinition[],
  additions: SpeciesBuilderDefinition[],
): SpeciesBuilderDefinition[] {
  return [...current, ...additions.map(clonePlain)];
}

export function setSpeciesStringField(
  definition: SpeciesBuilderDefinition,
  field: "age" | "key" | "name",
  value: string,
): SpeciesBuilderDefinition {
  return setOptionalField(definition, field, normalizeEditableText(value));
}

export function setSpeciesNumberField(
  definition: SpeciesBuilderDefinition,
  field: "extra" | "fate" | "movement" | "resilience",
  value: string,
): SpeciesBuilderDefinition {
  return setOptionalField(definition, field, normalizeNumberInput(value));
}

export function setSpeciesHeightField(
  definition: SpeciesBuilderDefinition,
  field: keyof SpeciesBuilderHeightDefinition,
  value: string,
): SpeciesBuilderDefinition {
  const height = definition.height ? { ...definition.height } : {};
  const normalizedValue = field === "die" ? normalizeText(value) : normalizeNumberInput(value);

  if (normalizedValue === undefined) {
    delete height[field];
  } else {
    height[field] = normalizedValue as never;
  }

  return setOptionalField(
    definition,
    "height",
    Object.keys(height).length > 0 ? height : undefined,
  );
}

export function setSpeciesCharacteristic(
  definition: SpeciesBuilderDefinition,
  key: WfrpCharacteristicKey,
  value: string,
): SpeciesBuilderDefinition {
  const characteristics = definition.characteristics ? { ...definition.characteristics } : {};
  const formula = normalizeText(value);

  if (formula) {
    characteristics[key] = formula;
  } else {
    delete characteristics[key];
  }

  return setOptionalField(
    definition,
    "characteristics",
    Object.keys(characteristics).length > 0 ? characteristics : undefined,
  );
}

export function setSpeciesArrayField(
  definition: SpeciesBuilderDefinition,
  field: SpeciesBuilderArrayField,
  value: string,
): SpeciesBuilderDefinition {
  return setOptionalField(definition, field, parseStringLines(value));
}

export function setSpeciesTextMapField(
  definition: SpeciesBuilderDefinition,
  field: SpeciesBuilderTextMapField,
  value: string,
): SpeciesBuilderDefinition {
  return setOptionalField(definition, field, parseTextMapField(field, value));
}

export function setSpeciesWoundFormula(
  definition: SpeciesBuilderDefinition,
  value: string,
): SpeciesBuilderDefinition {
  return setOptionalField(definition, "woundFormula", normalizeWoundFormulaInput(value));
}

export function setSpeciesCareerTableRows(
  definition: SpeciesBuilderDefinition,
  rows: SpeciesBuilderCareerTableRow[],
): SpeciesBuilderDefinition {
  return setOptionalField(definition, "careerTable", normalizeCareerTableRows(rows));
}

function nextAvailableSpeciesKey(baseKey: string, definitions: SpeciesBuilderDefinition[]): string {
  const existingKeys = new Set(definitions.map((definition) => definition.key));

  if (!existingKeys.has(baseKey)) {
    return baseKey;
  }

  let index = 2;
  let candidate = `${baseKey}-${index}`;

  while (existingKeys.has(candidate)) {
    index += 1;
    candidate = `${baseKey}-${index}`;
  }

  return candidate;
}
