import type { Component } from "vue";

import WfrpConfigApp from "../../../view/apps/species-builder-suite/WfrpConfigApp.vue";
import { MODULE_ID } from "../../constants";
import { SpeciesSuiteApplication } from "./SpeciesSuiteApplication";

export class WfrpConfigApplication extends SpeciesSuiteApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-species-wfrp-config`,
    classes: [MODULE_ID, "wfrp4e-customizer-species-wfrp-config"],
    position: { height: 700, width: 800 },
    window: {
      icon: "fa-solid fa-code",
      resizable: true,
      title: "Generated WFRP Species Config",
    },
  };

  constructor(private readonly openDirectory: () => void) {
    super();
  }

  protected override getVueComponent(): Component {
    return WfrpConfigApp;
  }

  protected override getApplicationProps(): Record<string, unknown> {
    return { onOpenDirectory: this.openDirectory };
  }
}
