<script setup lang="ts">
import { computed } from "vue";

import type { SpeciesBuilderRandomTalentSource } from "../../../../../../../../../types/species-builder/species-builder";
import type {
  SpeciesBuilderValidationIssue,
  SpeciesBuilderValidationSection,
} from "../../../../../../../../../types/species-builder/validation";
import type {
  RandomTableFieldEmits,
  RandomTableSectionValues,
  RandomTableTab,
} from "./random-table-events";

import CareerReplacementRows from "./tabs/career-replacement/CareerReplacementRows.vue";
import CareerTableRows from "./tabs/career-table/CareerTableRows.vue";
import RandomTalentRows from "./tabs/random-talents/RandomTalentRows.vue";
import TalentReplacementRows from "./tabs/talent-replacement/TalentReplacementRows.vue";
import {
  summarizeValidationIssues,
  validationIndicatorLabel,
} from "../../../../../../components/validation/validation-presentation";

interface RandomTableTabEntry {
  label: string;
  tab: RandomTableTab;
}

const props = withDefaults(
  defineProps<{
    activeTab: RandomTableTab;
    help: string;
    includeCareerReplacements?: boolean;
    isDisabled: boolean;
    isNavigationDisabled?: boolean;
    issues: SpeciesBuilderValidationIssue[];
    randomTalentSources: SpeciesBuilderRandomTalentSource[];
    showNavigation: boolean;
    values: RandomTableSectionValues;
  }>(),
  {
    includeCareerReplacements: false,
    isNavigationDisabled: false,
  },
);

const emit = defineEmits<
  RandomTableFieldEmits & {
    selectTab: [tab: RandomTableTab];
  }
>();
const randomTableTabs = computed<RandomTableTabEntry[]>(() => {
  const tabs: RandomTableTabEntry[] = [
    { label: "Career Table", tab: "careerTable" },
    { label: "Random Talents", tab: "randomTalents" },
    { label: "Talent Replacement", tab: "talentReplacement" },
  ];

  if (props.includeCareerReplacements) {
    tabs.push({ label: "Career Replacement", tab: "careerReplacement" });
  }

  return tabs;
});

function forwardCareerReplacementChoiceDrop(
  rowIndex: number,
  replacementIndex: number,
  data: string,
): void {
  emit("careerReplacementChoiceDrop", rowIndex, replacementIndex, data);
}

function forwardCareerReplacementRolledDrop(rowIndex: number, data: string): void {
  emit("careerReplacementRolledDrop", rowIndex, data);
}

function forwardTalentReplacementReplacementDrop(rowIndex: number, data: string): void {
  emit("talentReplacementReplacementDrop", rowIndex, data);
}

function forwardTalentReplacementRolledDrop(rowIndex: number, data: string): void {
  emit("talentReplacementRolledDrop", rowIndex, data);
}

function selectTableTab(tab: RandomTableTab): void {
  emit("selectTab", tab);
}

function sectionForTab(tab: RandomTableTab): SpeciesBuilderValidationSection {
  return tab;
}

function issuesForTab(tab: RandomTableTab): SpeciesBuilderValidationIssue[] {
  const section = sectionForTab(tab);

  return props.issues.filter((issue) => issue.section === section);
}

function validationLabelForTab(tab: RandomTableTab): string {
  const indicator = summarizeValidationIssues(issuesForTab(tab));

  return indicator ? validationIndicatorLabel(indicator) : "";
}

function tabHasValidationErrors(tab: RandomTableTab): boolean {
  return issuesForTab(tab).some((issue) => issue.severity !== "warning");
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <header v-if="showNavigation">
        <h3 class="dui-card-title">Tables And Replacements</h3>
        <p class="app:m-0">{{ help }}</p>
      </header>
      <p v-else class="app:m-0">{{ help }}</p>

      <div
        v-if="showNavigation"
        aria-label="Table editor"
        class="dui-tabs dui-tabs-border"
        role="tablist"
      >
        <button
          v-for="entry in randomTableTabs"
          :id="`random-table-tab-${entry.tab}`"
          :key="entry.tab"
          :aria-controls="`random-table-panel-${entry.tab}`"
          :aria-selected="activeTab === entry.tab"
          class="dui-tab"
          :class="{ 'dui-tab-active': activeTab === entry.tab }"
          :disabled="isNavigationDisabled"
          role="tab"
          type="button"
          @click="selectTableTab(entry.tab)"
        >
          {{ entry.label }}
          <span
            v-if="issuesForTab(entry.tab).length > 0"
            class="dui-status dui-status-sm"
            :class="tabHasValidationErrors(entry.tab) ? 'dui-status-error' : 'dui-status-warning'"
            :title="validationLabelForTab(entry.tab)"
          >
            <span class="app:sr-only">{{ validationLabelForTab(entry.tab) }}</span>
          </span>
        </button>
      </div>

      <CareerTableRows
        v-if="activeTab === 'careerTable'"
        id="random-table-panel-careerTable"
        aria-label="Career table"
        :aria-labelledby="showNavigation ? 'random-table-tab-careerTable' : undefined"
        :is-disabled="isDisabled"
        :issues="issuesForTab('careerTable')"
        :role="showNavigation ? 'tabpanel' : 'region'"
        :rows="values.careerTable?.rows"
        @drop-career="(rowIndex, data) => emit('careerTableCareerDrop', rowIndex, data)"
        @drop-journal="(rowIndex, data) => emit('careerTableJournalDrop', rowIndex, data)"
        @update-rows="(rows) => emit('updateCareerTableRows', rows)"
      />

      <RandomTalentRows
        v-else-if="activeTab === 'randomTalents'"
        id="random-table-panel-randomTalents"
        aria-label="Random Talents table"
        :aria-labelledby="showNavigation ? 'random-table-tab-randomTalents' : undefined"
        :is-disabled="isDisabled"
        :issues="issuesForTab('randomTalents')"
        :role="showNavigation ? 'tabpanel' : 'region'"
        :sources="randomTalentSources"
        :values="values.randomTalents"
        @update="(value) => emit('update', 'randomTalents', value)"
      />

      <TalentReplacementRows
        v-else-if="activeTab === 'talentReplacement'"
        id="random-table-panel-talentReplacement"
        aria-label="Talent replacement table"
        :aria-labelledby="showNavigation ? 'random-table-tab-talentReplacement' : undefined"
        :is-disabled="isDisabled"
        :issues="issuesForTab('talentReplacement')"
        :role="showNavigation ? 'tabpanel' : 'region'"
        :rows="values.talentReplacementRows"
        :values="values.talentReplacements"
        @drop-replacement="forwardTalentReplacementReplacementDrop"
        @drop-rolled="forwardTalentReplacementRolledDrop"
        @open-item="(uuid) => emit('openItem', uuid)"
        @update-rows="(rows) => emit('updateTalentReplacementRows', rows)"
      />

      <CareerReplacementRows
        v-else-if="includeCareerReplacements"
        id="random-table-panel-careerReplacement"
        aria-label="Career replacement table"
        :aria-labelledby="showNavigation ? 'random-table-tab-careerReplacement' : undefined"
        :is-disabled="isDisabled"
        :issues="issuesForTab('careerReplacement')"
        :role="showNavigation ? 'tabpanel' : 'region'"
        :rows="values.careerReplacementRows"
        :values="values.careerReplacements"
        @drop-replacement="forwardCareerReplacementChoiceDrop"
        @drop-rolled="forwardCareerReplacementRolledDrop"
        @open-item="(uuid) => emit('openItem', uuid)"
        @update-rows="(rows) => emit('updateCareerReplacementRows', rows)"
      />
    </div>
  </section>
</template>
