import type {
  NpcBaseTrappingSummary,
  NpcTrappingDraftEntry,
  NpcTrappingResolution,
} from "../../../../types/npc-builder";

import {
  createMatchedTrappingResolution,
  resolveTrappingCandidates,
  type TrappingResolutionItemInput,
} from "../../../../functions/npc-builder/trapping-resolution";
import {
  readNumberFromPaths,
  readStringArrayPath,
  setObjectPath,
} from "../../../../shared/object-readers";
import {
  getCompendiumIndexEntryUuid,
  isItemCompendiumPack,
  readCompendiumIndexEntries,
} from "../../../foundry/compendiums";
import { assertFoundryItem, isFoundryItem } from "../../../foundry/document-guards";
import { parseDropData } from "../../../foundry/drop-data";
import {
  applyEmbeddedItemChanges,
  createEmptyEmbeddedItemChanges,
} from "../../../foundry/embedded-items";
import {
  createItemSourceFromMatch,
  findActorItemByUuidOrName,
} from "../../../foundry/item-sources";
import { findWfrpItemByNameAndType } from "../../../wfrp4e/item-lookup";

const defaultTrappingItemTypes = [
  "ammunition",
  "armour",
  "container",
  "money",
  "trapping",
  "weapon",
];

export async function applyTrappings(
  actor: FoundryActorDocument,
  trappings: NpcTrappingDraftEntry[],
): Promise<void> {
  const itemChanges = createEmptyEmbeddedItemChanges();

  for (const trapping of trappings) {
    const existingItem =
      trapping.source === "base"
        ? findActorItemByUuidOrName(actor, trapping.sourceUuid, trapping.name)
        : null;

    if (trapping.ignored) {
      if (existingItem) {
        itemChanges.deletes.push(existingItem.id);
      }

      continue;
    }

    if (existingItem) {
      itemChanges.updates.push({
        "_id": existingItem.id,
        "system.quantity.value": trapping.quantity,
      });
      continue;
    }

    const sourceItem = await findTrappingSourceItem(trapping);
    const itemType = trapping.resolution.selectedItemType || trapping.itemType || "trapping";
    const itemName = trapping.resolution.selectedName || trapping.name;
    const itemData = createItemSourceFromMatch(sourceItem, itemName, itemType);

    itemData["type"] = itemType || itemData["type"] || "trapping";
    setObjectPath(itemData, ["system", "quantity", "value"], trapping.quantity);
    itemChanges.creates.push(itemData);
  }

  await applyEmbeddedItemChanges(actor, itemChanges);
}

export async function resolveTrapping(name: string): Promise<NpcTrappingResolution> {
  return resolveTrappingCandidates(name, await listTrappingResolutionItems());
}

export async function resolveTrappingDrop(data: string): Promise<NpcTrappingDraftEntry> {
  const dropData = parseDropData(data);

  if (dropData.type !== "Item" || !dropData.uuid) {
    throw new Error("Drop a Foundry Item here.");
  }

  const item = assertFoundryItem(await fromUuid(dropData.uuid), "Drop a Foundry Item here.");

  return {
    ignored: false,
    itemType: item.type,
    key: `custom:${item.uuid}`,
    name: item.name,
    quantity: readItemQuantity(item),
    resolution: createMatchedTrappingResolution({
      itemType: item.type,
      name: item.name,
      uuid: item.uuid,
    }),
    source: "custom",
    sourceUuid: item.uuid,
  };
}

export function readActorTrappings(actor: FoundryActorDocument): NpcBaseTrappingSummary[] {
  const trappingTypes = getTrappingItemTypes();

  return (
    actor.items?.contents
      .filter((item) => trappingTypes.includes(item.type))
      .map((item) => ({
        itemType: item.type,
        name: item.name,
        quantity: readItemQuantity(item),
        uuid: item.uuid,
      })) ?? []
  );
}

export function readItemQuantity(item: FoundryItemDocument): number {
  return readNumberFromPaths(item.system, [["quantity", "value"], ["quantity"]]) || 1;
}

export function getTrappingItemTypes(): string[] {
  const configuredTypes = readStringArrayPath(game.wfrp4e?.config, ["trappingItems"]);

  return configuredTypes.length ? configuredTypes : defaultTrappingItemTypes;
}

async function findTrappingSourceItem(
  trapping: NpcTrappingDraftEntry,
): Promise<FoundryItemDocument | null> {
  if (trapping.sourceUuid) {
    const sourceItem = await fromUuid(trapping.sourceUuid);

    return isFoundryItem(sourceItem) ? sourceItem : null;
  }

  if (trapping.resolution.selectedCandidateUuid) {
    const resolvedItem = await fromUuid(trapping.resolution.selectedCandidateUuid);

    return isFoundryItem(resolvedItem) ? resolvedItem : null;
  }

  if (trapping.resolution.status === "fallback") {
    return null;
  }

  return await findWfrpItemByNameAndType(
    trapping.resolution.selectedName || trapping.name,
    getTrappingItemTypes(),
  );
}

async function listTrappingResolutionItems(): Promise<TrappingResolutionItemInput[]> {
  const items: TrappingResolutionItemInput[] = [];
  const trappingTypes = getTrappingItemTypes();

  for (const item of game.items?.contents ?? []) {
    if (trappingTypes.includes(item.type)) {
      items.push(toTrappingResolutionItem(item, "World"));
    }
  }

  for (const pack of game.packs ?? []) {
    if (!isItemCompendiumPack(pack)) {
      continue;
    }

    const indexedItems = await listTrappingResolutionItemsFromIndex(pack, trappingTypes);

    if (indexedItems.length) {
      items.push(...indexedItems);
      continue;
    }

    if (!pack.getDocuments) {
      continue;
    }

    const documents = await pack.getDocuments();

    for (const document of documents) {
      if (isFoundryItem(document) && trappingTypes.includes(document.type)) {
        items.push(toTrappingResolutionItem(document, pack.title ?? "Compendium"));
      }
    }
  }

  return items;
}

async function listTrappingResolutionItemsFromIndex(
  pack: FoundryCompendiumCollection,
  trappingTypes: string[],
): Promise<TrappingResolutionItemInput[]> {
  if (!pack.getIndex) {
    return [];
  }

  const index = await pack.getIndex({ fields: ["name", "type"] });
  const entries = readCompendiumIndexEntries(index);

  return entries
    .filter((entry) => {
      return Boolean(
        entry.name &&
        entry.type &&
        getCompendiumIndexEntryUuid(pack, entry) &&
        trappingTypes.includes(entry.type),
      );
    })
    .map((entry) => ({
      itemType: entry.type ?? "trapping",
      name: entry.name ?? "",
      sourceLabel: pack.title ?? "Compendium",
      uuid: getCompendiumIndexEntryUuid(pack, entry),
    }));
}

function toTrappingResolutionItem(
  item: FoundryItemDocument,
  sourceLabel: string,
): TrappingResolutionItemInput {
  return {
    itemType: item.type,
    name: item.name,
    sourceLabel,
    uuid: item.uuid,
  };
}
