import type { ComputedRef, Ref } from "vue";

import type {
  SpeciesBuilderBridge,
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderDefinition,
  SpeciesBuilderItemReference,
  SpeciesBuilderJournalReference,
} from "../../types/species-builder/species-builder";

import {
  setCareerTableRowCareer,
  setCareerTableRowJournal,
} from "../../functions/species-builder/editor/career-table-rows";
import { getErrorMessage } from "../../functions/species-builder/editor/draft";

interface CareerTableDefinitionActions {
  updateCareerTableRows: (rows: SpeciesBuilderCareerTableRow[]) => void;
}

interface CareerTableSubspeciesActions {
  updateSubspeciesCareerTableRows: (index: number, rows: SpeciesBuilderCareerTableRow[]) => void;
}

interface CareerTableDropActionsContext {
  bridge: SpeciesBuilderBridge;
  definitionActions: CareerTableDefinitionActions;
  loadError: Ref<string>;
  resolveDroppedItem: (field: "career", data: string) => Promise<SpeciesBuilderItemReference>;
  selectedDefinition: ComputedRef<SpeciesBuilderDefinition | undefined>;
  subspeciesActions: CareerTableSubspeciesActions;
}

export function createCareerTableDropActions(context: CareerTableDropActionsContext) {
  async function setCareerTableCareerDrop(rowIndex: number, data: string): Promise<void> {
    const definition = context.selectedDefinition.value;

    if (!definition) {
      return;
    }

    const career = await context.resolveDroppedItem("career", data);
    context.definitionActions.updateCareerTableRows(
      setCareerTableRowCareer(definition.careerTable?.rows, rowIndex, career),
    );
  }

  async function setCareerTableJournalDrop(rowIndex: number, data: string): Promise<void> {
    const definition = context.selectedDefinition.value;

    if (!definition) {
      return;
    }

    const journal = await resolveDroppedJournal(context, data);
    context.definitionActions.updateCareerTableRows(
      setCareerTableRowJournal(definition.careerTable?.rows, rowIndex, journal.uuid),
    );
  }

  async function setSubspeciesCareerTableCareerDrop(
    subspeciesIndex: number,
    rowIndex: number,
    data: string,
  ): Promise<void> {
    const subspecies = context.selectedDefinition.value?.subspecies?.[subspeciesIndex];

    if (!subspecies) {
      return;
    }

    const career = await context.resolveDroppedItem("career", data);
    context.subspeciesActions.updateSubspeciesCareerTableRows(
      subspeciesIndex,
      setCareerTableRowCareer(subspecies.careerTable?.rows, rowIndex, career),
    );
  }

  async function setSubspeciesCareerTableJournalDrop(
    subspeciesIndex: number,
    rowIndex: number,
    data: string,
  ): Promise<void> {
    const subspecies = context.selectedDefinition.value?.subspecies?.[subspeciesIndex];

    if (!subspecies) {
      return;
    }

    const journal = await resolveDroppedJournal(context, data);
    context.subspeciesActions.updateSubspeciesCareerTableRows(
      subspeciesIndex,
      setCareerTableRowJournal(subspecies.careerTable?.rows, rowIndex, journal.uuid),
    );
  }

  return {
    setCareerTableCareerDrop,
    setCareerTableJournalDrop,
    setSubspeciesCareerTableCareerDrop,
    setSubspeciesCareerTableJournalDrop,
  };
}

async function resolveDroppedJournal(
  context: CareerTableDropActionsContext,
  data: string,
): Promise<SpeciesBuilderJournalReference> {
  try {
    return await context.bridge.resolveJournalDrop(data);
  } catch (error) {
    context.loadError.value = getErrorMessage(error);
    throw error;
  }
}
