import type { NpcTraitDraftConfig } from "../../../../../types/npc-builder";

import { createDefaultTraitConfig } from "../../../../../functions/npc-builder/create-default-trait-config";
import {
  readBooleanFromPaths,
  readUnknownPath,
  setObjectPath,
} from "../../../../../shared/object-readers";

export function applyTraitConfigToSource(
  itemData: FoundryItemSource,
  config: NpcTraitDraftConfig,
): void {
  setObjectPath(itemData, ["system", "specification", "value"], config.specification);

  if (config.rollable && !config.damage) {
    setObjectPath(itemData, ["system", "rollable", "defaultDifficulty"], config.defaultDifficulty);
  }

  if (config.damage && config.dice) {
    setObjectPath(itemData, ["system", "rollable", "dice"], config.dice);
  }
}

export function createTraitConfigUpdate(
  id: string,
  config: NpcTraitDraftConfig,
): Record<string, unknown> {
  return {
    "_id": id,
    "system.specification.value": config.specification,
    ...(config.rollable && !config.damage
      ? { "system.rollable.defaultDifficulty": config.defaultDifficulty }
      : {}),
    ...(config.damage && config.dice ? { "system.rollable.dice": config.dice } : {}),
  };
}

export function readTraitConfig(item: FoundryItemDocument): NpcTraitDraftConfig {
  return {
    ...createDefaultTraitConfig(),
    attackType: readTraitString(item.system, ["rollable", "attackType"]) || "melee",
    bonusCharacteristic: readTraitString(item.system, ["rollable", "bonusCharacteristic"]),
    damage: readBooleanFromPaths(item.system, [["rollable", "damage"]]),
    defaultDifficulty:
      readTraitString(item.system, ["rollable", "defaultDifficulty"]) || "challenging",
    dice: readTraitString(item.system, ["rollable", "dice"]),
    rollable: readBooleanFromPaths(item.system, [["rollable", "value"]]),
    skill: readTraitString(item.system, ["rollable", "skill"]),
    sl: readBooleanFromPaths(item.system, [["rollable", "SL"]], true),
    specification: readTraitString(item.system, ["specification", "value"]),
  };
}

export function isTraitDisabled(item: FoundryItemDocument): boolean {
  return readTraitDisabledFlag(item.system);
}

export function isTraitSourceDisabled(item: FoundryItemSource): boolean {
  return readTraitDisabledFlag(item["system"]);
}

function readTraitDisabledFlag(system: unknown): boolean {
  return readBooleanFromPaths(system, [["disabled"], ["disabled", "value"]]);
}

function readTraitString(source: unknown, path: string[]): string {
  const value = readUnknownPath(source, path);

  if (typeof value === "string") {
    return value.trim();
  }

  if (typeof value === "number") {
    return String(value);
  }

  return "";
}
