<script setup lang="ts">
import type {
  GrantItemReference,
  GrantItemsLifetime,
  GrantItemsOwnerAction,
} from "../../../types/item-grants";
import ApplicationShell from "../../components/ApplicationShell.vue";
import DocumentDrop from "../../components/DocumentDrop.vue";

defineProps<{
  carrierName: string;
  effectName: string;
  items: GrantItemReference[];
  lifetime: GrantItemsLifetime;
  ownerAction: GrantItemsOwnerAction;
  onCancel: () => void;
  onCreate: () => void;
  onDropData: (data: string) => void;
  onEffectNameInput: (value: string) => void;
  onLifetimeChange: (value: GrantItemsLifetime) => void;
  onOwnerActionChange: (value: GrantItemsOwnerAction) => void;
  onRemoveItem: (uuid: string) => void;
}>();

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement ? event.target.value : "";
}
</script>

<template>
  <ApplicationShell
    :description="`Build an item-granting Active Effect on ${carrierName}.`"
    title="Grant Builder"
  >
    <section class="dui-card dui-card-border dui-card-sm">
      <div class="dui-card-body">
        <h2 class="dui-card-title">Granted Items</h2>

        <DocumentDrop
          description="World and compendium Items can be added one at a time."
          manual-entry-trigger="button"
          title="Drop Items Here"
          @drop-data="onDropData"
        />

        <ul class="dui-list">
          <li v-if="items.length === 0" class="dui-list-row">No granted items configured.</li>
          <li v-for="item in items" v-else :key="item.uuid" class="dui-list-row">
            <img v-if="item.img" alt="" :src="item.img" />
            <div class="dui-list-col-grow">
              <strong>{{ item.name }}</strong>
              <small>{{ item.uuid }}</small>
            </div>
            <button
              class="dui-btn dui-btn-ghost dui-btn-sm dui-btn-square"
              type="button"
              :title="`Remove ${item.name}`"
              @click="onRemoveItem(item.uuid)"
            >
              <i class="fa-solid fa-times" aria-hidden="true" />
            </button>
          </li>
        </ul>
      </div>
    </section>

    <section class="dui-card dui-card-border dui-card-sm">
      <div class="dui-card-body">
        <fieldset class="dui-fieldset">
          <legend class="dui-fieldset-legend">Effect</legend>
          <label class="dui-label">
            <span>Effect name</span>
            <input
              class="dui-input"
              :value="effectName"
              type="text"
              @input="onEffectNameInput(inputValue($event))"
            />
          </label>
        </fieldset>
      </div>
    </section>

    <form class="dui-card dui-card-border dui-card-sm" @submit.prevent>
      <div class="dui-card-body">
        <fieldset class="dui-fieldset">
          <legend class="dui-fieldset-legend">Granted Item Lifetime</legend>
          <label class="dui-label">
            <input
              class="dui-radio"
              name="grant-lifetime"
              type="radio"
              value="linked-to-effect"
              :checked="lifetime === 'linked-to-effect'"
              @change="onLifetimeChange('linked-to-effect')"
            />
            <span>
              <strong>Linked to this effect</strong><br />
              Granted Items are removed when this effect is deleted.
            </span>
          </label>
          <label class="dui-label">
            <input
              class="dui-radio"
              name="grant-lifetime"
              type="radio"
              value="detached"
              :checked="lifetime === 'detached'"
              @change="onLifetimeChange('detached')"
            />
            <span>
              <strong>Detached copies</strong><br />
              Granted Items remain after this effect or source Item is removed.
            </span>
          </label>
          <label class="dui-label">
            <input
              class="dui-checkbox"
              type="checkbox"
              :checked="ownerAction === 'delete-after-grant'"
              :disabled="lifetime !== 'detached'"
              @change="
                onOwnerActionChange(
                  ownerAction === 'delete-after-grant' ? 'keep' : 'delete-after-grant',
                )
              "
            />
            Remove the source Item after granting.
          </label>
        </fieldset>
      </div>
    </form>

    <template #actions>
      <button class="dui-btn dui-btn-ghost" type="button" @click="onCancel">Cancel</button>
      <button
        class="dui-btn dui-btn-primary"
        type="button"
        :disabled="items.length === 0"
        @click="onCreate"
      >
        Create Grant Effect
      </button>
    </template>
  </ApplicationShell>
</template>
