import type {
  SpeciesBuilderCareerReplacementRow,
  SpeciesBuilderDefinition,
  SpeciesBuilderItemReference,
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderSubspeciesDefinition,
  SpeciesBuilderTalentReplacementRow,
} from "../../../types/species-builder/species-builder";

import { formatItemReferenceName } from "../item-reference-names";
import {
  careerReplacementRecordFromRows,
  talentReplacementRecordFromRows,
} from "../replacement-row-records";
import { setOptionalField } from "./draft";

export { careerReplacementRecordFromRows, talentReplacementRecordFromRows };

export type TalentReplacementSlot = "replacement" | "rolled";

function emptyLinkedItemName(): SpeciesBuilderLinkedItemName {
  return {
    name: "",
  };
}

export function createEmptyTalentReplacementRow(): SpeciesBuilderTalentReplacementRow {
  return {
    replacement: emptyLinkedItemName(),
    rolled: emptyLinkedItemName(),
  };
}

export function createEmptyCareerReplacementRow(): SpeciesBuilderCareerReplacementRow {
  return {
    replacements: [emptyLinkedItemName()],
    rolled: emptyLinkedItemName(),
  };
}

export function appendTalentReplacementRow(
  rows: SpeciesBuilderTalentReplacementRow[],
): SpeciesBuilderTalentReplacementRow[] {
  return [...rows, createEmptyTalentReplacementRow()];
}

export function removeTalentReplacementRow(
  rows: SpeciesBuilderTalentReplacementRow[],
  rowIndex: number,
): SpeciesBuilderTalentReplacementRow[] {
  return rows.filter((_, index) => index !== rowIndex);
}

export function appendCareerReplacementRow(
  rows: SpeciesBuilderCareerReplacementRow[],
): SpeciesBuilderCareerReplacementRow[] {
  return [...rows, createEmptyCareerReplacementRow()];
}

export function appendCareerReplacementChoice(
  rows: SpeciesBuilderCareerReplacementRow[],
  rowIndex: number,
): SpeciesBuilderCareerReplacementRow[] {
  return rows.map((row, index) =>
    index === rowIndex
      ? {
          ...row,
          replacements: [...row.replacements, emptyLinkedItemName()],
        }
      : row,
  );
}

export function removeCareerReplacementChoice(
  rows: SpeciesBuilderCareerReplacementRow[],
  rowIndex: number,
  choiceIndex: number,
): SpeciesBuilderCareerReplacementRow[] {
  return rows
    .map((row, index) =>
      index === rowIndex
        ? {
            ...row,
            replacements: row.replacements.filter(
              (_, replacementIndex) => replacementIndex !== choiceIndex,
            ),
          }
        : row,
    )
    .filter((row) => row.replacements.length > 0);
}

export function removeCareerReplacementRow(
  rows: SpeciesBuilderCareerReplacementRow[],
  rowIndex: number,
): SpeciesBuilderCareerReplacementRow[] {
  return rows.filter((_, index) => index !== rowIndex);
}

export function talentReplacementRowsForDefinition(
  definition: SpeciesBuilderDefinition | SpeciesBuilderSubspeciesDefinition,
): SpeciesBuilderTalentReplacementRow[] {
  return definition.talentReplacementRows?.length
    ? cloneRows(definition.talentReplacementRows)
    : talentReplacementRowsFromRecord(definition.talentReplacements);
}

export function careerReplacementRowsForDefinition(
  definition: SpeciesBuilderDefinition,
): SpeciesBuilderCareerReplacementRow[] {
  return definition.careerReplacementRows?.length
    ? cloneRows(definition.careerReplacementRows)
    : careerReplacementRowsFromRecord(definition.careerReplacements);
}

export function talentReplacementRowsFromRecord(
  values: Record<string, string> | undefined,
): SpeciesBuilderTalentReplacementRow[] {
  return Object.entries(values ?? {}).map(([rolled, replacement]) => ({
    replacement: {
      name: replacement,
    },
    rolled: {
      name: rolled,
    },
  }));
}

export function careerReplacementRowsFromRecord(
  values: Record<string, string[]> | undefined,
): SpeciesBuilderCareerReplacementRow[] {
  return Object.entries(values ?? {}).map(([rolled, replacements]) => ({
    replacements: replacements.map((replacement) => ({
      name: replacement,
    })),
    rolled: {
      name: rolled,
    },
  }));
}

export function setTalentReplacementItem(
  rows: SpeciesBuilderTalentReplacementRow[],
  rowIndex: number,
  slot: TalentReplacementSlot,
  item: SpeciesBuilderItemReference,
): SpeciesBuilderTalentReplacementRow[] {
  return rows.map((row, index) => {
    if (index !== rowIndex) {
      return row;
    }

    return {
      ...row,
      [slot]: linkedItemNameFromReference(item),
    };
  });
}

export function setCareerReplacementRolledItem(
  rows: SpeciesBuilderCareerReplacementRow[],
  rowIndex: number,
  item: SpeciesBuilderItemReference,
): SpeciesBuilderCareerReplacementRow[] {
  return rows.map((row, index) =>
    index === rowIndex
      ? {
          ...row,
          rolled: linkedItemNameFromReference(item),
        }
      : row,
  );
}

export function setCareerReplacementChoiceItem(
  rows: SpeciesBuilderCareerReplacementRow[],
  rowIndex: number,
  replacementIndex: number,
  item: SpeciesBuilderItemReference,
): SpeciesBuilderCareerReplacementRow[] {
  return rows.map((row, index) => {
    if (index !== rowIndex) {
      return row;
    }

    const replacements = row.replacements.map((replacement, choiceIndex) =>
      choiceIndex === replacementIndex ? linkedItemNameFromReference(item) : replacement,
    );

    return {
      ...row,
      replacements,
    };
  });
}

export function linkedItemNameFromReference(
  item: SpeciesBuilderItemReference,
): SpeciesBuilderLinkedItemName {
  return {
    item,
    name: formatItemReferenceName(item),
  };
}

export function setSpeciesTalentReplacementRows(
  definition: SpeciesBuilderDefinition,
  rows: SpeciesBuilderTalentReplacementRow[],
): SpeciesBuilderDefinition {
  const withRows = setOptionalField(
    definition,
    "talentReplacementRows",
    rows.length > 0 ? rows : undefined,
  );

  return setOptionalField(withRows, "talentReplacements", talentReplacementRecordFromRows(rows));
}

export function setSpeciesCareerReplacementRows(
  definition: SpeciesBuilderDefinition,
  rows: SpeciesBuilderCareerReplacementRow[],
): SpeciesBuilderDefinition {
  const withRows = setOptionalField(
    definition,
    "careerReplacementRows",
    rows.length > 0 ? rows : undefined,
  );

  return setOptionalField(withRows, "careerReplacements", careerReplacementRecordFromRows(rows));
}

export function setSubspeciesTalentReplacementRows(
  subspecies: SpeciesBuilderSubspeciesDefinition,
  rows: SpeciesBuilderTalentReplacementRow[],
): SpeciesBuilderSubspeciesDefinition {
  const withRows = setOptionalField(
    subspecies,
    "talentReplacementRows",
    rows.length > 0 ? rows : undefined,
  );

  return setOptionalField(withRows, "talentReplacements", talentReplacementRecordFromRows(rows));
}

function cloneRows<T>(rows: T[]): T[] {
  return JSON.parse(JSON.stringify(rows)) as T[];
}
