<script setup lang="ts">
import type {
  SpeciesBuilderSpeciesOption,
  SpeciesBuilderSpeciesTableDraft,
  SpeciesBuilderSpeciesTableRow,
} from "../../../../../types/species-builder/species-builder";
import type { SpeciesTableRowSummary } from "../../../../../functions/species-builder/world-table";
import type { SpeciesBuilderValidationIssue } from "../../../../../types/species-builder/validation";

import TableEditorHeader from "../species/pages/editor/tabs/tables/components/TableEditorHeader.vue";

const props = defineProps<{
  draft: SpeciesBuilderSpeciesTableDraft;
  isDisabled: boolean;
  isValidationBlocking: boolean;
  options: SpeciesBuilderSpeciesOption[];
  summaries: SpeciesTableRowSummary[];
  issues: SpeciesBuilderValidationIssue[];
  validationMessages: string[];
}>();

const emit = defineEmits<{
  addRow: [];
  removeRow: [index: number];
  updateRowKey: [index: number, key: string];
  updateRowWeight: [index: number, value: string];
}>();

function selectValue(event: Event): string {
  return event.target instanceof HTMLSelectElement ? event.target.value : "";
}

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement ? event.target.value : "";
}

function isOptionUsed(key: string, currentIndex: number): boolean {
  return props.draft.rows.some((row, index) => index !== currentIndex && row.speciesKey === key);
}

function speciesFieldIsInvalid(row: SpeciesBuilderSpeciesTableRow, index: number): boolean {
  return (
    !row.speciesKey ||
    !props.options.some((option) => option.key === row.speciesKey) ||
    isOptionUsed(row.speciesKey, index) ||
    fieldIssues(index, "speciesKey").length > 0
  );
}

function weightFieldIsInvalid(row: SpeciesBuilderSpeciesTableRow, index: number): boolean {
  return !Number.isInteger(row.weight) || row.weight < 1 || fieldIssues(index, "weight").length > 0;
}

function rowErrorLabel(row: SpeciesBuilderSpeciesTableRow, index: number): string {
  const errors: string[] = [];

  if (!row.speciesKey || !props.options.some((option) => option.key === row.speciesKey)) {
    errors.push("Choose a known species");
  } else if (isOptionUsed(row.speciesKey, index)) {
    errors.push("Choose each species only once");
  }
  if (weightFieldIsInvalid(row, index)) {
    errors.push("Use a whole-number weight of at least 1");
  }

  errors.push(...rowIssues(index).map((issue) => issue.message));

  return [...new Set(errors)].join(". ");
}

function rowIssues(index: number): SpeciesBuilderValidationIssue[] {
  return props.issues.filter((issue) => issue.rowIndex === index);
}

function fieldIssues(index: number, field: "speciesKey" | "weight") {
  return rowIssues(index).filter((issue) => issue.field === field);
}

function panelValidationMessages(): string[] {
  const locatedMessages = props.issues
    .filter((issue) => issue.rowIndex === undefined)
    .map((issue) => issue.message);

  return [...new Set([...props.validationMessages, ...locatedMessages])];
}

function validationIsBlocking(): boolean {
  return props.isValidationBlocking;
}

function summaryLabel(summary: SpeciesTableRowSummary | undefined): string {
  if (!summary || summary.chance <= 0) {
    return "Invalid weight";
  }

  const percentage = new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 1,
    style: "percent",
  }).format(summary.chance);

  return `${percentage} · ${summary.range[0]}–${summary.range[1]}`;
}

function statusLabel(): string {
  if (props.draft.ownership === "external") {
    return props.draft.isRegistered ? "External table active" : "External table";
  }

  if (props.draft.ownership === "managed") {
    return props.draft.isRegistered ? "Registered" : "Not registered";
  }

  return "No managed table yet";
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <TableEditorHeader
        action-label="Add Species"
        action-title="Add a weighted species result"
        :count="draft.rows.length"
        description="Weights set each species' share of random character-creation rolls."
        :is-disabled="isDisabled"
        heading-level="h2"
        title="Random Species Table"
        @add="emit('addRow')"
      />

      <div class="app:flex app:flex-wrap app:items-center app:gap-2">
        <span class="dui-badge dui-badge-sm">{{ statusLabel() }}</span>
        <span class="app:text-base-content/70">{{ draft.name }}</span>
      </div>

      <div v-if="draft.ownership === 'external'" class="dui-alert dui-alert-info" role="status">
        <i aria-hidden="true" class="fa-solid fa-copy" />
        <span>
          This is the current WFRP source table. On Save, table changes create a Species
          Builder-managed copy and leave the imported source unchanged.
        </span>
      </div>

      <div v-if="draft.requiresLinkRepair" class="dui-alert dui-alert-warning" role="status">
        <i aria-hidden="true" class="fa-solid fa-link-slash" />
        <span>
          One or more results lack WFRP's required UUID-link description. Save to generate or reuse
          species Journals and repair both the result name and link label.
        </span>
      </div>

      <div
        v-if="panelValidationMessages()[0]"
        class="dui-alert"
        :class="validationIsBlocking() ? 'dui-alert-error' : 'dui-alert-info'"
        :role="validationIsBlocking() ? 'alert' : 'status'"
      >
        <i aria-hidden="true" class="fa-solid fa-triangle-exclamation" />
        <span>
          {{ validationIsBlocking() ? "Fix before saving:" : "Imported table needs attention:" }}
          {{ panelValidationMessages()[0] }}
          <template v-if="panelValidationMessages().length > 1">
            ({{ panelValidationMessages().length }} issues total)
          </template>
        </span>
      </div>

      <div v-if="draft.rows.length" class="app:overflow-x-auto">
        <table class="dui-table dui-table-sm">
          <caption class="app:sr-only">
            Weighted results for the world WFRP Species table
          </caption>
          <thead>
            <tr>
              <th scope="col">#</th>
              <th scope="col">Species</th>
              <th scope="col">Weight</th>
              <th scope="col">Chance / range</th>
              <th scope="col"><span class="app:sr-only">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            <tr
              v-for="(row, index) in draft.rows"
              :key="row.resultId ?? `new-${index}`"
              :class="{
                'app:outline app:outline-1 app:outline-error': rowIssues(index).length > 0,
              }"
            >
              <th scope="row">{{ index + 1 }}</th>
              <td>
                <label class="app:sr-only" :for="`species-table-species-${index}`">
                  Species for row {{ index + 1 }}
                </label>
                <select
                  :id="`species-table-species-${index}`"
                  :aria-describedby="
                    rowErrorLabel(row, index) ? `species-table-row-error-${index}` : undefined
                  "
                  :aria-invalid="speciesFieldIsInvalid(row, index) || undefined"
                  class="dui-select dui-select-sm app:min-w-48 app:w-full"
                  :class="{ 'dui-select-error': speciesFieldIsInvalid(row, index) }"
                  :disabled="isDisabled"
                  :value="row.speciesKey"
                  @change="emit('updateRowKey', index, selectValue($event))"
                >
                  <option value="">
                    {{ row.name ? `Unrecognized: ${row.name}` : "Choose a species" }}
                  </option>
                  <option
                    v-for="option in options"
                    :key="option.key"
                    :disabled="isOptionUsed(option.key, index)"
                    :value="option.key"
                  >
                    {{ option.label }}
                  </option>
                </select>
                <span
                  v-if="rowErrorLabel(row, index)"
                  :id="`species-table-row-error-${index}`"
                  class="app:mt-1 app:block app:text-xs app:text-error"
                >
                  {{ rowErrorLabel(row, index) }}
                </span>
              </td>
              <td>
                <label class="app:sr-only" :for="`species-table-weight-${index}`">
                  Weight for row {{ index + 1 }}
                </label>
                <input
                  :id="`species-table-weight-${index}`"
                  :aria-describedby="
                    rowErrorLabel(row, index) ? `species-table-row-error-${index}` : undefined
                  "
                  :aria-invalid="weightFieldIsInvalid(row, index) || undefined"
                  class="dui-input dui-input-sm app:w-24"
                  :class="{ 'dui-input-error': weightFieldIsInvalid(row, index) }"
                  :disabled="isDisabled"
                  inputmode="numeric"
                  min="1"
                  step="1"
                  type="number"
                  :value="row.weight"
                  @input="emit('updateRowWeight', index, inputValue($event))"
                />
              </td>
              <td>
                <output :for="`species-table-weight-${index}`">
                  {{ summaryLabel(summaries[index]) }}
                </output>
              </td>
              <td>
                <button
                  class="dui-btn dui-btn-error dui-btn-outline dui-btn-sm"
                  :disabled="isDisabled"
                  :title="`Remove ${row.name || `row ${index + 1}`}`"
                  type="button"
                  @click="emit('removeRow', index)"
                >
                  <i aria-hidden="true" class="fa-solid fa-trash" />
                  <span class="app:sr-only">Remove row {{ index + 1 }}</span>
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <div v-else class="dui-alert dui-alert-info" role="status">
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>Add at least one species to create a managed world table.</span>
      </div>
    </div>
  </section>
</template>
