import type { NpcMagicGrant, NpcSpellDraftEntry } from "../../../../../types/npc-builder";

import { assertFoundryItemType, isFoundryItem } from "../../../../foundry/document-guards";
import { parseDropData } from "../../../../foundry/drop-data";
import {
  createItemSourceFromMatch,
  findActorItemByNameAndType,
} from "../../../../foundry/item-sources";
import { spellItemType } from "./constants";
import { logSpellLookupDebug } from "./debug";
import {
  createPettyMagicProfile,
  createUnknownMagicLoreProfile,
  findMatchingSpellLore,
  readMagicLoreProfiles,
  readSpellLoreTerms,
  resolveGrantedLoreProfiles,
} from "./lore-profiles";
import { listSpellResolutionInputs, toSpellResolutionInput } from "./spell-resolution-inputs";

export { listMagicLoreOptions } from "./lore-profiles";

export async function applySpells(
  actor: FoundryActorDocument,
  spells: NpcSpellDraftEntry[],
): Promise<void> {
  const itemCreates: FoundryItemSource[] = [];

  for (const spell of spells) {
    if (!spell.selected) {
      continue;
    }

    const existingItem = findActorItemByNameAndType(actor, spell.name, spellItemType);

    if (existingItem) {
      continue;
    }

    const sourceItem = spell.sourceUuid ? await resolveSpellSourceItem(spell.sourceUuid) : null;
    const itemData = createItemSourceFromMatch(sourceItem, spell.name, spellItemType);

    itemData["type"] = spellItemType;
    itemCreates.push(itemData);
  }

  if (itemCreates.length) {
    await actor.createEmbeddedDocuments("Item", itemCreates);
  }
}

export async function listSpellsForMagicGrants(
  grants: NpcMagicGrant[],
): Promise<NpcSpellDraftEntry[]> {
  const loreProfiles = readMagicLoreProfiles();
  const resolvedProfiles = resolveGrantedLoreProfiles(grants, loreProfiles);

  logSpellLookupDebug("Grant resolution start", {
    grants: grants.map((grant) => ({
      isAmbiguous: grant.isAmbiguous,
      kind: grant.kind,
      rawLore: grant.rawLore,
      sourceName: grant.sourceName,
    })),
    resolvedProfiles: resolvedProfiles.map((profile) => ({
      key: profile.key,
      matchTerms: profile.matchTerms,
      name: profile.name,
      wind: profile.wind,
    })),
  });

  if (!resolvedProfiles.length) {
    return [];
  }

  const candidates = await listSpellResolutionInputs();
  const spells = new Map<string, NpcSpellDraftEntry>();
  const unmatchedLoreSamples: Array<Record<string, unknown>> = [];

  for (const candidate of candidates) {
    const matchingProfile = findMatchingSpellLore(candidate, resolvedProfiles);

    if (!matchingProfile) {
      if (unmatchedLoreSamples.length < 20) {
        unmatchedLoreSamples.push({
          loreTerms: readSpellLoreTerms(candidate.system),
          name: candidate.name,
          sourceLabel: candidate.sourceLabel,
          uuid: candidate.uuid,
        });
      }

      continue;
    }

    const key = `detected:${candidate.uuid || candidate.name}`;

    spells.set(key, {
      img: candidate.img,
      key,
      loreKey: matchingProfile.key,
      loreName: matchingProfile.name,
      name: candidate.name,
      selected: false,
      source: "detected",
      sourceLabel: candidate.sourceLabel,
      sourceUuid: candidate.uuid,
    });
  }

  logSpellLookupDebug("Grant resolution complete", {
    candidateCount: candidates.length,
    matchedSpellCount: spells.size,
    matchedSpellSamples: [...spells.values()].slice(0, 10).map((spell) => ({
      loreName: spell.loreName,
      name: spell.name,
      sourceLabel: spell.sourceLabel,
      sourceUuid: spell.sourceUuid,
    })),
    unmatchedLoreSamples,
  });

  return [...spells.values()].sort((left, right) => {
    if (left.loreName !== right.loreName) {
      return left.loreName.localeCompare(right.loreName);
    }

    return left.name.localeCompare(right.name);
  });
}

export async function resolveSpellDrop(data: string): Promise<NpcSpellDraftEntry> {
  const dropData = parseDropData(data);

  if (dropData.type !== "Item" || !dropData.uuid) {
    throw new Error("Drop a Foundry Spell item here.");
  }

  const item = assertFoundryItemType(
    await fromUuid(dropData.uuid),
    spellItemType,
    "Drop a Foundry Spell item here.",
  );
  const matchingProfile =
    findMatchingSpellLore(toSpellResolutionInput(item, "Dropped"), [
      ...readMagicLoreProfiles(),
      createPettyMagicProfile(),
    ]) ?? createUnknownMagicLoreProfile(readSpellLoreTerms(item.system)[0] ?? "");

  return {
    img: item.img ?? "",
    key: `custom:${item.uuid}`,
    loreKey: matchingProfile.key,
    loreName: matchingProfile.name,
    name: item.name,
    selected: true,
    source: "custom",
    sourceLabel: "Dropped",
    sourceUuid: item.uuid,
  };
}

async function resolveSpellSourceItem(uuid: string): Promise<FoundryItemDocument | null> {
  const item = await fromUuid(uuid);

  return isFoundryItem(item) && item.type === spellItemType ? item : null;
}
