<script setup lang="ts">
import { nextTick, ref } from "vue";

defineProps<{
  canManageDefinition: boolean;
  contextLabel: string;
  definitionName?: string;
  isBusy: boolean;
}>();

const emit = defineEmits<{
  delete: [];
  duplicate: [];
  reload: [];
  selectSpecies: [];
}>();

const actionsDropdown = ref<HTMLDetailsElement>();
const portabilityDialogHost = ref<HTMLElement>();
let handledEscapeKeydown = false;

function emitEditorAction(action: "delete" | "duplicate"): void {
  closeActionsDropdown();
  emit(action);
}

function emitReload(): void {
  closeActionsDropdown();
  emit("reload");
}

async function selectSpecies(event: MouseEvent): Promise<void> {
  const scrollContainer =
    event.currentTarget instanceof HTMLElement
      ? event.currentTarget.closest<HTMLElement>(".wfrp4e-customizer-apps-root")
      : null;

  closeActionsDropdown();
  emit("selectSpecies");
  await nextTick();
  scrollContainer?.scrollTo({ top: 0 });
  scrollContainer?.querySelector<HTMLElement>("#species-builder-species-list-heading")?.focus();
}

function closeActionsDropdown(): void {
  actionsDropdown.value?.removeAttribute("open");
}

function handleEscapeKeydown(event: KeyboardEvent): void {
  if (!actionsDropdown.value?.open) {
    return;
  }

  handledEscapeKeydown = true;
  event.preventDefault();
  event.stopPropagation();
  closeActionsDropdown();
}

function handleEscapeKeyup(event: KeyboardEvent): void {
  if (!handledEscapeKeydown) {
    return;
  }

  handledEscapeKeydown = false;
  event.preventDefault();
  event.stopPropagation();
}
</script>

<template>
  <header
    class="dui-navbar app:sticky app:top-0 app:z-20 app:bg-base-200"
    @keydown.esc="handleEscapeKeydown"
    @keyup.esc="handleEscapeKeyup"
  >
    <div class="dui-navbar-start app:min-w-0 app:flex-1">
      <div class="app:min-w-0">
        <h1 class="app:m-0 app:text-xl app:leading-tight">Species Builder</h1>
        <nav aria-label="Current location" class="dui-breadcrumbs app:py-0 app:text-sm">
          <ul class="app:m-0 app:p-0">
            <li v-if="definitionName">
              <button class="dui-btn dui-btn-link dui-btn-xs" type="button" @click="selectSpecies">
                Species List
              </button>
            </li>
            <li v-if="definitionName">
              <span>{{ definitionName }}</span>
            </li>
            <li>
              <span aria-current="page">{{ contextLabel }}</span>
            </li>
          </ul>
        </nav>
      </div>
    </div>

    <div class="dui-navbar-end">
      <details ref="actionsDropdown" class="dui-dropdown dui-dropdown-end">
        <summary class="dui-btn dui-btn-outline dui-btn-sm">
          <i aria-hidden="true" class="fa-solid fa-ellipsis" />
          Actions
        </summary>
        <div
          class="dui-dropdown-content dui-card dui-card-border app:z-30 app:w-52 app:bg-base-100"
        >
          <ul class="dui-menu dui-menu-sm app:w-full">
            <li @click="closeActionsDropdown">
              <slot name="actions" :dialog-host="portabilityDialogHost" />
            </li>
            <li>
              <button :disabled="isBusy" type="button" @click="emitReload">
                <i aria-hidden="true" class="fa-solid fa-rotate-right" />
                Reload
              </button>
            </li>
            <li v-if="canManageDefinition">
              <button :disabled="isBusy" type="button" @click="emitEditorAction('duplicate')">
                <i aria-hidden="true" class="fa-solid fa-copy" />
                Duplicate
              </button>
            </li>
            <li v-if="canManageDefinition">
              <button
                class="app:text-error"
                :disabled="isBusy"
                type="button"
                @click="emitEditorAction('delete')"
              >
                <i aria-hidden="true" class="fa-solid fa-trash" />
                Delete
              </button>
            </li>
          </ul>
        </div>
      </details>
    </div>

    <div ref="portabilityDialogHost" />
  </header>
</template>
