<script setup lang="ts">
import { type SpeciesBuilderStatField, statFields } from "../../support/field-definitions";
import {
  hasValidationErrors,
  issuesForField,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../../validation-presentation";

const props = defineProps<{
  fields: SpeciesBuilderStatField[];
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  values: Partial<Record<SpeciesBuilderStatField, number>>;
}>();

const emit = defineEmits<{
  update: [field: SpeciesBuilderStatField, value: string];
}>();

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement ? event.target.value : "";
}

function statIssues(field: SpeciesBuilderStatField): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, field);
}

function statMessages(field: SpeciesBuilderStatField): string[] {
  return uniqueIssueMessages(statIssues(field));
}
</script>

<template>
  <table class="dui-table dui-table-sm">
    <thead>
      <tr>
        <th scope="col">Stat</th>
        <th scope="col">Value</th>
      </tr>
    </thead>
    <tbody>
      <tr
        v-for="entry in statFields.filter(({ field }) => fields.includes(field))"
        :key="entry.field"
      >
        <th scope="row">
          <label :for="`species-stat-${entry.field}`">{{ entry.label }}</label>
        </th>
        <td>
          <input
            :id="`species-stat-${entry.field}`"
            :aria-describedby="
              statIssues(entry.field).length ? `species-stat-${entry.field}-errors` : undefined
            "
            :aria-invalid="hasValidationErrors(statIssues(entry.field)) || undefined"
            class="dui-input dui-input-sm"
            :class="
              validationClass(statIssues(entry.field), 'dui-input-error', 'dui-input-warning')
            "
            :disabled="isDisabled"
            :value="values[entry.field] ?? ''"
            type="number"
            @input="emit('update', entry.field, inputValue($event))"
          />
          <div v-if="statMessages(entry.field).length" :id="`species-stat-${entry.field}-errors`">
            <p
              v-for="message in statMessages(entry.field)"
              :key="message"
              class="app:m-0 app:text-xs"
              :class="
                validationClass(statIssues(entry.field), 'app:text-error', 'app:text-warning')
              "
            >
              {{ message }}
            </p>
          </div>
        </td>
      </tr>
    </tbody>
  </table>
</template>
