import type {
  SpeciesBuilderValidationIssue,
  SpeciesBuilderValidationSeverity,
} from "../../../../../../../types/species-builder/validation";

export type { SpeciesBuilderValidationIssue };

type ValidationField = string | readonly string[];

function fields(field: ValidationField): readonly string[] {
  return typeof field === "string" ? [field] : field;
}

export function issuesForField(
  issues: SpeciesBuilderValidationIssue[],
  field: ValidationField,
  rowIndex?: number,
  choiceIndex?: number,
): SpeciesBuilderValidationIssue[] {
  return issues.filter(
    (issue) =>
      fields(field).includes(issue.field ?? "") &&
      issue.rowIndex === rowIndex &&
      issue.choiceIndex === choiceIndex,
  );
}

export function issuesForFieldAtAnyRow(
  issues: SpeciesBuilderValidationIssue[],
  field: ValidationField,
): SpeciesBuilderValidationIssue[] {
  return issues.filter((issue) => fields(field).includes(issue.field ?? ""));
}

export function issuesForRow(
  issues: SpeciesBuilderValidationIssue[],
  rowIndex: number,
): SpeciesBuilderValidationIssue[] {
  return issues.filter((issue) => issue.rowIndex === rowIndex);
}

export function issuesForFieldRow(
  issues: SpeciesBuilderValidationIssue[],
  field: ValidationField,
  rowIndex: number,
): SpeciesBuilderValidationIssue[] {
  return issues.filter(
    (issue) => fields(field).includes(issue.field ?? "") && issue.rowIndex === rowIndex,
  );
}

export function issuesForChoice(
  issues: SpeciesBuilderValidationIssue[],
  rowIndex: number,
  choiceIndex: number,
): SpeciesBuilderValidationIssue[] {
  return issues.filter((issue) => issue.rowIndex === rowIndex && issue.choiceIndex === choiceIndex);
}

export function sectionIssues(
  issues: SpeciesBuilderValidationIssue[],
): SpeciesBuilderValidationIssue[] {
  return issues.filter((issue) => issue.rowIndex === undefined && issue.field === undefined);
}

export function issuesWithoutRow(
  issues: SpeciesBuilderValidationIssue[],
): SpeciesBuilderValidationIssue[] {
  return issues.filter((issue) => issue.rowIndex === undefined);
}

export function uniqueIssueMessages(issues: SpeciesBuilderValidationIssue[]): string[] {
  return [...new Set(issues.map((issue) => issue.message))];
}

export function validationSeverity(
  issues: SpeciesBuilderValidationIssue[],
): SpeciesBuilderValidationSeverity | undefined {
  if (issues.some((issue) => issue.severity !== "warning")) {
    return "error";
  }

  return issues.length > 0 ? "warning" : undefined;
}

export function hasValidationErrors(issues: SpeciesBuilderValidationIssue[]): boolean {
  return validationSeverity(issues) === "error";
}

export function validationClass(
  issues: SpeciesBuilderValidationIssue[],
  errorClass: string,
  warningClass: string,
): string | undefined {
  const severity = validationSeverity(issues);
  return severity === "error" ? errorClass : severity === "warning" ? warningClass : undefined;
}
