<script setup lang="ts">
import type { DocumentDropReference } from "../../../types/foundry/document-drop";

defineProps<{
  documents: DocumentDropReference[];
  emptyLabel: string;
  isClickable: boolean;
}>();

const emit = defineEmits<{
  documentClicked: [document: DocumentDropReference];
}>();

function emitDocumentClicked(document: DocumentDropReference): void {
  if (document.uuid) {
    emit("documentClicked", document);
  }
}
</script>

<template>
  <ul class="dui-list">
    <template v-if="documents.length > 0">
      <li v-for="document in documents" :key="document.uuid" class="dui-list-row">
        <button
          :aria-label="isClickable ? `Use ${document.name}` : undefined"
          class="dui-btn dui-btn-ghost"
          :disabled="!isClickable"
          :title="isClickable ? document.name : undefined"
          type="button"
          @click.stop="emitDocumentClicked(document)"
        >
          <img v-if="document.img" alt="" aria-hidden="true" :src="document.img" />
          <i v-else aria-hidden="true" class="fa-solid fa-scroll" />
          <span>{{ document.name }}</span>
        </button>
      </li>
    </template>

    <li v-else class="dui-list-row">
      <i aria-hidden="true" class="fa-solid fa-arrow-down" />
      <span>{{ emptyLabel }}</span>
    </li>
  </ul>
</template>
