import type { SpeciesBuilderDetailPanelEmits } from "../../detail-panel-events";

type DetailPanelEmit = <TEvent extends keyof SpeciesBuilderDetailPanelEmits>(
  event: TEvent,
  ...args: SpeciesBuilderDetailPanelEmits[TEvent]
) => void;

interface SubspeciesOverlayEventOptions {
  close: () => void;
  deleteSubspecies: (index: number) => void;
}

export function createSubspeciesOverlayEvents(
  emit: DetailPanelEmit,
  options: SubspeciesOverlayEventOptions,
) {
  return {
    close: options.close,
    deleteSubspecies: options.deleteSubspecies,
    openItem: (uuid: string) => {
      emit("openItem", uuid);
    },
    save: () => {
      emit("save");
    },
    subspeciesCareerTableCareerDrop: (
      ...args: SpeciesBuilderDetailPanelEmits["subspeciesCareerTableCareerDrop"]
    ) => {
      emit("subspeciesCareerTableCareerDrop", ...args);
    },
    subspeciesCareerTableJournalDrop: (
      ...args: SpeciesBuilderDetailPanelEmits["subspeciesCareerTableJournalDrop"]
    ) => {
      emit("subspeciesCareerTableJournalDrop", ...args);
    },
    subspeciesTalentDrop: (...args: SpeciesBuilderDetailPanelEmits["subspeciesTalentDrop"]) => {
      emit("subspeciesTalentDrop", ...args);
    },
    subspeciesTalentReplacementReplacementDrop: (
      ...args: SpeciesBuilderDetailPanelEmits["subspeciesTalentReplacementReplacementDrop"]
    ) => {
      emit("subspeciesTalentReplacementReplacementDrop", ...args);
    },
    subspeciesTalentReplacementRolledDrop: (
      ...args: SpeciesBuilderDetailPanelEmits["subspeciesTalentReplacementRolledDrop"]
    ) => {
      emit("subspeciesTalentReplacementRolledDrop", ...args);
    },
    updateSubspeciesArrayField: (
      ...args: SpeciesBuilderDetailPanelEmits["updateSubspeciesArrayField"]
    ) => {
      emit("updateSubspeciesArrayField", ...args);
    },
    updateSubspeciesCharacteristic: (
      ...args: SpeciesBuilderDetailPanelEmits["updateSubspeciesCharacteristic"]
    ) => {
      emit("updateSubspeciesCharacteristic", ...args);
    },
    updateSubspeciesNumberField: (
      ...args: SpeciesBuilderDetailPanelEmits["updateSubspeciesNumberField"]
    ) => {
      emit("updateSubspeciesNumberField", ...args);
    },
    updateSubspeciesStringField: (
      ...args: SpeciesBuilderDetailPanelEmits["updateSubspeciesStringField"]
    ) => {
      emit("updateSubspeciesStringField", ...args);
    },
    updateSubspeciesCareerTableRows: (
      ...args: SpeciesBuilderDetailPanelEmits["updateSubspeciesCareerTableRows"]
    ) => {
      emit("updateSubspeciesCareerTableRows", ...args);
    },
    updateSubspeciesWoundFormula: (
      ...args: SpeciesBuilderDetailPanelEmits["updateSubspeciesWoundFormula"]
    ) => {
      emit("updateSubspeciesWoundFormula", ...args);
    },
    updateSubspeciesTalentReplacementRows: (
      ...args: SpeciesBuilderDetailPanelEmits["updateSubspeciesTalentReplacementRows"]
    ) => {
      emit("updateSubspeciesTalentReplacementRows", ...args);
    },
    updateSubspeciesTextMapField: (
      ...args: SpeciesBuilderDetailPanelEmits["updateSubspeciesTextMapField"]
    ) => {
      emit("updateSubspeciesTextMapField", ...args);
    },
  };
}
