import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";

import { assignIfPresent } from "../../../shared/assign-if-present";
import {
  skillsForDefinition,
  skillsForSubspecies,
  talentsForDefinition,
  talentsForSubspecies,
  traitsForDefinition,
  traitsForSubspecies,
} from "../subspecies-list-fields";
import { validateCareerTables } from "./career-tables";
import { validateDefinitionFields } from "./definitions";
import { validateDefinitionGrants } from "./grants";
import { validateRandomTalentTables } from "./random-talents";
import { validateReplacementTables } from "./replacements";
import { createIssue, type ValidationCatalogIndex } from "./shared";

export function validateRuntimeExtensionEffectiveSetup(
  definitions: SpeciesBuilderEditingDefinition[],
  catalog: ValidationCatalogIndex,
  existingIssues: SpeciesBuilderValidationIssue[],
): SpeciesBuilderValidationIssue[] {
  const existingClasses = new Set(existingIssues.map(issueClass));

  return definitions.flatMap((definition, definitionIndex) => {
    if (definition.origin !== "runtime" || definition.runtimeUnavailable) {
      return [];
    }

    return (definition.subspecies ?? []).flatMap((subspecies, subspeciesIndex) => {
      if (subspeciesIndex < definition.runtimeSubspeciesCount) {
        return [];
      }

      return validateEffectiveDefinition(definition, subspecies, catalog).flatMap((issue) => {
        const mapped = mapEffectiveIssue(issue, definitionIndex, subspeciesIndex, subspecies.name);

        return existingClasses.has(issueClass(mapped)) ? [] : [mapped];
      });
    });
  });
}

function validateEffectiveDefinition(
  parent: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
  catalog: ValidationCatalogIndex,
): SpeciesBuilderValidationIssue[] {
  const effective = buildEffectiveDefinition(parent, subspecies);
  const issues: SpeciesBuilderValidationIssue[] = [];

  if (effective.skills === undefined) {
    issues.push(
      createIssue(
        { definitionIndex: 0, scope: "definition", section: "skills" },
        "effective-skills-required",
        "The effective Skill list is missing. WFRP character creation requires an array, even when it is empty.",
      ),
    );
  }
  if (effective.talents === undefined) {
    issues.push(
      createIssue(
        { definitionIndex: 0, scope: "definition", section: "talents" },
        "effective-talents-required",
        "The effective Talent list is missing. WFRP character creation requires an array, even when it is empty.",
      ),
    );
  }

  return [
    ...issues,
    ...validateDefinitionFields([effective]),
    ...validateDefinitionGrants([effective], catalog),
    ...validateRandomTalentTables([effective], catalog),
    ...validateCareerTables([effective], catalog),
    ...validateReplacementTables([effective], catalog),
  ];
}

function buildEffectiveDefinition(
  parent: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
): SpeciesBuilderDefinition {
  const effective: SpeciesBuilderDefinition = {
    includeInExtraSpecies: false,
    key: subspecies.key,
    name: subspecies.name,
  };

  assignIfPresent(effective, "age", parent.age);
  assignIfPresent(effective, "height", parent.height);
  assignIfPresent(
    effective,
    "characteristics",
    subspecies.characteristics
      ? { ...parent.characteristics, ...subspecies.characteristics }
      : parent.characteristics,
  );
  assignIfPresent(effective, "movement", subspecies.movement ?? parent.movement);
  assignIfPresent(effective, "fate", subspecies.fate ?? parent.fate);
  assignIfPresent(effective, "resilience", subspecies.resilience ?? parent.resilience);
  assignIfPresent(effective, "extra", subspecies.extra ?? parent.extra);
  assignIfPresent(
    effective,
    "skills",
    skillsForSubspecies(parent, subspecies) ?? skillsForDefinition(parent),
  );
  assignIfPresent(
    effective,
    "talents",
    talentsForSubspecies(parent, subspecies) ?? talentsForDefinition(parent),
  );
  assignIfPresent(
    effective,
    "traits",
    traitsForSubspecies(parent, subspecies) ?? traitsForDefinition(parent),
  );
  assignIfPresent(effective, "randomTalents", subspecies.randomTalents ?? parent.randomTalents);
  assignIfPresent(effective, "careerTable", subspecies.careerTable ?? parent.careerTable);
  assignIfPresent(effective, "careerReplacements", subspecies.careerReplacements);
  assignIfPresent(effective, "careerReplacementRows", subspecies.careerReplacementRows);
  assignTalentReplacements(effective, parent, subspecies);
  assignIfPresent(effective, "woundFormula", subspecies.woundFormula);

  return effective;
}

function assignTalentReplacements(
  effective: SpeciesBuilderDefinition,
  parent: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
): void {
  const hasOverride =
    subspecies.talentReplacementRows !== undefined || subspecies.talentReplacements !== undefined;

  assignIfPresent(
    effective,
    "talentReplacementRows",
    hasOverride ? subspecies.talentReplacementRows : parent.talentReplacementRows,
  );
  assignIfPresent(
    effective,
    "talentReplacements",
    hasOverride ? subspecies.talentReplacements : parent.talentReplacements,
  );
}

function mapEffectiveIssue(
  issue: SpeciesBuilderValidationIssue,
  definitionIndex: number,
  subspeciesIndex: number,
  subspeciesName: string,
): SpeciesBuilderValidationIssue {
  const mapped: SpeciesBuilderValidationIssue = {
    ...issue,
    definitionIndex,
    message: `Effective setup for ${subspeciesName || "this custom subspecies"}: ${issue.message}`,
    scope: "subspecies",
    subspeciesIndex,
  };

  if (!["attributes", "details", "wounds"].includes(mapped.section)) {
    delete mapped.choiceIndex;
    delete mapped.field;
    delete mapped.rowIndex;
  }

  return mapped;
}

function issueClass(issue: SpeciesBuilderValidationIssue): string {
  return [issue.definitionIndex ?? "", issue.subspeciesIndex ?? "", issue.section, issue.code].join(
    ":",
  );
}
