import type { SpeciesCareerTableSyncSummary } from "../../../types/species-builder/generated-documents";
import type { SpeciesBuilderSettings } from "../../../types/species-builder/species-builder";

import { planCareerTableSync } from "../../../functions/species-builder/generated-table-sync";
import {
  ANIMAL_FAMILIAR_CAREER_JOURNAL_UUID,
  buildSpeciesCareerTableSource,
  buildSpeciesCareerTableSpecs,
  fingerprintSpeciesCareerTableResult,
  GENERATED_CAREER_TABLE_FLAG,
  isFamiliarCorrectionCareerUuid,
} from "../../../functions/species-builder/career-tables";
import { isRecord, readStringPath, readUnknownPath } from "../../../shared/object-readers";
import { MODULE_ID } from "../../constants";
import { applyRollTableResultChanges } from "../../foundry/roll-table-results";
import { logInfo } from "../../logging";
import { loadSpeciesItemSettings } from "./items/repository";
import { managedSpeciesCareerTables } from "./items/career-outputs";
import { hasNativeSpeciesSupport } from "./items/migration";
import { loadRuntimeSpecies } from "./runtime-species";

const GENERATED_TABLE_FOLDER_NAME = "WFRP Customizer Generated Career Tables";
const FALLBACK_JOURNAL_NAME = "WFRP Customizer Career Table Link Fallback";

interface CareerTableSyncOptions {
  force?: boolean;
}

let syncInFlight: Promise<SpeciesCareerTableSyncSummary> | undefined;
let inFlightIsForced = false;

export function syncSpeciesBuilderCareerTables(
  settings?: SpeciesBuilderSettings,
  options: CareerTableSyncOptions = {},
): Promise<SpeciesCareerTableSyncSummary> {
  const force = options.force === true;

  if (!isActiveGmClient() || hasNativeSpeciesSupport()) {
    return Promise.resolve(emptySummary());
  }

  const resolvedSettings = settings ?? loadSpeciesItemSettings();

  if (syncInFlight) {
    return force && !inFlightIsForced
      ? syncInFlight.then(() => syncSpeciesBuilderCareerTables(resolvedSettings, { force: true }))
      : syncInFlight;
  }

  inFlightIsForced = force;
  syncInFlight = runCareerTableSync(resolvedSettings, force).finally(() => {
    syncInFlight = undefined;
    inFlightIsForced = false;
  });

  return syncInFlight;
}

async function runCareerTableSync(
  settings: SpeciesBuilderSettings,
  force: boolean,
): Promise<SpeciesCareerTableSyncSummary> {
  const startedAt = performance.now();
  const specs = buildSpeciesCareerTableSpecs(settings, await loadRuntimeSpecies());
  const applicableSpecs = specs.filter(
    (spec) => !isKnownSpeciesCorrection(spec) || !hasExternalCareerTable(spec.column),
  );
  const fallbackJournalUuid = applicableSpecs.some((spec) =>
    spec.rows.some((row) => !row.journalUuid?.trim()),
  )
    ? await ensureCareerFallbackJournalUuid()
    : undefined;
  const desiredSources = applicableSpecs.map((spec) =>
    buildSpeciesCareerTableSource({
      fallbackJournalUuid,
      flagScope: MODULE_ID,
      speciesItemBridge: true,
      spec,
    }),
  );
  const generatedTables = managedSpeciesCareerTables();
  const tablesById = new Map(generatedTables.map((table) => [table.id, table]));
  const plan = planCareerTableSync(
    desiredSources,
    generatedTables.map((table) => ({ id: table.id, source: table.toObject() })),
    MODULE_ID,
    force,
  );
  let folder: FoundryFolderDocument | undefined;
  let skipped = 0;
  let regenerated = 0;

  for (const entry of plan.entries) {
    if (entry.action === "skip") {
      skipped += 1;
      continue;
    }

    if (entry.action === "create") {
      folder ??= await ensureGeneratedTableFolder();
      await createCareerTable(entry.source, folder);
    } else {
      const table = entry.existingId ? tablesById.get(entry.existingId) : undefined;

      if (!table) {
        throw new Error("A generated career table changed during synchronization.");
      }

      await updateCareerTable(table, entry.source, force);
    }

    regenerated += 1;
  }

  for (const id of plan.obsoleteIds) {
    await tablesById.get(id)?.delete();
  }

  const summary: SpeciesCareerTableSyncSummary = {
    checked: desiredSources.length,
    elapsedMilliseconds: performance.now() - startedAt,
    regenerated,
    removed: plan.obsoleteIds.length,
    skipped,
  };
  logSyncSummary(summary, force);

  return summary;
}

function isActiveGmClient(): boolean {
  return game.user?.isGM === true && game.users?.activeGM?.id === game.user.id;
}

function isKnownSpeciesCorrection(spec: { rows: Array<{ journalUuid?: string }> }): boolean {
  return spec.rows.some(
    (row) =>
      row.journalUuid === ANIMAL_FAMILIAR_CAREER_JOURNAL_UUID ||
      isFamiliarCorrectionCareerUuid(row.journalUuid),
  );
}

function hasExternalCareerTable(column: string): boolean {
  return (game.tables?.contents ?? []).some(
    (table) =>
      !isGeneratedTable(table) &&
      table.getFlag("wfrp4e", "key") === "career" &&
      table.getFlag("wfrp4e", "column") === column,
  );
}

function isGeneratedTable(table: FoundryRollTableDocument): boolean {
  return isRecord(
    readUnknownPath(table.toObject(), ["flags", MODULE_ID, GENERATED_CAREER_TABLE_FLAG]),
  );
}

async function createCareerTable(
  source: Record<string, unknown>,
  folder: FoundryFolderDocument,
): Promise<void> {
  const table = await RollTable.create({ ...source, folder: folder.id });

  if (!table) {
    throw new Error("Foundry did not create a generated Species Builder career table.");
  }
}

async function updateCareerTable(
  table: FoundryRollTableDocument,
  source: Record<string, unknown>,
  force: boolean,
): Promise<void> {
  const generatedFlag = readUnknownPath(source, ["flags", MODULE_ID, GENERATED_CAREER_TABLE_FLAG]);

  await table.update({
    "displayRoll": source["displayRoll"],
    [`flags.${MODULE_ID}.${GENERATED_CAREER_TABLE_FLAG}`]: generatedFlag,
    "flags.wfrp4e.column": readUnknownPath(source, ["flags", "wfrp4e", "column"]),
    "flags.wfrp4e.key": readUnknownPath(source, ["flags", "wfrp4e", "key"]),
    "formula": source["formula"],
    "img": source["img"],
    "name": source["name"],
    "replacement": source["replacement"],
  });
  await reconcileCareerTableResults(table, source, force);
}

async function reconcileCareerTableResults(
  table: FoundryRollTableDocument,
  source: Record<string, unknown>,
  force: boolean,
): Promise<void> {
  const existingResults = readResults(table.toObject());
  const desiredResults = readResults(source);
  const updates: Record<string, unknown>[] = [];
  const creates: Record<string, unknown>[] = [];

  desiredResults.forEach((result, index) => {
    const existing = existingResults[index];
    const existingId = readStringPath(existing, ["_id"]);

    if (!existingId) {
      creates.push(result);
    } else if (
      force ||
      fingerprintSpeciesCareerTableResult(existing) !== fingerprintSpeciesCareerTableResult(result)
    ) {
      updates.push({ ...result, _id: existingId });
    }
  });

  const deletedIds = existingResults
    .slice(desiredResults.length)
    .map((result) => readStringPath(result, ["_id"]))
    .filter(Boolean);

  await applyRollTableResultChanges(table, { creates, deletedIds, updates });
}

function readResults(source: unknown): Record<string, unknown>[] {
  const results = readUnknownPath(source, ["results"]);

  return Array.isArray(results) ? results.filter(isRecord) : [];
}

async function ensureGeneratedTableFolder(): Promise<FoundryFolderDocument> {
  const existing = game.folders.contents.find(
    (folder) => folder.type === "RollTable" && folder.name === GENERATED_TABLE_FOLDER_NAME,
  );

  if (existing) {
    return existing;
  }

  const folder = await Folder.create({ name: GENERATED_TABLE_FOLDER_NAME, type: "RollTable" });

  if (!folder) {
    throw new Error("Foundry did not create the generated career table folder.");
  }

  return folder;
}

async function ensureCareerFallbackJournalUuid(): Promise<string> {
  const existing = game.journal?.contents.find((journal) => journal.name === FALLBACK_JOURNAL_NAME);

  if (existing) {
    return existing.uuid;
  }

  const journal = await JournalEntry.create({
    name: FALLBACK_JOURNAL_NAME,
    pages: [
      {
        name: "Why This Link Exists",
        text: {
          content:
            "<p>This Journal Entry exists as a fallback link target for generated WFRP career RollTables.</p><p>WFRP character generation ignores the linked document and reads only the visible career group name in the table result link. Species Builder rows can point at a more specific Journal Entry or Journal Entry Page when one exists.</p>",
          format: 1,
        },
        type: "text",
      },
    ],
  });

  if (!journal) {
    throw new Error("Foundry did not create the Species Builder career table fallback journal.");
  }

  return journal.uuid;
}

function emptySummary(): SpeciesCareerTableSyncSummary {
  return { checked: 0, elapsedMilliseconds: 0, regenerated: 0, removed: 0, skipped: 0 };
}

function logSyncSummary(summary: SpeciesCareerTableSyncSummary, force: boolean): void {
  const mode = force ? "Forced rebuild" : "Validation";
  logInfo(
    `${MODULE_ID} | ${mode} checked ${summary.checked} Species Builder career table(s): ` +
      `${summary.skipped} skipped, ${summary.regenerated} regenerated, ${summary.removed} removed ` +
      `in ${summary.elapsedMilliseconds.toFixed(1)} ms.`,
  );
}
