import type { SpeciesItemSheetBridge } from "../../../types/species-builder/species-item";

export function speciesNotesEditors() {
  const editors = new Map<string, foundry.applications.elements.HTMLProseMirrorElement>();
  const mount: SpeciesItemSheetBridge["mountNotes"] = (host, field, value, editable, changed) => {
    const editor = new foundry.applications.elements.HTMLProseMirrorElement({
      value,
      enriched: value,
      toggled: true,
    });
    editor.name = `system.${field}.value`;
    editor.disabled = !editable;
    const update = () => changed(editor.value);
    editor.addEventListener("input", update);
    editor.addEventListener("change", update);
    editors.set(field, editor);
    host.append(editor);
    return () => {
      editor.removeEventListener("input", update);
      editor.removeEventListener("change", update);
      editor.remove();
      if (editors.get(field) === editor) editors.delete(field);
    };
  };
  return {
    mount,
    edit(field: string) {
      editors.get(field)?.setAttribute("open", "");
    },
    flush() {
      // Foundry's toggled editor throws when save() is called before it has been opened.
      for (const editor of editors.values()) {
        if (editor.classList.contains("active")) editor.save();
      }
    },
  };
}
