<script setup lang="ts">
import type { NpcMagicGrant } from "../../../../../types/npc-builder";

import {
  getMagicGrantKindLabel,
  getMagicGrantSourceLabel,
} from "../../../../../functions/npc-builder/magic-lore-resolution";
import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  ambiguousGrantCount: number;
  isLoadingLoreOptions: boolean;
  magicGrants: NpcMagicGrant[];
}>();

const emit = defineEmits<{
  resolveLores: [];
}>();
</script>

<template>
  <NpcBuilderSection
    description="Magic Talents and Traits determine which spell Lores are available."
    number="1"
    title="Magic Access"
  >
    <p v-if="!magicGrants.length" class="dui-alert">
      No magic-enabling Talent or Trait is selected.
    </p>

    <ul v-else class="dui-list">
      <li
        v-for="grant in magicGrants"
        :key="`${grant.source}:${grant.sourceName}:${grant.rawLore}`"
        class="dui-list-row"
      >
        <div class="dui-list-col-grow">
          <strong>{{ getMagicGrantKindLabel(grant) }}</strong>
          <span>{{ getMagicGrantSourceLabel(grant) }} - {{ grant.sourceName }}</span>
          <small v-if="grant.isAmbiguous">
            Needs Lore resolution before automatic spells can be found.
          </small>
          <small v-else> Lore: {{ grant.rawLore || grant.normalizedLore }} </small>
        </div>
      </li>
    </ul>

    <div v-if="ambiguousGrantCount" class="dui-card-actions">
      <button
        class="dui-btn dui-btn-sm"
        :disabled="isLoadingLoreOptions"
        type="button"
        @click="emit('resolveLores')"
      >
        {{ isLoadingLoreOptions ? "Loading Lores..." : "Resolve Lores" }}
      </button>
    </div>
  </NpcBuilderSection>
</template>
