<script setup lang="ts">
import { computed, nextTick, ref, watch } from "vue";

import type {
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderRandomTalentSource,
} from "../../../../../../../types/species-builder/species-builder";
import type { SpeciesBuilderDetailPanelEmits } from "./detail-panel-events";
import type { SpeciesBuilderEditorTab } from "./editor-tabs";
import type { SpeciesBuilderArrayField } from "../../../../../../../functions/species-builder/editor/field-values";
import type { RandomTableTab } from "./tabs/tables/random-table-events";
import type { SpeciesBuilderValidationIssue } from "../../../../../../../types/species-builder/validation";
import type { SpeciesBuilderValidationNavigationRequest } from "../../../../components/validation/species-builder-validation-summary";

import {
  getSpeciesWoundFormulaTraitName,
  getSubspeciesWoundFormulaTraitName,
} from "../../../../../../../functions/species-builder/wound-formula-traits";
import ArrayFields from "./components/ArrayFields.vue";
import {
  talentGrantNames,
  talentGrantsForValues,
} from "../../../../../../../functions/species-builder/editor/linked-grants";
import SpeciesBuilderAttributesTab from "./tabs/attributes/SpeciesBuilderAttributesTab.vue";
import SpeciesBuilderDetailsTab from "./tabs/details/SpeciesBuilderDetailsTab.vue";
import SpeciesBuilderSubspeciesOverlay from "./tabs/subspecies/SpeciesBuilderSubspeciesOverlay.vue";
import { summarizeValidationIssues } from "../../../../components/validation/validation-presentation";
import { createSubspeciesOverlayEvents } from "./tabs/subspecies/subspecies-overlay-events";
import SubspeciesSection from "./tabs/subspecies/SubspeciesSection.vue";
import RandomTablesSection from "./tabs/tables/RandomTablesSection.vue";
import SpeciesBuilderWoundsTab from "./tabs/wounds/SpeciesBuilderWoundsTab.vue";

const props = defineProps<{
  activeEditorTab: SpeciesBuilderEditorTab;
  activeTableTab: RandomTableTab;
  definition: SpeciesBuilderEditingDefinition;
  isLoading: boolean;
  isSaving: boolean;
  issues: SpeciesBuilderValidationIssue[];
  randomTalentSources: SpeciesBuilderRandomTalentSource[];
  validationNavigationRequest?: SpeciesBuilderValidationNavigationRequest;
}>();

const emit = defineEmits<SpeciesBuilderDetailPanelEmits>();

const activeSubspeciesIndex = ref(-1);
const detailPanelElement = ref<HTMLElement | null>(null);
const activeSubspecies = computed(() => props.definition.subspecies?.[activeSubspeciesIndex.value]);
const isDefinitionReadOnly = computed(() => props.definition.origin === "runtime");
const areDefinitionControlsDisabled = computed(
  () => props.isLoading || props.isSaving || isDefinitionReadOnly.value,
);
const isActiveSubspeciesReadOnly = computed(
  () =>
    props.definition.origin === "runtime" &&
    activeSubspeciesIndex.value >= 0 &&
    activeSubspeciesIndex.value < props.definition.runtimeSubspeciesCount,
);
const parentTalentNames = computed(() =>
  talentGrantNames(talentGrantsForValues(props.definition.talents, props.definition.linkedTalents)),
);
const woundFormulaTraitName = computed(() => getSpeciesWoundFormulaTraitName(props.definition));
const activeSubspeciesWoundFormulaTraitName = computed(() => {
  const subspecies = activeSubspecies.value;

  return subspecies ? getSubspeciesWoundFormulaTraitName(props.definition, subspecies) : "";
});
const definitionIssues = computed(() =>
  props.issues.filter((issue) => issue.scope === "definition"),
);
const activeSubspeciesIssues = computed(() =>
  props.issues.filter(
    (issue) =>
      issue.scope === "subspecies" && issue.subspeciesIndex === activeSubspeciesIndex.value,
  ),
);
const subspeciesValidationIndicators = computed(() =>
  (props.definition.subspecies ?? []).map((_, index) =>
    summarizeValidationIssues(
      props.issues.filter(
        (issue) => issue.scope === "subspecies" && issue.subspeciesIndex === index,
      ),
    ),
  ),
);
const activeArrayFields = computed<SpeciesBuilderArrayField[]>(() =>
  props.activeEditorTab === "skills" ||
  props.activeEditorTab === "talents" ||
  props.activeEditorTab === "traits"
    ? [props.activeEditorTab]
    : [],
);

watch(
  () => props.definition.key,
  () => {
    activeSubspeciesIndex.value = -1;
  },
);

watch(
  () => props.definition.subspecies?.length ?? 0,
  (length) => {
    if (activeSubspeciesIndex.value >= length) {
      activeSubspeciesIndex.value = -1;
    }
  },
);

watch(
  () => props.validationNavigationRequest,
  async (request) => {
    if (request?.destination.kind === "subspecies") {
      await openSubspecies(request.destination.subspeciesIndex);
    }
  },
  { flush: "post" },
);

async function addSubspecies(): Promise<void> {
  const newIndex = props.definition.subspecies?.length ?? 0;

  emit("addSubspecies");
  await nextTick();
  await openSubspecies(newIndex);
}

async function openSubspecies(index: number): Promise<void> {
  activeSubspeciesIndex.value = index;
  await nextTick();
  scrollSubspeciesEditorIntoView();
}

function deleteSubspecies(index: number): void {
  emit("deleteSubspecies", index);
  activeSubspeciesIndex.value = -1;
}

const subspeciesOverlayEvents = createSubspeciesOverlayEvents(emit, {
  close: () => {
    activeSubspeciesIndex.value = -1;
  },
  deleteSubspecies,
});

function scrollSubspeciesEditorIntoView(): void {
  let current = detailPanelElement.value?.parentElement ?? null;

  while (current) {
    if (isScrollableElement(current)) {
      current.scrollTop = 0;
      return;
    }

    current = current.parentElement;
  }
}

function isScrollableElement(element: HTMLElement): boolean {
  const overflowY = window.getComputedStyle(element).overflowY;

  return (
    element.scrollHeight > element.clientHeight &&
    (overflowY === "auto" || overflowY === "scroll" || overflowY === "overlay")
  );
}
</script>

<template>
  <section ref="detailPanelElement">
    <SpeciesBuilderSubspeciesOverlay
      :index="activeSubspeciesIndex"
      :is-loading="isLoading"
      :is-open="activeSubspeciesIndex >= 0"
      :is-read-only="isActiveSubspeciesReadOnly"
      :is-saving="isSaving"
      :issues="activeSubspeciesIssues"
      :parent-talents="parentTalentNames"
      :parent-definition="definition"
      :random-talent-sources="randomTalentSources"
      :subspecies="activeSubspecies"
      :validation-navigation-request="validationNavigationRequest"
      :wound-formula-trait-name="activeSubspeciesWoundFormulaTraitName"
      v-on="subspeciesOverlayEvents"
    />

    <SpeciesBuilderDetailsTab
      v-if="activeEditorTab === 'details'"
      id="species-editor-panel-details"
      aria-label="Species details"
      :definition="definition"
      :is-disabled="areDefinitionControlsDisabled"
      :issues="definitionIssues"
      role="region"
      @review-issues="emit('reviewIssues')"
      @update-boolean-field="(field, value) => emit('updateBooleanField', field, value)"
      @update-height-field="(field, value) => emit('updateHeightField', field, value)"
      @update-string-field="(field, value) => emit('updateStringField', field, value)"
    />

    <SpeciesBuilderAttributesTab
      v-else-if="activeEditorTab === 'attributes'"
      id="species-editor-panel-attributes"
      aria-label="Species attributes"
      :definition="definition"
      :is-disabled="areDefinitionControlsDisabled"
      :issues="definitionIssues"
      role="region"
      @update-characteristic="(key, value) => emit('updateCharacteristic', key, value)"
      @update-number-field="(field, value) => emit('updateNumberField', field, value)"
    />

    <SpeciesBuilderWoundsTab
      v-else-if="activeEditorTab === 'wounds'"
      id="species-editor-panel-wounds"
      aria-label="Species wounds"
      :formula="definition.woundFormula?.formula"
      :generated-trait-name="woundFormulaTraitName"
      :is-disabled="areDefinitionControlsDisabled"
      :issues="definitionIssues"
      role="region"
      @update-wound-formula="(value) => emit('updateWoundFormula', value)"
    />

    <ArrayFields
      v-else-if="activeArrayFields.length > 0"
      :id="`species-editor-panel-${activeEditorTab}`"
      :aria-label="`Species ${activeEditorTab}`"
      :fields="activeArrayFields"
      :is-disabled="areDefinitionControlsDisabled"
      :issues="definitionIssues"
      role="region"
      :values="definition"
    />

    <RandomTablesSection
      v-else-if="activeEditorTab === 'tables'"
      id="species-editor-panel-tables"
      :active-tab="activeTableTab"
      aria-label="Species tables"
      help="Configure random Talent draws, Talent swap offers, and Career replacement choices without writing object-map syntax by hand."
      include-career-replacements
      :is-disabled="areDefinitionControlsDisabled"
      :issues="definitionIssues"
      :random-talent-sources="randomTalentSources"
      role="region"
      :show-navigation="false"
      :values="definition"
      @career-table-career-drop="(rowIndex, data) => emit('careerTableCareerDrop', rowIndex, data)"
      @career-table-journal-drop="
        (rowIndex, data) => emit('careerTableJournalDrop', rowIndex, data)
      "
      @career-replacement-choice-drop="
        (rowIndex, replacementIndex, data) =>
          emit('careerReplacementChoiceDrop', rowIndex, replacementIndex, data)
      "
      @career-replacement-rolled-drop="
        (rowIndex, data) => emit('careerReplacementRolledDrop', rowIndex, data)
      "
      @open-item="(uuid) => emit('openItem', uuid)"
      @talent-replacement-replacement-drop="
        (rowIndex, data) => emit('talentReplacementReplacementDrop', rowIndex, data)
      "
      @talent-replacement-rolled-drop="
        (rowIndex, data) => emit('talentReplacementRolledDrop', rowIndex, data)
      "
      @update="(field, value) => emit('updateTextMapField', field, value)"
      @update-career-table-rows="(rows) => emit('updateCareerTableRows', rows)"
      @update-career-replacement-rows="(rows) => emit('updateCareerReplacementRows', rows)"
      @update-talent-replacement-rows="(rows) => emit('updateTalentReplacementRows', rows)"
    />

    <SubspeciesSection
      v-else
      id="species-editor-panel-subspecies"
      aria-label="Subspecies"
      :definition="definition"
      :is-loading="isLoading"
      :is-saving="isSaving"
      :validation-indicators="subspeciesValidationIndicators"
      role="region"
      @add-subspecies="addSubspecies"
      @edit-subspecies="openSubspecies"
    />
  </section>
</template>
