import type { Component } from "vue";

import { buildWfrpGrantItemsEffect } from "../../../functions/item-grants/wfrp-grant-effect";
import type {
  GrantItemReference,
  GrantItemsEffectRecipe,
  GrantItemsLifetime,
  GrantItemsOwnerAction,
} from "../../../types/item-grants";
import GrantBuilderApp from "../../../view/apps/grant-builder/GrantBuilderApp.vue";
import { MODULE_ID } from "../../constants";
import { createGrantItemReference, resolveDroppedItem } from "../../wfrp4e/grant/item-documents";
import { FoundryVueApplication } from "../FoundryVueApplication";

const SELF_REMOVAL_LIFETIME: GrantItemsLifetime = "detached";

export class GrantBuilderApplication extends FoundryVueApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    classes: [MODULE_ID, "wfrp4e-customizer-grant-builder"],
    id: `${MODULE_ID}-grant-builder`,
    position: {
      height: 640,
      width: 620,
    },
    window: {
      icon: "fa-solid fa-sitemap",
      resizable: true,
      title: "Advanced Item Grant Builder",
    },
  };

  readonly carrierItem: FoundryItemDocument;
  #effectName = "Grant Items";
  #effectNameEdited = false;
  #items: GrantItemReference[] = [];
  #lifetime: GrantItemsLifetime = "linked-to-effect";
  #ownerAction: GrantItemsOwnerAction = "keep";

  constructor(carrierItem: FoundryItemDocument) {
    super();
    this.carrierItem = carrierItem;
  }

  protected override getVueComponent(): Component {
    return GrantBuilderApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return {
      carrierName: this.carrierItem.name,
      effectName: this.#effectName,
      items: this.#items,
      lifetime: this.#lifetime,
      ownerAction: this.#ownerAction,
      onCancel: () => this.close(),
      onCreate: () => this.createGrantEffect(),
      onDropData: (data: string) => this.handleDrop(data),
      onEffectNameInput: (value: string) => {
        this.#effectName = value;
        this.#effectNameEdited = true;
      },
      onLifetimeChange: (value: GrantItemsLifetime) => this.changeLifetime(value),
      onOwnerActionChange: (value: GrantItemsOwnerAction) => this.changeOwnerAction(value),
      onRemoveItem: (uuid: string) => this.removeItem(uuid),
    };
  }

  private changeLifetime(value: GrantItemsLifetime): void {
    this.#lifetime = value;

    if (value !== SELF_REMOVAL_LIFETIME) {
      this.#ownerAction = "keep";
    }

    void this.render();
  }

  private changeOwnerAction(value: GrantItemsOwnerAction): void {
    this.#ownerAction = value;
    void this.render();
  }

  private removeItem(uuid: string): void {
    this.#items = this.#items.filter((entry) => entry.uuid !== uuid);
    void this.render();
  }

  private async handleDrop(data: string): Promise<void> {
    try {
      const droppedItem = await resolveDroppedItem(data);

      if (droppedItem.uuid === this.carrierItem.uuid) {
        throw new Error("An Item cannot grant itself.");
      }

      if (this.#items.some((item) => item.uuid === droppedItem.uuid)) {
        ui.notifications?.warn?.(`"${droppedItem.name}" is already in this grant effect.`);
        return;
      }

      this.#items = [...this.#items, createGrantItemReference(droppedItem)];
      this.updateDefaultEffectName();
      void this.render();
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "The dropped Item could not be converted.";
      ui.notifications?.warn?.(message);
    }
  }

  private updateDefaultEffectName(): void {
    if (this.#effectNameEdited) {
      return;
    }

    const onlyItem = this.#items.length === 1 ? this.#items[0] : undefined;
    this.#effectName = onlyItem ? `Grant ${onlyItem.name}` : "Grant Item Package";
  }

  private async createGrantEffect(): Promise<void> {
    const effectName = this.#effectName.trim();

    if (!effectName) {
      ui.notifications?.warn?.("Enter an effect name before creating the grant effect.");
      return;
    }

    if (this.#items.length === 0) {
      ui.notifications?.warn?.("Add at least one Item before creating the grant effect.");
      return;
    }

    if (!this.carrierItem.createEmbeddedDocuments) {
      ui.notifications?.warn?.("This Item sheet does not support creating Active Effects.");
      return;
    }

    try {
      const recipe: GrantItemsEffectRecipe = {
        grantMode: "all",
        lifetime: this.#lifetime,
        ownerAction: this.#ownerAction,
      };
      const effectSource = buildWfrpGrantItemsEffect({
        effectName,
        flagScope: MODULE_ID,
        items: this.#items,
        recipe,
      });

      await this.carrierItem.createEmbeddedDocuments("ActiveEffect", [effectSource]);
      ui.notifications?.info(`Created "${effectName}" grant effect.`);
      await this.close();
    } catch (error) {
      const message = error instanceof Error ? error.message : "Could not create the grant effect.";
      ui.notifications?.warn?.(message);
    }
  }
}
