import type {
  SpeciesBuilderSettings,
  SpeciesBuilderSpeciesTableDraft,
} from "../../../types/species-builder/species-builder";
import type {
  SpeciesBuilderRuntimeSpeciesValidation,
  SpeciesBuilderValidationCatalog,
  SpeciesBuilderValidationIssue,
} from "../../../types/species-builder/validation";

import { createSpeciesConfigKey } from "../config-keys";
import { createIssue, normalizeLookupName, type ValidationIssueLocation } from "./shared";

export function validateSpeciesTableForCharacterCreation(
  settings: SpeciesBuilderSettings,
  draft: SpeciesBuilderSpeciesTableDraft | undefined,
  catalog: SpeciesBuilderValidationCatalog,
  definitionIssues: SpeciesBuilderValidationIssue[],
): SpeciesBuilderValidationIssue[] {
  if (!draft) {
    return [];
  }

  const issues: SpeciesBuilderValidationIssue[] = [];
  const requireRows = settings.autoRegisterSpeciesTable || draft.isRegistered;

  if (draft.rows.length === 0) {
    return requireRows
      ? [
          createIssue(
            tableLocation(),
            "species-table-empty",
            "Add at least one species while this table is registered for character creation.",
          ),
        ]
      : [];
  }

  const definitionsByKey = new Map(
    settings.definitions.map((definition, definitionIndex) => [
      createSpeciesConfigKey(definition.key),
      { definition, definitionIndex },
    ]),
  );
  const runtimeByKey = new Map(
    catalog.runtimeSpecies.map((species) => [species.key.trim(), species]),
  );
  const keyCounts = countNormalized(draft.rows.map((row) => row.speciesKey));
  const nameCounts = countNormalized(draft.rows.map((row) => row.name));

  draft.rows.forEach((row, rowIndex) => {
    const key = row.speciesKey.trim();
    const name = row.name.trim();
    const location = rowLocation(rowIndex);

    validateRowIdentity(key, name, keyCounts, nameCounts, location, issues);
    if (key) {
      const custom = definitionsByKey.get(key);

      if (custom) {
        validateCustomSpeciesRow(
          name,
          custom.definition.name.trim(),
          custom.definitionIndex,
          definitionIssues,
          location,
          issues,
        );
      } else {
        validateRuntimeSpeciesRow(name, runtimeByKey.get(key), key, location, issues);
      }
    }
    if (!Number.isInteger(row.weight) || row.weight < 1) {
      issues.push(
        createIssue(
          { ...location, field: "weight" },
          "species-table-weight-invalid",
          `Species Table row ${rowIndex + 1} needs a whole-number weight of at least 1.`,
        ),
      );
    }
  });

  return issues;
}

function validateRowIdentity(
  key: string,
  name: string,
  keyCounts: Map<string, number>,
  nameCounts: Map<string, number>,
  location: ValidationIssueLocation,
  issues: SpeciesBuilderValidationIssue[],
): void {
  if (!key) {
    issues.push(
      createIssue(
        { ...location, field: "speciesKey" },
        "species-table-species-required",
        `Species Table row ${(location.rowIndex ?? 0) + 1} must select a species.`,
      ),
    );
  } else if ((keyCounts.get(normalizeLookupName(key)) ?? 0) > 1) {
    issues.push(
      createIssue(
        { ...location, field: "speciesKey" },
        "species-table-species-duplicate",
        `Species key “${key}” appears more than once in the Species Table.`,
      ),
    );
  }

  const normalizedName = normalizeLookupName(name);

  if (normalizedName && (nameCounts.get(normalizedName) ?? 0) > 1) {
    issues.push(
      createIssue(
        { ...location, field: "speciesKey" },
        "species-table-name-duplicate",
        `Species name “${name}” appears more than once in the Species Table.`,
      ),
    );
  }
  if (/[{}]/u.test(name)) {
    issues.push(
      createIssue(
        { ...location, field: "speciesKey" },
        "species-table-name-unsafe",
        `Species name “${name}” cannot be encoded in WFRP's UUID-link label.`,
      ),
    );
  }
}

function validateCustomSpeciesRow(
  actualName: string,
  expectedName: string,
  definitionIndex: number,
  definitionIssues: SpeciesBuilderValidationIssue[],
  location: ValidationIssueLocation,
  issues: SpeciesBuilderValidationIssue[],
): void {
  validateTableName(actualName, expectedName, location, issues);

  if (
    definitionIssues.some(
      (issue) => issue.definitionIndex === definitionIndex && issue.severity === "error",
    )
  ) {
    issues.push(
      createIssue(
        { ...location, field: "speciesKey" },
        "species-table-definition-not-ready",
        `Custom species “${expectedName || "unnamed species"}” has character-creation errors.`,
      ),
    );
  }
}

function validateRuntimeSpeciesRow(
  actualName: string,
  runtime: SpeciesBuilderRuntimeSpeciesValidation | undefined,
  key: string,
  location: ValidationIssueLocation,
  issues: SpeciesBuilderValidationIssue[],
): void {
  if (!runtime) {
    issues.push(
      createIssue(
        { ...location, field: "speciesKey" },
        "species-table-species-missing",
        `Species key “${key}” is not registered in the current WFRP world.`,
      ),
    );
    return;
  }

  validateTableName(actualName, runtime.name, location, issues);
  if (!runtime.readyForCharacterCreation) {
    const suffix = runtime.reason ? `: ${runtime.reason}` : ".";
    issues.push(
      createIssue(
        { ...location, field: "speciesKey" },
        "species-table-runtime-not-ready",
        `Runtime species “${runtime.name}” is not ready for character creation${suffix}`,
      ),
    );
  }
}

function validateTableName(
  actualName: string,
  expectedName: string,
  location: ValidationIssueLocation,
  issues: SpeciesBuilderValidationIssue[],
): void {
  if (!actualName || actualName !== expectedName) {
    issues.push(
      createIssue(
        { ...location, field: "speciesKey" },
        "species-table-name-mismatch",
        `WFRP reads the UUID-link label as the species name; this row must use “${expectedName}”.`,
      ),
    );
  }
}

function tableLocation(): ValidationIssueLocation {
  return { scope: "species-table", section: "species-table" };
}

function rowLocation(rowIndex: number): ValidationIssueLocation {
  return { ...tableLocation(), rowIndex };
}

function countNormalized(values: string[]): Map<string, number> {
  const counts = new Map<string, number>();

  for (const value of values) {
    const normalized = normalizeLookupName(value);

    if (normalized) {
      counts.set(normalized, (counts.get(normalized) ?? 0) + 1);
    }
  }

  return counts;
}
