<script setup lang="ts">
import { computed, nextTick, ref, watch } from "vue";

import type { SpeciesBuilderDefinition } from "../../../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../../../../types/species-builder/validation";

import { useDialogFocusReturn } from "../dialog-focus";
import { buildSpeciesBuilderValidationSummaryItems } from "./species-builder-validation-summary";
import { validationIssueSeverity } from "./validation-presentation";

const props = defineProps<{
  definitions: SpeciesBuilderDefinition[];
  isOpen: boolean;
  issues: SpeciesBuilderValidationIssue[];
}>();

const emit = defineEmits<{
  close: [];
  selectIssue: [issue: SpeciesBuilderValidationIssue];
}>();

const dialog = ref<HTMLDialogElement>();
const dialogFocus = useDialogFocusReturn();
const pendingIssue = ref<SpeciesBuilderValidationIssue>();
const items = computed(() =>
  buildSpeciesBuilderValidationSummaryItems(props.issues, props.definitions),
);
const errorCount = computed(
  () => props.issues.filter((issue) => validationIssueSeverity(issue) === "error").length,
);
const warningCount = computed(() => props.issues.length - errorCount.value);

function closeDialog(): void {
  dialog.value?.close();
}

function selectIssue(issue: SpeciesBuilderValidationIssue): void {
  pendingIssue.value = issue;
  closeDialog();
}

function handleDialogClosed(): void {
  const issue = pendingIssue.value;

  pendingIssue.value = undefined;
  emit("close");
  dialogFocus.restore();

  if (issue) {
    emit("selectIssue", issue);
  }
}

watch(
  () => props.isOpen,
  async (isOpen) => {
    if (isOpen) {
      dialogFocus.capture();
      await nextTick();

      if (props.isOpen && !dialog.value?.open) {
        dialog.value?.showModal();
      }
    } else if (dialog.value?.open) {
      dialog.value.close();
    }
  },
  { flush: "post", immediate: true },
);
</script>

<template>
  <dialog
    ref="dialog"
    aria-describedby="species-builder-validation-description"
    aria-labelledby="species-builder-validation-title"
    class="dui-modal"
    @close="handleDialogClosed"
    @keydown.esc.stop.prevent="closeDialog"
    @keyup.esc.stop
  >
    <section class="dui-modal-box app:max-w-3xl">
      <header class="app:flex app:items-start app:justify-between app:gap-4">
        <div>
          <div class="app:flex app:flex-wrap app:gap-2">
            <span v-if="errorCount > 0" class="dui-badge dui-badge-error">
              {{ errorCount }} {{ errorCount === 1 ? "error" : "errors" }}
            </span>
            <span v-if="warningCount > 0" class="dui-badge dui-badge-warning">
              {{ warningCount }} {{ warningCount === 1 ? "warning" : "warnings" }}
            </span>
          </div>
          <h2 id="species-builder-validation-title">Character-Creation Validation</h2>
        </div>
        <button
          aria-label="Close validation summary"
          class="dui-btn dui-btn-ghost dui-btn-sm dui-btn-square"
          type="button"
          @click="closeDialog"
        >
          <i aria-hidden="true" class="fa-solid fa-xmark" />
        </button>
      </header>

      <p id="species-builder-validation-description">
        Errors mark reachable data that prevents character creation. Warnings mark playable
        incomplete data or inactive problems. Choose an item to open the most relevant editor
        section.
      </p>

      <ul class="dui-list app:max-h-96 app:overflow-y-auto">
        <li
          v-for="(item, index) in items"
          :key="`${item.issue.code}-${index}`"
          class="dui-list-row app:p-0"
        >
          <button
            :autofocus="index === 0"
            class="dui-btn dui-btn-outline app:h-auto app:w-full app:justify-start app:whitespace-normal app:p-3 app:text-left"
            :class="
              validationIssueSeverity(item.issue) === 'error' ? 'dui-btn-error' : 'dui-btn-warning'
            "
            type="button"
            @click="selectIssue(item.issue)"
          >
            <i
              v-if="validationIssueSeverity(item.issue) === 'error'"
              aria-hidden="true"
              class="fa-solid fa-circle-exclamation app:text-error"
            />
            <i
              v-else
              aria-hidden="true"
              class="fa-solid fa-triangle-exclamation app:text-warning"
            />
            <span class="app:flex app:min-w-0 app:flex-1 app:flex-col app:items-start">
              <strong>{{ item.context }}</strong>
              <span class="app:sr-only">
                {{ validationIssueSeverity(item.issue) === "error" ? "Error:" : "Warning:" }}
              </span>
              <span>{{ item.issue.message }}</span>
            </span>
            <i aria-hidden="true" class="fa-solid fa-chevron-right" />
          </button>
        </li>
      </ul>

      <div class="dui-modal-action">
        <button class="dui-btn dui-btn-ghost" type="button" @click="closeDialog">Close</button>
      </div>
    </section>
    <form class="dui-modal-backdrop" method="dialog">
      <button aria-label="Close validation summary" type="submit">Close</button>
    </form>
  </dialog>
</template>
