<script setup lang="ts">
import type { NpcCareerSummary } from "../../../../types/npc-builder";
import type { PendingLowerCareerPrompt } from "../../../../types/npc-builder";

defineProps<{
  candidateGroups: Array<{
    candidates: NpcCareerSummary[];
    level: number;
  }>;
  isCareerQueued: (uuid: string) => boolean;
  isLowerCareerSelected: (uuid: string) => boolean;
  prompt: PendingLowerCareerPrompt;
}>();

const emit = defineEmits<{
  addDroppedOnly: [];
  addSelected: [];
  lowerCareerSelected: [candidate: NpcCareerSummary, selected: boolean];
}>();

function emitSelection(candidate: NpcCareerSummary, event: Event): void {
  const input = event.currentTarget as HTMLInputElement;

  emit("lowerCareerSelected", candidate, input.checked);
}
</script>

<template>
  <section>
    <p>
      {{ prompt.droppedCareer.name }} appears to belong to the
      {{ prompt.droppedCareer.careerGroup }} career track. The following lower-tier candidates were
      found.
    </p>

    <fieldset v-for="group in candidateGroups" :key="group.level" class="dui-fieldset">
      <legend class="dui-fieldset-legend">Tier {{ group.level || "Unknown" }}</legend>

      <label v-for="candidate in group.candidates" :key="candidate.uuid" class="dui-label">
        <input
          class="dui-checkbox dui-checkbox-sm"
          :checked="isCareerQueued(candidate.uuid) || isLowerCareerSelected(candidate.uuid)"
          :disabled="isCareerQueued(candidate.uuid)"
          type="checkbox"
          @change="emitSelection(candidate, $event)"
        />
        <span>
          <strong>{{ candidate.name }}</strong>
          <small>
            {{ candidate.careerGroup || "Career" }}
            <template v-if="isCareerQueued(candidate.uuid)"> already queued </template>
          </small>
        </span>
      </label>
    </fieldset>

    <div class="dui-card-actions">
      <button class="dui-btn dui-btn-sm" type="button" @click="emit('addDroppedOnly')">
        Add Dropped Only
      </button>
      <button class="dui-btn dui-btn-sm" type="button" @click="emit('addSelected')">
        Add Selected
      </button>
    </div>
  </section>
</template>
