import type { SpeciesBuilderRandomTalentSource } from "../../../types/species-builder/species-builder";

export type RandomTalentEntry = readonly [key: string, count: number];

export function randomTalentEntries(
  values: Record<string, number> | undefined,
): RandomTalentEntry[] {
  return Object.entries(values ?? {});
}

export function appendRandomTalentEntry(
  entries: RandomTalentEntry[],
  sources: SpeciesBuilderRandomTalentSource[],
): string {
  const sourceKey = sources[0]?.key ?? "talents";

  return formatRandomTalentEntries([...entries, [sourceKey, 1]]);
}

export function setRandomTalentEntryKey(
  entries: RandomTalentEntry[],
  entryIndex: number,
  key: string,
): string {
  return formatRandomTalentEntries(
    entries.map(([entryKey, count], index) =>
      index === entryIndex ? [key, count] : [entryKey, count],
    ),
  );
}

export function setRandomTalentEntryCount(
  entries: RandomTalentEntry[],
  entryIndex: number,
  value: string,
): string {
  const count = Number(value);

  return formatRandomTalentEntries(
    entries.map(([key, currentCount], index) =>
      index === entryIndex && Number.isFinite(count) ? [key, count] : [key, currentCount],
    ),
  );
}

export function removeRandomTalentEntry(entries: RandomTalentEntry[], entryIndex: number): string {
  return formatRandomTalentEntries(entries.filter((_, index) => index !== entryIndex));
}

export function randomTalentSourceOptions(
  sources: SpeciesBuilderRandomTalentSource[],
  currentKey: string,
): SpeciesBuilderRandomTalentSource[] {
  if (sources.some((source) => source.key === currentKey)) {
    return sources;
  }

  return [
    ...sources,
    {
      key: currentKey,
      label: `Saved source missing from this world (${currentKey})`,
    },
  ];
}

export function formatRandomTalentEntries(entries: RandomTalentEntry[]): string {
  return entries
    .flatMap(([key, value]) => (key.trim() ? [`${key.trim()}: ${value}`] : []))
    .join("\n");
}
