import type {
  SpeciesBuilderCareerReplacementRow,
  SpeciesBuilderTalentReplacementRow,
} from "../../types/species-builder/species-builder";

import { formatLinkedItemName } from "./item-reference-names";

export function talentReplacementRecordFromRows(
  rows: SpeciesBuilderTalentReplacementRow[] | undefined,
): Record<string, string> | undefined {
  if (!rows) {
    return undefined;
  }

  const entries = rows.flatMap((row) => {
    const rolled = formatLinkedItemName(row.rolled);
    const replacement = formatLinkedItemName(row.replacement);

    return rolled && replacement ? [[rolled, replacement] as const] : [];
  });

  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

export function careerReplacementRecordFromRows(
  rows: SpeciesBuilderCareerReplacementRow[] | undefined,
): Record<string, string[]> | undefined {
  if (!rows) {
    return undefined;
  }

  const entries = rows.flatMap((row) => {
    const rolled = formatLinkedItemName(row.rolled);
    const replacements = row.replacements
      .map(formatLinkedItemName)
      .filter((replacement) => replacement.length > 0);

    return rolled && replacements.length > 0 ? [[rolled, replacements] as const] : [];
  });

  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}
