import { MODULE_ID } from "../constants";

interface FoundryObjectSettingDefinition<TSetting> {
  config?: boolean;
  defaultValue: TSetting;
  key: string;
  name: string;
  normalize: (value: unknown) => TSetting;
  scope?: "client" | "world";
}

export function defineFoundryObjectSetting<TSetting>(
  definition: FoundryObjectSettingDefinition<TSetting>,
): FoundryObjectSettingDefinition<TSetting> {
  return definition;
}

export function registerObjectSetting<TSetting>(
  definition: FoundryObjectSettingDefinition<TSetting>,
): void {
  game.settings.register(MODULE_ID, definition.key, {
    config: definition.config ?? false,
    default: definition.defaultValue,
    name: definition.name,
    scope: definition.scope ?? "world",
    type: Object,
  });
}

export function loadObjectSetting<TSetting>(
  definition: FoundryObjectSettingDefinition<TSetting>,
): TSetting {
  return definition.normalize(game.settings.get(MODULE_ID, definition.key));
}

export async function saveObjectSetting<TSetting>(
  definition: FoundryObjectSettingDefinition<TSetting>,
  value: TSetting,
): Promise<TSetting> {
  const normalized = definition.normalize(value);

  await game.settings.set(MODULE_ID, definition.key, normalized);

  return normalized;
}
