<script setup lang="ts">
withDefaults(
  defineProps<{
    headingLevel?: "h2" | "h4";
    actionLabel: string;
    actionTitle: string;
    count: number;
    description: string;
    isDisabled: boolean;
    title: string;
  }>(),
  { headingLevel: "h4" },
);

const emit = defineEmits<{
  add: [];
}>();
</script>

<template>
  <header>
    <component :is="headingLevel" class="dui-card-title">{{ title }}</component>
    <p>{{ description }}</p>
    <div class="dui-card-actions">
      <span class="dui-badge">{{ count }}</span>
      <button
        class="dui-btn dui-btn-sm"
        :disabled="isDisabled"
        :title="actionTitle"
        type="button"
        @click="emit('add')"
      >
        <i aria-hidden="true" class="fa-solid fa-plus" />
        {{ actionLabel }}
      </button>
    </div>
  </header>
</template>
