<script setup lang="ts">
import { computed } from "vue";

import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../../../../../../../types/species-builder/species-builder";
import type { SpeciesBuilderSubspeciesArrayField } from "../../../../../../../../../functions/species-builder/editor/field-values";
import type { SpeciesBuilderValidationIssue } from "../../../../../../../../../types/species-builder/validation";

import {
  previewSkillsForSubspecies,
  previewTraitsForSubspecies,
} from "../../../../../../../../../functions/species-builder/subspecies-list-fields";
import { getSpeciesWoundFormulaTraitName } from "../../../../../../../../../functions/species-builder/wound-formula-traits";
import {
  hasValidationErrors,
  issuesForFieldAtAnyRow,
  uniqueIssueMessages,
  validationClass,
} from "../../validation-presentation";

const changeFields: Array<{
  field: SpeciesBuilderSubspeciesArrayField;
  label: string;
}> = [
  { field: "skillsAdded", label: "Skills Added" },
  { field: "skillsRemoved", label: "Skills Removed" },
  { field: "traitsAdded", label: "Traits Added" },
  { field: "traitsRemoved", label: "Traits Removed" },
];

const props = defineProps<{
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  parentDefinition: SpeciesBuilderDefinition;
  subspecies: SpeciesBuilderSubspeciesDefinition;
  woundFormulaTraitName: string;
}>();

const emit = defineEmits<{
  updateArrayField: [field: SpeciesBuilderSubspeciesArrayField, value: string];
}>();

function inputValue(event: Event): string {
  return event.target instanceof HTMLTextAreaElement ? event.target.value : "";
}

function linesValue(values: string[] | undefined): string {
  return values?.join("\n") ?? "";
}

const compiledSkills = computed(() =>
  previewSkillsForSubspecies(props.parentDefinition, props.subspecies),
);
const compiledTraits = computed(() =>
  previewTraitsForSubspecies(props.parentDefinition, props.subspecies, {
    parent: props.parentDefinition.woundFormula
      ? getSpeciesWoundFormulaTraitName(props.parentDefinition)
      : undefined,
    subspecies: props.subspecies.woundFormula ? props.woundFormulaTraitName : undefined,
  }),
);
const issueMessages = computed(() => uniqueIssueMessages(props.issues));

function fieldIssues(field: SpeciesBuilderSubspeciesArrayField): SpeciesBuilderValidationIssue[] {
  return issuesForFieldAtAnyRow(props.issues, field);
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <h3 class="dui-card-title">Skill And Trait Changes</h3>
      <p>
        These changes are applied to the parent lists and exported as complete WFRP subspecies
        lists. Open only the list you need to edit.
      </p>

      <div
        v-if="issueMessages.length"
        class="dui-alert"
        :class="validationClass(issues, 'dui-alert-error', 'dui-alert-warning')"
        role="alert"
      >
        <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
        <div>
          <p v-for="message in issueMessages" :key="message" class="app:m-0 app:text-xs">
            {{ message }}
          </p>
        </div>
      </div>

      <details
        v-for="entry in changeFields"
        :key="entry.field"
        class="dui-collapse dui-collapse-arrow"
      >
        <summary class="dui-collapse-title">
          {{ entry.label }}
          <span class="dui-badge">{{ subspecies[entry.field]?.length ?? 0 }}</span>
        </summary>
        <div class="dui-collapse-content">
          <fieldset class="dui-fieldset">
            <legend class="dui-fieldset-legend">One name per line</legend>
            <textarea
              class="dui-textarea"
              :class="
                validationClass(
                  fieldIssues(entry.field),
                  'dui-textarea-error',
                  'dui-textarea-warning',
                )
              "
              :aria-invalid="hasValidationErrors(fieldIssues(entry.field)) || undefined"
              :disabled="isDisabled"
              :value="linesValue(subspecies[entry.field])"
              rows="5"
              @input="emit('updateArrayField', entry.field, inputValue($event))"
            />
          </fieldset>
        </div>
      </details>

      <div class="dui-divider">Compiled Preview</div>
      <div class="dui-alert dui-alert-info">
        <i aria-hidden="true" class="fa-solid fa-eye" />
        <span>Read-only previews show the final inherited lists WFRP will receive.</span>
      </div>

      <details class="dui-collapse dui-collapse-arrow">
        <summary class="dui-collapse-title">
          Compiled Skills
          <span class="dui-badge">{{ compiledSkills.length }}</span>
        </summary>
        <div class="dui-collapse-content">
          <ul v-if="compiledSkills.length > 0" class="dui-list">
            <li v-for="skill in compiledSkills" :key="skill" class="dui-list-row">
              <i aria-hidden="true" class="fa-solid fa-check" />
              <span>{{ skill }}</span>
            </li>
          </ul>
          <p v-else class="dui-alert">The compiled Skill list is empty.</p>
        </div>
      </details>

      <details class="dui-collapse dui-collapse-arrow">
        <summary class="dui-collapse-title">
          Compiled Traits
          <span class="dui-badge">{{ compiledTraits.length }}</span>
        </summary>
        <div class="dui-collapse-content">
          <ul v-if="compiledTraits.length > 0" class="dui-list">
            <li v-for="trait in compiledTraits" :key="trait" class="dui-list-row">
              <i aria-hidden="true" class="fa-solid fa-check" />
              <span>{{ trait }}</span>
            </li>
          </ul>
          <p v-else class="dui-alert">The compiled Trait list is empty.</p>
        </div>
      </details>
    </div>
  </section>
</template>
