<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from "vue";

import type { SpeciesBuilderBridge } from "../../../types/species-builder/species-builder";

import { WOUND_FORMULA_KEYWORDS } from "../../../functions/species-builder/wound-formula-keywords";
import {
  getSpeciesWoundFormulaTraitName,
  getSubspeciesWoundFormulaTraitName,
} from "../../../functions/species-builder/wound-formula-traits";
import { useSpeciesBuilderEditor } from "../../../state/species-builder/editor";
import UnsafeSaveConfirmationSubView from "../species-builder/components/UnsafeSaveConfirmationSubView.vue";
import { useSpeciesBuilderUnsafeSave } from "../species-builder/components/unsafe-save";
import SpeciesSuiteHeader from "./components/SpeciesSuiteHeader.vue";

const props = defineProps<{
  bridge: SpeciesBuilderBridge;
  definitionIndex: number;
  onOpenParent: () => void;
  onSettingsSaved?: () => void;
  subspeciesIndex?: number;
}>();
const editor = useSpeciesBuilderEditor(props.bridge, { onSettingsSaved: props.onSettingsSaved });
const unsafeSave = useSpeciesBuilderUnsafeSave(editor);
const textarea = ref<HTMLTextAreaElement>();
const definition = computed(() => editor.definitions.value[props.definitionIndex]);
const subspecies = computed(() => definition.value?.subspecies?.[props.subspeciesIndex ?? -1]);
const formula = computed(() =>
  props.subspeciesIndex === undefined
    ? (definition.value?.woundFormula?.formula ?? "")
    : (subspecies.value?.woundFormula?.formula ?? ""),
);
const issues = computed(() =>
  editor.validationIssues.value.filter(
    (issue) =>
      issue.definitionIndex === props.definitionIndex &&
      issue.field === "woundFormula" &&
      (props.subspeciesIndex === undefined
        ? issue.scope === "definition"
        : issue.scope === "subspecies" && issue.subspeciesIndex === props.subspeciesIndex),
  ),
);
const errorCount = computed(
  () => issues.value.filter((issue) => issue.severity === "error").length,
);
const warningCount = computed(() => issues.value.length - errorCount.value);
const isBusy = computed(() => editor.isLoading.value || editor.isSaving.value);
const isReadOnly = computed(() => {
  const parent = definition.value;
  if (!parent || parent.origin !== "runtime") return false;
  if (props.subspeciesIndex === undefined) return true;
  return props.subspeciesIndex < (parent.runtimeSubspeciesCount ?? 0);
});
const entityName = computed(
  () =>
    subspecies.value?.name.trim() ||
    definition.value?.name.trim() ||
    subspecies.value?.key.trim() ||
    definition.value?.key.trim() ||
    "Untitled Species",
);
const generatedTraitName = computed(() => {
  const parent = definition.value;
  if (!parent) return "";
  return subspecies.value
    ? getSubspeciesWoundFormulaTraitName(parent, subspecies.value)
    : getSpeciesWoundFormulaTraitName(parent);
});
const actorReferenceTokens = [
  "{Strength}",
  "[Strength]",
  "{Toughness}",
  "[Toughness]",
  "{Willpower}",
  "[Willpower]",
] as const;

onMounted(async () => {
  await editor.ensureSettingsLoaded();
  editor.selectDefinition(props.definitionIndex);
});

function updateFormula(value: string): void {
  if (props.subspeciesIndex === undefined) {
    editor.updateWoundFormula(value);
  } else {
    editor.updateSubspeciesWoundFormula(props.subspeciesIndex, value);
  }
}

async function insertToken(token: string): Promise<void> {
  if (isBusy.value || isReadOnly.value) return;

  const field = textarea.value;
  const start = field?.selectionStart ?? formula.value.length;
  const end = field?.selectionEnd ?? start;
  const prefix = formula.value.slice(0, start);
  const suffix = formula.value.slice(end);
  const spacerBefore = prefix && !prefix.endsWith(" ") ? " " : "";
  const spacerAfter = suffix && !suffix.startsWith(" ") ? " " : "";
  const insertion = `${spacerBefore}${token}${spacerAfter}`;

  updateFormula(`${prefix}${insertion}${suffix}`);
  await nextTick();
  field?.focus();
  field?.setSelectionRange(start + insertion.length, start + insertion.length);
}

function startTokenDrag(event: DragEvent, token: string): void {
  event.dataTransfer?.setData("text/plain", token);
  if (event.dataTransfer) event.dataTransfer.effectAllowed = "copy";
}

function dropToken(event: DragEvent): void {
  const token = event.dataTransfer?.getData("text/plain");
  if (token) void insertToken(token);
}

function textareaValue(event: Event): string {
  return event.target instanceof HTMLTextAreaElement ? event.target.value : "";
}
</script>

<template>
  <section class="app:flex app:min-h-full app:flex-col" :aria-busy="isBusy">
    <SpeciesSuiteHeader
      :can-save="editor.canSave.value"
      :context="`${entityName} / Wounds`"
      :error-count="errorCount"
      :has-unsaved-changes="editor.hasUnsavedChanges.value"
      :is-busy="isBusy"
      :parent-label="entityName"
      :show-issues="false"
      title="Wound Formula Builder"
      :warning-count="warningCount"
      @open-parent="onOpenParent"
      @reload="editor.loadSettings"
      @save="unsafeSave.requestSave"
    />

    <UnsafeSaveConfirmationSubView
      :is-open="unsafeSave.isConfirmationOpen.value"
      @close="unsafeSave.closeConfirmation"
      @confirm="unsafeSave.confirmSave"
    />

    <main class="app:grid app:flex-1 app:gap-3 app:p-3 app:md:grid-cols-[minmax(0,1fr)_16rem]">
      <section class="dui-card dui-card-border dui-card-sm app:min-w-0">
        <div class="dui-card-body">
          <h2 class="dui-card-title">Formula</h2>
          <p class="app:m-0">
            Click a token to insert it at the cursor, or drag it into the formula field.
          </p>
          <label class="dui-label" for="suite-wound-formula">Wound calculation</label>
          <textarea
            id="suite-wound-formula"
            ref="textarea"
            class="dui-textarea dui-textarea-sm app:min-h-40 app:w-full app:font-mono"
            :class="errorCount ? 'dui-textarea-error' : warningCount ? 'dui-textarea-warning' : ''"
            :disabled="isBusy || isReadOnly"
            :value="formula"
            @dragover.prevent
            @drop.prevent="dropToken"
            @input="updateFormula(textareaValue($event))"
          />
          <div
            v-if="issues.length"
            class="dui-alert"
            :class="errorCount ? 'dui-alert-error' : 'dui-alert-warning'"
            role="alert"
          >
            <i aria-hidden="true" class="fa-solid fa-triangle-exclamation" />
            <ul class="app:m-0 app:pl-4">
              <li v-for="(issue, index) in issues" :key="`${issue.code}-${index}`">
                {{ issue.message }}
              </li>
            </ul>
          </div>
          <p v-if="generatedTraitName" class="dui-alert dui-alert-info">
            <i aria-hidden="true" class="fa-solid fa-wand-magic-sparkles" />
            <span>Generated Trait: {{ generatedTraitName }}</span>
          </p>
        </div>
      </section>

      <aside class="app:flex app:flex-col app:gap-3" aria-label="Formula tokens">
        <fieldset
          class="dui-fieldset app:rounded-box app:border app:border-base-300 app:bg-base-200 app:p-3"
        >
          <legend class="dui-fieldset-legend">WFRP values</legend>
          <p class="dui-label">Bonuses, multipliers, Actor state, and scale.</p>
          <div class="app:flex app:flex-wrap app:gap-1">
            <button
              v-for="token in WOUND_FORMULA_KEYWORDS"
              :key="token"
              class="dui-btn dui-btn-outline dui-btn-xs app:font-mono"
              :disabled="isBusy || isReadOnly"
              draggable="true"
              type="button"
              @click="insertToken(token)"
              @dragstart="startTokenDrag($event, token)"
            >
              {{ token }}
            </button>
          </div>
        </fieldset>

        <fieldset
          class="dui-fieldset app:rounded-box app:border app:border-base-300 app:bg-base-200 app:p-3"
        >
          <legend class="dui-fieldset-legend">Actor references</legend>
          <p class="dui-label">
            <code>{Name}</code> inserts a total; <code>[Name]</code> inserts its bonus.
          </p>
          <div class="app:flex app:flex-wrap app:gap-1">
            <button
              v-for="token in actorReferenceTokens"
              :key="token"
              class="dui-btn dui-btn-outline dui-btn-xs app:font-mono"
              :disabled="isBusy || isReadOnly"
              draggable="true"
              type="button"
              @click="insertToken(token)"
              @dragstart="startTokenDrag($event, token)"
            >
              {{ token }}
            </button>
          </div>
        </fieldset>
      </aside>
    </main>
  </section>
</template>
