import type {
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderSettings,
  SpeciesBuilderSpeciesTableDraft,
} from "../../../types/species-builder/species-builder";
import type {
  SpeciesBuilderValidationCatalog,
  SpeciesBuilderValidationIssue,
} from "../../../types/species-builder/validation";

import { validateCareerTables } from "./career-tables";
import { validateDefinitionFields } from "./definitions";
import { validateDefinitionGrants } from "./grants";
import { validateDefinitionIdentities } from "./identity";
import {
  classifyDefinitionIssueSeverities,
  createRuntimeSpeciesReadinessIssues,
} from "./issue-severity";
import { validateRandomTalentTables } from "./random-talents";
import { validateReplacementTables } from "./replacements";
import { validateRuntimeExtensionEffectiveSetup } from "./runtime-extensions";
import { createIssue, createValidationCatalogIndex } from "./shared";
import { validateSpeciesTableForCharacterCreation } from "./species-table";

export {
  countValidationIssues,
  hasValidationIssue,
  issuesForDefinition,
  issuesForDefinitionNavigationSection,
  issuesForValidationLocation,
} from "./selectors";

export function validateSpeciesBuilder(
  settings: SpeciesBuilderSettings,
  catalog: SpeciesBuilderValidationCatalog,
  speciesTable?: SpeciesBuilderSpeciesTableDraft,
  editingDefinitions?: SpeciesBuilderEditingDefinition[],
): SpeciesBuilderValidationIssue[] {
  const catalogIndex = createValidationCatalogIndex(catalog);
  const definitions = editingDefinitions ?? settings.definitions;
  const allDefinitionIssues = [
    ...validateDefinitionIdentities(definitions, catalog),
    ...validateDefinitionFields(definitions),
    ...validateDefinitionGrants(definitions, catalogIndex),
    ...validateRandomTalentTables(definitions, catalogIndex),
    ...validateCareerTables(definitions, catalogIndex),
    ...validateReplacementTables(definitions, catalogIndex),
  ];
  const relevantDefinitionIssues = editingDefinitions
    ? filterEditingDefinitionIssues(allDefinitionIssues, editingDefinitions)
    : allDefinitionIssues;
  const unclassifiedDefinitionIssues = editingDefinitions
    ? [
        ...relevantDefinitionIssues,
        ...validateRuntimeExtensionEffectiveSetup(
          editingDefinitions,
          catalogIndex,
          relevantDefinitionIssues,
        ),
        ...createRuntimeSpeciesReadinessIssues(editingDefinitions, catalog),
      ]
    : relevantDefinitionIssues;
  const definitionIssues = classifyDefinitionIssueSeverities(
    unclassifiedDefinitionIssues,
    definitions,
    speciesTable,
  );

  return [
    ...definitionIssues,
    ...validateSpeciesTableForCharacterCreation(settings, speciesTable, catalog, definitionIssues),
  ];
}

function filterEditingDefinitionIssues(
  issues: SpeciesBuilderValidationIssue[],
  definitions: SpeciesBuilderEditingDefinition[],
): SpeciesBuilderValidationIssue[] {
  const unavailableParentIssues = definitions.flatMap((definition, definitionIndex) => {
    if (
      definition.origin !== "runtime" ||
      !definition.runtimeUnavailable ||
      (definition.subspecies?.length ?? 0) <= definition.runtimeSubspeciesCount
    ) {
      return [];
    }

    return [
      createIssue(
        { definitionIndex, scope: "definition", section: "subspecies" },
        "runtime-parent-unavailable",
        `Runtime species “${definition.name}” is unavailable. Its authored subspecies cannot be generated until the parent returns.`,
      ),
    ];
  });
  const relevantIssues = issues.filter((issue) => {
    if (issue.definitionIndex === undefined) {
      return true;
    }

    const definition = definitions[issue.definitionIndex];

    if (definition.origin === "custom") {
      return true;
    }

    return (
      issue.scope === "subspecies" &&
      issue.subspeciesIndex !== undefined &&
      issue.subspeciesIndex >= definition.runtimeSubspeciesCount
    );
  });

  return [...unavailableParentIssues, ...relevantIssues];
}
