import type { Component } from "vue";

import type { SubspeciesEditorTab } from "../../../view/apps/species-builder/tabs/species/pages/editor/tabs/subspecies/subspecies-editor-tabs";
import type { RandomTableTab } from "../../../view/apps/species-builder/tabs/species/pages/editor/tabs/tables/random-table-events";

import SubspeciesEditorApp from "../../../view/apps/species-builder-suite/SubspeciesEditorApp.vue";
import { MODULE_ID } from "../../constants";
import { SpeciesSuiteApplication } from "./SpeciesSuiteApplication";

interface SubspeciesEditorNavigation {
  openIssues: (definitionIndex: number) => void;
  openParent: (definitionIndex: number) => void;
  openWoundFormula: (definitionIndex: number, subspeciesIndex: number) => void;
}

export class SubspeciesEditorApplication extends SpeciesSuiteApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-subspecies-editor`,
    classes: [MODULE_ID, "wfrp4e-customizer-subspecies-editor"],
    position: { height: 700, width: 860 },
    window: {
      icon: "fa-solid fa-code-branch",
      resizable: true,
      title: "Edit WFRP4e Subspecies",
    },
  };

  #definitionIndex = 0;
  #initialTab: SubspeciesEditorTab = "details";
  #initialTableTab: RandomTableTab = "careerTable";
  #subspeciesIndex = 0;

  constructor(private readonly navigation: SubspeciesEditorNavigation) {
    super();
  }

  open(
    definitionIndex: number,
    subspeciesIndex: number,
    initialTab: SubspeciesEditorTab = "details",
    initialTableTab: RandomTableTab = "careerTable",
  ): Promise<this> {
    this.#definitionIndex = definitionIndex;
    this.#subspeciesIndex = subspeciesIndex;
    this.#initialTab = initialTab;
    this.#initialTableTab = initialTableTab;
    return this.render(true);
  }

  protected override getVueComponent(): Component {
    return SubspeciesEditorApp;
  }

  protected override getApplicationProps(): Record<string, unknown> {
    return {
      definitionIndex: this.#definitionIndex,
      initialTab: this.#initialTab,
      initialTableTab: this.#initialTableTab,
      onOpenIssues: () => this.navigation.openIssues(this.#definitionIndex),
      onOpenParent: () => this.navigation.openParent(this.#definitionIndex),
      onOpenWoundFormula: () =>
        this.navigation.openWoundFormula(this.#definitionIndex, this.#subspeciesIndex),
      subspeciesIndex: this.#subspeciesIndex,
    };
  }
}
