import type { PortraitCandidate, PortraitSourceGroup } from "../../types/portrait-gallery";

export function uniquePortraitCandidates(candidates: PortraitCandidate[]): PortraitCandidate[] {
  const seen = new Set<string>();
  const uniqueCandidates: PortraitCandidate[] = [];

  for (const candidate of candidates) {
    const normalizedPath = normalizeCandidatePath(candidate.img);

    if (!normalizedPath || seen.has(normalizedPath)) {
      continue;
    }

    seen.add(normalizedPath);
    uniqueCandidates.push(candidate);
  }

  return uniqueCandidates;
}

export function mergePortraitCandidateCollection(options: {
  assetCandidates: PortraitCandidate[];
  immediateCandidates: PortraitCandidate[];
  selectedPortraitPath: string;
}): PortraitCandidate[] {
  const candidates = uniquePortraitCandidates(
    sortPortraitCandidatesBySource([...options.assetCandidates, ...options.immediateCandidates]),
  );

  if (
    !options.selectedPortraitPath ||
    candidates.some(
      (candidate) =>
        normalizeCandidatePath(candidate.img) ===
        normalizeCandidatePath(options.selectedPortraitPath),
    )
  ) {
    return candidates;
  }

  return [
    {
      img: options.selectedPortraitPath,
      key: `selected:${options.selectedPortraitPath}`,
      label: "Selected portrait",
      source: "foundry-asset",
      sourceLabel: "Selected",
    },
    ...candidates,
  ];
}

function sortPortraitCandidatesBySource(candidates: PortraitCandidate[]): PortraitCandidate[] {
  return candidates
    .map((candidate, index) => ({ candidate, index }))
    .sort(
      (left, right) =>
        getPortraitCandidateSourcePriority(left.candidate) -
          getPortraitCandidateSourcePriority(right.candidate) || left.index - right.index,
    )
    .map(({ candidate }) => candidate);
}

function getPortraitCandidateSourcePriority(candidate: PortraitCandidate): number {
  if (candidate.sourceFilter?.value.startsWith("priority-folder:")) {
    return 0;
  }

  const priorities: Partial<Record<PortraitSourceGroup, number>> = {
    "career": 1,
    "compendiums": 2,
    "world": 3,
    "dig-down": 4,
  };

  return candidate.sourceGroup ? (priorities[candidate.sourceGroup] ?? 5) : 5;
}

function normalizeCandidatePath(path: string): string {
  return path.trim().toLocaleLowerCase();
}
