import type { Component } from "vue";

import SpeciesTableApp from "../../../view/apps/species-builder-suite/SpeciesTableApp.vue";
import { MODULE_ID } from "../../constants";
import { SpeciesSuiteApplication } from "./SpeciesSuiteApplication";

export class SpeciesTableApplication extends SpeciesSuiteApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-species-table-editor`,
    classes: [MODULE_ID, "wfrp4e-customizer-species-table-editor"],
    position: { height: 690, width: 840 },
    window: {
      icon: "fa-solid fa-dice-d20",
      resizable: true,
      title: "WFRP4e Species Table",
    },
  };

  constructor(
    private readonly openDirectory: () => void,
    private readonly openIssues: () => void,
  ) {
    super();
  }

  protected override getVueComponent(): Component {
    return SpeciesTableApp;
  }

  protected override getApplicationProps(): Record<string, unknown> {
    return { onOpenDirectory: this.openDirectory, onOpenIssues: this.openIssues };
  }
}
