<script setup lang="ts">
import { useSpeciesItemStore } from "../../../state/species-item";
import DocumentDrop from "../../components/DocumentDrop.vue";
const props = defineProps<{ uuid: string; editable: boolean }>();
const store = useSpeciesItemStore(props.uuid);
</script>

<template>
  <fieldset class="dui-fieldset" :disabled="!editable">
    <legend class="app:sr-only">Skills and Talents</legend>
    <DocumentDrop
      title="Skills"
      variant="bare"
      :show-prompt="false"
      manual-entry-trigger="none"
      :disabled="!editable"
      @drop-data="store.drop($event, 'skills')"
    >
      <span class="dui-label">Skills</span> — Drop Skills here
    </DocumentDrop>
    <div
      v-for="(_, index) in store.draft.system.skills.list"
      :key="index"
      class="app:flex app:gap-2"
    >
      <input
        v-model="store.draft.system.skills.list[index]"
        aria-label="Skill name"
        class="dui-input dui-input-sm"
        required
      />
      <button
        type="button"
        class="dui-btn dui-btn-sm"
        :aria-label="`Remove Skill ${index + 1}`"
        @click="store.draft.system.skills.list.splice(index, 1)"
      >
        Remove
      </button>
    </div>
    <button
      type="button"
      class="dui-btn dui-btn-sm app:justify-self-start"
      @click="store.draft.system.skills.list.push('New Skill')"
    >
      Add Skill
    </button>
    <div v-if="store.choiceWarning" class="dui-alert dui-alert-warning" role="status">
      {{ store.choiceWarning }} The stored choices are preserved.
    </div>
    <fieldset class="dui-fieldset" :disabled="!!store.choiceWarning">
      <legend class="dui-fieldset-legend">Talents</legend>
      <DocumentDrop
        title="Talents"
        variant="bare"
        :show-prompt="false"
        manual-entry-trigger="none"
        :disabled="!editable || !!store.choiceWarning"
        @drop-data="store.drop($event, 'talents')"
      >
        Drop Talents here, or add a Talent with alternatives below.
      </DocumentDrop>
      <fieldset v-for="(grant, group) in store.grants" :key="group" class="dui-fieldset">
        <legend class="dui-fieldset-legend">Talent {{ group + 1 }}</legend>
        <label v-for="(choice, option) in grant.choices" :key="option" class="dui-label">
          {{ option ? "Or" : "Talent" }}
          <input
            class="dui-input dui-input-sm"
            :value="choice.name"
            required
            @change="store.editTalent(group, option, ($event.target as HTMLInputElement).value)"
          />
        </label>
        <div class="app:flex app:gap-2">
          <button type="button" class="dui-btn dui-btn-sm" @click="store.addTalent(group)">
            Add alternative
          </button>
          <button type="button" class="dui-btn dui-btn-sm" @click="store.removeTalent(group)">
            Remove grant
          </button>
        </div>
      </fieldset>
      <button
        type="button"
        class="dui-btn dui-btn-sm app:justify-self-start"
        @click="store.addTalent()"
      >
        Add Talent
      </button>
    </fieldset>
    <label class="dui-label" :for="`${uuid}-random-talents`">Random Talents</label>
    <input
      :id="`${uuid}-random-talents`"
      aria-label="Random Talents"
      class="dui-input dui-input-sm"
      type="number"
      min="0"
      :value="store.draft.system.talents.random"
      placeholder="Inherit"
      @input="
        store.draft.system.talents.random =
          ($event.target as HTMLInputElement).value === ''
            ? null
            : Number(($event.target as HTMLInputElement).value)
      "
    />
  </fieldset>
</template>
