import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderSettings,
  SpeciesBuilderSpeciesOption,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../types/species-builder/species-builder";

import { createSpeciesConfigKey } from "../config-keys";
import {
  parseNumberRecordLines,
  parseStringArrayRecordLines,
  parseStringRecordLines,
  type SpeciesBuilderSubspeciesTextMapField,
  type SpeciesBuilderTextMapField,
} from "./field-values";

export function parseTextMapField(field: SpeciesBuilderTextMapField, value: string) {
  if (field === "careerReplacements") {
    return parseStringArrayRecordLines(value);
  }

  if (field === "randomTalents") {
    return parseNumberRecordLines(value);
  }

  return parseStringRecordLines(value);
}

export function parseSubspeciesTextMapField(
  field: SpeciesBuilderSubspeciesTextMapField,
  value: string,
) {
  if (field === "randomTalents") {
    return parseNumberRecordLines(value);
  }

  return parseStringRecordLines(value);
}

type SpeciesBuilderEditableDefinition =
  | SpeciesBuilderDefinition
  | SpeciesBuilderSubspeciesDefinition;

export function setOptionalField<
  TDefinition extends SpeciesBuilderEditableDefinition,
  TField extends keyof TDefinition,
>(definition: TDefinition, field: TField, value: TDefinition[TField] | undefined): TDefinition {
  const updated = { ...definition };

  if (value === undefined) {
    delete updated[field];
  } else {
    updated[field] = value;
  }

  return updated;
}

export function findDuplicateKeys(items: Array<{ key: string }>): string[] {
  const counts = new Map<string, number>();

  for (const item of items) {
    const key = item.key.trim();

    if (key) {
      counts.set(key, (counts.get(key) ?? 0) + 1);
    }
  }

  return [...counts.entries()].flatMap(([key, count]) => (count > 1 ? [key] : []));
}

export function findDuplicateSpeciesNames(
  definitions: SpeciesBuilderDefinition[],
  runtimeOptions: SpeciesBuilderSpeciesOption[],
): string[] {
  const definitionKeys = new Set(definitions.map((definition) => definition.key.trim()));
  const runtimeNames = new Set(
    runtimeOptions
      .filter((option) => !definitionKeys.has(option.key.trim()))
      .map((option) => normalizeSpeciesName(option.label))
      .filter(Boolean),
  );
  const counts = new Map<string, { count: number; label: string }>();

  for (const definition of definitions) {
    const label = definition.name.trim();
    const normalized = normalizeSpeciesName(label);

    if (!normalized) {
      continue;
    }

    const current = counts.get(normalized);
    counts.set(normalized, {
      count: (current?.count ?? 0) + 1,
      label: current?.label ?? label,
    });
  }

  return [...counts.entries()]
    .flatMap(([normalized, entry]) =>
      entry.count > 1 || runtimeNames.has(normalized) ? [entry.label] : [],
    )
    .sort((left, right) => left.localeCompare(right));
}

export function findInvalidSpeciesLinkNames(definitions: SpeciesBuilderDefinition[]): string[] {
  return definitions
    .map((definition) => definition.name.trim())
    .filter((name) => name && /[{}]/u.test(name));
}

function normalizeSpeciesName(value: string): string {
  return value.trim().toLocaleLowerCase();
}

export function createDefinitionsWithGeneratedKeys<TDefinition extends SpeciesBuilderDefinition>(
  definitions: TDefinition[],
): TDefinition[] {
  const usedSpeciesKeys = new Set<string>();

  return definitions.map((definition) => {
    const generatedDefinition = clonePlain(definition);

    if (isRuntimeEditingDefinition(definition)) {
      generatedDefinition.key = definition.key.trim();

      if (definition.subspecies) {
        generatedDefinition.subspecies = createSubspeciesWithGeneratedKeys(
          definition.subspecies,
          definition.runtimeSubspeciesCount,
        );
      }

      return generatedDefinition;
    }

    generatedDefinition.key = createEffectiveKey(
      definition.key,
      definition.name,
      "new-species",
      usedSpeciesKeys,
    );

    if (definition.subspecies) {
      generatedDefinition.subspecies = createSubspeciesWithGeneratedKeys(definition.subspecies);
    }

    return generatedDefinition;
  });
}

function createSubspeciesWithGeneratedKeys(
  subspecies: SpeciesBuilderSubspeciesDefinition[],
  preservedCount = 0,
): SpeciesBuilderSubspeciesDefinition[] {
  const usedSubspeciesKeys = new Set(
    subspecies
      .slice(0, preservedCount)
      .map(({ key }) => key.trim())
      .filter(Boolean),
  );

  return subspecies.map((entry, index) => ({
    ...clonePlain(entry),
    key:
      index < preservedCount
        ? entry.key.trim()
        : createEffectiveKey(entry.key, entry.name, "new-subspecies", usedSubspeciesKeys),
  }));
}

function isRuntimeEditingDefinition(
  definition: SpeciesBuilderDefinition,
): definition is SpeciesBuilderEditingDefinition {
  return "origin" in definition && definition.origin === "runtime";
}

function createEffectiveKey(
  rawKey: string,
  name: string,
  fallback: string,
  usedKeys: Set<string>,
): string {
  const explicitKey = createSpeciesConfigKey(rawKey);

  if (explicitKey) {
    usedKeys.add(explicitKey);
    return explicitKey;
  }

  const generatedKey = createSpeciesConfigKey(name) || fallback;
  const availableKey = nextAvailableKey(generatedKey, usedKeys);
  usedKeys.add(availableKey);

  return availableKey;
}

function nextAvailableKey(baseKey: string, usedKeys: Set<string>): string {
  if (!usedKeys.has(baseKey)) {
    return baseKey;
  }

  let index = 2;
  let candidate = `${baseKey}-${index}`;

  while (usedKeys.has(candidate)) {
    index += 1;
    candidate = `${baseKey}-${index}`;
  }

  return candidate;
}

export interface DuplicateSubspeciesKeys {
  keys: string[];
  speciesName: string;
}

export interface InvalidSubspeciesEntry {
  index: number;
  speciesName: string;
}

export function findDuplicateSubspeciesKeys(
  definitions: SpeciesBuilderDefinition[],
): DuplicateSubspeciesKeys[] {
  return definitions.flatMap((definition) => {
    const keys = findDuplicateKeys(definition.subspecies ?? []);

    return keys.length > 0 ? [{ keys, speciesName: definition.name }] : [];
  });
}

export function findInvalidSubspeciesEntries(
  definitions: SpeciesBuilderDefinition[],
): InvalidSubspeciesEntry[] {
  return definitions.flatMap((definition) =>
    (definition.subspecies ?? []).flatMap((subspecies, index) =>
      subspecies.key.trim() && subspecies.name.trim()
        ? []
        : [
            {
              index,
              speciesName: definition.name,
            },
          ],
    ),
  );
}

export function snapshotSettings(settings: SpeciesBuilderSettings): string {
  return JSON.stringify(sortSnapshotValue(settings));
}

function sortSnapshotValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(sortSnapshotValue);
  }

  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value)
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([key, entry]) => [key, sortSnapshotValue(entry)]),
    );
  }

  return value;
}

export function formatJson(value: unknown): string {
  return JSON.stringify(value, null, 2);
}

export function clonePlain<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

export function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "Unknown Species Builder error.";
}
