import type {
  PortraitCandidate,
  PortraitSearchProgressHandler,
} from "../../../types/portrait-gallery";
import type { PortraitSearchState } from "./types";

import {
  createPriorityPortraitFilterSource,
  doesPortraitTextMatch,
  normalizePortraitFolderPaths,
} from "../../../functions/portrait-gallery";
import { MODULE_ID } from "../../constants";
import { logWarning } from "../../logging";
import {
  addPortraitCandidate,
  doesCandidateMatchStateFilters,
  emitPortraitSearchProgress,
  getPortraitAssetLabel,
  getPortraitFileName,
  isPortraitAssetPath,
  portraitAssetExtensions,
} from "./candidate-utils";

interface QueuedPortraitDirectory {
  path: string;
  root: string;
}

export async function collectPriorityFolderPortraitCandidates(
  state: PortraitSearchState,
  folderPaths: string[],
  onProgress: PortraitSearchProgressHandler | undefined,
): Promise<void> {
  const queue = createInitialQueue(folderPaths);
  const scheduledPaths = new Set(queue.map(({ path }) => normalizePathKey(path)));

  state.maxDirectoryBudget += queue.length;

  while (queue.length) {
    const directory = queue.shift();

    if (!directory) {
      break;
    }

    emitFolderProgress(state, onProgress, directory.path);
    const contents = await browsePortraitFolder(directory.path);

    state.visitedDirectories += 1;

    if (!contents) {
      continue;
    }

    collectFolderFiles(state, directory.root, contents.files ?? []);

    for (const childPath of sortPaths(contents.dirs ?? [])) {
      const normalizedChildPath = normalizePortraitFolderPaths([childPath])[0];
      const childKey = normalizePathKey(normalizedChildPath ?? "");

      if (!normalizedChildPath || scheduledPaths.has(childKey)) {
        continue;
      }

      scheduledPaths.add(childKey);
      queue.push({ path: normalizedChildPath, root: directory.root });
      state.maxDirectoryBudget += 1;
    }

    emitFolderProgress(state, onProgress, directory.path);
  }
}

function createInitialQueue(folderPaths: string[]): QueuedPortraitDirectory[] {
  return normalizePortraitFolderPaths(folderPaths).map((path) => ({ path, root: path }));
}

async function browsePortraitFolder(path: string): Promise<FoundryFilePickerBrowseResult | null> {
  try {
    return await foundry.applications.apps.FilePicker.browse("data", path, {
      extensions: portraitAssetExtensions,
    });
  } catch (error) {
    logWarning(`${MODULE_ID} | Could not browse priority portrait folder "${path}".`, error);
    return null;
  }
}

function collectFolderFiles(state: PortraitSearchState, root: string, files: string[]): void {
  const sourceLabel = `Priority: ${getPortraitFileName(root)}`;

  for (const path of sortPaths(files)) {
    if (
      !isPortraitAssetPath(path) ||
      !doesPortraitTextMatch(getPortraitFileName(path), state.searchTerms)
    ) {
      continue;
    }

    const candidate: PortraitCandidate = {
      img: path,
      key: `foundry-asset:${path}`,
      label: getPortraitAssetLabel(path, sourceLabel),
      source: "foundry-asset",
      sourceFilter: createPriorityPortraitFilterSource(root),
      sourceGroup: "priority-folders",
      sourceLabel,
    };

    if (doesCandidateMatchStateFilters(candidate, state)) {
      addPortraitCandidate(state, candidate);
    }
  }
}

function emitFolderProgress(
  state: PortraitSearchState,
  onProgress: PortraitSearchProgressHandler | undefined,
  currentLocation: string,
): void {
  emitPortraitSearchProgress(onProgress, state, {
    currentLocation,
    maxDirectories: state.maxDirectoryBudget,
    phase: "filesystem",
  });
}

function normalizePathKey(path: string): string {
  return path.toLocaleLowerCase();
}

function sortPaths(paths: string[]): string[] {
  return [...paths].sort((left, right) =>
    left.toLocaleLowerCase().localeCompare(right.toLocaleLowerCase()),
  );
}
