import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

import { careers, species, subspecies } from "./shared";

const GOBLIN_CAREERS = careers(
  "Thief",
  "Outlaw",
  "Scout",
  "Hunter",
  "Rat Catcher",
  "Smuggler",
  "Beggar",
  "Entertainer",
  "Servant",
);

export function createGoblinFamilyDefinition(): SpeciesBuilderDefinition {
  return species("goblin", "Goblin", [15, 25, 20, 20, 10, 25, 20, 20, 10, 10], {
    age: "2d10+8",
    careerTable: GOBLIN_CAREERS,
    extra: 3,
    fate: 2,
    height: { die: "1d10", feet: 3, inches: 8 },
    includeInExtraSpecies: true,
    movement: 4,
    randomTalents: { "talents": 0, "talents-cowardly-goblins": 1 },
    resilience: 1,
    skills: [
      "Athletics",
      "Bribery",
      "Consume Alcohol",
      "Dodge",
      "Gamble",
      "Language (Goblin Tongue)",
      "Lore (Greenskins)",
      "Outdoor Survival",
      "Perception",
      "Ranged (Bow)",
      "Sleight of Hand",
      "Stealth (Rural)",
    ],
    subspecies: createGoblinSubspecies(),
    talents: ["Night Vision", "Snivel", "Step Aside, Beneath Notice, Flee!"],
    traits: ["Afraid (Elves)"],
  });
}

function createGoblinSubspecies() {
  return [
    subspecies("forest", "Forest Goblin", [15, 25, 20, 20, 15, 30, 20, 20, 15, 10], {
      careerTable: careers("Hunter", "Scout", "Trapper", "Outlaw", "Herbalist"),
      skillsAdded: ["Animal Care", "Charm Animal", "Lore (Poison)", "Set Trap", "Stealth (Rural)"],
      talentsAdded: ["Rover", "Strider (Woodlands)", "Resistance (Poison)"],
      traitsAdded: ["Arboreal", "Venom (Challenging)"],
    }),
    subspecies("night", "Night Goblin", [20, 25, 20, 25, 10, 25, 20, 20, 10, 10], {
      careerTable: careers("Miner", "Herbalist", "Scout", "Hunter", "Outlaw"),
      skillsAdded: ["Charm Animal", "Ranged (Entangling)", "Set Trap", "Stealth (Underground)"],
      skillsRemoved: ["Gamble", "Stealth (Rural)"],
      talentsAdded: ["Resistance (Poison)", "Orientation, Sixth Sense"],
      traitsAdded: ["Dark Vision", "Infected", "Sun-Sick"],
    }),
    subspecies("hobgoblin", "Hobgoblin", [20, 30, 25, 25, 30, 30, 25, 25, 20, 15], {
      careerTable: careers("Cavalryman", "Scout", "Spy", "Assassin", "Outlaw", "Duellist"),
      skillsAdded: [
        "Language (Dark Tongue)",
        "Lore (Steppes)",
        "Melee (Basic)",
        "Ride (Wolf)",
        "Stealth (Rural)",
      ],
      talentsAdded: ["Cat-tongued", "Rover", "Strike to Injure"],
      traitsAdded: ["Animosity (Greenskins)"],
    }),
    subspecies("gnoblar", "Gnoblar", [10, 25, 15, 15, 10, 25, 25, 20, 10, 10], {
      careerTable: careers("Servant", "Beggar", "Thief", "Rat Catcher", "Entertainer", "Pedlar"),
      randomTalents: { talents: 1 },
      skillsAdded: [
        "Charm",
        "Entertain (Sports)",
        "Language (Grumbarth)",
        "Lore (Ogres)",
        "Ranged (Throwing)",
        "Set Trap",
      ],
      talentsAdded: [
        "Small",
        "Beneath Notice, Step Aside, Flee!",
        "Acute Sense (Hearing)",
        "Acute Sense (Smell)",
        "Strong Back, Strong Legs, Sturdy",
      ],
    }),
    subspecies("fire-kobold", "Fire Kobold", [15, 30, 20, 25, 15, 30, 25, 20, 20, 10], {
      careerTable: careers("Hunter", "Scout", "Outlaw", "Miner", "Engineer"),
      skillsAdded: ["Endurance", "Lore (Volcanoes)", "Ranged (Throwing)", "Set Trap"],
      talentsAdded: ["Resistance (Fire)", "Very Resilient"],
      traitsAdded: ["Breath (Fire)", "Ward (8+)"],
    }),
    subspecies("troglagob", "Troglagob", [15, 25, 20, 20, 20, 30, 20, 20, 15, 10], {
      careerTable: careers("Boatman", "Riverwarden", "Hunter", "Scout", "Outlaw"),
      skillsAdded: ["Navigation", "Row", "Sail", "Swim", "Ranged (Throwing)"],
      skillsRemoved: ["Stealth (Rural)"],
      talentsAdded: ["Orientation", "Resistance (Poison)"],
      traitsAdded: ["Amphibious", "Cold Blooded", "Swamp-strider", "Venom (Challenging)"],
    }),
  ];
}

