<script setup lang="ts">
import { computed, ref } from "vue";

import type { SpeciesBuilderEditingDefinition } from "../../../../../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIndicator } from "../../../../components/validation/validation-presentation";

import SpeciesBuilderEntityRow from "../../components/SpeciesBuilderEntityRow.vue";
import { getSuggestedSpeciesKey } from "../../species-key-suggestions";

const props = defineProps<{
  definitions: SpeciesBuilderEditingDefinition[];
  isDisabled: boolean;
  selectedIndex: number;
  validationIndicators: Array<SpeciesBuilderValidationIndicator | undefined>;
}>();

const emit = defineEmits<{
  addSpecies: [];
  editSpecies: [index: number];
}>();

const filter = ref("");
const normalizedFilter = computed(() => filter.value.trim().toLocaleLowerCase());
const visibleDefinitions = computed(() =>
  props.definitions
    .map((definition, index) => ({ definition, index }))
    .filter(({ definition }) => matchesFilter(definition)),
);
const customDefinitions = computed(() =>
  visibleDefinitions.value.filter(({ definition }) => definition.origin === "custom"),
);
const runtimeDefinitions = computed(() =>
  visibleDefinitions.value.filter(
    ({ definition }) => definition.origin === "runtime" && !definition.runtimeUnavailable,
  ),
);
const unavailableDefinitions = computed(() =>
  visibleDefinitions.value.filter(({ definition }) => definition.runtimeUnavailable),
);
const installedCount = computed(
  () =>
    props.definitions.filter(
      (definition) => definition.origin === "runtime" && !definition.runtimeUnavailable,
    ).length,
);
const customCount = computed(
  () => props.definitions.filter((definition) => definition.origin === "custom").length,
);

function speciesLabel(definition: SpeciesBuilderEditingDefinition): string {
  return definition.name.trim() || definition.key.trim() || "Untitled Species";
}

function speciesKeyLabel(definition: SpeciesBuilderEditingDefinition): string {
  return definition.key.trim() || getSuggestedSpeciesKey(definition);
}

function matchesFilter(definition: SpeciesBuilderEditingDefinition): boolean {
  const query = normalizedFilter.value;

  return (
    !query ||
    definition.name.toLocaleLowerCase().includes(query) ||
    definition.key.toLocaleLowerCase().includes(query)
  );
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <header class="app:flex app:items-start app:justify-between app:gap-4">
        <div>
          <h2 id="species-builder-species-list-heading" class="dui-card-title" tabindex="-1">
            Species Catalog
          </h2>
          <p class="app:m-0">
            Manage your custom species or inspect species supplied by WFRP and active modules.
          </p>
        </div>
        <div class="dui-card-actions app:items-center">
          <button
            class="dui-btn dui-btn-primary"
            :disabled="isDisabled"
            type="button"
            @click="emit('addSpecies')"
          >
            <i aria-hidden="true" class="fa-solid fa-plus" />
            New Species
          </button>
        </div>
      </header>

      <label v-if="definitions.length > 0" class="dui-input app:w-full">
        <i aria-hidden="true" class="fa-solid fa-magnifying-glass" />
        <input v-model="filter" type="search" placeholder="Filter by species name or key" />
      </label>

      <div v-if="definitions.length === 0" role="status" class="dui-alert dui-alert-info">
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>No species yet. Add one to begin.</span>
      </div>

      <div v-else class="app:flex app:flex-col app:gap-4">
        <section aria-labelledby="species-builder-custom-species-heading">
          <header class="app:flex app:items-center app:justify-between app:gap-2">
            <div>
              <h3 id="species-builder-custom-species-heading" class="dui-card-title">
                Custom Species
              </h3>
              <p class="app:m-0">Species owned and editable by this world.</p>
            </div>
            <span class="dui-badge dui-badge-sm">{{ customCount }}</span>
          </header>
          <div v-if="customDefinitions.length === 0" role="status" class="dui-alert">
            <i aria-hidden="true" class="fa-solid fa-circle-info" />
            <span>{{
              normalizedFilter ? "No custom species match this filter." : "No custom species yet."
            }}</span>
          </div>
          <ul v-else class="dui-list">
            <SpeciesBuilderEntityRow
              v-for="entry in customDefinitions"
              :key="`custom-${entry.definition.key}-${entry.index}`"
              action-label="Edit species"
              edit-icon-class="fa-solid fa-pen-to-square"
              :entry-key="speciesKeyLabel(entry.definition)"
              icon-class="fa-solid fa-users"
              :is-disabled="isDisabled"
              :is-selected="entry.index === selectedIndex"
              :title="speciesLabel(entry.definition)"
              :validation-indicator="validationIndicators[entry.index]"
              @open="emit('editSpecies', entry.index)"
            />
          </ul>
        </section>

        <section aria-labelledby="species-builder-installed-species-heading">
          <header class="app:flex app:items-center app:justify-between app:gap-2">
            <div>
              <h3 id="species-builder-installed-species-heading" class="dui-card-title">
                Installed Species
              </h3>
              <p class="app:m-0">
                Read-only reference data. You can add custom subspecies to these entries.
              </p>
            </div>
            <span class="dui-badge dui-badge-ghost dui-badge-sm">{{ installedCount }}</span>
          </header>
          <div v-if="runtimeDefinitions.length === 0" role="status" class="dui-alert">
            <i aria-hidden="true" class="fa-solid fa-circle-info" />
            <span>{{
              normalizedFilter
                ? "No installed species match this filter."
                : "No installed species were found."
            }}</span>
          </div>
          <ul v-else class="dui-list">
            <SpeciesBuilderEntityRow
              v-for="entry in runtimeDefinitions"
              :key="`runtime-${entry.definition.key}-${entry.index}`"
              action-label="View setup"
              edit-icon-class="fa-solid fa-eye"
              :entry-key="speciesKeyLabel(entry.definition)"
              icon-class="fa-solid fa-book-open"
              :is-disabled="isDisabled"
              is-read-only
              :is-selected="entry.index === selectedIndex"
              :title="speciesLabel(entry.definition)"
              :validation-indicator="validationIndicators[entry.index]"
              @open="emit('editSpecies', entry.index)"
            />
          </ul>
        </section>

        <section
          v-if="unavailableDefinitions.length > 0"
          aria-labelledby="species-builder-unavailable-species-heading"
        >
          <header class="app:flex app:items-center app:justify-between app:gap-2">
            <div>
              <h3 id="species-builder-unavailable-species-heading" class="dui-card-title">
                Unavailable Sources
              </h3>
              <p class="app:m-0">
                The source package is inactive; custom variants are retained for recovery.
              </p>
            </div>
            <span class="dui-badge dui-badge-warning dui-badge-sm">
              {{ unavailableDefinitions.length }}
            </span>
          </header>
          <ul class="dui-list">
            <SpeciesBuilderEntityRow
              v-for="entry in unavailableDefinitions"
              :key="`unavailable-${entry.definition.key}-${entry.index}`"
              action-label="Review variants"
              edit-icon-class="fa-solid fa-eye"
              :entry-key="speciesKeyLabel(entry.definition)"
              icon-class="fa-solid fa-triangle-exclamation"
              :is-disabled="isDisabled"
              is-read-only
              :is-selected="entry.index === selectedIndex"
              meta="Custom variants retained"
              read-only-label="Source unavailable"
              :title="speciesLabel(entry.definition)"
              :validation-indicator="validationIndicators[entry.index]"
              @open="emit('editSpecies', entry.index)"
            />
          </ul>
        </section>
      </div>
    </div>
  </section>
</template>
