import type { NpcXpEstimateResult } from "../../../../types/npc-builder";

import { calculateNpcXpFromBaseDelta } from "../../../../functions/npc-builder/xp-cost";
import { assertFoundryActor } from "../../../foundry/document-guards";
import { loadNpcBuilderSettings } from "../settings";
import { getActorSpecies } from "../foundry-bridge/actors";
import { createNpcXpActorProfile } from "./actor-profile";
import { findSpeciesActor } from "./species-actor";

export async function estimateNpcXp(actorUuid: string): Promise<NpcXpEstimateResult> {
  const actor = assertFoundryActor(await fromUuid(actorUuid), "Expected an NPC Actor.");

  if (actor.type !== "npc") {
    throw new Error(`Expected an NPC Actor, but received Actor type “${actor.type}”.`);
  }

  return await estimateNpcXpForActor(actor);
}

export async function estimateNpcXpForActor(
  actor: FoundryActorDocument,
): Promise<NpcXpEstimateResult> {
  const species = getActorSpecies(actor);

  if (!species) {
    return { status: "missing-species" };
  }

  const settings = loadNpcBuilderSettings();
  const baseline = await findSpeciesActor(species, actor, settings.baseActorFolderUuid);

  if (!baseline) {
    return { species, status: "baseline-not-found" };
  }

  return {
    baselineName: baseline.actor.name,
    baselineSource: baseline.source,
    baselineUuid: baseline.actor.uuid,
    breakdown: calculateNpcXpFromBaseDelta(
      createNpcXpActorProfile(actor),
      createNpcXpActorProfile(baseline.actor),
    ),
    species,
    status: "ready",
  };
}
