import type { Component } from "vue";

import type { SpeciesBuilderEditorTab } from "../../../view/apps/species-builder/tabs/species/pages/editor/editor-tabs";
import type { RandomTableTab } from "../../../view/apps/species-builder/tabs/species/pages/editor/tabs/tables/random-table-events";

import SpeciesEditorApp from "../../../view/apps/species-builder-suite/SpeciesEditorApp.vue";
import { MODULE_ID } from "../../constants";
import { SpeciesSuiteApplication } from "./SpeciesSuiteApplication";

interface SpeciesEditorNavigation {
  openDirectory: () => void;
  openIssues: (definitionIndex: number) => void;
  openSubspecies: (definitionIndex: number, subspeciesIndex: number) => void;
  openWoundFormula: (definitionIndex: number) => void;
}

export class SpeciesEditorApplication extends SpeciesSuiteApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-species-editor`,
    classes: [MODULE_ID, "wfrp4e-customizer-species-editor"],
    position: { height: 760, width: 920 },
    window: {
      icon: "fa-solid fa-pen-to-square",
      resizable: true,
      title: "Edit WFRP4e Species",
    },
  };

  #definitionIndex = 0;
  #initialTab: SpeciesBuilderEditorTab = "details";
  #initialTableTab: RandomTableTab = "careerTable";

  constructor(private readonly navigation: SpeciesEditorNavigation) {
    super();
  }

  open(
    definitionIndex: number,
    initialTab: SpeciesBuilderEditorTab = "details",
    initialTableTab: RandomTableTab = "careerTable",
  ): Promise<this> {
    this.#definitionIndex = definitionIndex;
    this.#initialTab = initialTab;
    this.#initialTableTab = initialTableTab;
    return this.render(true);
  }

  protected override getVueComponent(): Component {
    return SpeciesEditorApp;
  }

  protected override getApplicationProps(): Record<string, unknown> {
    return {
      definitionIndex: this.#definitionIndex,
      initialTab: this.#initialTab,
      initialTableTab: this.#initialTableTab,
      onOpenDirectory: this.navigation.openDirectory,
      onOpenIssues: () => this.navigation.openIssues(this.#definitionIndex),
      onOpenSubspecies: (subspeciesIndex: number) =>
        this.navigation.openSubspecies(this.#definitionIndex, subspeciesIndex),
      onOpenWoundFormula: () => this.navigation.openWoundFormula(this.#definitionIndex),
    };
  }
}
