import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

import { careers, species, subspecies } from "./shared";

export function createMedusaDefinition(): SpeciesBuilderDefinition {
  return species("medusa", "Medusa", [25, 35, 25, 35, 35, 15, 25, 35, 35, 10], {
    age: "8d10+20",
    careerTable: careers("Hunter", "Mystic", "Outlaw", "Spy", "Warrior", "Wizard"),
    extra: 1,
    fate: 1,
    height: { die: "1d10", feet: 5, inches: 2 },
    includeInExtraSpecies: true,
    movement: 4,
    resilience: 2,
    skills: [
      "Cool",
      "Dodge",
      "Intimidate",
      "Intuition",
      "Lore (Monsters)",
      "Melee (Basic)",
      "Perception",
      "Ranged (Sling)",
      "Stealth (Any)",
    ],
    subspecies: [
      subspecies("armoured-medusa", "Armoured Medusa", undefined, {
        skillsAdded: ["Endurance"],
        talentsAdded: ["Hardy", "Very Resilient"],
        traitsAdded: ["Armour (2)"],
      }),
      subspecies("serpentine-medusa", "Serpentine Medusa", undefined, {
        movement: 3,
        skillsAdded: ["Athletics", "Swim"],
        talentsAdded: ["Resistance (Poison)"],
        traitsAdded: ["Snake Body", "Tail Attack (5)"],
      }),
    ],
    talents: ["Menacing", "Night Vision", "Resistance (Poison)", "Strong-minded"],
    traits: ["Fear (1)", "Petrifying Gaze", "Snake Hair (4)", "Venom"],
  });
}

