import type { RuntimeTableReadiness } from "./table-results";

import { isRecord } from "../../../../shared/object-readers";
import { validateCareerTable } from "./table-results";

export interface RuntimeCareerTableCompendiumSource {
  name: string;
  packTitle: string;
}

export function validateRuntimeCareerTable(
  speciesKey: string,
  subspeciesKey: string | undefined,
  configuredColumn: unknown,
  careerGroupNames: ReadonlySet<string>,
  compendiumSources: ReadonlyMap<string, RuntimeCareerTableCompendiumSource> = new Map(),
): RuntimeTableReadiness {
  const configured = typeof configuredColumn === "string" ? configuredColumn.trim() : "";
  const candidates = careerColumnCandidates(speciesKey, subspeciesKey, configured);

  for (const column of candidates) {
    const source = findCareerTable(column);

    if (!source) {
      continue;
    }

    // A table-family wrapper is only a match when it actually contains the requested column.
    const table = resolveCareerTableColumn(source, column);

    if (table) {
      return describeCareerTableReadiness(column, table, careerGroupNames);
    }
  }

  for (const column of candidates) {
    const compendiumSource = compendiumSources.get(column);

    if (compendiumSource) {
      return {
        readyForCharacterCreation: false,
        reason: `career table column ${column} is not active in this world; import “${compendiumSource.name}” from “${compendiumSource.packTitle}”`,
        requiresWorldTableImport: true,
      };
    }
  }

  const fallbackColumn = candidates.at(-1) ?? speciesKey;
  return describeCareerTableReadiness(fallbackColumn, undefined, careerGroupNames);
}

function careerColumnCandidates(
  speciesKey: string,
  subspeciesKey: string | undefined,
  configuredColumn: string,
): string[] {
  const candidates = subspeciesKey
    ? [configuredColumn, `${speciesKey}-${subspeciesKey}`, speciesKey]
    : [speciesKey];

  if (speciesKey === "human") {
    candidates.push("human-reiklander");
  }

  return [...new Set(candidates.filter(Boolean))];
}

function describeCareerTableReadiness(
  column: string,
  table: unknown,
  careerGroupNames: ReadonlySet<string>,
): RuntimeTableReadiness {
  const readiness = validateCareerTable(table, careerGroupNames);

  return readiness.readyForCharacterCreation
    ? readiness
    : {
        readyForCharacterCreation: false,
        reason: `career table column ${column} is not ready: ${readiness.reason ?? "invalid table"}`,
      };
}

function findCareerTable(column: string): unknown {
  return game.wfrp4e?.tables?.findTable?.("career", column);
}

function resolveCareerTableColumn(source: unknown, column: string): unknown {
  if (!isRecord(source) || !Array.isArray(source["columns"])) {
    return source;
  }

  return source["columns"].find((candidate) => readCareerTableColumn(candidate) === column);
}

function readCareerTableColumn(source: unknown): string {
  if (!isRecord(source) || typeof source["getFlag"] !== "function") {
    return "";
  }

  const value = source["getFlag"].call(source, "wfrp4e", "column");

  return typeof value === "string" ? value : "";
}
