import type {
  SpeciesBuilderValidationCatalog,
  SpeciesBuilderValidationIssue,
} from "../../../types/species-builder/validation";

export interface ValidationCatalogIndex {
  careerGroups: Set<string>;
  randomTalentSources: Map<string, SpeciesBuilderValidationCatalog["randomTalentSources"][number]>;
  skills: Set<string>;
  talents: Set<string>;
  traits: Set<string>;
}

export type ValidationIssueLocation = Omit<
  SpeciesBuilderValidationIssue,
  "code" | "message" | "severity"
>;

export function createValidationCatalogIndex(
  catalog: SpeciesBuilderValidationCatalog,
): ValidationCatalogIndex {
  return {
    careerGroups: exactSet(catalog.careerGroupNames),
    randomTalentSources: new Map(
      catalog.randomTalentSources.map((source) => [source.key.trim(), source]),
    ),
    skills: exactSet(catalog.itemBaseNames.skill),
    talents: exactSet(catalog.itemBaseNames.talent),
    traits: exactSet(catalog.itemBaseNames.trait),
  };
}

export function createIssue(
  location: ValidationIssueLocation,
  code: string,
  message: string,
): SpeciesBuilderValidationIssue {
  return { ...location, code, message, severity: "error" };
}

export function normalizeLookupName(value: string): string {
  return value.trim().toLocaleLowerCase();
}

export function itemBaseName(value: string): string {
  return (value.split("(")[0] ?? "").trim();
}

export function isKnownItem(value: string, knownBaseNames: Set<string>): boolean {
  return knownBaseNames.has(itemBaseName(value));
}

export function isSensibleDiceFormula(value: string, requireDice: boolean): boolean {
  const formula = value.trim();

  if (!formula || !/^\d+(?:d\d+)?(?:\s*[+-]\s*\d+(?:d\d+)?)*$/iu.test(formula)) {
    return false;
  }

  const dice = [...formula.matchAll(/(\d+)d(\d+)/giu)];

  if (requireDice && dice.length === 0) {
    return false;
  }

  return dice.every((match) => Number(match[1]) > 0 && Number(match[2]) > 0);
}

export function isCharacteristicFormula(value: string): boolean {
  const match = /^(?:(\d+)|(\d*)d(\d+))(?:\s*\+\s*(-?\d+))?$/iu.exec(value.trim());

  if (!match) {
    return false;
  }

  if (match[1]) {
    return Number.isSafeInteger(Number(match[1]));
  }

  const diceCount = match[2] ? Number(match[2]) : 1;

  return diceCount > 0 && Number(match[3]) > 0;
}

export function isNonNegativeInteger(value: number | undefined): value is number {
  return Number.isInteger(value) && (value ?? -1) >= 0;
}

function exactSet(values: string[]): Set<string> {
  return new Set(values.map((value) => value.trim()).filter(Boolean));
}
