import type { SpeciesBuilderDefinition } from "../../../../../types/species-builder/species-builder";

import { careers, species } from "../shared";

export function createAlbionGiantDefinition(): SpeciesBuilderDefinition {
  return species("albion-giant", "Albion Giant", [25, 20, 40, 40, 25, 15, 10, 25, 30, 15], {
    age: "10d10+40",
    careerTable: careers("Druid", "Hunter", "Labourer", "Mystic", "Warrior"),
    extra: 1,
    fate: 1,
    height: { die: "2d10", feet: 12, inches: 0 },
    includeInExtraSpecies: true,
    movement: 6,
    resilience: 3,
    skills: [
      "Athletics",
      "Endurance",
      "Intimidate",
      "Language (Albion)",
      "Lore (Albion)",
      "Melee (Two-Handed)",
      "Outdoor Survival",
      "Perception",
    ],
    talents: ["Hardy", "Second Sight", "Strong Back", "Very Strong"],
    traits: ["Armour (1)", "Magic Resistance (1)", "Size (Enormous)", "Stride"],
    woundFormula: { formula: "@sb * 4 + @tb * 8 + @wpb * 2" },
  });
}

