import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderSpeciesTableDraft,
} from "../../../types/species-builder/species-builder";
import type {
  SpeciesBuilderValidationCatalog,
  SpeciesBuilderValidationIssue,
} from "../../../types/species-builder/validation";

import { createIssue } from "./shared";

const PLAYABLE_INCOMPLETE_ISSUE_CODES = new Set([
  "age-formula-invalid",
  "age-required",
  "career-replacement-blank",
  "career-replacement-duplicate",
  "career-replacement-unresolved",
  "grant-blank",
  "grant-unresolved",
  "height-die-invalid",
  "height-feet-invalid",
  "height-inches-invalid",
  "height-required",
  "talent-replacement-blank",
  "talent-replacement-duplicate",
  "talent-replacement-unresolved",
]);
const ALWAYS_ERROR_ISSUE_CODES = new Set(["runtime-species-import-required"]);

export function createRuntimeSpeciesReadinessIssues(
  definitions: SpeciesBuilderEditingDefinition[],
  catalog: SpeciesBuilderValidationCatalog,
): SpeciesBuilderValidationIssue[] {
  const readinessByKey = new Map(catalog.runtimeSpecies.map((entry) => [entry.key.trim(), entry]));

  return definitions.flatMap((definition, definitionIndex) => {
    if (definition.origin !== "runtime") {
      return [];
    }

    const readiness = readinessByKey.get(definition.key.trim());

    if (!readiness) {
      return [];
    }

    const issues: SpeciesBuilderValidationIssue[] = [];

    if (!readiness.readyForCharacterCreation) {
      const errorReasons = detailedReasons(readiness.errorReasons, readiness.reason);

      issues.push(
        ...(errorReasons.length > 0 ? errorReasons : [undefined]).map((reason) =>
          createIssue(
            { definitionIndex, scope: "definition", section: "details" },
            readiness.requiresWorldTableImport
              ? "runtime-species-import-required"
              : "runtime-species-not-ready",
            `Runtime species “${readiness.name}” is not ready for character creation${reason ? `: ${reason}` : "."}`,
          ),
        ),
      );
    }
    issues.push(
      ...detailedReasons(readiness.warningReasons, readiness.warningReason).map((reason) => ({
        ...createIssue(
          { definitionIndex, scope: "definition", section: "details" },
          "runtime-species-incomplete",
          `Runtime species “${readiness.name}” is playable but incomplete: ${reason}`,
        ),
        severity: "warning" as const,
      })),
    );

    return issues;
  });
}

function detailedReasons(reasons: string[] | undefined, summary: string | undefined): string[] {
  return reasons?.length ? reasons : summary ? [summary] : [];
}

export function classifyDefinitionIssueSeverities(
  issues: SpeciesBuilderValidationIssue[],
  definitions: SpeciesBuilderDefinition[],
  speciesTable: SpeciesBuilderSpeciesTableDraft | undefined,
): SpeciesBuilderValidationIssue[] {
  const tableKeys = new Set(
    (speciesTable?.rows ?? []).map((row) => row.speciesKey.trim()).filter(Boolean),
  );

  return issues.map((issue) => {
    if (ALWAYS_ERROR_ISSUE_CODES.has(issue.code)) {
      return { ...issue, severity: "error" };
    }
    if (issue.severity === "warning" || PLAYABLE_INCOMPLETE_ISSUE_CODES.has(issue.code)) {
      return { ...issue, severity: "warning" };
    }
    if (issue.definitionIndex === undefined) {
      return issue;
    }

    const definition = definitions[issue.definitionIndex];
    const isActive =
      Boolean(definition?.includeInExtraSpecies) ||
      Boolean(definition?.key.trim() && tableKeys.has(definition.key.trim()));

    return { ...issue, severity: isActive ? "error" : "warning" };
  });
}
