import { storeToRefs } from "pinia";
import { computed, ref } from "vue";

import type { NpcBuilderBridge, NpcCareerSummary } from "../../../types/npc-builder";
import type {
  PendingCareerAddEntry,
  PendingLowerCareerPrompt,
  PendingSkillResolutionPrompt,
} from "../../../types/npc-builder";

import {
  createDroppedCareerBatch,
  createSelectedLowerCareerBatch,
  getSelectedLowerCareerMessage,
  groupLowerCareerCandidates,
  isLowerCareerSelected as getIsLowerCareerSelected,
  updateLowerCareerSelection,
} from "../../../functions/npc-builder/career-workflow/lower-careers";
import {
  createSkillResolutionPrompt,
  getResolvedSkillName,
  getSkillResolutionLabel,
  usesFreeformSkillSpecialization,
} from "../../../functions/npc-builder/career-workflow/skill-resolution";
import { useNpcBuilderStore } from "..";
import { hydrateSkillSpecializationSuggestions } from "./skill-suggestions";

export function createNpcBuilderCareerDropWorkflow(bridge: NpcBuilderBridge) {
  const store = useNpcBuilderStore();
  const { careers, settings } = storeToRefs(store);
  const buildMessage = ref("");
  const errorMessage = ref("");
  const isFindingLowerCareers = ref(false);
  const pendingLowerCareerPrompt = ref<null | PendingLowerCareerPrompt>(null);
  const pendingSkillResolutionPrompt = ref<null | PendingSkillResolutionPrompt>(null);

  const lowerCareerCandidateGroups = computed(() =>
    groupLowerCareerCandidates(pendingLowerCareerPrompt.value),
  );

  async function handleCareerDrop(
    data: string,
    options: { replaceQueue?: boolean } = {},
  ): Promise<void> {
    errorMessage.value = "";

    try {
      const career = await bridge.resolveCareerDrop(data);

      await addCareerSummaryWithLowerCareerMode(career, options);
    } catch (error) {
      errorMessage.value = toWorkflowErrorMessage(error);
    }
  }

  async function addCareerSummaryWithLowerCareerMode(
    career: NpcCareerSummary,
    options: { replaceQueue?: boolean } = {},
  ): Promise<void> {
    if (options.replaceQueue) {
      store.clearCareers();
    }

    if (settings.value.lowerCareerMode === "never") {
      addDroppedCareerOnly(career);
      return;
    }

    isFindingLowerCareers.value = true;
    buildMessage.value = "Checking for lower-tier career candidates.";

    try {
      await addCareerWithLowerCareerCandidates(career);
    } finally {
      isFindingLowerCareers.value = false;
    }
  }

  async function addCareerWithLowerCareerCandidates(career: NpcCareerSummary): Promise<void> {
    const candidates = await bridge.findLowerCareerCandidates(career);
    const addableCandidates = candidates.filter((candidate) => !isCareerQueued(candidate.uuid));

    if (!addableCandidates.length) {
      addDroppedCareerOnly(career);
      buildMessage.value = "";
      return;
    }

    if (settings.value.lowerCareerMode === "auto-add-all") {
      addCareerBatch(
        [
          ...addableCandidates.map((candidate) => ({
            career: candidate,
            mode: "add-if-missing" as const,
          })),
          { career, mode: "add-or-increment" },
        ],
        {
          enableLinkedSkillResolution: !settings.value.askForLinkedSkillSpecializations,
          message: `Added ${addableCandidates.length} lower-tier career candidate${addableCandidates.length === 1 ? "" : "s"}.`,
        },
      );
      return;
    }

    pendingLowerCareerPrompt.value = {
      candidates,
      droppedCareer: career,
      selectedUuids: addableCandidates.map((candidate) => candidate.uuid),
    };
    buildMessage.value = "";
  }

  function addDroppedCareerOnly(career: NpcCareerSummary): void {
    addCareerBatch(createDroppedCareerBatch(career), {
      enableLinkedSkillResolution: false,
      message: "",
    });
  }

  function addCareerBatch(
    entries: PendingCareerAddEntry[],
    options: { enableLinkedSkillResolution: boolean; message: string },
  ): void {
    const skillPrompt = createSkillResolutionPrompt(entries, options);

    if (skillPrompt.rows.length) {
      pendingSkillResolutionPrompt.value = skillPrompt;

      // Vue wraps the assigned prompt. Mutating the reactive value keeps async
      // suggestion loading visible without another user input event.
      void hydrateSkillSpecializationSuggestions(bridge, pendingSkillResolutionPrompt.value);
      return;
    }

    finalizeCareerBatch(entries, options.message);
  }

  function confirmLowerCareerPrompt(): void {
    const prompt = pendingLowerCareerPrompt.value;

    if (!prompt) {
      return;
    }

    pendingLowerCareerPrompt.value = null;
    addCareerBatch(createSelectedLowerCareerBatch(prompt), {
      enableLinkedSkillResolution: !settings.value.askForLinkedSkillSpecializations,
      message: getSelectedLowerCareerMessage(prompt),
    });
  }

  function chooseSkillSpecialization(
    row: PendingSkillResolutionPrompt["rows"][number],
    specialization: string,
  ): void {
    row.resolvedSpecialization = specialization;
  }

  function dismissLowerCareerPrompt(): void {
    const prompt = pendingLowerCareerPrompt.value;

    if (!prompt) {
      return;
    }

    pendingLowerCareerPrompt.value = null;
    addDroppedCareerOnly(prompt.droppedCareer);
  }

  function confirmSkillResolutionPrompt(): void {
    const prompt = pendingSkillResolutionPrompt.value;

    if (!prompt) {
      return;
    }

    for (const row of prompt.rows) {
      store.setSkillGrantResolution(row.resolutionKey, getResolvedSkillName(row));
    }

    for (const linkedRow of prompt.linkedRows) {
      store.setSkillGrantResolution(
        linkedRow.resolutionKey,
        store.getSkillGrantResolution(linkedRow.linkedFromKey),
      );
    }

    pendingSkillResolutionPrompt.value = null;
    finalizeCareerBatch(prompt.entries, prompt.message);
  }

  function dismissSkillResolutionPrompt(): void {
    const prompt = pendingSkillResolutionPrompt.value;

    if (!prompt) {
      return;
    }

    pendingSkillResolutionPrompt.value = null;
    finalizeCareerBatch(prompt.entries, prompt.message);
  }

  function finalizeCareerBatch(entries: PendingCareerAddEntry[], message: string): void {
    for (const entry of entries) {
      if (entry.mode === "add-if-missing") {
        store.addCareerIfMissing(entry.career);
      } else {
        store.addCareer(entry.career);
      }
    }

    buildMessage.value = message;
  }

  function isCareerQueued(uuid: string): boolean {
    return careers.value.some((career) => career.uuid === uuid);
  }

  function isLowerCareerSelected(uuid: string): boolean {
    return getIsLowerCareerSelected(pendingLowerCareerPrompt.value, uuid);
  }

  function setLowerCareerSelected(candidate: NpcCareerSummary, selected: boolean): void {
    const nextSelection = updateLowerCareerSelection({
      candidateUuid: candidate.uuid,
      isAlreadyQueued: isCareerQueued(candidate.uuid),
      prompt: pendingLowerCareerPrompt.value,
      selected,
    });

    if (nextSelection && pendingLowerCareerPrompt.value) {
      pendingLowerCareerPrompt.value.selectedUuids = nextSelection;
    }
  }

  return {
    buildMessage,
    chooseSkillSpecialization,
    confirmLowerCareerPrompt,
    confirmSkillResolutionPrompt,
    dismissLowerCareerPrompt,
    dismissSkillResolutionPrompt,
    errorMessage,
    getSkillResolutionLabel,
    addCareerSummaryWithLowerCareerMode,
    handleCareerDrop,
    isCareerQueued,
    isFindingLowerCareers,
    isLowerCareerSelected,
    lowerCareerCandidateGroups,
    pendingLowerCareerPrompt,
    pendingSkillResolutionPrompt,
    setLowerCareerSelected,
    usesFreeformSkillSpecialization,
  };
}

function toWorkflowErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "The NPC Builder could not finish that action.";
}
