import type {
  SpeciesItemSystem,
  SpeciesItemReference,
} from "../../../types/species-builder/species-item";
import type { SpeciesBuilderDefinition } from "../../../types/species-builder/species-builder";
import { WfrpCharacteristicKey } from "../../../types/wfrp4e/characteristics";
import { encodeTalentChoices } from "./choices";

export function emptySpeciesReference(): SpeciesItemReference {
  return { uuid: "", id: "", name: "" };
}

export function createSpeciesItemSystem(): SpeciesItemSystem {
  return {
    description: { value: "" },
    gmdescription: { value: "" },
    characteristics: Object.fromEntries(
      Object.values(WfrpCharacteristicKey).map((key) => [key, { base: 20, dice: 2 }]),
    ),
    fate: 0,
    resilience: 0,
    extra: 0,
    movement: 4,
    skills: { list: [] },
    talents: { choices: encodeTalentChoices([]), random: 0 },
    size: "avg",
    subspeciesOf: emptySpeciesReference(),
    keys: [],
    tables: {
      talents: emptySpeciesReference(),
      eye: emptySpeciesReference(),
      hair: emptySpeciesReference(),
      career: emptySpeciesReference(),
    },
  };
}

export function decodeCharacteristics(
  system: SpeciesItemSystem,
): SpeciesBuilderDefinition["characteristics"] {
  const formulas: NonNullable<SpeciesBuilderDefinition["characteristics"]> = {};
  for (const key of Object.values(WfrpCharacteristicKey)) {
    const value = system.characteristics[key];
    if (value && value.base !== null && value.dice !== null) {
      formulas[key] = value.dice === 0 ? String(value.base) : `${value.dice}d10+${value.base}`;
    }
  }
  return Object.keys(formulas).length ? formulas : undefined;
}
