<script setup lang="ts">
import type {
  PendingSkillResolutionPrompt,
  SkillResolutionPromptRow,
} from "../../../../types/npc-builder";

import { isSkillSpecializationAlreadyGranted } from "../../../../functions/npc-builder/career-workflow/skill-resolution";

defineProps<{
  getSkillResolutionLabel: (row: SkillResolutionPromptRow) => string;
  prompt: PendingSkillResolutionPrompt;
  usesFreeformSkillSpecialization: (row: SkillResolutionPromptRow) => boolean;
}>();

const emit = defineEmits<{
  addWithoutResolving: [];
  applySpecializations: [];
  chooseSkillSpecialization: [row: SkillResolutionPromptRow, specialization: string];
}>();

function hasAlreadyGrantedSelection(row: SkillResolutionPromptRow): boolean {
  return (
    Boolean(row.resolvedSpecialization) &&
    isSkillSpecializationAlreadyGranted(row, row.resolvedSpecialization)
  );
}
</script>

<template>
  <section>
    <p>
      Some Career skills need a specialization before they become concrete WFRP skills. Blank rows
      can be left unresolved and edited later.
    </p>

    <section
      v-for="row in prompt.rows"
      :key="row.resolutionKey"
      class="dui-card dui-card-border dui-card-sm"
    >
      <div class="dui-card-body">
        <h3 class="dui-card-title">{{ getSkillResolutionLabel(row) }}</h3>
        <span class="dui-badge">{{ row.careerLabel }}</span>

        <fieldset class="dui-fieldset">
          <legend class="dui-fieldset-legend">Specialization</legend>
          <label class="app:grid app:gap-1">
            <span class="dui-label">Choice</span>
            <select
              v-if="row.options.length > 1"
              v-model="row.resolvedSpecialization"
              :aria-label="`Specialization for ${getSkillResolutionLabel(row)}`"
              :class="[
                'dui-select dui-select-sm',
                {
                  'dui-select-error': isSkillSpecializationAlreadyGranted(
                    row,
                    row.resolvedSpecialization,
                  ),
                },
              ]"
            >
              <option value="">Leave unresolved</option>
              <option
                v-for="option in row.options"
                :key="option"
                :class="{ 'app:text-error': isSkillSpecializationAlreadyGranted(row, option) }"
                :value="option"
              >
                {{ option
                }}{{ isSkillSpecializationAlreadyGranted(row, option) ? " — already granted" : "" }}
              </option>
            </select>
            <input
              v-else
              v-model="row.resolvedSpecialization"
              :aria-label="`Specialization for ${getSkillResolutionLabel(row)}`"
              :class="[
                'dui-input dui-input-sm',
                {
                  'dui-input-error': isSkillSpecializationAlreadyGranted(
                    row,
                    row.resolvedSpecialization,
                  ),
                },
              ]"
              :placeholder="
                row.suggestedSpecializations.length ? 'Type or choose below' : row.specialization
              "
              type="text"
            />
          </label>
          <p v-if="hasAlreadyGrantedSelection(row)" class="dui-label app:text-error">
            Already granted by this Career.
          </p>
        </fieldset>

        <div v-if="usesFreeformSkillSpecialization(row)" class="dui-card-actions">
          <small v-if="row.isLoadingSuggestions">Finding known choices.</small>
          <button
            v-for="specialization in row.suggestedSpecializations"
            :key="`${row.resolutionKey}:${specialization}`"
            :class="[
              'dui-btn dui-btn-sm',
              {
                'dui-btn-error dui-btn-outline': isSkillSpecializationAlreadyGranted(
                  row,
                  specialization,
                ),
              },
            ]"
            type="button"
            @click="emit('chooseSkillSpecialization', row, specialization)"
          >
            {{ specialization }}
            <span
              v-if="isSkillSpecializationAlreadyGranted(row, specialization)"
              class="dui-badge dui-badge-error dui-badge-xs"
            >
              Already granted
            </span>
          </button>
        </div>
      </div>
    </section>

    <div v-if="prompt.linkedRows.length" class="dui-alert dui-alert-info">
      {{ prompt.linkedRows.length }} linked skill specialization{{
        prompt.linkedRows.length === 1 ? "" : "s"
      }}
      will reuse earlier choices from this career chain.
    </div>

    <div class="dui-card-actions">
      <button class="dui-btn dui-btn-sm" type="button" @click="emit('addWithoutResolving')">
        Add Without Resolving
      </button>
      <button class="dui-btn dui-btn-sm" type="button" @click="emit('applySpecializations')">
        Apply Specializations
      </button>
    </div>
  </section>
</template>
