import type { ComputedRef, Ref } from "vue";

import type {
  SpeciesBuilderSettings,
  SpeciesBuilderSpeciesTableDraft,
} from "../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../types/species-builder/validation";

import { snapshotSettings } from "../../functions/species-builder/editor/draft";
import { getSpeciesBuilderSavePolicy } from "../../functions/species-builder/save-policy";
import { computed } from "vue";

interface SpeciesBuilderSaveStateContext {
  autoRegisterSpeciesTable: Ref<boolean>;
  isLoading: Ref<boolean>;
  isSaving: Ref<boolean>;
  loadError: Ref<string>;
  normalizedSettings: ComputedRef<SpeciesBuilderSettings>;
  savedDefinitionsSnapshot: Ref<string>;
  savedSettingsSnapshot: Ref<string>;
  savedSpeciesTableSnapshot: Ref<string>;
  speciesTable: Ref<SpeciesBuilderSpeciesTableDraft>;
  speciesTableSnapshot: ComputedRef<string>;
  speciesTableValidationMessages: ComputedRef<string[]>;
  validationIssues: ComputedRef<SpeciesBuilderValidationIssue[]>;
}

export interface SpeciesBuilderSaveOptions {
  allowValidationErrors?: boolean;
}

export function createSpeciesBuilderSaveState(context: SpeciesBuilderSaveStateContext) {
  const settingsHaveUnsavedChanges = computed(
    () =>
      context.savedSettingsSnapshot.value !== snapshotSettings(context.normalizedSettings.value),
  );
  const definitionsSnapshot = computed(() =>
    snapshotDefinitionSettings(context.normalizedSettings.value),
  );
  const definitionsHaveUnsavedChanges = computed(
    () => context.savedDefinitionsSnapshot.value !== definitionsSnapshot.value,
  );
  const speciesTableNeedsRegistration = computed(
    () =>
      context.autoRegisterSpeciesTable.value &&
      (context.speciesTable.value.ownership !== "managed" ||
        !context.speciesTable.value.isRegistered),
  );
  const speciesTableHasUnsavedChanges = computed(
    () =>
      context.savedSpeciesTableSnapshot.value !== context.speciesTableSnapshot.value ||
      speciesTableNeedsRegistration.value ||
      context.speciesTable.value.requiresLinkRepair,
  );
  const hasUnsavedChanges = computed(
    () => settingsHaveUnsavedChanges.value || speciesTableHasUnsavedChanges.value,
  );
  const speciesTableWillSave = computed(
    () =>
      speciesTableHasUnsavedChanges.value ||
      (settingsHaveUnsavedChanges.value && context.autoRegisterSpeciesTable.value),
  );
  const blockingSpeciesTableValidationMessages = computed(() =>
    speciesTableWillSave.value ? context.speciesTableValidationMessages.value : [],
  );
  const blockingValidationIssues = computed(() =>
    context.validationIssues.value.filter(
      (issue) =>
        issue.severity === "error" &&
        (issue.scope !== "species-table" || speciesTableWillSave.value),
    ),
  );
  const savePolicy = computed(() =>
    getSpeciesBuilderSavePolicy({
      hasLoadError: Boolean(context.loadError.value),
      hasUnsavedChanges: hasUnsavedChanges.value,
      isLoading: context.isLoading.value,
      isSaving: context.isSaving.value,
      validationErrorCount:
        blockingValidationIssues.value.length + blockingSpeciesTableValidationMessages.value.length,
    }),
  );
  const canSave = computed(() => savePolicy.value.canSave);
  const requiresUnsafeSaveConfirmation = computed(
    () => savePolicy.value.requiresUnsafeSaveConfirmation,
  );

  return {
    blockingSpeciesTableValidationMessages,
    blockingValidationIssues,
    canSave,
    definitionsHaveUnsavedChanges,
    hasUnsavedChanges,
    requiresUnsafeSaveConfirmation,
    settingsHaveUnsavedChanges,
    speciesTableWillSave,
  };
}

export function snapshotDefinitionSettings(settings: SpeciesBuilderSettings): string {
  return JSON.stringify({
    definitions: settings.definitions,
    runtimeSpeciesExtensions: settings.runtimeSpeciesExtensions,
  });
}
