import type { NpcTalentMaximumSummary } from "../../types/npc-builder";

import { readStringPath } from "../../shared/object-readers";
import { findWfrpItemByNameAndType } from "./item-lookup";

export async function listWfrpTalentMaximums(
  talentNames: string[],
): Promise<NpcTalentMaximumSummary[]> {
  const summaries: NpcTalentMaximumSummary[] = [];

  for (const talentName of uniqueNames(talentNames)) {
    const item = await findWfrpItemByNameAndType(talentName, ["talent"]);

    if (!item) {
      continue;
    }

    summaries.push({
      maximumFormula: readStringPath(item.system, ["max", "formula"]),
      maximumKey: readStringPath(item.system, ["max", "value"]),
      talentName,
    });
  }

  return summaries;
}

function uniqueNames(names: string[]): string[] {
  const seen = new Set<string>();
  const unique: string[] = [];

  for (const name of names) {
    const normalized = name.trim().toLocaleLowerCase();

    if (!normalized || seen.has(normalized)) {
      continue;
    }

    seen.add(normalized);
    unique.push(name);
  }

  return unique;
}
