import {
  type ValueValidator,
  validateArray,
  validateBoolean,
  validateCareerReplacementRows,
  validateCareerTable,
  validateCharacteristics,
  validateFields,
  validateFiniteNumber,
  validateHeight,
  validateLinkedItems,
  validateNonEmptyString,
  validateNumberRecord,
  validateObject,
  validateStringArray,
  validateStringArrayRecord,
  validateStringRecord,
  validateTalentGrants,
  validateTalentReplacementRows,
  validateWoundFormula,
} from "./field-validation";
import { createSpeciesConfigKey } from "../config-keys";

const NAMED_FIELDS = [
  "careerTable",
  "characteristics",
  "extra",
  "fate",
  "key",
  "movement",
  "name",
  "randomTalents",
  "resilience",
  "talentReplacementRows",
  "talentReplacements",
  "woundFormula",
] as const;

const SPECIES_FIELDS = [
  ...NAMED_FIELDS,
  "age",
  "careerReplacementRows",
  "careerReplacements",
  "height",
  "includeInExtraSpecies",
  "linkedSkills",
  "linkedTalents",
  "linkedTraits",
  "skills",
  "subspecies",
  "talents",
  "traits",
] as const;

const SUBSPECIES_FIELDS = [
  ...NAMED_FIELDS,
  "skillsAdded",
  "skillsRemoved",
  "talentsAdded",
  "talentsRemoved",
  "traitsAdded",
  "traitsRemoved",
] as const;

export function validatePortableSpeciesDefinition(value: unknown): string {
  return validateObject(value, "definition", SPECIES_FIELDS, validateSpeciesFields);
}

function validateSpeciesFields(value: Record<string, unknown>, path: string): string {
  const namedError = validateNamedFields(value, path);

  if (namedError) {
    return namedError;
  }

  const validators: Array<[string, ValueValidator]> = [
    ["includeInExtraSpecies", validateBoolean],
    ["age", validateNonEmptyString],
    ["height", validateHeight],
    ["careerReplacementRows", validateCareerReplacementRows],
    ["careerReplacements", validateStringArrayRecord],
    ["linkedSkills", validateLinkedItems],
    ["linkedTalents", validateTalentGrants],
    ["linkedTraits", validateLinkedItems],
    ["skills", validateStringArray],
    ["talents", validateStringArray],
    ["traits", validateStringArray],
    ["subspecies", validateSubspecies],
  ];

  return validateFields(value, path, validators, new Set(["includeInExtraSpecies"]));
}

function validateNamedFields(value: Record<string, unknown>, path: string): string {
  const validators: Array<[string, ValueValidator]> = [
    ["key", validateConfigKey],
    ["name", validateNonEmptyString],
    ["characteristics", validateCharacteristics],
    ["randomTalents", validateNumberRecord],
    ["talentReplacementRows", validateTalentReplacementRows],
    ["talentReplacements", validateStringRecord],
    ["movement", validateFiniteNumber],
    ["fate", validateFiniteNumber],
    ["resilience", validateFiniteNumber],
    ["extra", validateFiniteNumber],
    ["woundFormula", validateWoundFormula],
    ["careerTable", validateCareerTable],
  ];

  return validateFields(value, path, validators, new Set(["key", "name"]));
}

function validateSubspecies(value: unknown, path: string): string {
  const validationError = validateArray(value, path, (entry, entryPath) =>
    validateObject(entry, entryPath, SUBSPECIES_FIELDS, (record, recordPath) => {
      const namedError = validateNamedFields(record, recordPath);

      if (namedError) {
        return namedError;
      }

      return validateFields(
        record,
        recordPath,
        [
          ["skillsAdded", validateStringArray],
          ["skillsRemoved", validateStringArray],
          ["talentsAdded", validateStringArray],
          ["talentsRemoved", validateStringArray],
          ["traitsAdded", validateStringArray],
          ["traitsRemoved", validateStringArray],
        ],
        new Set(),
      );
    }),
  );

  if (validationError || !Array.isArray(value)) {
    return validationError;
  }

  const usedKeys = new Set<string>();

  for (const [index, entry] of value.entries()) {
    const key = createSpeciesConfigKey((entry as Record<string, unknown>)["key"] as string);

    if (usedKeys.has(key)) {
      return `${path}[${index}].key duplicates normalized subspecies key ${JSON.stringify(key)}.`;
    }

    usedKeys.add(key);
  }

  return "";
}

function validateConfigKey(value: unknown, path: string): string {
  const stringError = validateNonEmptyString(value, path);

  if (stringError) {
    return stringError;
  }

  return createSpeciesConfigKey(value as string)
    ? ""
    : `${path} must contain at least one ASCII letter or number.`;
}
