import type { NpcBuilderSettings, NpcQuickTraitSummary } from "../../../../../types/npc-builder";

import { RECOMMENDED_QUICK_TRAIT_NAMES } from "../../../../../functions/npc-builder/recommended-quick-traits";
import { createItemSourceFromMatch } from "../../../../foundry/item-sources";
import { findWfrpItemByNameAndType } from "../../../../wfrp4e/item-lookup";
import { getItemFolderByUuid } from "../folders";
import { readTraitConfig } from "./config";

export async function importRecommendedQuickTraits(
  settings: NpcBuilderSettings,
): Promise<NpcQuickTraitSummary[]> {
  const folder = getItemFolderByUuid(settings.quickTraitFolderUuid);

  if (!folder) {
    throw new Error("Choose a Quick Traits item folder before importing traits.");
  }

  const existingNames = new Set(
    listQuickTraitItems(settings).map((item) => item.name.trim().toLocaleLowerCase()),
  );

  for (const traitName of RECOMMENDED_QUICK_TRAIT_NAMES) {
    if (existingNames.has(traitName.trim().toLocaleLowerCase())) {
      continue;
    }

    const sourceItem = await findWfrpItemByNameAndType(traitName, ["trait"]);
    const itemData = createItemSourceFromMatch(sourceItem, traitName, "trait");

    itemData["folder"] = folder.id;
    itemData["type"] = "trait";
    await Item.create(itemData);
  }

  ui.notifications?.info("Imported recommended quick traits.");

  return await listQuickTraits(settings);
}

export async function listQuickTraits(
  settings: NpcBuilderSettings,
): Promise<NpcQuickTraitSummary[]> {
  return listQuickTraitItems(settings)
    .map(toQuickTraitSummary)
    .sort((left, right) => left.name.localeCompare(right.name));
}

function isItemInQuickTraitFolder(
  item: FoundryItemDocument,
  settings: NpcBuilderSettings,
): boolean {
  if (!settings.quickTraitFolderUuid) {
    return false;
  }

  return item.folder?.uuid === settings.quickTraitFolderUuid;
}

function listQuickTraitItems(settings: NpcBuilderSettings): FoundryItemDocument[] {
  return (
    game.items?.contents.filter((item) => {
      return item.type === "trait" && isItemInQuickTraitFolder(item, settings);
    }) ?? []
  );
}

function toQuickTraitSummary(item: FoundryItemDocument): NpcQuickTraitSummary {
  return {
    config: readTraitConfig(item),
    img: item.img ?? "",
    name: item.name,
    uuid: item.uuid,
  };
}
