import type { SpeciesBuilderBridge } from "../../../types/species-builder/species-builder";

import { FoundryVueApplication } from "../FoundryVueApplication";
import { foundrySpeciesBuilderBridge } from "../species-builder/foundry-bridge";
import { requestReloadConfirmation } from "../species-builder/reload-confirmation";

export abstract class SpeciesSuiteApplication extends FoundryVueApplication {
  #hasSavedChanges = false;

  protected getApplicationProps(): Record<string, unknown> {
    return {};
  }

  protected override getVueProps(): Record<string, unknown> {
    return {
      ...this.getApplicationProps(),
      bridge: foundrySpeciesBuilderBridge satisfies SpeciesBuilderBridge,
      onSettingsSaved: () => {
        this.#hasSavedChanges = true;
      },
    };
  }

  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    const shouldPromptForReload = this.#hasSavedChanges;

    this.#hasSavedChanges = false;

    if (shouldPromptForReload && (await requestReloadConfirmation())) {
      window.location.reload();
    }

    await super._preClose(options);
  }
}
