import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";

import {
  careerReplacementRowsForDefinition,
  talentReplacementRowsForDefinition,
} from "../editor/replacements";
import { formatLinkedItemName } from "../item-reference-names";
import {
  createIssue,
  isKnownItem,
  normalizeLookupName,
  type ValidationCatalogIndex,
  type ValidationIssueLocation,
} from "./shared";

export function validateReplacementTables(
  definitions: SpeciesBuilderDefinition[],
  catalog: ValidationCatalogIndex,
): SpeciesBuilderValidationIssue[] {
  const issues: SpeciesBuilderValidationIssue[] = [];

  definitions.forEach((definition, definitionIndex) => {
    validateTalentReplacements(
      definition,
      definitionLocation(definitionIndex, "talentReplacement"),
      catalog,
      issues,
    );
    validateCareerReplacements(
      definition,
      definitionLocation(definitionIndex, "careerReplacement"),
      catalog,
      issues,
    );

    (definition.subspecies ?? []).forEach((subspecies, subspeciesIndex) =>
      validateTalentReplacements(
        subspecies,
        subspeciesLocation(definitionIndex, subspeciesIndex),
        catalog,
        issues,
      ),
    );
  });

  return issues;
}

function validateTalentReplacements(
  definition: SpeciesBuilderDefinition | SpeciesBuilderSubspeciesDefinition,
  location: ValidationIssueLocation,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const rows = talentReplacementRowsForDefinition(definition);
  const rolledCounts = countNames(rows.map((row) => formatLinkedItemName(row.rolled)));

  rows.forEach((row, rowIndex) => {
    const rolled = formatLinkedItemName(row.rolled);

    validateTalentReplacementName(row.rolled, "rolled", rowIndex, location, catalog, issues);
    validateTalentReplacementName(
      row.replacement,
      "replacement",
      rowIndex,
      location,
      catalog,
      issues,
    );
    if (rolled && (rolledCounts.get(normalizeLookupName(rolled)) ?? 0) > 1) {
      issues.push(
        createIssue(
          { ...location, field: "rolled", rowIndex },
          "talent-replacement-duplicate",
          `Talent “${rolled}” appears in more than one replacement row; only the last row would be used.`,
        ),
      );
    }
  });
}

function validateTalentReplacementName(
  row: SpeciesBuilderLinkedItemName,
  field: "replacement" | "rolled",
  rowIndex: number,
  location: ValidationIssueLocation,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const name = formatLinkedItemName(row);
  const fieldLocation = { ...location, field, rowIndex };

  if (!name) {
    issues.push(
      createIssue(
        fieldLocation,
        "talent-replacement-blank",
        `Talent Replacement row ${rowIndex + 1} needs a ${field} Talent.`,
      ),
    );
  } else if (!isKnownItem(name, catalog.talents)) {
    issues.push(
      createIssue(
        fieldLocation,
        "talent-replacement-unresolved",
        `Talent “${name}” does not match an available WFRP Talent Item.`,
      ),
    );
  }
}

function validateCareerReplacements(
  definition: SpeciesBuilderDefinition,
  location: ValidationIssueLocation,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const rows = careerReplacementRowsForDefinition(definition);
  const rolledCounts = countNames(rows.map((row) => formatLinkedItemName(row.rolled)));

  rows.forEach((row, rowIndex) => {
    const rolled = formatLinkedItemName(row.rolled);

    validateCareerName(rolled, "rolled", rowIndex, undefined, location, catalog, issues);
    if (rolled && (rolledCounts.get(normalizeLookupName(rolled)) ?? 0) > 1) {
      issues.push(
        createIssue(
          { ...location, field: "rolled", rowIndex },
          "career-replacement-duplicate",
          `Career group “${rolled}” appears in more than one replacement row; only the last row would be used.`,
        ),
      );
    }

    if (row.replacements.length === 0) {
      validateCareerName("", "replacement", rowIndex, 0, location, catalog, issues);
    } else {
      row.replacements.forEach((replacement, choiceIndex) =>
        validateCareerName(
          formatLinkedItemName(replacement),
          "replacement",
          rowIndex,
          choiceIndex,
          location,
          catalog,
          issues,
        ),
      );
    }
  });
}

function validateCareerName(
  name: string,
  field: "replacement" | "rolled",
  rowIndex: number,
  choiceIndex: number | undefined,
  location: ValidationIssueLocation,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const fieldLocation =
    choiceIndex === undefined
      ? { ...location, field, rowIndex }
      : { ...location, choiceIndex, field, rowIndex };

  if (!name.trim()) {
    issues.push(
      createIssue(
        fieldLocation,
        "career-replacement-blank",
        `Career Replacement row ${rowIndex + 1} needs a ${field} Career group.`,
      ),
    );
  } else if (!catalog.careerGroups.has(name.trim())) {
    issues.push(
      createIssue(
        fieldLocation,
        "career-replacement-unresolved",
        `Career group “${name}” does not match an available WFRP Career group.`,
      ),
    );
  }
}

function definitionLocation(
  definitionIndex: number,
  section: "careerReplacement" | "talentReplacement",
): ValidationIssueLocation {
  return { definitionIndex, scope: "definition", section };
}

function subspeciesLocation(
  definitionIndex: number,
  subspeciesIndex: number,
): ValidationIssueLocation {
  return { definitionIndex, scope: "subspecies", section: "talentReplacement", subspeciesIndex };
}

function countNames(values: string[]): Map<string, number> {
  const counts = new Map<string, number>();

  for (const value of values) {
    const normalized = normalizeLookupName(value);

    if (normalized) {
      counts.set(normalized, (counts.get(normalized) ?? 0) + 1);
    }
  }

  return counts;
}
