import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";

import {
  createIssue,
  isKnownItem,
  type ValidationCatalogIndex,
  type ValidationIssueLocation,
} from "./shared";

export function validateTalentRows(
  rows: string[][],
  field: string,
  location: ValidationIssueLocation,
  configuredRandomTalentSources: ReadonlySet<string>,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  rows.forEach((choices, rowIndex) => {
    if (choices.length === 0) {
      issues.push(
        createIssue(
          { ...location, field, rowIndex },
          "grant-blank",
          `Talent row ${rowIndex + 1} has no choices.`,
        ),
      );
      return;
    }

    choices.forEach((choice, choiceIndex) => {
      const name = choice.trim();
      const choiceLocation = { ...location, choiceIndex, field, rowIndex };

      if (!name) {
        issues.push(
          createIssue(choiceLocation, "grant-blank", `Talent choice ${choiceIndex + 1} is blank.`),
        );
      } else if (choices.length === 1 && isNumericTalent(name)) {
        validateNumericTalent(name, choiceLocation, configuredRandomTalentSources, catalog, issues);
      } else if (choices.length > 1 && isRandomTalentChoice(name)) {
        validateRandomTalentChoice(
          name,
          choiceLocation,
          configuredRandomTalentSources,
          catalog,
          issues,
        );
      } else if (!isKnownItem(name, catalog.talents)) {
        issues.push(
          createIssue(
            choiceLocation,
            "grant-unresolved",
            `Talent “${name}” does not match an available WFRP Talent Item.`,
          ),
        );
      }
    });
  });
}

export function configuredRandomTalentKeys(
  value: Record<string, number> | undefined,
): ReadonlySet<string> {
  return new Set(Object.keys(value ?? { talents: 0 }));
}

function validateNumericTalent(
  value: string,
  location: ValidationIssueLocation,
  configuredRandomTalentSources: ReadonlySet<string>,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const count = Number(value);

  if (!Number.isInteger(count) || count < 0) {
    issues.push(
      createIssue(
        location,
        "talent-random-count-invalid",
        "A numeric Talent grant must be a non-negative whole number.",
      ),
    );
  }

  validateTalentSource(
    "talents",
    `Numeric Talent grant “${value}”`,
    location,
    configuredRandomTalentSources,
    catalog,
    issues,
  );
}

function validateRandomTalentChoice(
  value: string,
  location: ValidationIssueLocation,
  configuredRandomTalentSources: ReadonlySet<string>,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const match = /^random\[(\d)\](?:\[([a-zA-Z-_]+)\])?$/iu.exec(value);
  const key = match?.[2] ?? "talents";

  validateTalentSource(
    key,
    `Random Talent choice “${value}”`,
    location,
    configuredRandomTalentSources,
    catalog,
    issues,
  );
}

function validateTalentSource(
  key: string,
  label: string,
  location: ValidationIssueLocation,
  configuredRandomTalentSources: ReadonlySet<string>,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  if (!configuredRandomTalentSources.has(key)) {
    issues.push(
      createIssue(
        location,
        "random-talent-source-unconfigured",
        `${label} uses table key “${key}”, but that key is not configured in Random Talents.`,
      ),
    );
    return;
  }

  const source = catalog.randomTalentSources.get(key);

  if (!source) {
    issues.push(
      createIssue(
        location,
        "random-talent-source-missing",
        `${label} uses missing table key “${key}”.`,
      ),
    );
  } else if (!source.readyForCharacterCreation) {
    issues.push(
      createIssue(
        location,
        "random-talent-source-not-ready",
        `Random Talent table “${source.key}” is not ready: ${source.reason ?? "its results are invalid"}.`,
      ),
    );
  }
}

function isNumericTalent(value: string): boolean {
  return /^-?\d+(?:\.\d+)?$/u.test(value);
}

function isRandomTalentChoice(value: string): boolean {
  return /^random\[\d\](?:\[[a-zA-Z-_]+\])?$/iu.test(value);
}
