<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";

import type {
  SpeciesBuilderBridge,
  SpeciesBuilderDefinition,
} from "../../../types/species-builder/species-builder";
import type { SpeciesBuilderActiveTab } from "./tabs/active-tab";
import type { SpeciesBuilderEditorTab } from "./tabs/species/pages/editor/editor-tabs";
import type { RandomTableTab } from "./tabs/species/pages/editor/tabs/tables/random-table-events";

import { createDefinitionsWithGeneratedKeys } from "../../../functions/species-builder/editor/draft";
import { useSpeciesBuilderEditor } from "../../../state/species-builder/editor";
import DeleteConfirmationSubView from "./components/DeleteConfirmationSubView.vue";
import SpeciesBuilderEditorContext from "./components/SpeciesBuilderEditorContext.vue";
import SpeciesBuilderHeader from "./components/SpeciesBuilderHeader.vue";
import SpeciesBuilderNavigation from "./components/SpeciesBuilderNavigation.vue";
import SpeciesBuilderStatus from "./components/SpeciesBuilderStatus.vue";
import SpeciesDefinitionPortability from "./components/SpeciesDefinitionPortability.vue";
import UnsafeSaveConfirmationSubView from "./components/UnsafeSaveConfirmationSubView.vue";
import { useSpeciesBuilderUnsafeSave } from "./components/unsafe-save";
import { useSpeciesBuilderDeletion } from "./components/deletion";
import SpeciesBuilderValidationSummaryDialog from "./components/validation/SpeciesBuilderValidationSummaryDialog.vue";
import { useSpeciesBuilderValidationSummary } from "./components/validation/use-validation-summary";
import {
  buildSpeciesBuilderNavigationValidationCounts,
  getSpeciesBuilderPageMeta,
} from "./components/species-builder-navigation";
import SpeciesBuilderProjectPages from "./tabs/SpeciesBuilderProjectPages.vue";
import { createSpeciesBuilderEditorPageEvents } from "./tabs/species/pages/editor/editor-page-events";
import SpeciesBuilderEditorPage from "./tabs/species/pages/editor/SpeciesBuilderEditorPage.vue";

const props = defineProps<{
  bridge: SpeciesBuilderBridge;
  onSettingsSaved?: () => void;
}>();
const editor = useSpeciesBuilderEditor(props.bridge, {
  onSettingsSaved: props.onSettingsSaved,
});
const activeTab = ref<SpeciesBuilderActiveTab>("species");
const isEditorOpen = ref(false);
const activeEditorTab = ref<SpeciesBuilderEditorTab>("details");
const activeTableTab = ref<RandomTableTab>("careerTable");
const unsafeSave = useSpeciesBuilderUnsafeSave(editor);
const isBusy = computed(() => editor.isLoading.value || editor.isSaving.value);
const canManageSelectedDefinition = computed(
  () => isEditorOpen.value && editor.selectedDefinition.value?.origin === "custom",
);
const pageMeta = computed(() =>
  getSpeciesBuilderPageMeta(
    activeTab.value,
    isEditorOpen.value,
    activeEditorTab.value,
    activeTableTab.value,
  ),
);
const currentDefinitionName = computed(() =>
  isEditorOpen.value
    ? editor.selectedDefinition.value?.name.trim() ||
      editor.selectedDefinition.value?.key.trim() ||
      "Untitled Species"
    : "",
);
const definitionKeys = computed(() =>
  createDefinitionsWithGeneratedKeys(editor.definitions.value).map((definition) => definition.key),
);
const {
  close: closeValidationSummary,
  isOpen: isValidationSummaryOpen,
  navigationRequest: validationNavigationRequest,
  open: openValidationSummary,
  openForDefinition: openDefinitionValidationSummary,
  selectIssue: selectValidationIssue,
  summaryIssues: validationSummaryIssues,
} = useSpeciesBuilderValidationSummary({
  definitions: editor.definitions,
  issues: editor.validationIssues,
  openEditorTab: openSelectedDefinitionEditor,
  openTableTab: openSelectedDefinitionTable,
  selectDefinition: editor.selectDefinition,
  selectProjectTab: selectTopLevelTab,
});
const hasValidationErrors = computed(
  () =>
    editor.blockingValidationIssues.value.length > 0 ||
    editor.blockingSpeciesTableValidationMessages.value.length > 0,
);
const validationCounts = computed(() => ({
  errors: validationSummaryIssues.value.filter((issue) => issue.severity === "error").length,
  warnings: validationSummaryIssues.value.filter((issue) => issue.severity === "warning").length,
}));
const hasValidationWarnings = computed(() => validationCounts.value.warnings > 0);
const selectedDefinitionIssues = computed(() =>
  editor.validationIssues.value.filter(
    (issue) => issue.definitionIndex === editor.selectedIndex.value,
  ),
);
const navigationValidationCounts = computed(() =>
  buildSpeciesBuilderNavigationValidationCounts(
    editor.validationIssues.value,
    editor.selectedIndex.value,
  ),
);
const hasStatusBanner = computed(
  () =>
    Boolean(editor.loadError.value) ||
    Boolean(editor.saveError.value) ||
    Boolean(editor.message.value) ||
    editor.validationIssues.value.length > 0 ||
    hasValidationErrors.value,
);
const {
  confirmPendingDelete,
  pendingDelete,
  requestDeleteDefinition: requestDeleteSelectedDefinition,
  requestDeleteSubspecies,
} = useSpeciesBuilderDeletion({
  deleteDefinition: editor.deleteSelectedDefinition,
  deleteSubspecies: editor.deleteSubspecies,
  selectedDefinition: editor.selectedDefinition,
});
onMounted(() => {
  void editor.loadSettings();
});
watch(
  () => editor.showGeneratedConfigTab.value,
  (showGeneratedConfigTab) => {
    if (!showGeneratedConfigTab && activeTab.value === "wfrp-config") {
      activeTab.value = "species";
    }
  },
);
watch(
  () => editor.selectedDefinition.value,
  (definition) => {
    if (!definition) {
      isEditorOpen.value = false;
    }
  },
);
function stopFormControlKeyPropagation(event: KeyboardEvent): void {
  if (
    event.target instanceof HTMLInputElement ||
    event.target instanceof HTMLSelectElement ||
    event.target instanceof HTMLTextAreaElement
  ) {
    event.stopPropagation();
  }
}

function openDefinitionEditor(index: number, tab: SpeciesBuilderEditorTab = "details"): void {
  editor.selectDefinition(index);
  openSelectedDefinitionEditor(tab);
}

function openSelectedDefinitionEditor(tab: SpeciesBuilderEditorTab): void {
  activeTab.value = "species";
  activeEditorTab.value = tab;
  isEditorOpen.value = true;
}

function openSelectedDefinitionTable(tab: RandomTableTab): void {
  activeTableTab.value = tab;
  openSelectedDefinitionEditor("tables");
}

function selectTopLevelTab(tab: SpeciesBuilderActiveTab): void {
  activeTab.value = tab;
  isEditorOpen.value = false;
}

function importDefinition(definition: SpeciesBuilderDefinition): void {
  editor.addDefinition(definition);
  openSelectedDefinitionEditor("details");
}

const editorPageEvents = createSpeciesBuilderEditorPageEvents(editor, {
  requestDeleteSubspecies,
  requestSave: unsafeSave.requestSave,
});
</script>

<template>
  <section
    class="app:flex app:min-h-full app:flex-col"
    :aria-busy="isBusy"
    @keydown="stopFormControlKeyPropagation"
    @keyup="stopFormControlKeyPropagation"
  >
    <SpeciesBuilderHeader
      :can-manage-definition="canManageSelectedDefinition"
      :context-label="pageMeta.label"
      :definition-name="currentDefinitionName"
      :is-busy="isBusy"
      @delete="requestDeleteSelectedDefinition"
      @duplicate="editor.duplicateSelectedDefinition"
      @reload="editor.loadSettings"
      @select-species="selectTopLevelTab('species')"
    >
      <template #actions="{ dialogHost }">
        <SpeciesDefinitionPortability
          :definition="
            editor.selectedDefinition.value?.origin === 'custom'
              ? editor.selectedDefinition.value
              : undefined
          "
          :dialog-host="dialogHost"
          :existing-keys="definitionKeys"
          :is-disabled="isBusy"
          :is-import-only="editor.selectedDefinition.value?.origin === 'runtime'"
          @import-definition="importDefinition"
        />
      </template>
    </SpeciesBuilderHeader>
    <DeleteConfirmationSubView
      :message="pendingDelete?.message"
      @close="pendingDelete = null"
      @confirm="confirmPendingDelete"
    />
    <UnsafeSaveConfirmationSubView
      :is-open="unsafeSave.isConfirmationOpen.value"
      @close="unsafeSave.closeConfirmation"
      @confirm="unsafeSave.confirmSave"
    />
    <SpeciesBuilderValidationSummaryDialog
      :definitions="editor.definitions.value"
      :is-open="isValidationSummaryOpen"
      :issues="validationSummaryIssues"
      @close="closeValidationSummary"
      @select-issue="selectValidationIssue"
    />

    <main class="app:flex app:flex-1 app:items-start app:gap-3 app:p-3">
      <SpeciesBuilderNavigation
        :active-editor-tab="activeEditorTab"
        :active-table-tab="activeTableTab"
        :active-tab="activeTab"
        :has-selected-definition="Boolean(editor.selectedDefinition.value)"
        :is-busy="isBusy"
        :is-editor-open="isEditorOpen"
        :show-generated-config-tab="editor.showGeneratedConfigTab.value"
        :validation-counts="navigationValidationCounts"
        @select-editor-tab="openSelectedDefinitionEditor"
        @select-table-tab="openSelectedDefinitionTable"
        @select-tab="selectTopLevelTab"
      />

      <div class="app:flex app:min-w-0 app:flex-1 app:flex-col app:gap-3">
        <SpeciesBuilderStatus
          v-if="hasStatusBanner"
          :chargen-error-count="validationCounts.errors"
          :chargen-warning-count="validationCounts.warnings"
          :load-error="editor.loadError.value || editor.saveError.value"
          :message="editor.message.value"
          :validation-message="editor.blockingSpeciesTableValidationMessages.value[0] ?? ''"
          @review-issues="openValidationSummary"
        />

        <SpeciesBuilderProjectPages
          v-if="!isEditorOpen"
          :active-tab="activeTab"
          :is-disabled="isBusy"
          @edit-species="openDefinitionEditor"
        />

        <SpeciesBuilderEditorPage
          v-else
          id="species-builder-panel-species"
          :active-editor-tab="activeEditorTab"
          :active-table-tab="activeTableTab"
          aria-label="Species editor"
          :definition="editor.selectedDefinition.value"
          :is-loading="editor.isLoading.value"
          :is-saving="editor.isSaving.value"
          :issues="selectedDefinitionIssues"
          :random-talent-sources="editor.randomTalentSources.value"
          :validation-navigation-request="validationNavigationRequest"
          role="region"
          @review-issues="openDefinitionValidationSummary(editor.selectedIndex.value)"
          v-on="editorPageEvents"
        />
      </div>
    </main>

    <SpeciesBuilderEditorContext
      :can-save="editor.canSave.value"
      :definition="isEditorOpen ? editor.selectedDefinition.value : undefined"
      :has-unsaved-changes="editor.hasUnsavedChanges.value"
      :has-validation-errors="hasValidationErrors"
      :has-validation-warnings="hasValidationWarnings"
      :is-loading="editor.isLoading.value"
      :is-saving="editor.isSaving.value"
      :load-error="editor.loadError.value || editor.saveError.value"
      :entity-name="activeTab === 'species-table' ? 'Species Table' : undefined"
      @save="unsafeSave.requestSave"
    />
  </section>
</template>
