import { storeToRefs } from "pinia";

import type { SpeciesBuilderBridge } from "../../types/species-builder/species-builder";
import type { SpeciesBuilderSaveOptions } from "./save-state";

import { useSpeciesBuilderStore } from ".";

interface SpeciesBuilderEditorOptions {
  onSettingsSaved?: (() => void) | undefined;
}

export function useSpeciesBuilderEditor(
  bridge: SpeciesBuilderBridge,
  editorOptions: SpeciesBuilderEditorOptions = {},
) {
  const store = useSpeciesBuilderStore();

  store.configure(bridge);

  async function saveChanges(saveOptions: SpeciesBuilderSaveOptions = {}): Promise<void> {
    const didSaveSettings = await store.saveChanges(saveOptions);

    if (didSaveSettings) {
      editorOptions.onSettingsSaved?.();
    }
  }

  return {
    ...store,
    ...storeToRefs(store),
    saveChanges,
  };
}
