import type {
  SpeciesBuilderValidationIssue,
  SpeciesBuilderValidationSection,
} from "../../../../../../../../../types/species-builder/validation";

export type SubspeciesEditorTab = "changes" | "details" | "tables" | "talents" | "wounds";

export const SUBSPECIES_EDITOR_TABS: Array<{ label: string; tab: SubspeciesEditorTab }> = [
  { label: "Details", tab: "details" },
  { label: "Talents", tab: "talents" },
  { label: "Skills & Traits", tab: "changes" },
  { label: "Wounds", tab: "wounds" },
  { label: "Tables", tab: "tables" },
];

const TAB_SECTIONS: Record<SubspeciesEditorTab, SpeciesBuilderValidationSection[]> = {
  changes: ["skills", "traits"],
  details: ["subspecies", "details", "attributes"],
  tables: ["careerTable", "randomTalents", "talentReplacement", "careerReplacement"],
  talents: ["talents"],
  wounds: ["wounds"],
};

export function subspeciesIssuesForTab(
  issues: SpeciesBuilderValidationIssue[],
  tab: SubspeciesEditorTab,
): SpeciesBuilderValidationIssue[] {
  return issues.filter((issue) => TAB_SECTIONS[tab].includes(issue.section));
}
