import type {
  SpeciesBuilderCareerTableDefinition,
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderWoundFormulaDefinition,
} from "../../../types/species-builder/species-builder";

export type SpeciesBuilderArrayField = "skills" | "talents" | "traits";
export type SpeciesBuilderSubspeciesArrayField =
  | "skillsAdded"
  | "skillsRemoved"
  | "talentsAdded"
  | "talentsRemoved"
  | "traitsAdded"
  | "traitsRemoved";
export type SpeciesBuilderSubspeciesTextMapField = "randomTalents" | "talentReplacements";
export type SpeciesBuilderTextMapField =
  | "careerReplacements"
  | "randomTalents"
  | "talentReplacements";

export function parseStringLines(value: string): string[] | undefined {
  const entries = value
    .split(/\r?\n/)
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0);

  return entries.length > 0 ? entries : undefined;
}

export function parseStringRecordLines(value: string): Record<string, string> | undefined {
  const entries = parseKeyValueLines(value).flatMap(([key, entry]) =>
    entry ? [[key, entry] as const] : [],
  );

  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

export function parseNumberRecordLines(value: string): Record<string, number> | undefined {
  const entries = parseKeyValueLines(value).flatMap(([key, entry]) => {
    const numberValue = normalizeNumberInput(entry);

    return numberValue === undefined ? [] : [[key, numberValue] as const];
  });

  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

export function parseStringArrayRecordLines(value: string): Record<string, string[]> | undefined {
  const entries = parseKeyValueLines(value).flatMap(([key, entry]) => {
    const values = entry
      .split(",")
      .map((item) => item.trim())
      .filter((item) => item.length > 0);

    return values.length > 0 ? [[key, values] as const] : [];
  });

  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

export function normalizeText(value: string): string | undefined {
  const trimmed = value.trim();

  return trimmed.length > 0 ? trimmed : undefined;
}

export function normalizeEditableText(value: string): string | undefined {
  return value.length > 0 ? value : undefined;
}

export function normalizeWoundFormulaInput(
  value: string,
): SpeciesBuilderWoundFormulaDefinition | undefined {
  const formula = normalizeText(value);

  return formula ? { formula } : undefined;
}

export function normalizeCareerTableRows(
  rows: SpeciesBuilderCareerTableRow[],
): SpeciesBuilderCareerTableDefinition | undefined {
  const normalizedRows = rows.map((row) => {
    const normalizedRow: SpeciesBuilderCareerTableRow = { name: row.name };
    const journalUuid = normalizeText(row.journalUuid ?? "");

    if (journalUuid) {
      normalizedRow.journalUuid = journalUuid;
    }

    return normalizedRow;
  });

  return normalizedRows.length > 0 ? { rows: normalizedRows } : undefined;
}

export function normalizeNumberInput(value: string): number | undefined {
  const trimmed = value.trim();

  if (!trimmed) {
    return undefined;
  }

  const numberValue = Number(trimmed);

  return Number.isFinite(numberValue) ? numberValue : undefined;
}

function parseKeyValueLines(value: string): Array<readonly [string, string]> {
  return value.split(/\r?\n/).flatMap((line) => {
    const separatorIndex = line.indexOf(":");

    if (separatorIndex < 0) {
      return [];
    }

    const key = line.slice(0, separatorIndex).trim();
    const entry = line.slice(separatorIndex + 1).trim();

    return key ? [[key, entry] as const] : [];
  });
}
