<script setup lang="ts">
import {
  appendRandomTalentEntry,
  randomTalentEntries,
  randomTalentSourceOptions,
  removeRandomTalentEntry,
  setRandomTalentEntryCount,
  setRandomTalentEntryKey,
  type RandomTalentEntry,
} from "../../../../../../../../../../../functions/species-builder/editor/random-talents";
import type { SpeciesBuilderRandomTalentSource } from "../../../../../../../../../../../types/species-builder/species-builder";

import TableEditorHeader from "../../components/TableEditorHeader.vue";
import {
  hasValidationErrors,
  issuesForField,
  issuesForRow,
  issuesWithoutRow,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../../../../validation-presentation";

const props = defineProps<{
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  sources: SpeciesBuilderRandomTalentSource[];
  values: Record<string, number> | undefined;
}>();

const emit = defineEmits<{
  update: [value: string];
}>();

function entries(): RandomTalentEntry[] {
  return randomTalentEntries(props.values);
}

function addRow(): void {
  emit("update", appendRandomTalentEntry(entries(), props.sources));
}

function updateKey(index: number, key: string): void {
  emit("update", setRandomTalentEntryKey(entries(), index, key));
}

function updateCount(index: number, value: string): void {
  emit("update", setRandomTalentEntryCount(entries(), index, value));
}

function sourceOptions(currentKey: string): SpeciesBuilderRandomTalentSource[] {
  return randomTalentSourceOptions(props.sources, currentKey);
}

function removeRow(index: number): void {
  emit("update", removeRandomTalentEntry(entries(), index));
}

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement || event.target instanceof HTMLSelectElement
    ? event.target.value
    : "";
}

function fieldIssues(field: "count" | "key", rowIndex: number): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, field, rowIndex);
}

function fieldMessages(field: "count" | "key", rowIndex: number): string[] {
  return uniqueIssueMessages(fieldIssues(field, rowIndex));
}

function sectionMessages(): string[] {
  return uniqueIssueMessages(issuesWithoutRow(props.issues));
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <TableEditorHeader
        action-label="Add Source"
        action-title="Add a random Talent source and draw count"
        :count="entries().length"
        description="Choose an available Talent table and the number of draws from that source."
        :is-disabled="isDisabled"
        title="Random Talents"
        @add="addRow"
      />

      <div
        v-if="sectionMessages().length"
        class="dui-alert"
        :class="validationClass(issuesWithoutRow(issues), 'dui-alert-error', 'dui-alert-warning')"
        role="alert"
      >
        <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
        <div>
          <p v-for="message in sectionMessages()" :key="message" class="app:m-0 app:text-xs">
            {{ message }}
          </p>
        </div>
      </div>

      <ul v-if="entries().length > 0" class="dui-list">
        <li
          v-for="([key, count], index) in entries()"
          :key="`random-${index}`"
          class="dui-list-row"
          :class="
            validationClass(
              issuesForRow(issues, index),
              'app:border app:border-error',
              'app:border app:border-warning',
            )
          "
        >
          <span class="dui-badge dui-badge-ghost">{{ index + 1 }}</span>
          <div class="dui-list-col-grow">
            <fieldset class="dui-fieldset">
              <legend class="dui-fieldset-legend">Talent source</legend>
              <select
                :aria-describedby="
                  fieldIssues('key', index).length
                    ? `random-talents-key-${index}-errors`
                    : undefined
                "
                :aria-invalid="hasValidationErrors(fieldIssues('key', index)) || undefined"
                class="dui-select"
                :class="
                  validationClass(
                    fieldIssues('key', index),
                    'dui-select-error',
                    'dui-select-warning',
                  )
                "
                :disabled="isDisabled"
                title="Random Talent table source available in this world."
                :value="key"
                @input="updateKey(index, inputValue($event))"
              >
                <option v-for="source in sourceOptions(key)" :key="source.key" :value="source.key">
                  {{ source.label }}
                </option>
              </select>
              <div
                v-if="fieldMessages('key', index).length"
                :id="`random-talents-key-${index}-errors`"
              >
                <p
                  v-for="message in fieldMessages('key', index)"
                  :key="message"
                  class="app:m-0 app:text-xs"
                  :class="
                    validationClass(fieldIssues('key', index), 'app:text-error', 'app:text-warning')
                  "
                >
                  {{ message }}
                </p>
              </div>
            </fieldset>
            <fieldset class="dui-fieldset">
              <legend class="dui-fieldset-legend">Draws</legend>
              <input
                :aria-describedby="
                  fieldIssues('count', index).length
                    ? `random-talents-count-${index}-errors`
                    : undefined
                "
                :aria-invalid="hasValidationErrors(fieldIssues('count', index)) || undefined"
                class="dui-input"
                :class="
                  validationClass(
                    fieldIssues('count', index),
                    'dui-input-error',
                    'dui-input-warning',
                  )
                "
                :disabled="isDisabled"
                min="0"
                title="How many random Talents this species draws from that table."
                :value="count"
                type="number"
                @input="updateCount(index, inputValue($event))"
              />
              <div
                v-if="fieldMessages('count', index).length"
                :id="`random-talents-count-${index}-errors`"
              >
                <p
                  v-for="message in fieldMessages('count', index)"
                  :key="message"
                  class="app:m-0 app:text-xs"
                  :class="
                    validationClass(
                      fieldIssues('count', index),
                      'app:text-error',
                      'app:text-warning',
                    )
                  "
                >
                  {{ message }}
                </p>
              </div>
            </fieldset>
          </div>
          <button
            :disabled="isDisabled"
            title="Remove this random Talent source"
            class="dui-btn dui-btn-error dui-btn-sm"
            type="button"
            @click="removeRow(index)"
          >
            <i aria-hidden="true" class="fa-solid fa-trash" />
            Remove
          </button>
        </li>
      </ul>
      <div v-else class="dui-alert" role="status">
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>No random Talent draws.</span>
      </div>
    </div>
  </section>
</template>
