import type { NpcTraitDraftEntry } from "../../../../../types/npc-builder";

import { setObjectPath } from "../../../../../shared/object-readers";
import { isFoundryItem } from "../../../../foundry/document-guards";
import {
  applyEmbeddedItemChanges,
  createEmptyEmbeddedItemChanges,
} from "../../../../foundry/embedded-items";
import {
  createItemSourceFromMatch,
  findActorItemByNameAndType,
  findActorItemByUuidOrName,
} from "../../../../foundry/item-sources";
import { findWfrpItemByNameAndType } from "../../../../wfrp4e/item-lookup";
import { applyTraitConfigToSource, createTraitConfigUpdate } from "./config";

export async function applyTraits(
  actor: FoundryActorDocument,
  traits: NpcTraitDraftEntry[],
): Promise<void> {
  const itemChanges = createEmptyEmbeddedItemChanges();

  for (const trait of traits) {
    const existingItem =
      trait.source === "base"
        ? findActorItemByUuidOrName(actor, trait.sourceUuid, trait.name)
        : findActorItemByNameAndType(actor, trait.name, "trait");

    if (trait.ignored) {
      if (existingItem) {
        itemChanges.deletes.push(existingItem.id);
      }

      continue;
    }

    if (existingItem) {
      itemChanges.updates.push(createTraitConfigUpdate(existingItem.id, trait.config));
      continue;
    }

    const sourceItem = trait.sourceUuid
      ? await resolveTraitSourceItem(trait.sourceUuid)
      : await findWfrpItemByNameAndType(trait.name, ["trait"]);
    const itemData = createItemSourceFromMatch(sourceItem, trait.name, "trait");

    itemData["type"] = "trait";
    setObjectPath(itemData, ["system", "disabled"], false);
    applyTraitConfigToSource(itemData, trait.config);
    itemChanges.creates.push(itemData);
  }

  await applyEmbeddedItemChanges(actor, itemChanges);
}

async function resolveTraitSourceItem(uuid: string): Promise<FoundryItemDocument | null> {
  const sourceItem = await fromUuid(uuid);

  return isFoundryItem(sourceItem) ? sourceItem : null;
}
