import { buildWfrpGrantItemsEffect } from "../../functions/item-grants/wfrp-grant-effect";
import { GrantBuilderApplication } from "../apps/grant-builder/GrantBuilderApplication";
import { MODULE_ID } from "../constants";
import { isFoundryItem } from "../foundry/document-guards";
import {
  createGrantItemReference,
  getDroppedItemData,
  resolveDroppedItem,
} from "./grant/item-documents";

const SUPPORTED_CARRIER_ITEM_TYPES = new Set(["talent", "trait"]);
const hookedSheetRoots = new WeakSet<HTMLElement>();
let hasRegisteredItemEffectDropHook = false;
const GRANT_BUILDER_BUTTON_CLASS = "wfrp4e-customizer-grant-builder-button";
const EFFECT_TAB_ACTIVE_SELECTOR = [
  'section[data-application-part="effects"].active',
  'section[data-tab="effects"].active',
  '.tab[data-tab="effects"].active',
  ".tab.effects.active",
].join(",");
const EFFECT_TAB_SELECTOR = [
  'section[data-application-part="effects"]',
  'section[data-tab="effects"]',
  '.tab[data-tab="effects"]',
  ".tab.effects",
].join(",");

export function registerWfrpItemEffectDropHooks(): void {
  if (hasRegisteredItemEffectDropHook) {
    return;
  }

  hasRegisteredItemEffectDropHook = true;

  Hooks.on("renderApplicationV2", (application, html) => {
    if (!(html instanceof HTMLElement)) {
      return;
    }

    const item = getRenderedItem(application);

    if (!item || !SUPPORTED_CARRIER_ITEM_TYPES.has(item.type)) {
      return;
    }

    registerEffectTabDropHandlers(item, html);
    insertGrantBuilderButton(item, html);
  });
}

function registerEffectTabDropHandlers(item: FoundryItemDocument, html: HTMLElement): void {
  if (hookedSheetRoots.has(html)) {
    return;
  }

  hookedSheetRoots.add(html);

  html.addEventListener(
    "dragover",
    (event) => {
      if (!isEffectTabDropContext(html, event.target)) {
        return;
      }

      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.dropEffect = "copy";
      }
    },
    true,
  );

  html.addEventListener(
    "drop",
    (event) => {
      void handleEffectTabDrop(item, html, event);
    },
    true,
  );
}

function insertGrantBuilderButton(item: FoundryItemDocument, html: HTMLElement): void {
  if (html.querySelector(`.${GRANT_BUILDER_BUTTON_CLASS}`)) {
    return;
  }

  const effectsTab = findEffectTabContent(html, { includeInactive: true });

  if (!effectsTab) {
    return;
  }

  const toolbar = document.createElement("div");
  toolbar.classList.add("wfrp4e-customizer-grant-builder-toolbar");

  const button = document.createElement("button");
  button.type = "button";
  button.classList.add(GRANT_BUILDER_BUTTON_CLASS);
  button.title = "Open the advanced item grant builder";
  button.innerHTML =
    '<i class="fa-solid fa-sitemap" aria-hidden="true"></i><span>Grant Builder</span>';
  button.addEventListener("click", () => {
    void new GrantBuilderApplication(item).render(true);
  });

  toolbar.append(button);
  effectsTab.prepend(toolbar);
}

async function handleEffectTabDrop(
  carrierItem: FoundryItemDocument,
  html: HTMLElement,
  event: DragEvent,
): Promise<void> {
  if (!isEffectTabDropContext(html, event.target)) {
    return;
  }

  const dropData = getDroppedItemData(event);

  if (!dropData) {
    return;
  }

  event.preventDefault();
  event.stopPropagation();

  try {
    const droppedItem = await resolveDroppedItem(dropData);

    if (droppedItem.uuid === carrierItem.uuid) {
      throw new Error("An Item cannot grant itself.");
    }

    const itemReference = createGrantItemReference(droppedItem);
    const effectName = `Grant ${droppedItem.name}`;
    const effectSource = buildWfrpGrantItemsEffect({
      effectName,
      flagScope: MODULE_ID,
      items: [itemReference],
    });

    if (!carrierItem.createEmbeddedDocuments) {
      throw new Error("This Item sheet does not support creating Active Effects.");
    }

    await carrierItem.createEmbeddedDocuments("ActiveEffect", [effectSource]);
    ui.notifications?.info(`Added grant effect for "${droppedItem.name}".`);
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "The dropped Item could not be converted.";
    ui.notifications?.warn?.(message);
  }
}

function getRenderedItem(application: unknown): FoundryItemDocument | null {
  if (typeof application !== "object" || application === null) {
    return null;
  }

  const item = "item" in application ? application.item : undefined;

  if (isFoundryItem(item)) {
    return item;
  }

  const document = "document" in application ? application.document : undefined;

  return isFoundryItem(document) ? document : null;
}

function isEffectTabDropContext(root: HTMLElement, target: EventTarget | null): boolean {
  if (!(target instanceof Element)) {
    return false;
  }

  if (!root.contains(target)) {
    return false;
  }

  if (getEffectTab(root)) {
    return true;
  }

  return false;
}

function getEffectTab(root: HTMLElement): HTMLElement | null {
  const activeEffectTab = root.querySelector<HTMLElement>(EFFECT_TAB_ACTIVE_SELECTOR);

  if (activeEffectTab) {
    return activeEffectTab;
  }

  return findEffectTabContent(root, { includeInactive: false });
}

function findEffectTabContent(
  root: HTMLElement,
  options: { includeInactive: boolean },
): HTMLElement | null {
  return (
    [...root.querySelectorAll<HTMLElement>(EFFECT_TAB_SELECTOR)].find(
      (element) => options.includeInactive || element.offsetParent !== null,
    ) ?? null
  );
}
