import { ref, type ComputedRef } from "vue";

import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

type PendingDelete =
  | {
      index: number;
      kind: "subspecies";
      message: string;
    }
  | {
      kind: "species";
      message: string;
    };

interface SpeciesBuilderDeletionOptions {
  deleteDefinition: () => void;
  deleteSubspecies: (index: number) => void;
  selectedDefinition: ComputedRef<SpeciesBuilderDefinition | undefined>;
}

export function useSpeciesBuilderDeletion(options: SpeciesBuilderDeletionOptions) {
  const pendingDelete = ref<null | PendingDelete>(null);

  function requestDeleteDefinition(): void {
    const definition = options.selectedDefinition.value;

    if (!definition) {
      return;
    }

    pendingDelete.value = {
      kind: "species",
      message: `Delete species "${definitionLabel(definition)}"?`,
    };
  }

  function requestDeleteSubspecies(index: number): void {
    const subspecies = options.selectedDefinition.value?.subspecies?.[index];

    if (!subspecies) {
      return;
    }

    pendingDelete.value = {
      index,
      kind: "subspecies",
      message: `Delete subspecies "${definitionLabel(subspecies)}"?`,
    };
  }

  function confirmPendingDelete(): void {
    const request = pendingDelete.value;

    if (request?.kind === "species") {
      options.deleteDefinition();
    } else if (request?.kind === "subspecies") {
      options.deleteSubspecies(request.index);
    }

    pendingDelete.value = null;
  }

  return {
    confirmPendingDelete,
    pendingDelete,
    requestDeleteDefinition,
    requestDeleteSubspecies,
  };
}

function definitionLabel(definition: { key: string; name: string }): string {
  return definition.name.trim() || definition.key.trim() || "Untitled Species";
}
