<script setup lang="ts">
import { computed } from "vue";

import type { SpeciesBuilderSubspeciesDefinition } from "../../../../../../../../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../../../../../../../../types/wfrp4e/characteristics";
import type { SpeciesBuilderStatField } from "../../support/field-definitions";
import type { SpeciesBuilderValidationIssue } from "../../../../../../../../../types/species-builder/validation";

import { getSuggestedSubspeciesKey } from "../../../../species-key-suggestions";
import CharacteristicFields from "../attributes/CharacteristicFields.vue";
import StatFields from "../attributes/StatFields.vue";
import {
  hasValidationErrors,
  issuesForField,
  uniqueIssueMessages,
  validationClass,
} from "../../validation-presentation";

const props = defineProps<{
  index: number;
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  subspecies: SpeciesBuilderSubspeciesDefinition;
}>();

const emit = defineEmits<{
  updateCharacteristic: [key: WfrpCharacteristicKey, value: string];
  updateNumberField: [field: SpeciesBuilderStatField, value: string];
  updateStringField: [field: "key" | "name", value: string];
}>();
const issueMessages = computed(() => uniqueIssueMessages(props.issues));

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement ? event.target.value : "";
}

function fieldIssues(field: "key" | "name"): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, field);
}

function fieldMessages(field: "key" | "name"): string[] {
  return uniqueIssueMessages(fieldIssues(field));
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <div
        v-if="issueMessages.length"
        class="dui-alert"
        :class="validationClass(issues, 'dui-alert-error', 'dui-alert-warning')"
        role="alert"
      >
        <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
        <div>
          <p v-for="message in issueMessages" :key="message" class="app:m-0 app:text-xs">
            {{ message }}
          </p>
        </div>
      </div>

      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">Identity</legend>
        <p class="dui-fieldset-label">
          Name this variant and give it a unique key under its parent species.
        </p>
        <table class="dui-table dui-table-sm">
          <tbody>
            <tr>
              <th scope="row"><label :for="`subspecies-${index}-name`">Name</label></th>
              <td>
                <input
                  :id="`subspecies-${index}-name`"
                  class="dui-input dui-input-sm"
                  :class="
                    validationClass(fieldIssues('name'), 'dui-input-error', 'dui-input-warning')
                  "
                  :aria-invalid="hasValidationErrors(fieldIssues('name')) || undefined"
                  :disabled="isDisabled"
                  :value="subspecies.name"
                  type="text"
                  @input="emit('updateStringField', 'name', inputValue($event))"
                />
                <p
                  v-for="message in fieldMessages('name')"
                  :key="message"
                  class="app:m-0 app:text-xs"
                  :class="
                    validationClass(fieldIssues('name'), 'app:text-error', 'app:text-warning')
                  "
                >
                  {{ message }}
                </p>
              </td>
            </tr>
            <tr>
              <th scope="row"><label :for="`subspecies-${index}-key`">Key</label></th>
              <td>
                <input
                  :id="`subspecies-${index}-key`"
                  class="dui-input dui-input-sm"
                  :class="
                    validationClass(fieldIssues('key'), 'dui-input-error', 'dui-input-warning')
                  "
                  :aria-invalid="hasValidationErrors(fieldIssues('key')) || undefined"
                  :disabled="isDisabled"
                  :placeholder="getSuggestedSubspeciesKey(subspecies)"
                  :value="subspecies.key"
                  type="text"
                  @input="emit('updateStringField', 'key', inputValue($event))"
                />
                <p
                  v-for="message in fieldMessages('key')"
                  :key="message"
                  class="app:m-0 app:text-xs"
                  :class="validationClass(fieldIssues('key'), 'app:text-error', 'app:text-warning')"
                >
                  {{ message }}
                </p>
              </td>
            </tr>
          </tbody>
        </table>
      </fieldset>

      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">Characteristic Overrides</legend>
        <p class="dui-fieldset-label">
          Enter only formulas that replace the parent species characteristic value.
        </p>
        <CharacteristicFields
          :characteristics="subspecies.characteristics"
          :is-disabled="isDisabled"
          :issues="issues"
          @update="(key, value) => emit('updateCharacteristic', key, value)"
        />
      </fieldset>

      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">Resource Overrides</legend>
        <p class="dui-fieldset-label">Leave a value blank to keep the parent species value.</p>
        <StatFields
          :fields="['movement', 'fate', 'resilience', 'extra']"
          :is-disabled="isDisabled"
          :issues="issues"
          :values="subspecies"
          @update="(field, value) => emit('updateNumberField', field, value)"
        />
      </fieldset>
    </div>
  </section>
</template>
