import type {
  SpeciesBuilderExamplePackage,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../../types/species-builder/species-builder";

import { careers, subspecies } from "./shared";

export function createMonstrousHumanPackage(includedKeys?: string[]): SpeciesBuilderExamplePackage {
  const included = includedKeys ? new Set(includedKeys) : undefined;
  const variants = createHumanVariants().filter(
    (variant) => !included || included.has(variant.key),
  );

  return {
    definitions: [],
    runtimeSpeciesExtensions: [
      {
        speciesKey: "human",
        speciesName: "Human",
        subspecies: variants,
      },
    ],
  };
}

