import type {
  SpeciesBuilderValidationIssue,
  SpeciesBuilderValidationSeverity,
} from "../../../../../types/species-builder/validation";

export interface SpeciesBuilderValidationIndicator {
  count: number;
  severity: SpeciesBuilderValidationSeverity;
}

export function addValidationIssueToIndicator(
  indicator: SpeciesBuilderValidationIndicator | undefined,
  issue: SpeciesBuilderValidationIssue,
): SpeciesBuilderValidationIndicator {
  return {
    count: (indicator?.count ?? 0) + 1,
    severity:
      indicator?.severity === "error" || validationIssueSeverity(issue) === "error"
        ? "error"
        : "warning",
  };
}

export function summarizeValidationIssues(
  issues: SpeciesBuilderValidationIssue[],
): SpeciesBuilderValidationIndicator | undefined {
  return issues.reduce<SpeciesBuilderValidationIndicator | undefined>(
    (indicator, issue) => addValidationIssueToIndicator(indicator, issue),
    undefined,
  );
}

export function validationIndicatorLabel(
  indicator: SpeciesBuilderValidationIndicator | undefined,
): string {
  if (!indicator) {
    return "";
  }

  const noun = indicator.severity === "error" ? "error" : "warning";

  return `${indicator.count} character-creation ${noun}${indicator.count === 1 ? "" : "s"}`;
}

export function validationIssueSeverity(
  issue: SpeciesBuilderValidationIssue,
): SpeciesBuilderValidationSeverity {
  return issue.severity === "warning" ? "warning" : "error";
}
