import type {
  GrantItemReference,
  GrantItemsEffectInput,
  GrantItemsEffectRecipe,
  GrantItemsEffectSource,
} from "../../types/item-grants";

const GENERATED_GRANT_EFFECT_FLAG = "generatedGrantItemsEffect";
const DEFAULT_GRANT_RECIPE: GrantItemsEffectRecipe = {
  grantMode: "all",
  lifetime: "linked-to-effect",
  ownerAction: "keep",
};

export function buildWfrpGrantItemsEffect(input: GrantItemsEffectInput): GrantItemsEffectSource {
  const recipe = input.recipe ?? DEFAULT_GRANT_RECIPE;
  validateGrantRecipe(recipe);

  const itemUuids = input.items.map((item) => item.uuid);
  const description = buildGrantEffectDescription(input.effectName, input.items, recipe);

  return {
    changes: [],
    description,
    disabled: false,
    flags: {
      [input.flagScope]: {
        [GENERATED_GRANT_EFFECT_FLAG]: true,
        itemUuids,
        recipe,
      },
    },
    img: input.items[0]?.img ?? "icons/svg/aura.svg",
    name: input.effectName,
    system: {
      scriptData: [
        {
          label: input.effectName,
          script: buildGrantItemsScript(itemUuids, recipe),
          trigger: "addItems",
        },
      ],
      transferData: {
        documentType: "Item",
        type: "document",
      },
    },
    transfer: true,
  };
}

function validateGrantRecipe(recipe: GrantItemsEffectRecipe): void {
  if (recipe.lifetime === "linked-to-effect" && recipe.ownerAction === "delete-after-grant") {
    throw new Error("Self-removing grant effects must create detached item copies.");
  }
}

function buildGrantItemsScript(itemUuids: string[], recipe: GrantItemsEffectRecipe): string {
  const createOptions =
    recipe.lifetime === "linked-to-effect" ? "{ fromEffect: this.effect.id }" : "{}";
  const ownerCleanupLines =
    recipe.ownerAction === "delete-after-grant"
      ? [
          "",
          "if (this.item) {",
          "  await this.item.delete({ skipDeletingItems: true });",
          '  this.script.notification("Removed " + this.item.name + " after granting items.");',
          "} else {",
          '  this.script.notification("Could not remove the source item after granting items.", "warn");',
          "}",
        ]
      : [];

  return [
    "// Generated by Drowsy's WFRP4e Customizers.",
    `const itemUuids = ${JSON.stringify(itemUuids, null, 2)};`,
    "const itemDataToCreate = [];",
    "",
    "for (const uuid of itemUuids) {",
    "  const sourceItem = await fromUuid(uuid);",
    "  if (!sourceItem) {",
    '    this.script.notification("Could not resolve Item UUID: " + uuid, "warn");',
    "    continue;",
    "  }",
    "",
    "  const itemData = sourceItem.toObject();",
    "  delete itemData._id;",
    "  itemDataToCreate.push(itemData);",
    "}",
    "",
    "if (itemDataToCreate.length) {",
    `  await this.actor.createEmbeddedDocuments("Item", itemDataToCreate, ${createOptions});`,
    '  this.script.notification("Added " + itemDataToCreate.length + " granted item(s).");',
    "} else {",
    '  this.script.notification("No granted items were added.", "warn");',
    "}",
    ...ownerCleanupLines,
  ].join("\n");
}

function buildGrantEffectDescription(
  effectName: string,
  items: GrantItemReference[],
  recipe: GrantItemsEffectRecipe,
): string {
  const escapedName = escapeHtml(effectName);
  const itemRows = items.map((item) => `<li>${escapeHtml(item.name)}</li>`).join("");
  const lifetimeText =
    recipe.lifetime === "linked-to-effect"
      ? "granted item copies are removed with this effect"
      : "granted item copies remain after this effect is removed";
  const ownerActionText =
    recipe.ownerAction === "delete-after-grant"
      ? " The source Item removes itself after granting."
      : "";

  return `<p><strong>${escapedName}</strong>: grants item copies; ${lifetimeText}.${ownerActionText}</p><ul>${itemRows}</ul>`;
}

function escapeHtml(value: string): string {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}
