import { isRecord } from "../../../../shared/object-readers";

export const RUNTIME_SPECIES_RECORD_FIELDS = [
  "species",
  "speciesAge",
  "speciesCareerReplacements",
  "speciesCharacteristics",
  "speciesExtra",
  "speciesFate",
  "speciesHeight",
  "speciesMovement",
  "speciesRandomTalents",
  "speciesRes",
  "speciesSkills",
  "speciesTalentReplacement",
  "speciesTalents",
  "speciesTraits",
  "subspecies",
] as const;

export type RuntimeSpeciesRecordField = (typeof RUNTIME_SPECIES_RECORD_FIELDS)[number];

export interface RuntimeSpeciesConfigSnapshot {
  extraSpecies: string[];
  records: Record<RuntimeSpeciesRecordField, Record<string, unknown>>;
}

export function captureRuntimeSpeciesSnapshot(source: unknown): RuntimeSpeciesConfigSnapshot {
  const config = isRecord(source) ? source : {};
  const records = Object.fromEntries(
    RUNTIME_SPECIES_RECORD_FIELDS.map((field) => [field, cloneRecord(config[field])]),
  ) as RuntimeSpeciesConfigSnapshot["records"];

  return {
    extraSpecies: readStringArray(config["extraSpecies"]),
    records,
  };
}

export function mergeRuntimeSpeciesSnapshots(
  captured: RuntimeSpeciesConfigSnapshot,
  current: RuntimeSpeciesConfigSnapshot,
  excludedSpeciesKeys: ReadonlySet<string>,
): RuntimeSpeciesConfigSnapshot {
  const records = Object.fromEntries(
    RUNTIME_SPECIES_RECORD_FIELDS.map((field) => [
      field,
      mergeRecordField(field, captured.records[field], current.records[field], excludedSpeciesKeys),
    ]),
  ) as RuntimeSpeciesConfigSnapshot["records"];

  return {
    extraSpecies: uniqueStrings([...captured.extraSpecies, ...current.extraSpecies]).filter(
      (key) => !excludedSpeciesKeys.has(key) || captured.extraSpecies.includes(key),
    ),
    records,
  };
}

export function runtimeConfigEntry(
  snapshot: RuntimeSpeciesConfigSnapshot,
  field: RuntimeSpeciesRecordField,
  key: string,
): unknown {
  return snapshot.records[field][key];
}

function mergeRecordField(
  field: RuntimeSpeciesRecordField,
  captured: Record<string, unknown>,
  current: Record<string, unknown>,
  excludedSpeciesKeys: ReadonlySet<string>,
): Record<string, unknown> {
  const merged =
    field === "subspecies" ? mergeSubspecies(captured, current) : { ...captured, ...current };

  for (const key of excludedSpeciesKeys) {
    if (Object.hasOwn(captured, key)) {
      merged[key] = cloneConfigValue(captured[key]);
    } else {
      delete merged[key];
    }
  }

  return merged;
}

function mergeSubspecies(
  captured: Record<string, unknown>,
  current: Record<string, unknown>,
): Record<string, unknown> {
  const speciesKeys = new Set([...Object.keys(captured), ...Object.keys(current)]);

  return Object.fromEntries(
    [...speciesKeys].map((key) => {
      const early = isRecord(captured[key]) ? captured[key] : {};
      const ready = isRecord(current[key]) ? current[key] : {};

      return [key, { ...early, ...ready }];
    }),
  );
}

function cloneRecord(value: unknown): Record<string, unknown> {
  if (!isRecord(value)) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(value).map(([key, entry]) => [key, cloneConfigValue(entry)]),
  );
}

export function cloneConfigValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(cloneConfigValue);
  }

  if (isRecord(value)) {
    return Object.fromEntries(
      Object.entries(value).map(([key, entry]) => [key, cloneConfigValue(entry)]),
    );
  }

  return value;
}

function readStringArray(value: unknown): string[] {
  return Array.isArray(value)
    ? value.flatMap((entry) => (typeof entry === "string" && entry.trim() ? [entry.trim()] : []))
    : [];
}

function uniqueStrings(values: string[]): string[] {
  return [...new Set(values)];
}
