import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderExamplePackage,
  SpeciesBuilderExampleSpeciesOption,
} from "../../../types/species-builder/species-builder";

import {
  createAllMonsterSpeciesPackage,
  MONSTER_SPECIES_EXAMPLES,
} from "./monster-species/catalog";
import { definitionPackage } from "./monster-species/shared";
import { createViltrumiteExampleDefinition } from "./viltrumite";

interface SpeciesBuilderExample extends SpeciesBuilderExampleSpeciesOption {
  createPackage: () => SpeciesBuilderExamplePackage;
}

const EXAMPLE_SPECIES: SpeciesBuilderExample[] = [
  ...MONSTER_SPECIES_EXAMPLES,
  {
    createPackage: () => definitionPackage(createViltrumiteExampleDefinition()),
    description: "A deliberately extreme species for stress-testing formulas and generated Traits.",
    id: "viltrumite",
    label: "Viltrumite (stress test)",
  },
].sort((left, right) => left.label.localeCompare(right.label));

export const EXAMPLE_SPECIES_OPTIONS: SpeciesBuilderExampleSpeciesOption[] = EXAMPLE_SPECIES.map(
  ({ description, id, label }) => ({
    description,
    id,
    label,
  }),
);

export function createAllExampleSpeciesDefinitions(): SpeciesBuilderDefinition[] {
  return createAllExampleSpeciesPackage().definitions;
}

export function createAllExampleSpeciesPackage(): SpeciesBuilderExamplePackage {
  const monsterPackage = createAllMonsterSpeciesPackage();

  return {
    definitions: [createViltrumiteExampleDefinition(), ...monsterPackage.definitions],
    runtimeSpeciesExtensions: monsterPackage.runtimeSpeciesExtensions,
  };
}

export function createExampleSpeciesDefinition(id: string): SpeciesBuilderDefinition | undefined {
  return createExampleSpeciesPackage(id)?.definitions[0];
}

export function createExampleSpeciesPackage(id: string): SpeciesBuilderExamplePackage | undefined {
  return EXAMPLE_SPECIES.find((example) => example.id === id)?.createPackage();
}

export { createGoblinExampleDefinition, createNightGoblinExampleDefinition } from "./goblins";
export { createViltrumiteExampleDefinition };
