<script setup lang="ts">
import type { SpeciesBuilderCareerReplacementRow } from "../../../../../../../../../../../types/species-builder/species-builder";

import {
  appendCareerReplacementChoice,
  appendCareerReplacementRow,
  careerReplacementRowsFromRecord,
  removeCareerReplacementChoice,
  removeCareerReplacementRow,
} from "../../../../../../../../../../../functions/species-builder/editor/replacements";
import LinkedItemDropField from "../../components/LinkedItemDropField.vue";
import TableEditorHeader from "../../components/TableEditorHeader.vue";
import {
  issuesForChoice,
  issuesForField,
  issuesForRow,
  issuesWithoutRow,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../../../../validation-presentation";

const props = defineProps<{
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  rows: SpeciesBuilderCareerReplacementRow[] | undefined;
  values: Record<string, string[]> | undefined;
}>();

const emit = defineEmits<{
  dropReplacement: [rowIndex: number, replacementIndex: number, data: string];
  dropRolled: [rowIndex: number, data: string];
  openItem: [uuid: string];
  updateRows: [rows: SpeciesBuilderCareerReplacementRow[]];
}>();

function replacementRows(): SpeciesBuilderCareerReplacementRow[] {
  return props.rows?.length ? props.rows : careerReplacementRowsFromRecord(props.values);
}

function addRow(): void {
  emit("updateRows", appendCareerReplacementRow(replacementRows()));
}

function addChoice(index: number): void {
  emit("updateRows", appendCareerReplacementChoice(replacementRows(), index));
}

function removeChoice(entryIndex: number, choiceIndex: number): void {
  emit("updateRows", removeCareerReplacementChoice(replacementRows(), entryIndex, choiceIndex));
}

function removeRow(index: number): void {
  emit("updateRows", removeCareerReplacementRow(replacementRows(), index));
}

function sectionMessages(): string[] {
  return uniqueIssueMessages(issuesWithoutRow(props.issues));
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <TableEditorHeader
        action-label="Add Rule"
        action-title="Add a rolled Career and replacement choices"
        :count="replacementRows().length"
        description="Offer one or more replacement Careers for a rolled Career group."
        :is-disabled="isDisabled"
        title="Career Replacements"
        @add="addRow"
      />

      <div
        v-if="sectionMessages().length"
        class="dui-alert"
        :class="validationClass(issuesWithoutRow(issues), 'dui-alert-error', 'dui-alert-warning')"
        role="alert"
      >
        <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
        <div>
          <p v-for="message in sectionMessages()" :key="message" class="app:m-0 app:text-xs">
            {{ message }}
          </p>
        </div>
      </div>

      <ul v-if="replacementRows().length > 0" class="dui-list">
        <li
          v-for="(row, index) in replacementRows()"
          :key="`career-replacement-${index}`"
          class="dui-list-row"
          :class="
            validationClass(
              issuesForRow(issues, index),
              'app:border app:border-error',
              'app:border app:border-warning',
            )
          "
        >
          <span class="dui-badge dui-badge-ghost">Rule {{ index + 1 }}</span>
          <div class="dui-list-col-grow">
            <LinkedItemDropField
              description="Drop the Career result that should allow replacement choices."
              :is-disabled="isDisabled"
              :issues="issuesForField(issues, 'rolled', index)"
              label="Rolled Career"
              title="Drop Rolled Career"
              :value="row.rolled"
              @drop-data="(data) => emit('dropRolled', index, data)"
              @open-item="(uuid) => emit('openItem', uuid)"
            />

            <strong>Replacement choices</strong>
            <ul class="dui-list">
              <li
                v-for="(replacement, replacementIndex) in row.replacements"
                :key="`${index}-${replacementIndex}`"
                class="dui-list-row"
                :class="
                  validationClass(
                    issuesForChoice(issues, index, replacementIndex),
                    'app:border app:border-error',
                    'app:border app:border-warning',
                  )
                "
              >
                <span class="dui-badge dui-badge-ghost">{{ replacementIndex + 1 }}</span>
                <LinkedItemDropField
                  class="dui-list-col-grow"
                  description="Drop one Career offered instead of the rolled Career."
                  :is-disabled="isDisabled"
                  :issues="issuesForField(issues, 'replacement', index, replacementIndex)"
                  label="Replacement Career"
                  title="Drop Replacement Career"
                  :value="replacement"
                  @drop-data="(data) => emit('dropReplacement', index, replacementIndex, data)"
                  @open-item="(uuid) => emit('openItem', uuid)"
                />
                <button
                  :disabled="isDisabled"
                  title="Remove this replacement Career choice"
                  class="dui-btn dui-btn-error dui-btn-sm"
                  type="button"
                  @click="removeChoice(index, replacementIndex)"
                >
                  <i aria-hidden="true" class="fa-solid fa-xmark" />
                  Remove
                </button>
              </li>
            </ul>
          </div>
          <div class="dui-join">
            <button
              class="dui-btn dui-btn-sm dui-join-item"
              :disabled="isDisabled"
              title="Add another replacement Career choice"
              type="button"
              @click="addChoice(index)"
            >
              <i aria-hidden="true" class="fa-solid fa-plus" />
              Choice
            </button>
            <button
              :disabled="isDisabled"
              title="Remove this Career replacement rule"
              class="dui-btn dui-btn-error dui-btn-sm dui-join-item"
              type="button"
              @click="removeRow(index)"
            >
              <i aria-hidden="true" class="fa-solid fa-trash" />
              Remove Rule
            </button>
          </div>
        </li>
      </ul>
      <div v-else class="dui-alert" role="status">
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>No Career replacements.</span>
      </div>
    </div>
  </section>
</template>
