<script setup lang="ts">
import type { SpeciesItemReference } from "../../../types/species-builder/species-item";
import { useSpeciesItemStore } from "../../../state/species-item";
const props = defineProps<{
  uuid: string;
  label: string;
  reference: SpeciesItemReference;
  editable: boolean;
}>();
const emit = defineEmits<{ "clear": []; "drop-data": [data: string] }>();
const store = useSpeciesItemStore(props.uuid);
function drop(event: DragEvent): void {
  if (props.editable && event.dataTransfer)
    emit("drop-data", event.dataTransfer.getData("text/plain"));
}
</script>

<template>
  <div
    class="app:flex app:flex-wrap app:items-center app:gap-2"
    @dragover.prevent
    @drop.prevent="drop"
  >
    <span class="dui-label">{{ label }}</span>
    <button
      v-if="reference.uuid"
      type="button"
      class="dui-btn dui-btn-sm"
      @click="store.openReference(reference.uuid)"
    >
      {{ reference.name || label }}
    </button>
    <span v-else>Drop {{ label === "Subspecies Of" ? "a Species Item" : "a RollTable" }} here</span>
    <button
      v-if="editable && (reference.uuid || reference.id)"
      type="button"
      class="dui-btn dui-btn-sm"
      :aria-label="`Clear ${label}`"
      @click="emit('clear')"
    >
      Clear
    </button>
  </div>
</template>
