<script setup lang="ts">
import { computed, nextTick, ref, watch } from "vue";

import type {
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderRandomTalentSource,
  SpeciesBuilderSubspeciesDefinition,
  SpeciesBuilderTalentReplacementRow,
} from "../../../../../../../../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../../../../../../../../types/wfrp4e/characteristics";
import type { SpeciesBuilderStatField } from "../../support/field-definitions";
import type { RandomTableTab } from "../tables/random-table-events";
import type { SpeciesBuilderValidationIssue } from "../../../../../../../../../types/species-builder/validation";
import type { SpeciesBuilderValidationNavigationRequest } from "../../../../../../components/validation/species-builder-validation-summary";
import type {
  SpeciesBuilderSubspeciesArrayField,
  SpeciesBuilderSubspeciesTextMapField,
  SpeciesBuilderTextMapField,
} from "../../../../../../../../../functions/species-builder/editor/field-values";

import RandomTablesSection from "../tables/RandomTablesSection.vue";
import SpeciesBuilderEditorContext from "../../../../../../components/SpeciesBuilderEditorContext.vue";
import { useDialogFocusReturn } from "../../../../../../components/dialog-focus";
import SubspeciesChangesTab from "./SubspeciesChangesTab.vue";
import SubspeciesDetailsTab from "./SubspeciesDetailsTab.vue";
import SubspeciesEditorHeader from "./SubspeciesEditorHeader.vue";
import SubspeciesEditorTabs from "./SubspeciesEditorTabs.vue";
import SubspeciesTalentInheritance from "./SubspeciesTalentInheritance.vue";
import SubspeciesWoundsPanel from "./SubspeciesWoundsPanel.vue";
import { useSpeciesBuilderStore } from "../../../../../../../../../state/species-builder";
import { subspeciesIssuesForTab, type SubspeciesEditorTab } from "./subspecies-editor-tabs";
import { getRequestedSubspeciesTabs } from "../../../../../../components/validation/species-builder-validation-summary";

const props = withDefaults(
  defineProps<{
    index: number;
    initialTab?: SubspeciesEditorTab;
    initialTableTab?: RandomTableTab;
    isLoading: boolean;
    isOpen: boolean;
    isReadOnly: boolean;
    isSaving: boolean;
    issues: SpeciesBuilderValidationIssue[];
    parentDefinition: SpeciesBuilderEditingDefinition;
    parentTalents: string[];
    randomTalentSources: SpeciesBuilderRandomTalentSource[];
    subspecies: SpeciesBuilderSubspeciesDefinition | undefined;
    standalone?: boolean;
    validationNavigationRequest?: SpeciesBuilderValidationNavigationRequest;
    woundFormulaTraitName: string;
  }>(),
  {
    initialTab: "details",
    initialTableTab: "careerTable",
    standalone: false,
    validationNavigationRequest: undefined,
  },
);

const emit = defineEmits<{
  close: [];
  delete: [index: number];
  openItem: [uuid: string];
  openWoundFormula: [];
  save: [];
  careerTableCareerDrop: [index: number, rowIndex: number, data: string];
  careerTableJournalDrop: [index: number, rowIndex: number, data: string];
  talentDrop: [index: number, data: string];
  talentReplacementReplacementDrop: [index: number, rowIndex: number, data: string];
  talentReplacementRolledDrop: [index: number, rowIndex: number, data: string];
  updateArrayField: [index: number, field: SpeciesBuilderSubspeciesArrayField, value: string];
  updateCharacteristic: [index: number, key: WfrpCharacteristicKey, value: string];
  updateNumberField: [index: number, field: SpeciesBuilderStatField, value: string];
  updateStringField: [index: number, field: "key" | "name", value: string];
  updateCareerTableRows: [index: number, rows: SpeciesBuilderCareerTableRow[]];
  updateWoundFormula: [index: number, value: string];
  updateTalentReplacementRows: [index: number, rows: SpeciesBuilderTalentReplacementRow[]];
  updateTextMapField: [index: number, field: SpeciesBuilderSubspeciesTextMapField, value: string];
}>();

const activeTab = ref<SubspeciesEditorTab>(props.initialTab);
const activeTableTab = ref<RandomTableTab>(props.initialTableTab);
const consumedValidationSequence = ref(-1);
const dialog = ref<HTMLElement>();
const dialogFocus = useDialogFocusReturn();
const store = useSpeciesBuilderStore();
const isBusy = computed(() => props.isLoading || props.isSaving);
const controlsDisabled = computed(() => isBusy.value || props.isReadOnly);
const hasValidationErrors = computed(
  () =>
    store.blockingValidationIssues.length > 0 ||
    store.blockingSpeciesTableValidationMessages.length > 0,
);
const hasValidationWarnings = computed(() =>
  store.validationIssues.some((issue) => issue.severity === "warning"),
);

function updateMappedField(field: SpeciesBuilderTextMapField, value: string): void {
  if (field === "careerReplacements") {
    return;
  }

  emit("updateTextMapField", props.index, field, value);
}

function issuesForTab(tab: SubspeciesEditorTab): SpeciesBuilderValidationIssue[] {
  return subspeciesIssuesForTab(props.issues, tab);
}

function closeDialog(): void {
  if (props.standalone) {
    emit("close");
  } else if (dialog.value instanceof HTMLDialogElement) {
    dialog.value.close();
  }
}

function handleDialogClosed(): void {
  if (props.isOpen) {
    emit("close");
  }

  dialogFocus.restore();
}

watch(
  () => props.isOpen,
  async (isOpen) => {
    if (props.standalone) {
      activeTab.value = props.initialTab;
      activeTableTab.value = props.initialTableTab;
      return;
    }

    if (isOpen) {
      const request = props.validationNavigationRequest;
      const requestedTabs =
        request?.sequence !== consumedValidationSequence.value
          ? getRequestedSubspeciesTabs(request, props.index)
          : undefined;

      consumedValidationSequence.value = request?.sequence ?? consumedValidationSequence.value;
      activeTab.value = requestedTabs?.tab ?? "details";
      activeTableTab.value = requestedTabs?.tableTab ?? "careerTable";
      dialogFocus.capture();
      await nextTick();

      if (props.isOpen && dialog.value instanceof HTMLDialogElement && !dialog.value.open) {
        dialog.value.showModal();
      }
    } else if (dialog.value instanceof HTMLDialogElement && dialog.value.open) {
      dialog.value.close();
    }
  },
  { flush: "post", immediate: true },
);
</script>

<template>
  <component
    :is="standalone ? 'section' : 'dialog'"
    ref="dialog"
    :class="standalone ? 'app:flex app:flex-col app:gap-3' : 'dui-modal'"
    aria-labelledby="species-builder-subspecies-title"
    @close="handleDialogClosed"
    @keydown.esc.stop.prevent="closeDialog"
    @keyup.esc.stop
  >
    <div
      v-if="subspecies"
      :class="standalone ? 'app:flex app:flex-col app:gap-3' : 'dui-modal-box app:max-w-5xl'"
      :aria-busy="isBusy"
    >
      <SubspeciesEditorHeader
        v-if="!standalone"
        :is-busy="isBusy"
        :is-read-only="isReadOnly"
        :name="subspecies.name || 'Untitled'"
        @close="closeDialog"
        @delete="emit('delete', index)"
      />

      <SubspeciesEditorTabs
        :active-tab="activeTab"
        :is-busy="isBusy"
        :issues="issues"
        @select="activeTab = $event"
      />

      <SubspeciesDetailsTab
        v-if="activeTab === 'details'"
        id="subspecies-editor-panel-details"
        aria-label="Subspecies details"
        aria-labelledby="subspecies-editor-tab-details"
        :index="index"
        :is-disabled="controlsDisabled"
        :issues="issuesForTab('details')"
        role="tabpanel"
        :subspecies="subspecies"
        @update-characteristic="(key, value) => emit('updateCharacteristic', index, key, value)"
        @update-number-field="(field, value) => emit('updateNumberField', index, field, value)"
        @update-string-field="(field, value) => emit('updateStringField', index, field, value)"
      />

      <SubspeciesTalentInheritance
        v-else-if="activeTab === 'talents'"
        id="subspecies-editor-panel-talents"
        aria-label="Subspecies Talents"
        aria-labelledby="subspecies-editor-tab-talents"
        :index="index"
        :is-disabled="controlsDisabled"
        :issues="issuesForTab('talents')"
        :parent-talents="parentTalents"
        role="tabpanel"
        :subspecies="subspecies"
        @talent-drop="(entryIndex, data) => emit('talentDrop', entryIndex, data)"
        @update-array-field="
          (entryIndex, field, value) => emit('updateArrayField', entryIndex, field, value)
        "
      />

      <SubspeciesChangesTab
        v-else-if="activeTab === 'changes'"
        id="subspecies-editor-panel-changes"
        aria-label="Subspecies Skill and Trait changes"
        aria-labelledby="subspecies-editor-tab-changes"
        :is-disabled="controlsDisabled"
        :issues="issuesForTab('changes')"
        :parent-definition="parentDefinition"
        role="tabpanel"
        :subspecies="subspecies"
        :wound-formula-trait-name="woundFormulaTraitName"
        @update-array-field="(field, value) => emit('updateArrayField', index, field, value)"
      />

      <SubspeciesWoundsPanel
        v-else-if="activeTab === 'wounds'"
        :formula="subspecies.woundFormula?.formula"
        :generated-trait-name="woundFormulaTraitName"
        :is-disabled="controlsDisabled"
        :issues="issuesForTab('wounds')"
        :standalone="standalone"
        @open-formula-builder="emit('openWoundFormula')"
        @update-wound-formula="(value) => emit('updateWoundFormula', index, value)"
      />

      <RandomTablesSection
        v-else
        id="subspecies-editor-panel-tables"
        :active-tab="activeTableTab"
        aria-label="Subspecies tables"
        aria-labelledby="subspecies-editor-tab-tables"
        help="Configure subspecies-specific random Talent draws and Talent replacement offers as rows."
        :include-career-replacements="isReadOnly"
        :is-disabled="controlsDisabled"
        :is-navigation-disabled="isBusy"
        :issues="issuesForTab('tables')"
        :random-talent-sources="randomTalentSources"
        role="tabpanel"
        show-navigation
        :values="subspecies"
        @career-table-career-drop="
          (rowIndex, data) => emit('careerTableCareerDrop', index, rowIndex, data)
        "
        @career-table-journal-drop="
          (rowIndex, data) => emit('careerTableJournalDrop', index, rowIndex, data)
        "
        @open-item="(uuid) => emit('openItem', uuid)"
        @select-tab="activeTableTab = $event"
        @talent-replacement-replacement-drop="
          (rowIndex, data) => emit('talentReplacementReplacementDrop', index, rowIndex, data)
        "
        @talent-replacement-rolled-drop="
          (rowIndex, data) => emit('talentReplacementRolledDrop', index, rowIndex, data)
        "
        @update="updateMappedField"
        @update-career-table-rows="(rows) => emit('updateCareerTableRows', index, rows)"
        @update-talent-replacement-rows="(rows) => emit('updateTalentReplacementRows', index, rows)"
      />

      <SpeciesBuilderEditorContext
        v-if="!standalone && !isReadOnly"
        :can-save="store.canSave"
        :entity-key="subspecies.key"
        :entity-name="subspecies.name || 'Untitled Subspecies'"
        :has-unsaved-changes="store.hasUnsavedChanges"
        :has-validation-errors="hasValidationErrors"
        :has-validation-warnings="hasValidationWarnings"
        :is-loading="store.isLoading"
        :is-saving="store.isSaving"
        :load-error="store.loadError"
        @save="emit('save')"
      />
    </div>
    <form v-if="!standalone" class="dui-modal-backdrop" method="dialog">
      <button aria-label="Close subspecies editor" type="submit">Close</button>
    </form>
  </component>
</template>
