import type { ComputedRef, Ref } from "vue";

import type {
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderSettings,
  SpeciesBuilderSpeciesTableDraft,
} from "../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationCatalog } from "../../types/species-builder/validation";

import { validateSpeciesBuilder } from "../../functions/species-builder/validation";
import { computed } from "vue";

interface SpeciesBuilderChargenValidationContext {
  catalog: Ref<SpeciesBuilderValidationCatalog>;
  editingDefinitions: ComputedRef<SpeciesBuilderEditingDefinition[]>;
  settings: ComputedRef<SpeciesBuilderSettings>;
  speciesTable: ComputedRef<SpeciesBuilderSpeciesTableDraft>;
}

export function createSpeciesBuilderChargenValidation(
  context: SpeciesBuilderChargenValidationContext,
) {
  const validationIssues = computed(() =>
    validateSpeciesBuilder(
      context.settings.value,
      context.catalog.value,
      context.speciesTable.value,
      context.editingDefinitions.value,
    ),
  );

  return { validationIssues };
}

export function createEmptySpeciesBuilderValidationCatalog(): SpeciesBuilderValidationCatalog {
  return {
    careerGroupNames: [],
    itemBaseNames: { skill: [], talent: [], trait: [] },
    randomTalentSources: [],
    runtimeSpecies: [],
  };
}
