import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

import { careers, species, subspecies } from "./shared";

export function createGhoulDefinition(): SpeciesBuilderDefinition {
  return species("ghoul", "Ghoul", [20, 0, 25, 20, 20, 25, 15, 15, 20, 5], {
    age: "4d10+10",
    careerTable: careers("Grave Robber", "Hunter", "Outlaw", "Scout", "Thief"),
    extra: 1,
    fate: 1,
    height: { die: "1d10", feet: 4, inches: 10 },
    includeInExtraSpecies: true,
    movement: 4,
    resilience: 2,
    skills: [
      "Athletics",
      "Cool",
      "Endurance",
      "Intimidate",
      "Melee (Brawling)",
      "Outdoor Survival",
      "Perception",
      "Stealth (Any)",
      "Track",
    ],
    talents: ["Acute Sense (Smell)", "Hardy", "Night Vision", "Resistance (Disease)"],
    traits: ["Bite (4)", "Hungry", "Infected", "Painless"],
  });
}

export function createRisenCorpseDefinition(): SpeciesBuilderDefinition {
  return species("risen-corpse", "Risen Corpse", [10, 0, 20, 20, 10, 10, 10, 10, 20, 0], {
    age: "5d10+10",
    careerTable: careers("Guard", "Labourer", "Outlaw", "Soldier", "Warrior"),
    extra: 0,
    fate: 0,
    height: { die: "2d10", feet: 4, inches: 9 },
    includeInExtraSpecies: true,
    movement: 3,
    resilience: 3,
    skills: ["Cool", "Endurance", "Intimidate", "Melee (Basic)", "Perception"],
    subspecies: [
      subspecies("skeleton", "Skeleton", [15, 15, 20, 20, 10, 10, 15, 5, 20, 0], {
        skillsAdded: ["Ranged (Bow)"],
        talentsAdded: ["Resistance (Poison)"],
        traitsAdded: ["Construct", "Ranged (Bow) (7)"],
        traitsRemoved: ["Infected"],
      }),
      subspecies("zombie", "Zombie", [5, 0, 20, 20, 0, 5, 5, 5, 15, 0], {
        movement: 2,
        talentsAdded: ["Hardy", "Very Resilient"],
        traitsAdded: ["Infected", "Mindless"],
      }),
    ],
    talents: ["Hardy", "Night Vision", "Resistance (Disease)", "Strong-minded"],
    traits: ["Dark Vision", "Painless", "Undead"],
  });
}

