import type {
  SpeciesBuilderItemReference,
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderTalentGrant,
} from "../../../types/species-builder/species-builder";

import { formatItemReferenceName, formatLinkedItemName } from "../item-reference-names";

export type SpeciesBuilderLinkedListField = "skills" | "traits";
export type SpeciesBuilderTalentGrantKind = "choice" | "single";

export function linkedListFieldForArrayField(
  field: "skills" | "talents" | "traits",
): SpeciesBuilderLinkedListField {
  return field === "traits" ? "traits" : "skills";
}

export function linkedRowsForValues(
  values: string[] | undefined,
  rows: SpeciesBuilderLinkedItemName[] | undefined,
): SpeciesBuilderLinkedItemName[] {
  if (rows && rows.length > 0) {
    return rows.map(copyLinkedItemName);
  }

  return (values ?? []).map((name) => ({ name }));
}

export function talentGrantsForValues(
  values: string[] | undefined,
  grants: SpeciesBuilderTalentGrant[] | undefined,
): SpeciesBuilderTalentGrant[] {
  if (grants && grants.length > 0) {
    return grants.map((grant) => ({
      choices: grant.choices.map(copyLinkedItemName),
    }));
  }

  return (values ?? []).map((entry) => ({
    choices: talentChoices(entry).map((name) => ({ name })),
  }));
}

export function linkedRowNames(rows: SpeciesBuilderLinkedItemName[]): string[] {
  return rows.map(formatLinkedItemName).filter((name) => name.length > 0);
}

export function talentGrantNames(grants: SpeciesBuilderTalentGrant[]): string[] {
  return grants.flatMap((grant) => {
    const choices = linkedRowNames(grant.choices);

    return choices.length > 0 ? [choices.join(", ")] : [];
  });
}

export function setLinkedRowName(
  rows: SpeciesBuilderLinkedItemName[],
  rowIndex: number,
  name: string,
): SpeciesBuilderLinkedItemName[] {
  return rows.map((row, index) =>
    index === rowIndex
      ? {
          name,
        }
      : copyLinkedItemName(row),
  );
}

export function setLinkedRowItem(
  rows: SpeciesBuilderLinkedItemName[],
  rowIndex: number,
  item: SpeciesBuilderItemReference,
): SpeciesBuilderLinkedItemName[] {
  return rows.map((row, index) =>
    index === rowIndex
      ? {
          item,
          name: formatItemReferenceName(item),
        }
      : copyLinkedItemName(row),
  );
}

export function setTalentChoiceName(
  grants: SpeciesBuilderTalentGrant[],
  grantIndex: number,
  choiceIndex: number,
  name: string,
): SpeciesBuilderTalentGrant[] {
  return grants.map((grant, index) =>
    index === grantIndex
      ? {
          choices: setLinkedRowName(grant.choices, choiceIndex, name),
        }
      : copyTalentGrant(grant),
  );
}

export function setTalentChoiceItem(
  grants: SpeciesBuilderTalentGrant[],
  grantIndex: number,
  choiceIndex: number,
  item: SpeciesBuilderItemReference,
): SpeciesBuilderTalentGrant[] {
  return grants.map((grant, index) =>
    index === grantIndex
      ? {
          choices: setLinkedRowItem(grant.choices, choiceIndex, item),
        }
      : copyTalentGrant(grant),
  );
}

export function appendLinkedRow(
  rows: SpeciesBuilderLinkedItemName[],
  field: SpeciesBuilderLinkedListField,
): SpeciesBuilderLinkedItemName[] {
  const name = field === "skills" ? "New Skill" : "New Trait";

  return [...rows.map(copyLinkedItemName), { name }];
}

export function removeLinkedRow(
  rows: SpeciesBuilderLinkedItemName[],
  rowIndex: number,
): SpeciesBuilderLinkedItemName[] {
  return rows.filter((_, index) => index !== rowIndex).map(copyLinkedItemName);
}

export function appendTalentGrant(
  grants: SpeciesBuilderTalentGrant[],
  kind: SpeciesBuilderTalentGrantKind,
): SpeciesBuilderTalentGrant[] {
  const choices: SpeciesBuilderLinkedItemName[] = [{ name: "New Talent" }];

  if (kind === "choice") {
    choices.push({ name: "Alternative Talent" });
  }

  return [...grants.map(copyTalentGrant), { choices }];
}

export function appendTalentChoice(
  grants: SpeciesBuilderTalentGrant[],
  grantIndex: number,
): SpeciesBuilderTalentGrant[] {
  return grants.map((grant, index) =>
    index === grantIndex
      ? {
          choices: [...grant.choices.map(copyLinkedItemName), { name: "Alternative Talent" }],
        }
      : copyTalentGrant(grant),
  );
}

export function removeTalentGrant(
  grants: SpeciesBuilderTalentGrant[],
  grantIndex: number,
): SpeciesBuilderTalentGrant[] {
  return grants.filter((_, index) => index !== grantIndex).map(copyTalentGrant);
}

export function removeTalentChoice(
  grants: SpeciesBuilderTalentGrant[],
  grantIndex: number,
  choiceIndex: number,
): SpeciesBuilderTalentGrant[] {
  const grant = grants[grantIndex];

  if (!grant || grant.choices.length === 1) {
    return removeTalentGrant(grants, grantIndex);
  }

  return grants.map((entry, index) =>
    index === grantIndex
      ? {
          choices: entry.choices
            .filter((_, candidateIndex) => candidateIndex !== choiceIndex)
            .map(copyLinkedItemName),
        }
      : copyTalentGrant(entry),
  );
}

function talentChoices(entry: string): string[] {
  const choices = entry
    .split(",")
    .map((choice) => choice.trim())
    .filter((choice) => choice.length > 0);

  return choices.length > 0 ? choices : [entry];
}

function copyLinkedItemName(row: SpeciesBuilderLinkedItemName): SpeciesBuilderLinkedItemName {
  return row.item
    ? {
        item: { ...row.item },
        name: row.name,
      }
    : {
        name: row.name,
      };
}

function copyTalentGrant(grant: SpeciesBuilderTalentGrant): SpeciesBuilderTalentGrant {
  return {
    choices: grant.choices.map(copyLinkedItemName),
  };
}
