import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

import { careers, species, subspecies } from "./shared";

export function createBeastmanFamilyDefinition(): SpeciesBuilderDefinition {
  return species("beastman", "Beastman", [30, 20, 20, 30, 20, 25, 15, 15, 25, 15], {
    age: "2d10+16",
    careerTable: careers(
      "Warrior",
      "Outlaw",
      "Hunter",
      "Scout",
      "Trapper",
      "Zealot",
      "Mystic",
      "Pit Fighter",
    ),
    extra: 2,
    fate: 1,
    height: { die: "1d10", feet: 5, inches: 6 },
    includeInExtraSpecies: true,
    movement: 4,
    resilience: 1,
    skills: [
      "Athletics",
      "Dodge",
      "Haggle",
      "Language (Beast Tongue)",
      "Lore (Beastmen)",
      "Lore (Chaos)",
      "Melee (Basic)",
      "Outdoor Survival",
      "Perception",
      "Perform (Dancing)",
      "Play (Drums)",
      "Pray",
      "Set Trap",
      "Stealth (Rural)",
    ],
    subspecies: [
      subspecies("gor", "Gor", [35, 15, 25, 35, 20, 20, 10, 15, 30, 10], {
        careerTable: careers("Warrior", "Pit Fighter", "Outlaw", "Hunter", "Zealot"),
        skillsAdded: ["Consume Alcohol", "Intimidate", "Play (Horn)"],
        skillsRemoved: ["Haggle", "Play (Drums)", "Set Trap"],
        talentsAdded: ["Furious Assault", "Menacing"],
        traitsAdded: ["Horns (3)"],
      }),
      subspecies("ungor", "Ungor", [25, 30, 15, 25, 30, 30, 20, 15, 25, 10], {
        careerTable: careers("Scout", "Hunter", "Trapper", "Outlaw", "Servant"),
        skillsAdded: ["Play (Horn)", "Ranged (Bow)", "Track"],
        skillsRemoved: ["Haggle", "Melee (Basic)", "Play (Drums)"],
        talentsAdded: ["Acute Sense (Hearing), Acute Sense (Smell)", "Rover"],
      }),
    ],
    talents: ["Night Vision", "Ruinous Mark"],
    traits: ["Arboreal"],
  });
}

