<script setup lang="ts">
import type { SpeciesBuilderValidationIndicator } from "../../../components/validation/validation-presentation";

import { validationIndicatorLabel } from "../../../components/validation/validation-presentation";

withDefaults(
  defineProps<{
    actionLabel?: string;
    editIconClass?: string;
    entryKey: string;
    iconClass: string;
    isDisabled: boolean;
    isReadOnly?: boolean;
    isSelected?: boolean;
    meta?: string;
    readOnlyLabel?: string;
    title: string;
    validationIndicator?: SpeciesBuilderValidationIndicator;
  }>(),
  {
    actionLabel: "Edit",
    editIconClass: "fa-solid fa-pen",
    isReadOnly: false,
    isSelected: false,
    meta: "",
    readOnlyLabel: "Installed",
    validationIndicator: undefined,
  },
);

const emit = defineEmits<{
  open: [];
}>();
</script>

<template>
  <li
    class="dui-list-row"
    :class="{
      'app:outline app:outline-1 app:outline-error': validationIndicator?.severity === 'error',
      'app:outline app:outline-1 app:outline-warning': validationIndicator?.severity === 'warning',
    }"
    :aria-current="isSelected ? 'true' : undefined"
  >
    <i aria-hidden="true" :class="iconClass" />
    <span class="dui-list-col-grow app:flex app:min-w-0 app:flex-col app:gap-1">
      <span class="app:flex app:flex-wrap app:items-center app:gap-2">
        <strong>{{ title }}</strong>
        <span
          class="dui-badge dui-badge-outline dui-badge-sm"
          :class="{ 'dui-badge-info': isSelected, 'dui-badge-ghost': !isSelected }"
        >
          {{ entryKey }}
        </span>
      </span>
      <span class="app:flex app:flex-wrap app:items-center app:gap-1">
        <span v-if="isReadOnly" class="dui-badge dui-badge-ghost dui-badge-sm">
          <i aria-hidden="true" class="fa-solid fa-lock" />
          {{ readOnlyLabel }}
        </span>
        <span v-if="meta" class="dui-badge dui-badge-ghost dui-badge-sm">{{ meta }}</span>
        <span
          v-if="validationIndicator"
          class="dui-badge dui-badge-sm"
          :class="
            validationIndicator.severity === 'error' ? 'dui-badge-error' : 'dui-badge-warning'
          "
          :title="validationIndicatorLabel(validationIndicator)"
        >
          <span
            aria-hidden="true"
            class="dui-status dui-status-xs"
            :class="
              validationIndicator.severity === 'error' ? 'dui-status-error' : 'dui-status-warning'
            "
          />
          {{ validationIndicator.count }}
          <span class="app:sr-only">{{ validationIndicatorLabel(validationIndicator) }}</span>
        </span>
      </span>
    </span>
    <button
      :aria-label="`${actionLabel}: ${title}`"
      class="dui-btn dui-btn-outline dui-btn-sm"
      :disabled="isDisabled"
      type="button"
      @click="emit('open')"
    >
      <i aria-hidden="true" :class="editIconClass" />
      {{ actionLabel }}
    </button>
  </li>
</template>
