<script setup lang="ts">
import type { SpeciesBuilderDefinition } from "../../../../../../../../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../../../../../../../../types/wfrp4e/characteristics";
import type { SpeciesBuilderStatField } from "../../support/field-definitions";

import type { SpeciesBuilderValidationIssue } from "../../validation-presentation";
import CharacteristicFields from "./CharacteristicFields.vue";
import StatFields from "./StatFields.vue";

const resourceFields: SpeciesBuilderStatField[] = ["movement", "fate", "resilience", "extra"];

defineProps<{
  definition: SpeciesBuilderDefinition;
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
}>();

const emit = defineEmits<{
  updateCharacteristic: [key: WfrpCharacteristicKey, value: string];
  updateNumberField: [field: SpeciesBuilderStatField, value: string];
}>();
</script>

<template>
  <section class="app:grid app:gap-3">
    <section class="dui-card dui-card-border dui-card-sm">
      <div class="dui-card-body">
        <fieldset class="dui-fieldset">
          <legend class="dui-fieldset-legend">Characteristic Roll Formulas</legend>
          <p class="dui-fieldset-label">
            Starting formulas used by WFRP character creation, usually values such as 2d10+20.
          </p>
          <CharacteristicFields
            :characteristics="definition.characteristics"
            :is-disabled="isDisabled"
            :issues="issues"
            @update="(key, value) => emit('updateCharacteristic', key, value)"
          />
        </fieldset>
      </div>
    </section>

    <section class="dui-card dui-card-border dui-card-sm">
      <div class="dui-card-body">
        <fieldset class="dui-fieldset">
          <legend class="dui-fieldset-legend">Movement, Fate And Resilience</legend>
          <p class="dui-fieldset-label">
            Set base Movement plus starting Fate, Resilience, and extra points distributed between
            them.
          </p>
          <StatFields
            :fields="resourceFields"
            :is-disabled="isDisabled"
            :issues="issues"
            :values="definition"
            @update="(field, value) => emit('updateNumberField', field, value)"
          />
        </fieldset>
      </div>
    </section>
  </section>
</template>
