<script setup lang="ts">
import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  includeSpeciesInName: boolean;
}>();

const emit = defineEmits<{
  includeSpeciesInNameChange: [value: boolean];
}>();

function handleIncludeSpeciesChange(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("includeSpeciesInNameChange", Boolean(input?.checked));
}
</script>

<template>
  <NpcBuilderSection number="3" title="Default Naming">
    <label class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="includeSpeciesInName"
        type="checkbox"
        @change="handleIncludeSpeciesChange"
      />
      <span>Include species in suggested names</span>
    </label>
  </NpcBuilderSection>
</template>
