import type { NpcMagicGrant, NpcMagicLoreOption } from "../../../../../types/npc-builder";
import type { SpellResolutionInput } from "./types";

import {
  DARK_MAGIC_LORE_KEYS,
  EIGHT_WIND_MAGIC_LORE_KEYS,
  getMagicLoreCategory,
  normalizeMagicLoreText,
} from "../../../../../functions/npc-builder/magic-grants";
import {
  isRecord,
  readStringPath,
  readUnknownPath,
  toStringList,
} from "../../../../../shared/object-readers";

export interface MagicLoreProfile {
  key: string;
  matchTerms: string[];
  name: string;
  wind: string;
}

const eightWindLoreKeys = new Set<string>(EIGHT_WIND_MAGIC_LORE_KEYS);
const darkLoreKeys = new Set<string>(DARK_MAGIC_LORE_KEYS);

export async function listMagicLoreOptions(): Promise<NpcMagicLoreOption[]> {
  return readMagicLoreProfiles()
    .map((profile) => ({
      category: getMagicLoreCategory(profile.key),
      key: profile.key,
      label: profile.name,
      value: profile.name,
      wind: profile.wind,
    }))
    .sort((left, right) => {
      if (left.category !== right.category) {
        return left.category.localeCompare(right.category);
      }

      return left.label.localeCompare(right.label);
    });
}

export function readMagicLoreProfiles(): MagicLoreProfile[] {
  const magicLores = readUnknownPath(game.wfrp4e?.config, ["magicLores"]);
  const magicWinds = readUnknownPath(game.wfrp4e?.config, ["magicWind"]);
  const profiles: MagicLoreProfile[] = [];

  if (!isRecord(magicLores)) {
    return [createPettyMagicProfile()];
  }

  for (const [key, value] of Object.entries(magicLores)) {
    const name = readConfigEntryLabel(value) || key;
    const wind = readMagicWindLabel(magicWinds, key);

    profiles.push({
      key,
      matchTerms: createLoreMatchTerms(key, name, wind),
      name,
      wind,
    });
  }

  if (!profiles.some((profile) => profile.key === "petty")) {
    profiles.push(createPettyMagicProfile());
  }

  return profiles;
}

export function resolveGrantedLoreProfiles(
  grants: NpcMagicGrant[],
  profiles: MagicLoreProfile[],
): MagicLoreProfile[] {
  const resolvedProfiles = new Map<string, MagicLoreProfile>();

  for (const grant of grants) {
    if (grant.isAmbiguous) {
      continue;
    }

    if (grant.kind === "petty-magic") {
      const pettyProfile = findProfileByTerm("petty magic", profiles);

      if (pettyProfile) {
        resolvedProfiles.set(pettyProfile.key, pettyProfile);
      }

      continue;
    }

    const profile = findProfileByTerm(grant.rawLore, profiles);

    if (profile) {
      resolvedProfiles.set(profile.key, profile);
    }
  }

  return [...resolvedProfiles.values()];
}

export function findMatchingSpellLore(
  spell: SpellResolutionInput,
  profiles: MagicLoreProfile[],
): MagicLoreProfile | null {
  const spellLoreTerms = [
    ...readSpellLoreTerms(spell.system),
    readSpellNameLoreSuffix(spell.name),
  ].filter(Boolean);

  for (const term of spellLoreTerms) {
    const broadProfile = findProfileForBroadSpellLore(term, profiles);

    if (broadProfile) {
      return broadProfile;
    }

    const profile = findProfileByTerm(term, profiles);

    if (profile) {
      return profile;
    }
  }

  return null;
}

export function readSpellLoreTerms(system: unknown): string[] {
  return [
    ...toStringList(readUnknownPath(system, ["lore", "value"])),
    ...toStringList(readUnknownPath(system, ["lore"])),
    ...toStringList(readUnknownPath(system, ["magicLore", "value"])),
    ...toStringList(readUnknownPath(system, ["magicLore"])),
    ...toStringList(readUnknownPath(system, ["category", "value"])),
    ...toStringList(readUnknownPath(system, ["system", "lore", "value"])),
    ...toStringList(readUnknownPath(system, ["system", "lore"])),
    ...toStringList(readUnknownPath(system, ["system.lore.value"])),
    ...toStringList(readUnknownPath(system, ["system.lore"])),
  ];
}

export function createPettyMagicProfile(): MagicLoreProfile {
  return {
    key: "petty",
    matchTerms: ["petty", "petty magic"],
    name: "Petty Magic",
    wind: "",
  };
}

export function createUnknownMagicLoreProfile(rawLore: string): MagicLoreProfile {
  const name = rawLore.trim() || "Unknown Lore";

  return {
    key: normalizeMagicLoreText(name) || "unknown",
    matchTerms: [name],
    name,
    wind: "",
  };
}

function findProfileForBroadSpellLore(
  term: string,
  profiles: MagicLoreProfile[],
): MagicLoreProfile | null {
  const normalizedTerm = normalizeMagicLoreText(term);

  if (normalizedTerm === "lore") {
    return profiles.find((profile) => profile.key !== "petty") ?? null;
  }

  if (normalizedTerm === "the eight winds" || normalizedTerm === "eight winds") {
    return profiles.find((profile) => eightWindLoreKeys.has(profile.key)) ?? null;
  }

  if (normalizedTerm === "dark lore") {
    return profiles.find((profile) => darkLoreKeys.has(profile.key)) ?? null;
  }

  return null;
}

export function readSpellNameLoreSuffix(name: string): string {
  return /\(([^)]+)\)\s*$/.exec(name)?.[1]?.trim() ?? "";
}

function findProfileByTerm(term: string, profiles: MagicLoreProfile[]): MagicLoreProfile | null {
  const normalizedTerm = normalizeMagicLoreText(term);

  if (!normalizedTerm) {
    return null;
  }

  return (
    profiles.find((profile) =>
      profile.matchTerms.some((matchTerm) => normalizeMagicLoreText(matchTerm) === normalizedTerm),
    ) ?? null
  );
}

function createLoreMatchTerms(key: string, name: string, wind: string): string[] {
  const terms = new Set<string>();
  const normalizedKey = normalizeMagicLoreText(key);
  const normalizedName = normalizeMagicLoreText(name);

  for (const term of [key, name, wind]) {
    if (term.trim()) {
      terms.add(term.trim());
    }
  }

  if (normalizedKey === "petty" || normalizedName === "petty") {
    terms.add("Petty Magic");
  }

  if (normalizedKey === "shadow" || normalizedName === "shadow") {
    terms.add("Shadows");
  }

  if (name && !/^lore of /i.test(name)) {
    terms.add(`Lore of ${name}`);
  }

  return [...terms];
}

function readMagicWindLabel(source: unknown, key: string): string {
  if (!isRecord(source)) {
    return "";
  }

  return readConfigEntryLabel(source[key]);
}

function readConfigEntryLabel(value: unknown): string {
  if (typeof value === "string") {
    return value.trim();
  }

  if (!isRecord(value)) {
    return "";
  }

  return (
    readStringPath(value, ["name"]) ||
    readStringPath(value, ["label"]) ||
    readStringPath(value, ["value"])
  );
}
