import type { Component } from "vue";

import SpeciesBuilderApp from "../../../view/apps/species-builder/SpeciesBuilderApp.vue";
import { MODULE_ID } from "../../constants";
import { FoundryVueApplication } from "../FoundryVueApplication";
import { foundrySpeciesBuilderBridge } from "./foundry-bridge";
import { requestReloadConfirmation } from "./reload-confirmation";

export class SpeciesBuilderApplication extends FoundryVueApplication {
  #hasSavedChanges = false;

  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-species-builder`,
    classes: [MODULE_ID, "wfrp4e-customizer-species-builder"],
    position: {
      height: 760,
      width: 1040,
    },
    window: {
      icon: "fa-solid fa-people-group",
      resizable: true,
      title: "WFRP4e Species Builder",
    },
  };

  protected override getVueComponent(): Component {
    return SpeciesBuilderApp;
  }

  protected override getVueProps(): Record<string, unknown> {
    return {
      bridge: foundrySpeciesBuilderBridge,
      onSettingsSaved: () => {
        this.#hasSavedChanges = true;
      },
    };
  }

  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    const shouldPromptForReload = this.#hasSavedChanges;

    this.#hasSavedChanges = false;

    if (shouldPromptForReload && (await requestReloadConfirmation())) {
      window.location.reload();
    }

    await super._preClose(options);
  }
}
