import type {
  SpeciesBuilderCareerTableDefinition,
  SpeciesBuilderCareerTableRow,
} from "../../../../types/species-builder/species-builder";

import { isRecord } from "../../../../shared/object-readers";

export function resolveRuntimeCareerTable(
  speciesKey: string,
  subspeciesKey: string | undefined,
  configuredColumn: unknown,
): SpeciesBuilderCareerTableDefinition | undefined {
  const configured = typeof configuredColumn === "string" ? configuredColumn.trim() : "";
  const candidates = careerColumnCandidates(speciesKey, subspeciesKey, configured);

  for (const column of candidates) {
    const source = game.wfrp4e?.tables?.findTable?.("career", column);

    if (!source) {
      continue;
    }

    // WFRP can return a table-family wrapper whose columns do not include the requested child.
    const table = resolveCareerTableColumn(source, column);

    if (table) {
      return careerTableFromDocument(table);
    }
  }

  return undefined;
}

export function careerTableFromDocument(
  source: unknown,
): SpeciesBuilderCareerTableDefinition | undefined {
  if (!isRecord(source)) {
    return undefined;
  }

  const rows = iterableValues(source["results"]).flatMap((result) => {
    const row = careerRowFromResult(result);

    return row ? [row] : [];
  });

  return rows.length > 0 ? { rows } : undefined;
}

function careerColumnCandidates(
  speciesKey: string,
  subspeciesKey: string | undefined,
  configuredColumn: string,
): string[] {
  const candidates = subspeciesKey
    ? [configuredColumn, `${speciesKey}-${subspeciesKey}`, speciesKey]
    : [speciesKey];

  if (speciesKey === "human") {
    candidates.push("human-reiklander");
  }

  return [...new Set(candidates.filter(Boolean))];
}

function resolveCareerTableColumn(source: unknown, column: string): unknown {
  if (!isRecord(source) || !Array.isArray(source["columns"])) {
    return source;
  }

  return source["columns"].find((candidate) => readCareerTableColumn(candidate) === column);
}

function readCareerTableColumn(source: unknown): string {
  if (!isRecord(source) || typeof source["getFlag"] !== "function") {
    return "";
  }

  const value = source["getFlag"].call(source, "wfrp4e", "column");

  return typeof value === "string" ? value : "";
}

function careerRowFromResult(source: unknown): SpeciesBuilderCareerTableRow | undefined {
  if (!isRecord(source)) {
    return undefined;
  }

  const chatText = resultChatText(source);
  const uuidLink = /@UUID\[([^\]]+)\]\{([^}]+)\}/u.exec(chatText);
  const linkedName = cleanVisibleText(uuidLink?.[2] ?? "");
  const fallbackName = cleanVisibleText(chatText) || cleanVisibleText(source["name"]);
  const name = linkedName || fallbackName;

  if (!name) {
    return undefined;
  }

  const journalUuid = uuidLink?.[1]?.trim();
  const sourceRange = readResultRange(source["range"]);
  const sourceWeight = readPositiveNumber(source["weight"]);
  const row: SpeciesBuilderCareerTableRow = { name };

  if (journalUuid) {
    row.journalUuid = journalUuid;
  }
  if (sourceRange) {
    row.sourceRange = sourceRange;
  }
  if (sourceWeight !== undefined) {
    row.sourceWeight = sourceWeight;
  }

  return row;
}

function readResultRange(value: unknown): [number, number] | undefined {
  if (!Array.isArray(value) || value.length < 2) {
    return undefined;
  }

  const start = Number(value[0]);
  const end = Number(value[1]);

  return Number.isFinite(start) && Number.isFinite(end) ? [start, end] : undefined;
}

function readPositiveNumber(value: unknown): number | undefined {
  const numberValue = Number(value);

  return Number.isFinite(numberValue) && numberValue > 0 ? numberValue : undefined;
}

function resultChatText(source: Record<string, unknown>): string {
  if (source["type"] === "document") {
    const documentUuid = source["documentUuid"];
    const name = source["name"];

    return typeof documentUuid === "string" && typeof name === "string"
      ? `@UUID[${documentUuid}]{${name}}`
      : "";
  }

  const description = source["description"] ?? source["text"];

  return typeof description === "string" ? description : "";
}

function cleanVisibleText(value: unknown): string {
  return typeof value === "string"
    ? value
        .replace(/@UUID\[[^\]]+\]\{([^}]+)\}/gu, "$1")
        .replace(/<[^>]*>/gu, "")
        .trim()
    : "";
}

function iterableValues(source: unknown): unknown[] {
  if (Array.isArray(source)) {
    return source;
  }

  if (typeof source === "object" && source !== null && Symbol.iterator in source) {
    return [...(source as Iterable<unknown>)];
  }

  return [];
}
