import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";

import { talentsForDefinition } from "../subspecies-list-fields";
import { createIssue, type ValidationCatalogIndex, type ValidationIssueLocation } from "./shared";

export function validateRandomTalentTables(
  definitions: SpeciesBuilderDefinition[],
  catalog: ValidationCatalogIndex,
): SpeciesBuilderValidationIssue[] {
  const issues: SpeciesBuilderValidationIssue[] = [];

  definitions.forEach((definition, definitionIndex) => {
    validateRandomTalentRecord(
      definition.randomTalents ?? { talents: 0 },
      definitionLocation(definitionIndex),
      catalog,
      issues,
    );

    (definition.subspecies ?? []).forEach((subspecies, subspeciesIndex) => {
      if (subspecies.randomTalents !== undefined) {
        validateRandomTalentRecord(
          subspecies.randomTalents,
          subspeciesLocation(definitionIndex, subspeciesIndex),
          catalog,
          issues,
        );
        validateInheritedTalentSources(
          definition,
          subspecies,
          definitionIndex,
          subspeciesIndex,
          issues,
        );
      }
    });
  });

  return issues;
}

function validateInheritedTalentSources(
  definition: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
  definitionIndex: number,
  subspeciesIndex: number,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const configuredKeys = new Set(Object.keys(subspecies.randomTalents ?? {}));
  const removedTalents = new Set(subspecies.talentsRemoved ?? []);
  const missingKeys = new Set<string>();

  for (const talent of talentsForDefinition(definition) ?? []) {
    if (removedTalents.has(talent)) {
      continue;
    }

    for (const key of requiredRandomTalentKeys(talent)) {
      if (!configuredKeys.has(key)) {
        missingKeys.add(key);
      }
    }
  }

  for (const key of missingKeys) {
    issues.push(
      createIssue(
        subspeciesLocation(definitionIndex, subspeciesIndex),
        "inherited-random-talent-source-unconfigured",
        `Inherited Talent grants use table key “${key}”, but this subspecies Random Talents override does not configure it.`,
      ),
    );
  }
}

function requiredRandomTalentKeys(value: string): string[] {
  if (/^-?\d+(?:\.\d+)?$/u.test(value.trim())) {
    return ["talents"];
  }
  if (!value.includes(",")) {
    return [];
  }

  return value.split(",").flatMap((choice) => {
    const match = /^random\[(\d)\](?:\[([a-zA-Z-_]+)\])?$/iu.exec(choice.trim());

    return match ? [match[2] ?? "talents"] : [];
  });
}

function validateRandomTalentRecord(
  record: NonNullable<SpeciesBuilderSubspeciesDefinition["randomTalents"]>,
  location: ValidationIssueLocation,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  Object.entries(record).forEach(([rawKey, count], rowIndex) => {
    const key = rawKey.trim();

    if (!key) {
      issues.push(
        createIssue(
          { ...location, field: "key", rowIndex },
          "random-talent-source-required",
          `Random Talent row ${rowIndex + 1} needs a table key.`,
        ),
      );
    } else {
      validateSource(key, rowIndex, location, catalog, issues);
    }

    if (!Number.isInteger(count) || count < 0) {
      issues.push(
        createIssue(
          { ...location, field: "count", rowIndex },
          "random-talent-count-invalid",
          `Random Talent count for “${key || "row " + (rowIndex + 1)}” must be a non-negative whole number.`,
        ),
      );
    }
  });
}

function validateSource(
  key: string,
  rowIndex: number,
  location: ValidationIssueLocation,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const source = catalog.randomTalentSources.get(key);

  if (!source) {
    issues.push(
      createIssue(
        { ...location, field: "key", rowIndex },
        "random-talent-source-missing",
        `No WFRP RollTable is registered with key “${key}”. WFRP looks it up even when the count is 0.`,
      ),
    );
  } else if (!source.readyForCharacterCreation) {
    issues.push(
      createIssue(
        { ...location, field: "key", rowIndex },
        "random-talent-source-not-ready",
        `Random Talent table “${source.key}” is not ready: ${source.reason ?? "its results are invalid"}.`,
      ),
    );
  }
}

function definitionLocation(definitionIndex: number): ValidationIssueLocation {
  return { definitionIndex, scope: "definition", section: "randomTalents" };
}

function subspeciesLocation(
  definitionIndex: number,
  subspeciesIndex: number,
): ValidationIssueLocation {
  return { definitionIndex, scope: "subspecies", section: "randomTalents", subspeciesIndex };
}
