import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../../../types/species-builder/species-builder";

import { createSpeciesConfigKey } from "../../../../../functions/species-builder/config-keys";

export function getSuggestedSpeciesKey(definition: SpeciesBuilderDefinition): string {
  return createSpeciesConfigKey(definition.name) || "new-species";
}

export function getSuggestedSubspeciesKey(subspecies: SpeciesBuilderSubspeciesDefinition): string {
  return createSpeciesConfigKey(subspecies.name) || "new-subspecies";
}
