<script setup lang="ts">
import { nextTick, ref, watch } from "vue";

import { useDialogFocusReturn } from "./dialog-focus";

const props = defineProps<{
  message: string | undefined;
}>();

const emit = defineEmits<{
  close: [];
  confirm: [];
}>();

const dialog = ref<HTMLDialogElement>();
const dialogFocus = useDialogFocusReturn();

function closeDialog(): void {
  dialog.value?.close();
}

function handleDialogClosed(): void {
  if (props.message) {
    emit("close");
  }

  dialogFocus.restore();
}

watch(
  () => props.message,
  async (message) => {
    if (message) {
      dialogFocus.capture();
      await nextTick();

      if (props.message && !dialog.value?.open) {
        dialog.value?.showModal();
      }
    } else if (dialog.value?.open) {
      dialog.value.close();
    }
  },
  { flush: "post", immediate: true },
);
</script>

<template>
  <dialog
    ref="dialog"
    class="dui-modal"
    aria-describedby="species-builder-delete-message"
    aria-labelledby="species-builder-delete-title"
    @close="handleDialogClosed"
    @keydown.esc.stop.prevent="closeDialog"
    @keyup.esc.stop
  >
    <div v-if="message" class="dui-modal-box">
      <h2 id="species-builder-delete-title">Confirm Deletion</h2>
      <p id="species-builder-delete-message">{{ message }}</p>
      <div class="dui-modal-action">
        <button class="dui-btn dui-btn-error" type="button" @click="emit('confirm')">Delete</button>
        <button autofocus class="dui-btn" type="button" @click="closeDialog">Cancel</button>
      </div>
    </div>
    <form class="dui-modal-backdrop" method="dialog">
      <button aria-label="Cancel deletion" type="submit">Close</button>
    </form>
  </dialog>
</template>
