import { defineStore } from "pinia";
import { ref } from "vue";

import type {
  NpcActorCombatProfile,
  NpcBaseActorDraftData,
  NpcBaseActorSummary,
  NpcBuilderSettings,
  NpcCareerQueueEntry,
  NpcCustomAdvancementSummary,
  NpcFolderSummary,
  NpcQuickTraitSummary,
  NpcSkillCharacteristicSummary,
  NpcSpellDraftEntry,
  NpcTalentMaximumSummary,
  NpcTraitDraftConfig,
  NpcTraitDraftEntry,
  NpcTrappingDraftEntry,
  NpcTrappingResolution,
} from "../../types/npc-builder";

import { createAdvancementStoreSlice } from "./advancements";
import { createDraftStoreSlice } from "./draft";
import { createHydrationStoreSlice } from "./hydration";
import { createMountStoreSlice } from "./mount";
import { createPortraitStoreSlice } from "./portraits";
import { defaultSettings, emptyBaseDraftData } from "./settings";
import { createSpellStoreSlice } from "./spells";
import { createTraitStoreSlice } from "./traits";
import { createTrappingStoreSlice } from "./trappings";

export const useNpcBuilderStore = defineStore("npc-builder", () => {
  const actorName = ref("");
  const actorFolders = ref<NpcFolderSummary[]>([]);
  const manualAdvancementDeltas = ref<Record<string, number>>({});
  const baseActorCombatProfile = ref<NpcActorCombatProfile | null>(null);
  const baseActorDraftData = ref<NpcBaseActorDraftData>({
    ...emptyBaseDraftData,
  });
  const baseActors = ref<NpcBaseActorSummary[]>([]);
  const careers = ref<NpcCareerQueueEntry[]>([]);
  const customTraits = ref<NpcTraitDraftEntry[]>([]);
  const customTrappings = ref<NpcTrappingDraftEntry[]>([]);
  const itemFolders = ref<NpcFolderSummary[]>([]);
  const mountActorProfile = ref<NpcActorCombatProfile | null>(null);
  const mountActors = ref<NpcBaseActorSummary[]>([]);
  const quickTraits = ref<NpcQuickTraitSummary[]>([]);
  const selectedPortraitPath = ref("");
  const settings = ref<NpcBuilderSettings>({ ...defaultSettings });
  const selectedBaseActorUuid = ref("");
  const selectedMountActorUuid = ref("");
  const skillCharacteristics = ref<Record<string, NpcSkillCharacteristicSummary>>({});
  const talentMaximums = ref<Record<string, NpcTalentMaximumSummary>>({});
  const skillGrantResolutions = ref<Record<string, string>>({});
  const detectedSpells = ref<NpcSpellDraftEntry[]>([]);
  const customSpells = ref<NpcSpellDraftEntry[]>([]);
  const customAdvancements = ref<NpcCustomAdvancementSummary[]>([]);
  const ignoredBaseTraitKeys = ref<Record<string, boolean>>({});
  const magicLoreResolutions = ref<Record<string, string>>({});
  const spellSelectionOverrides = ref<Record<string, boolean>>({});
  const traitConfigOverrides = ref<Record<string, Partial<NpcTraitDraftConfig>>>({});
  const trappingOverrides = ref<Record<string, { ignored?: boolean; quantity?: number }>>({});
  const trappingResolutionOverrides = ref<Record<string, NpcTrappingResolution>>({});

  const advancementSlice = createAdvancementStoreSlice({
    baseActorDraftData,
    careers,
    customAdvancements,
    manualAdvancementDeltas,
    settings,
    skillCharacteristics,
    skillGrantResolutions,
    talentMaximums,
  });

  const portraitSlice = createPortraitStoreSlice();

  const hydrationSlice = createHydrationStoreSlice({
    actorFolders,
    baseActorDraftData,
    baseActors,
    ignoredBaseTraitKeys,
    itemFolders,
    manualAdvancementDeltas,
    quickTraits,
    selectedBaseActorUuid,
    settings,
    traitConfigOverrides,
    trappingOverrides,
    trappingResolutionOverrides,
  });

  const mountSlice = createMountStoreSlice({
    baseActorCombatProfile,
    mountActorProfile,
    mountActors,
    selectedMountActorUuid,
  });

  const draftSlice = createDraftStoreSlice({
    actorName,
    baseActors,
    careers,
    clearBaseDraftData: hydrationSlice.clearBaseDraftData,
    clearMountSelection: mountSlice.clearMountSelection,
    customAdvancements,
    customSpells,
    customTraits,
    customTrappings,
    detectedSpells,
    ignoredBaseTraitKeys,
    magicLoreResolutions,
    removeSkillGrantResolutionsForCareer: advancementSlice.removeSkillGrantResolutionsForCareer,
    selectedBaseActorUuid,
    selectedPortraitPath,
    settings,
    skillGrantResolutions,
    spellSelectionOverrides,
  });

  const traitSlice = createTraitStoreSlice({
    baseActorDraftData,
    customTraits,
    ignoredBaseTraitKeys,
    quickTraits,
    settings,
    traitConfigOverrides,
  });

  const trappingSlice = createTrappingStoreSlice({
    baseActorDraftData,
    careers,
    customTrappings,
    settings,
    trappingOverrides,
    trappingResolutionOverrides,
  });

  const spellSlice = createSpellStoreSlice({
    advancements: advancementSlice.advancements,
    customSpells,
    detectedSpells,
    magicLoreResolutions,
    settings,
    spellSelectionOverrides,
    traits: traitSlice.traits,
  });

  function resetDraft(): void {
    draftSlice.resetDraft();
    portraitSlice.resetPortraitFilters();
  }

  return {
    actorName,
    actorFolders,
    addCareer: draftSlice.addCareer,
    addCareerIfMissing: draftSlice.addCareerIfMissing,
    addCustomAdvancement: advancementSlice.addCustomAdvancement,
    addCustomPortraitSearchTerm: portraitSlice.addCustomPortraitSearchTerm,
    addCustomSpell: spellSlice.addCustomSpell,
    addCustomTrait: traitSlice.addCustomTrait,
    addCustomTrapping: trappingSlice.addCustomTrapping,
    adjustAdvancementCurrent: advancementSlice.adjustAdvancementCurrent,
    advancements: advancementSlice.advancements,
    applyAutoAdvance: advancementSlice.applyAutoAdvance,
    baseActorCombatProfile,
    baseActorDraftData,
    baseActors,
    buildTraits: traitSlice.buildTraits,
    careers,
    clearCareers: draftSlice.clearCareers,
    clearBaseDraftData: hydrationSlice.clearBaseDraftData,
    clearMountSelection: mountSlice.clearMountSelection,
    customSpells,
    customAdvancements,
    customPortraitSearchTerms: portraitSlice.customPortraitSearchTerms,
    customTraits,
    customTrappings,
    estimatedNpcXp: advancementSlice.estimatedNpcXp,
    finalActorName: draftSlice.finalActorName,
    finalCareer: draftSlice.finalCareer,
    finalPortraitPath: draftSlice.finalPortraitPath,
    getSkillGrantResolution: advancementSlice.getSkillGrantResolution,
    grantTotals: draftSlice.grantTotals,
    hasMagicAccess: spellSlice.hasMagicAccess,
    hydrateActorFolders: hydrationSlice.hydrateActorFolders,
    hydrateBaseActorCombatProfile: mountSlice.hydrateBaseActorCombatProfile,
    hydrateBaseActorDraftData: hydrationSlice.hydrateBaseActorDraftData,
    hydrateBaseActors: hydrationSlice.hydrateBaseActors,
    hydrateDetectedSpells: spellSlice.hydrateDetectedSpells,
    hydrateItemFolders: hydrationSlice.hydrateItemFolders,
    hydrateMountActorProfile: mountSlice.hydrateMountActorProfile,
    hydrateMountActors: mountSlice.hydrateMountActors,
    hydrateQuickTraits: hydrationSlice.hydrateQuickTraits,
    hydrateSettings: hydrationSlice.hydrateSettings,
    hydrateSkillCharacteristics: advancementSlice.hydrateSkillCharacteristics,
    hydrateTalentMaximums: advancementSlice.hydrateTalentMaximums,
    itemFolders,
    magicGrants: spellSlice.magicGrants,
    magicLoreResolutions,
    mountActorProfile,
    mountActors,
    maximizableTalentCount: advancementSlice.maximizableTalentCount,
    maximizeTalents: advancementSlice.maximizeTalents,
    moveCareer: draftSlice.moveCareer,
    moveCareerToIndex: draftSlice.moveCareerToIndex,
    optionalTraits: traitSlice.optionalTraits,
    quickTraits,
    removeCareer: draftSlice.removeCareer,
    removeCustomAdvancement: advancementSlice.removeCustomAdvancement,
    removeCustomSpell: spellSlice.removeCustomSpell,
    removeCustomTrait: traitSlice.removeCustomTrait,
    removeCustomTrapping: trappingSlice.removeCustomTrapping,
    resetAdvancementCurrent: advancementSlice.resetAdvancementCurrent,
    resetAllAdvancementCurrents: advancementSlice.resetAllAdvancementCurrents,
    portraitSourceTagSections: portraitSlice.portraitSourceTagSections,
    portraitTermSections: portraitSlice.portraitTermSections,
    resetDraft,
    retainAvailablePortraitFilterTerms: portraitSlice.retainAvailablePortraitFilterTerms,
    selectBaseActor: draftSlice.selectBaseActor,
    selectBaseActorUuid: draftSlice.selectBaseActorUuid,
    selectMountActor: mountSlice.selectMountActor,
    selectMountActorUuid: mountSlice.selectMountActorUuid,
    selectedBaseActor: draftSlice.selectedBaseActor,
    selectedBaseActorUuid,
    selectedMountActorUuid,
    selectedPortraitPath,
    selectedSpells: spellSlice.selectedSpells,
    selectPortrait: draftSlice.selectPortrait,
    selectTrappingResolutionCandidate: trappingSlice.selectTrappingResolutionCandidate,
    setAdvancementCurrent: advancementSlice.setAdvancementCurrent,
    setAdvancementTotal: advancementSlice.setAdvancementTotal,
    setBaseTraitIgnored: traitSlice.setBaseTraitIgnored,
    setCareerQuantity: draftSlice.setCareerQuantity,
    setMagicGrantLoreResolution: spellSlice.setMagicGrantLoreResolution,
    setOptionalTraitSelected: traitSlice.setOptionalTraitSelected,
    setPortraitSourceTagSection: portraitSlice.setPortraitSourceTagSection,
    setPortraitTermSection: portraitSlice.setPortraitTermSection,
    setQuickTraitSelected: traitSlice.setQuickTraitSelected,
    setSkillGrantResolution: advancementSlice.setSkillGrantResolution,
    setSpellSelected: spellSlice.setSpellSelected,
    setTraitConfig: traitSlice.setTraitConfig,
    setTrappingFallback: trappingSlice.setTrappingFallback,
    setTrappingIgnored: trappingSlice.setTrappingIgnored,
    setTrappingQuantity: trappingSlice.setTrappingQuantity,
    setTrappingResolution: trappingSlice.setTrappingResolution,
    settings,
    spells: spellSlice.spells,
    suggestedActorName: draftSlice.suggestedActorName,
    traits: traitSlice.traits,
    trappings: trappingSlice.trappings,
  };
});
