import type { Component } from "vue";

import WoundFormulaApp from "../../../view/apps/species-builder-suite/WoundFormulaApp.vue";
import { MODULE_ID } from "../../constants";
import { SpeciesSuiteApplication } from "./SpeciesSuiteApplication";

export class WoundFormulaApplication extends SpeciesSuiteApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-wound-formula-builder`,
    classes: [MODULE_ID, "wfrp4e-customizer-wound-formula-builder"],
    position: { height: 610, width: 700 },
    window: {
      icon: "fa-solid fa-heart-pulse",
      resizable: true,
      title: "Wound Formula Builder",
    },
  };

  #definitionIndex = 0;
  #subspeciesIndex: number | undefined;

  constructor(
    private readonly openParent: (definitionIndex: number, subspeciesIndex?: number) => void,
  ) {
    super();
  }

  open(definitionIndex: number, subspeciesIndex?: number): Promise<this> {
    this.#definitionIndex = definitionIndex;
    this.#subspeciesIndex = subspeciesIndex;
    return this.render(true);
  }

  protected override getVueComponent(): Component {
    return WoundFormulaApp;
  }

  protected override getApplicationProps(): Record<string, unknown> {
    return {
      definitionIndex: this.#definitionIndex,
      onOpenParent: () => this.openParent(this.#definitionIndex, this.#subspeciesIndex),
      subspeciesIndex: this.#subspeciesIndex,
    };
  }
}
