import type { ComputedRef, Ref } from "vue";

import type {
  SpeciesBuilderBridge,
  SpeciesBuilderCareerReplacementRow,
  SpeciesBuilderDefinition,
  SpeciesBuilderItemReference,
  SpeciesBuilderItemReferenceType,
  SpeciesBuilderSubspeciesDefinition,
  SpeciesBuilderTalentReplacementRow,
} from "../../types/species-builder/species-builder";

import {
  careerReplacementRowsForDefinition,
  setCareerReplacementChoiceItem,
  setCareerReplacementRolledItem,
  setSpeciesCareerReplacementRows,
  setSpeciesTalentReplacementRows,
  setSubspeciesTalentReplacementRows,
  setTalentReplacementItem,
  talentReplacementRowsForDefinition,
  type TalentReplacementSlot,
} from "../../functions/species-builder/editor/replacements";
import { getErrorMessage } from "../../functions/species-builder/editor/draft";

interface DefinitionReplacementActions {
  updateSelectedDefinition: (
    update: (definition: SpeciesBuilderDefinition) => SpeciesBuilderDefinition,
  ) => void;
}

interface SubspeciesReplacementActions {
  updateSubspecies: (
    index: number,
    update: (subspecies: SpeciesBuilderSubspeciesDefinition) => SpeciesBuilderSubspeciesDefinition,
  ) => void;
}

interface ReplacementActionsContext {
  bridge: SpeciesBuilderBridge;
  definitionActions: DefinitionReplacementActions;
  loadError: Ref<string>;
  selectedDefinition: ComputedRef<SpeciesBuilderDefinition | undefined>;
  subspeciesActions: SubspeciesReplacementActions;
}

export function createSpeciesBuilderReplacementActions(context: ReplacementActionsContext) {
  function updateTalentReplacementRows(rows: SpeciesBuilderTalentReplacementRow[]): void {
    context.definitionActions.updateSelectedDefinition((definition) =>
      setSpeciesTalentReplacementRows(definition, rows),
    );
  }

  function updateCareerReplacementRows(rows: SpeciesBuilderCareerReplacementRow[]): void {
    context.definitionActions.updateSelectedDefinition((definition) =>
      setSpeciesCareerReplacementRows(definition, rows),
    );
  }

  function updateSubspeciesTalentReplacementRows(
    index: number,
    rows: SpeciesBuilderTalentReplacementRow[],
  ): void {
    context.subspeciesActions.updateSubspecies(index, (subspecies) =>
      setSubspeciesTalentReplacementRows(subspecies, rows),
    );
  }

  async function setTalentReplacementDrop(
    rowIndex: number,
    slot: TalentReplacementSlot,
    data: string,
  ): Promise<void> {
    const definition = context.selectedDefinition.value;

    if (!definition) {
      return;
    }

    const item = await resolveDroppedItem("talent", data);
    const rows = talentReplacementRowsForDefinition(definition);
    updateTalentReplacementRows(setTalentReplacementItem(rows, rowIndex, slot, item));
  }

  async function setSubspeciesTalentReplacementDrop(
    subspeciesIndex: number,
    rowIndex: number,
    slot: TalentReplacementSlot,
    data: string,
  ): Promise<void> {
    const subspecies = context.selectedDefinition.value?.subspecies?.[subspeciesIndex];

    if (!subspecies) {
      return;
    }

    const item = await resolveDroppedItem("talent", data);
    const rows = talentReplacementRowsForDefinition(subspecies);
    updateSubspeciesTalentReplacementRows(
      subspeciesIndex,
      setTalentReplacementItem(rows, rowIndex, slot, item),
    );
  }

  async function setCareerReplacementRolledDrop(rowIndex: number, data: string): Promise<void> {
    const definition = context.selectedDefinition.value;

    if (!definition) {
      return;
    }

    const item = await resolveDroppedItem("career", data);
    const rows = careerReplacementRowsForDefinition(definition);
    updateCareerReplacementRows(setCareerReplacementRolledItem(rows, rowIndex, item));
  }

  async function setCareerReplacementChoiceDrop(
    rowIndex: number,
    replacementIndex: number,
    data: string,
  ): Promise<void> {
    const definition = context.selectedDefinition.value;

    if (!definition) {
      return;
    }

    const item = await resolveDroppedItem("career", data);
    const rows = careerReplacementRowsForDefinition(definition);
    updateCareerReplacementRows(
      setCareerReplacementChoiceItem(rows, rowIndex, replacementIndex, item),
    );
  }

  async function openItemSheet(uuid: string): Promise<void> {
    try {
      await context.bridge.openItemSheet(uuid);
    } catch (error) {
      context.loadError.value = getErrorMessage(error);
    }
  }

  async function resolveDroppedItem(
    field: SpeciesBuilderItemReferenceType,
    data: string,
  ): Promise<SpeciesBuilderItemReference> {
    try {
      return await context.bridge.resolveItemDrop(data, field);
    } catch (error) {
      context.loadError.value = getErrorMessage(error);
      throw error;
    }
  }

  return {
    openItemSheet,
    resolveDroppedItem,
    setCareerReplacementChoiceDrop,
    setCareerReplacementRolledDrop,
    setSubspeciesTalentReplacementDrop,
    setTalentReplacementDrop,
    updateCareerReplacementRows,
    updateSubspeciesTalentReplacementRows,
    updateTalentReplacementRows,
  };
}
