export function requestReloadConfirmation(): Promise<boolean> {
  return new Promise((resolve) => {
    const dialog = document.createElement("dialog");
    dialog.classList.add("wfrp4e-customizer-confirm-dialog");

    const title = document.createElement("h2");
    title.textContent = "Reload Foundry?";

    const message = document.createElement("p");
    message.textContent = "Species Builder changes were saved. Reload Foundry now?";

    const actions = document.createElement("div");
    actions.classList.add("wfrp4e-customizer-confirm-dialog__actions");

    const reloadButton = document.createElement("button");
    reloadButton.type = "button";
    reloadButton.textContent = "Reload";

    const closeButton = document.createElement("button");
    closeButton.type = "button";
    closeButton.textContent = "Not Now";

    reloadButton.addEventListener("click", () => {
      finish(true);
    });
    closeButton.addEventListener("click", () => {
      finish(false);
    });
    dialog.addEventListener("cancel", (event) => {
      event.preventDefault();
      finish(false);
    });

    actions.append(reloadButton, closeButton);
    dialog.append(title, message, actions);
    document.body.append(dialog);
    dialog.showModal();

    function finish(shouldReload: boolean): void {
      dialog.close();
      dialog.remove();
      resolve(shouldReload);
    }
  });
}
