<script setup lang="ts">
import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderHeightDefinition,
} from "../../../../../../../../../types/species-builder/species-builder";
import {
  hasValidationErrors,
  issuesForField,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../../validation-presentation";

type DetailField = "age" | "height.die" | "height.feet" | "height.inches";

const props = defineProps<{
  definition: SpeciesBuilderDefinition;
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
}>();

const emit = defineEmits<{
  updateHeightField: [field: keyof SpeciesBuilderHeightDefinition, value: string];
  updateStringField: [field: "age", value: string];
}>();

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement ? event.target.value : "";
}

function fieldIssues(field: DetailField): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, field);
}

function fieldMessages(field: DetailField): string[] {
  return uniqueIssueMessages(fieldIssues(field));
}
</script>

<template>
  <div class="app:flex app:flex-wrap app:gap-3">
    <fieldset class="dui-fieldset app:min-w-56 app:flex-1">
      <legend class="dui-fieldset-legend">Age</legend>
      <p class="dui-fieldset-label">Formula used by character creation to roll age.</p>
      <label class="dui-label" for="species-age">Age formula</label>
      <input
        id="species-age"
        :aria-describedby="fieldIssues('age').length ? 'species-age-errors' : undefined"
        :aria-invalid="hasValidationErrors(fieldIssues('age')) || undefined"
        class="dui-input dui-input-sm app:w-full"
        :class="validationClass(fieldIssues('age'), 'dui-input-error', 'dui-input-warning')"
        :disabled="isDisabled"
        placeholder="2d10+15"
        :value="definition.age ?? ''"
        type="text"
        @input="emit('updateStringField', 'age', inputValue($event))"
      />
      <div v-if="fieldMessages('age').length" id="species-age-errors">
        <p
          v-for="message in fieldMessages('age')"
          :key="message"
          class="app:m-0 app:text-xs"
          :class="validationClass(fieldIssues('age'), 'app:text-error', 'app:text-warning')"
        >
          {{ message }}
        </p>
      </div>
    </fieldset>

    <fieldset class="dui-fieldset app:min-w-56 app:flex-1">
      <legend class="dui-fieldset-legend">Height</legend>
      <p class="dui-fieldset-label">Formula and base measurements used to roll random height.</p>
      <label class="dui-label" for="species-height-die">Height die</label>
      <input
        id="species-height-die"
        :aria-describedby="
          fieldIssues('height.die').length ? 'species-height-die-errors' : undefined
        "
        :aria-invalid="hasValidationErrors(fieldIssues('height.die')) || undefined"
        class="dui-input dui-input-sm app:w-full"
        :class="validationClass(fieldIssues('height.die'), 'dui-input-error', 'dui-input-warning')"
        :disabled="isDisabled"
        placeholder="1d10"
        :value="definition.height?.die ?? ''"
        type="text"
        @input="emit('updateHeightField', 'die', inputValue($event))"
      />
      <div v-if="fieldMessages('height.die').length" id="species-height-die-errors">
        <p
          v-for="message in fieldMessages('height.die')"
          :key="message"
          class="app:m-0 app:text-xs"
          :class="validationClass(fieldIssues('height.die'), 'app:text-error', 'app:text-warning')"
        >
          {{ message }}
        </p>
      </div>

      <label class="dui-label" for="species-height-feet">Base feet</label>
      <input
        id="species-height-feet"
        :aria-describedby="
          fieldIssues('height.feet').length ? 'species-height-feet-errors' : undefined
        "
        :aria-invalid="hasValidationErrors(fieldIssues('height.feet')) || undefined"
        class="dui-input dui-input-sm app:w-full"
        :class="validationClass(fieldIssues('height.feet'), 'dui-input-error', 'dui-input-warning')"
        :disabled="isDisabled"
        :value="definition.height?.feet ?? ''"
        type="number"
        @input="emit('updateHeightField', 'feet', inputValue($event))"
      />
      <div v-if="fieldMessages('height.feet').length" id="species-height-feet-errors">
        <p
          v-for="message in fieldMessages('height.feet')"
          :key="message"
          class="app:m-0 app:text-xs"
          :class="validationClass(fieldIssues('height.feet'), 'app:text-error', 'app:text-warning')"
        >
          {{ message }}
        </p>
      </div>

      <label class="dui-label" for="species-height-inches">Base inches</label>
      <input
        id="species-height-inches"
        :aria-describedby="
          fieldIssues('height.inches').length ? 'species-height-inches-errors' : undefined
        "
        :aria-invalid="hasValidationErrors(fieldIssues('height.inches')) || undefined"
        class="dui-input dui-input-sm app:w-full"
        :class="
          validationClass(fieldIssues('height.inches'), 'dui-input-error', 'dui-input-warning')
        "
        :disabled="isDisabled"
        :value="definition.height?.inches ?? ''"
        type="number"
        @input="emit('updateHeightField', 'inches', inputValue($event))"
      />
      <div v-if="fieldMessages('height.inches').length" id="species-height-inches-errors">
        <p
          v-for="message in fieldMessages('height.inches')"
          :key="message"
          class="app:m-0 app:text-xs"
          :class="
            validationClass(fieldIssues('height.inches'), 'app:text-error', 'app:text-warning')
          "
        >
          {{ message }}
        </p>
      </div>
    </fieldset>
  </div>
</template>
