import type { SpeciesBuilderBridge } from "../../../types/species-builder/species-builder";

import {
  openSpeciesBuilderItemSheet,
  resolveSpeciesBuilderItemDrop,
  resolveSpeciesBuilderJournalDrop,
} from "./item-drops";
import { loadRandomTalentSources } from "./random-talent-sources";
import { loadRuntimeSpecies } from "./runtime-species";
import { loadSpeciesBuilderSpeciesTable, saveSpeciesBuilderSpeciesTable } from "./world-table";
import { loadSpeciesBuilderSettings, saveSpeciesBuilderSettings } from "./settings";
import { loadSpeciesBuilderValidationCatalog } from "./validation/catalog";

export const foundrySpeciesBuilderBridge: SpeciesBuilderBridge = {
  loadSettings: async () => loadSpeciesBuilderSettings(),
  loadRandomTalentSources: async () => loadRandomTalentSources(),
  loadRuntimeSpecies,
  loadValidationCatalog: loadSpeciesBuilderValidationCatalog,
  loadSpeciesTable: async () => loadSpeciesBuilderSpeciesTable(),
  openItemSheet: openSpeciesBuilderItemSheet,
  resolveItemDrop: resolveSpeciesBuilderItemDrop,
  resolveJournalDrop: resolveSpeciesBuilderJournalDrop,
  saveSettings: async (settings) => ({ settings: await saveSpeciesBuilderSettings(settings) }),
  saveSpeciesTable: saveSpeciesBuilderSpeciesTable,
};
