import type {
  SpeciesBuilderItemReference,
  SpeciesBuilderItemReferenceType,
  SpeciesBuilderJournalReference,
} from "../../../types/species-builder/species-builder";

import { readUnknownPath } from "../../../shared/object-readers";
import { assertFoundryItem } from "../../foundry/document-guards";
import { parseDropData } from "../../foundry/drop-data";

export async function resolveSpeciesBuilderItemDrop(
  data: string,
  itemType: SpeciesBuilderItemReferenceType,
): Promise<SpeciesBuilderItemReference> {
  const dropData = parseDropData(data);

  if (dropData.type !== "Item" || !dropData.uuid) {
    throw new Error(`Drop a Foundry ${itemType} item here.`);
  }

  const item = assertFoundryItem(
    await fromUuid(dropData.uuid),
    `Drop a Foundry ${itemType} item here.`,
  );

  if (item.type !== itemType) {
    throw new Error(`Drop a Foundry ${itemType} item here.`);
  }

  const reference: SpeciesBuilderItemReference = {
    name: itemType === "career" ? readCareerGroupName(item) || item.name : item.name,
    type: itemType,
    uuid: item.uuid,
  };

  if (itemType === "career") {
    const careerJournalUuid = readCareerJournalUuid(item);

    if (careerJournalUuid) {
      reference.careerJournalUuid = careerJournalUuid;
    }
  }

  const specification = readSpeciesBuilderItemSpecification(item);

  if (specification) {
    reference.specification = specification;
  }

  if (item.img) {
    reference.img = item.img;
  }

  return reference;
}

export async function resolveSpeciesBuilderJournalDrop(
  data: string,
): Promise<SpeciesBuilderJournalReference> {
  const dropData = parseDropData(data);

  if (
    (dropData.type !== "JournalEntry" && dropData.type !== "JournalEntryPage") ||
    !dropData.uuid
  ) {
    throw new Error("Drop a Foundry Journal Entry or Journal Entry Page here.");
  }

  const document = await fromUuid(dropData.uuid);

  if (!isFoundryJournalDocument(document)) {
    throw new Error("Drop a Foundry Journal Entry or Journal Entry Page here.");
  }

  return {
    name: document.name,
    uuid: document.uuid,
  };
}

export async function openSpeciesBuilderItemSheet(uuid: string): Promise<void> {
  const item = assertFoundryItem(await fromUuid(uuid), "The linked Foundry Item was not found.");

  item.sheet?.render(true);
}

export function readSpeciesBuilderItemSpecification(
  item: Pick<FoundryItemDocument, "system"> & { specifier?: unknown },
): string {
  const candidates = [
    readUnknownPath(item.system, ["specification", "value"]),
    readUnknownPath(item, ["specifier"]),
    readUnknownPath(item.system, ["specifier"]),
    readUnknownPath(item.system, ["specifier", "value"]),
  ];

  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim()) {
      return candidate.trim();
    }

    if (typeof candidate === "number") {
      return String(candidate);
    }
  }

  return "";
}

function readCareerGroupName(item: FoundryItemDocument): string {
  const value = readUnknownPath(item.system, ["careergroup", "value"]);

  return typeof value === "string" ? value.trim() : "";
}

export function readCareerJournalUuid(item: Pick<FoundryItemDocument, "system">): string {
  const notes = readUnknownPath(item.system, ["description", "value"]);

  if (typeof notes !== "string") {
    return "";
  }

  const match = /^@UUID\[([^\]]+)]{[^{}]+}$/.exec(normalizeCareerNotes(notes));

  return match?.[1]?.trim() ?? "";
}

function normalizeCareerNotes(notes: string): string {
  let value = notes.trim();

  value = value.replaceAll(/<(p|div)>(?:\s|&nbsp;|<br\s*\/?>)*<\/\1>/gi, "").trim();

  const wrappedValue = /^<(p|div)>([\S\s]*)<\/\1>$/i.exec(value);

  if (wrappedValue?.[2] !== undefined) {
    value = wrappedValue[2].trim();
  }

  return decodeBasicHtmlEntities(value.replaceAll(/<br\s*\/?>/gi, "").trim());
}

function decodeBasicHtmlEntities(value: string): string {
  return value
    .replaceAll("&nbsp;", " ")
    .replaceAll("&amp;", "&")
    .replaceAll("&lt;", "<")
    .replaceAll("&gt;", ">")
    .replaceAll("&quot;", '"')
    .replaceAll("&#39;", "'")
    .trim();
}

function isFoundryJournalDocument(
  document: unknown,
): document is { documentName: "JournalEntry" | "JournalEntryPage"; name: string; uuid: string } {
  return (
    typeof document === "object" &&
    document !== null &&
    "documentName" in document &&
    ((document as { documentName?: unknown }).documentName === "JournalEntry" ||
      (document as { documentName?: unknown }).documentName === "JournalEntryPage") &&
    "name" in document &&
    typeof (document as { name?: unknown }).name === "string" &&
    "uuid" in document &&
    typeof (document as { uuid?: unknown }).uuid === "string"
  );
}
