import type {
  SpeciesBuilderCareerReplacementRow,
  SpeciesBuilderItemReference,
  SpeciesBuilderItemReferenceType,
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderTalentReplacementRow,
} from "../../types/species-builder/species-builder";

import { isRecord } from "../../shared/object-readers";

export function normalizeTalentReplacementRows(
  value: unknown,
): SpeciesBuilderTalentReplacementRow[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const rows = value.flatMap((entry) => {
    if (!isRecord(entry)) {
      return [];
    }

    const rolled = normalizeLinkedItemName(entry["rolled"], "talent");
    const replacement = normalizeLinkedItemName(entry["replacement"], "talent");

    if (!rolled.name || !replacement.name) {
      return [];
    }

    return [
      {
        replacement,
        rolled,
      },
    ];
  });

  return rows.length > 0 ? rows : undefined;
}

export function normalizeCareerReplacementRows(
  value: unknown,
): SpeciesBuilderCareerReplacementRow[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const rows = value.flatMap((entry) => {
    if (!isRecord(entry)) {
      return [];
    }

    const rolled = normalizeLinkedItemName(entry["rolled"], "career");
    const replacements = Array.isArray(entry["replacements"])
      ? entry["replacements"].flatMap((replacement) => {
          const normalized = normalizeLinkedItemName(replacement, "career");

          return normalized.name ? [normalized] : [];
        })
      : [];

    if (!rolled.name || replacements.length === 0) {
      return [];
    }

    return [
      {
        replacements,
        rolled,
      },
    ];
  });

  return rows.length > 0 ? rows : undefined;
}

export function normalizeLinkedItemName(
  value: unknown,
  itemType: SpeciesBuilderItemReferenceType,
): SpeciesBuilderLinkedItemName {
  if (typeof value === "string") {
    return {
      name: normalizeString(value) ?? "",
    };
  }

  if (!isRecord(value)) {
    return {
      name: "",
    };
  }

  const item = normalizeItemReference(value["item"], itemType);
  const name = normalizeString(value["name"]) ?? item?.name ?? "";

  return item
    ? {
        item,
        name,
      }
    : {
        name,
      };
}

function normalizeItemReference(
  value: unknown,
  itemType: SpeciesBuilderItemReferenceType,
): SpeciesBuilderItemReference | undefined {
  if (!isRecord(value)) {
    return undefined;
  }

  const name = normalizeString(value["name"]);
  const type = normalizeItemReferenceType(value["type"]);
  const uuid = normalizeString(value["uuid"]);

  if (!name || type !== itemType || !uuid) {
    return undefined;
  }

  const item: SpeciesBuilderItemReference = {
    name,
    type,
    uuid,
  };

  const specification =
    normalizeString(value["specification"]) ?? normalizeString(value["specifier"]);

  if (specification) {
    item.specification = specification;
  }

  const img = normalizeString(value["img"]);

  if (img) {
    item.img = img;
  }

  return item;
}

function normalizeItemReferenceType(value: unknown): SpeciesBuilderItemReferenceType | undefined {
  return value === "career" || value === "skill" || value === "talent" || value === "trait"
    ? value
    : undefined;
}

function normalizeString(value: unknown): string | undefined {
  if (typeof value !== "string") {
    return undefined;
  }

  const trimmed = value.trim();

  return trimmed || undefined;
}
