<script setup lang="ts">
import type { NpcTrappingDraftEntry } from "../../../../../types/npc-builder";

import { blankItemOptionValue } from "./constants";
import {
  canUseBlankItem,
  getResolutionLabel,
  getResolutionStatusLabel,
  getResolutionStatusPillClass,
  getResolutionTermsLabel,
  getResolutionValue,
  getTrappingSourceLabel,
  shouldShowResolutionSelect,
} from "./resolution-labels";

defineProps<{
  trappings: NpcTrappingDraftEntry[];
}>();

const emit = defineEmits<{
  quantityInput: [key: string, event: Event];
  removeCustomTrapping: [key: string];
  resolutionChange: [key: string, event: Event];
  useChange: [key: string, event: Event];
}>();
</script>

<template>
  <ul v-if="trappings.length" class="dui-list">
    <li v-for="trapping in trappings" :key="trapping.key" class="dui-list-row">
      <input
        :aria-label="`Use ${trapping.name}`"
        class="dui-checkbox dui-checkbox-sm"
        :checked="!trapping.ignored"
        type="checkbox"
        @change="emit('useChange', trapping.key, $event)"
      />
      <div class="dui-list-col-grow app:grid app:gap-2">
        <strong>{{ trapping.name }}</strong>
        <span>
          {{ trapping.resolution.selectedItemType || trapping.itemType || "trapping" }} ·
          {{ getTrappingSourceLabel(trapping) }}
        </span>
        <span v-if="getResolutionTermsLabel(trapping)">
          {{ getResolutionTermsLabel(trapping) }}
        </span>
        <span :class="getResolutionStatusPillClass(trapping)">
          {{ getResolutionStatusLabel(trapping) }}
        </span>
        <fieldset v-if="shouldShowResolutionSelect(trapping)" class="dui-fieldset">
          <legend class="dui-fieldset-legend">Resolution</legend>
          <select
            :aria-label="`Resolution for ${trapping.name}`"
            class="dui-select dui-select-sm"
            :value="getResolutionValue(trapping)"
            @change="emit('resolutionChange', trapping.key, $event)"
          >
            <option v-if="trapping.resolution.candidates.length" value="">Choose match</option>
            <option
              v-for="candidate in trapping.resolution.candidates"
              :key="candidate.uuid"
              :value="candidate.uuid"
            >
              {{ candidate.name }} ({{ candidate.sourceLabel }})
            </option>
            <option v-if="canUseBlankItem(trapping)" :value="blankItemOptionValue">
              Blank Item
            </option>
          </select>
        </fieldset>
        <span v-else>{{ getResolutionLabel(trapping) }}</span>
        <div class="dui-card-actions">
          <fieldset class="dui-fieldset">
            <legend class="dui-fieldset-legend">Quantity</legend>
            <input
              :aria-label="`Quantity for ${trapping.name}`"
              class="dui-input dui-input-sm"
              :value="trapping.quantity"
              min="1"
              type="number"
              @input="emit('quantityInput', trapping.key, $event)"
            />
          </fieldset>
          <button
            v-if="trapping.source === 'custom'"
            class="dui-btn dui-btn-sm"
            type="button"
            @click="emit('removeCustomTrapping', trapping.key)"
          >
            Remove
          </button>
        </div>
      </div>
    </li>
  </ul>
  <p v-else class="dui-alert">No trappings are selected yet.</p>
</template>
