import type { PortraitSearchProgressHandler } from "../../../types/portrait-gallery";
import type { PortraitSearchState } from "./types";

import { readStringPath } from "../../../shared/object-readers";
import { readCompendiumIndexEntries } from "../compendiums";
import {
  collectDocumentPortraitCandidates,
  emitPortraitSearchProgress,
  getActorPrototypeTokenImage,
} from "./candidate-utils";

export function collectWorldDocumentPortraitCandidates(
  state: PortraitSearchState,
  onProgress: PortraitSearchProgressHandler | undefined,
): void {
  emitPortraitSearchProgress(onProgress, state, {
    currentLocation: "World Actors and Items",
    maxDirectories: 0,
    phase: "world-documents",
  });

  for (const actor of game.actors.contents) {
    collectDocumentPortraitCandidates(state, {
      imagePaths: [
        {
          label: "actor image",
          path: actor.img ?? "",
        },
        {
          label: "token image",
          path: getActorPrototypeTokenImage(actor),
        },
      ],
      name: actor.name,
      sourceGroup: "world",
      sourceLabel: "World Actors",
      sourceKey: actor.uuid,
    });
  }

  for (const item of game.items?.contents ?? []) {
    collectDocumentPortraitCandidates(state, {
      imagePaths: [
        {
          label: "item image",
          path: item.img ?? "",
        },
      ],
      name: item.name,
      sourceGroup: "world",
      sourceLabel: "World Items",
      sourceKey: item.uuid,
    });
  }
}

export async function collectCompendiumPortraitCandidates(
  state: PortraitSearchState,
  onProgress: PortraitSearchProgressHandler | undefined,
): Promise<void> {
  emitPortraitSearchProgress(onProgress, state, {
    currentLocation: "Actor and Item compendiums",
    maxDirectories: 0,
    phase: "compendiums",
  });

  for (const pack of game.packs ?? []) {
    if (pack.documentName !== "Actor" && pack.documentName !== "Item") {
      continue;
    }

    const index = await pack
      .getIndex?.({
        fields: ["name", "img", "thumb", "prototypeToken.texture.src"],
      })
      .catch(() => undefined);

    const entries = index ? readCompendiumIndexEntries(index) : [];

    for (const entry of entries) {
      collectDocumentPortraitCandidates(state, {
        imagePaths: [
          {
            label: `${pack.documentName.toLocaleLowerCase()} image`,
            path: entry.img ?? "",
          },
          {
            label: "thumbnail",
            path: entry.thumb ?? "",
          },
          {
            label: "token image",
            path: readStringPath(entry, ["prototypeToken", "texture", "src"]),
          },
        ],
        name: entry.name ?? "",
        sourceGroup: "compendiums",
        sourceLabel: pack.title ?? "Compendium",
        sourceKey: `${pack.collection ?? pack.title ?? "pack"}:${entry._id ?? entry.name ?? ""}`,
      });
    }
  }
}
