import type { Component } from "vue";

import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";

import SpeciesIssuesApp from "../../../view/apps/species-builder-suite/SpeciesIssuesApp.vue";
import { MODULE_ID } from "../../constants";
import { SpeciesSuiteApplication } from "./SpeciesSuiteApplication";

export class SpeciesIssuesApplication extends SpeciesSuiteApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-species-issues`,
    classes: [MODULE_ID, "wfrp4e-customizer-species-issues"],
    position: { height: 640, width: 760 },
    window: {
      icon: "fa-solid fa-triangle-exclamation",
      resizable: true,
      title: "Species Validation Issues",
    },
  };

  #definitionIndex: number | undefined;

  constructor(
    private readonly openDirectory: () => void,
    private readonly selectIssue: (issue: SpeciesBuilderValidationIssue) => void,
  ) {
    super();
  }

  open(definitionIndex?: number): Promise<this> {
    this.#definitionIndex = definitionIndex;
    return this.render(true);
  }

  protected override getVueComponent(): Component {
    return SpeciesIssuesApp;
  }

  protected override getApplicationProps(): Record<string, unknown> {
    return {
      definitionIndex: this.#definitionIndex,
      onOpenDirectory: this.openDirectory,
      onSelectIssue: this.selectIssue,
    };
  }
}
