import type { Ref } from "vue";

import type {
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../types/wfrp4e/characteristics";

import type {
  SpeciesBuilderSubspeciesArrayField,
  SpeciesBuilderSubspeciesTextMapField,
} from "../../functions/species-builder/editor/field-values";
import { canEditSpeciesSubspecies } from "../../functions/species-builder/editing-definitions";
import {
  appendBlankSubspecies,
  removeSubspecies,
  setSubspeciesArrayField,
  setSubspeciesCareerTableRows,
  setSubspeciesCharacteristic,
  setSubspeciesNumberField,
  setSubspeciesStringField,
  setSubspeciesTextMapField,
  setSubspeciesWoundFormula,
  updateSubspeciesAtIndex,
} from "../../functions/species-builder/editor/subspecies-fields";
import { updateSelectedDefinitionAtIndex } from "./selected-definition";

interface SubspeciesActionContext {
  definitions: Ref<SpeciesBuilderEditingDefinition[]>;
  message: Ref<string>;
  selectedIndex: Ref<number>;
}

export function createSpeciesBuilderSubspeciesActions(context: SubspeciesActionContext) {
  function addSubspecies(): void {
    updateSelectedDefinition(appendBlankSubspecies, true);
  }

  function deleteSubspecies(index: number): void {
    if (!canEditSubspecies(index)) {
      return;
    }

    updateSelectedDefinition((definition) => removeSubspecies(definition, index), true);
  }

  function updateSubspeciesStringField(index: number, field: "key" | "name", value: string): void {
    updateSubspecies(index, (subspecies) => setSubspeciesStringField(subspecies, field, value));
  }

  function updateSubspeciesNumberField(
    index: number,
    field: "extra" | "fate" | "movement" | "resilience",
    value: string,
  ): void {
    updateSubspecies(index, (subspecies) => setSubspeciesNumberField(subspecies, field, value));
  }

  function updateSubspeciesCharacteristic(
    index: number,
    key: WfrpCharacteristicKey,
    value: string,
  ): void {
    updateSubspecies(index, (subspecies) => setSubspeciesCharacteristic(subspecies, key, value));
  }

  function updateSubspeciesArrayField(
    index: number,
    field: SpeciesBuilderSubspeciesArrayField,
    value: string,
  ): void {
    updateSubspecies(index, (subspecies) => setSubspeciesArrayField(subspecies, field, value));
  }

  function updateSubspeciesTextMapField(
    index: number,
    field: SpeciesBuilderSubspeciesTextMapField,
    value: string,
  ): void {
    updateSubspecies(index, (subspecies) => setSubspeciesTextMapField(subspecies, field, value));
  }

  function updateSubspeciesWoundFormula(index: number, value: string): void {
    updateSubspecies(index, (subspecies) => setSubspeciesWoundFormula(subspecies, value));
  }

  function updateSubspeciesCareerTableRows(
    index: number,
    rows: SpeciesBuilderCareerTableRow[],
  ): void {
    updateSubspecies(index, (subspecies) => setSubspeciesCareerTableRows(subspecies, rows));
  }

  function updateSubspecies(
    index: number,
    update: (subspecies: SpeciesBuilderSubspeciesDefinition) => SpeciesBuilderSubspeciesDefinition,
  ): void {
    updateDefinitionForSubspecies(index, (definition) =>
      updateSubspeciesAtIndex(definition, index, update),
    );
  }

  function updateDefinitionForSubspecies(
    index: number,
    update: (definition: SpeciesBuilderDefinition) => SpeciesBuilderDefinition,
  ): void {
    if (!canEditSubspecies(index)) {
      return;
    }

    updateSelectedDefinition(update, true);
  }

  function canEditSubspecies(index: number): boolean {
    const definition = context.definitions.value[context.selectedIndex.value];

    return (
      definition?.subspecies?.[index] !== undefined && canEditSpeciesSubspecies(definition, index)
    );
  }

  function updateSelectedDefinition(
    update: (definition: SpeciesBuilderDefinition) => SpeciesBuilderDefinition,
    allowRuntimeBase = false,
  ): void {
    updateSelectedDefinitionAtIndex(context, update, { allowRuntimeBase });
  }

  return {
    addSubspecies,
    canEditSubspecies,
    deleteSubspecies,
    updateSubspeciesArrayField,
    updateSubspeciesCharacteristic,
    updateSubspeciesCareerTableRows,
    updateSubspeciesNumberField,
    updateSubspeciesStringField,
    updateSubspecies,
    updateDefinitionForSubspecies,
    updateSubspeciesTextMapField,
    updateSubspeciesWoundFormula,
  };
}
