import type { ComputedRef, Ref } from "vue";

import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSpeciesTableDraft,
  SpeciesBuilderSpeciesTableLoad,
} from "../../types/species-builder/species-builder";

import {
  createEmptySpeciesTableDraft,
  mergeSpeciesTableOptions,
  prepareSpeciesTableDraft,
  snapshotSpeciesTable,
  summarizeSpeciesTableRows,
  validateSpeciesTableDraft,
} from "../../functions/species-builder/world-table";
import { clonePlain } from "../../functions/species-builder/editor/draft";
import { computed, ref } from "vue";

interface SpeciesTableActionContext {
  autoRegisterSpeciesTable: Ref<boolean>;
  definitions: ComputedRef<SpeciesBuilderDefinition[]>;
  message: Ref<string>;
}

export function createSpeciesTableActions(context: SpeciesTableActionContext) {
  const speciesTable = ref<SpeciesBuilderSpeciesTableDraft>(createEmptySpeciesTableDraft());
  const runtimeSpeciesOptions = ref<SpeciesBuilderSpeciesTableLoad["runtimeOptions"]>([]);
  const speciesTableOptions = computed(() =>
    mergeSpeciesTableOptions(runtimeSpeciesOptions.value, context.definitions.value),
  );
  const preparedSpeciesTable = computed(() =>
    prepareSpeciesTableDraft(speciesTable.value, speciesTableOptions.value),
  );
  const speciesTableSnapshot = computed(() => snapshotSpeciesTable(preparedSpeciesTable.value));
  const speciesTableSummaries = computed(() =>
    summarizeSpeciesTableRows(preparedSpeciesTable.value.rows),
  );
  const speciesTableValidationMessages = computed(() =>
    validateSpeciesTableDraft(
      preparedSpeciesTable.value,
      speciesTableOptions.value,
      context.autoRegisterSpeciesTable.value || preparedSpeciesTable.value.ownership !== "new",
    ),
  );

  function hydrateSpeciesTable(load: SpeciesBuilderSpeciesTableLoad): void {
    speciesTable.value = clonePlain(load.draft);
    runtimeSpeciesOptions.value = clonePlain(load.runtimeOptions);
  }

  function addSpeciesTableRow(): void {
    speciesTable.value.rows.push({
      name: "",
      speciesKey: "",
      weight: 1,
    });
    clearMessage();
  }

  function removeSpeciesTableRow(index: number): void {
    speciesTable.value.rows.splice(index, 1);
    clearMessage();
  }

  function updateSpeciesTableRowKey(index: number, speciesKey: string): void {
    const row = speciesTable.value.rows[index];

    if (!row) {
      return;
    }

    const option = speciesTableOptions.value.find((entry) => entry.key === speciesKey);
    delete row.journalUuid;
    row.speciesKey = speciesKey;
    row.name = option?.label ?? row.name;
    clearMessage();
  }

  function updateSpeciesTableRowWeight(index: number, value: string): void {
    const row = speciesTable.value.rows[index];

    if (!row) {
      return;
    }

    row.weight = value.trim() ? Number(value) : 0;
    clearMessage();
  }

  function clearMessage(): void {
    context.message.value = "";
  }

  return {
    addSpeciesTableRow,
    hydrateSpeciesTable,
    preparedSpeciesTable,
    removeSpeciesTableRow,
    runtimeSpeciesOptions,
    speciesTable,
    speciesTableOptions,
    speciesTableSnapshot,
    speciesTableSummaries,
    speciesTableValidationMessages,
    updateSpeciesTableRowKey,
    updateSpeciesTableRowWeight,
  };
}
