import type { SpeciesBuilderBridge } from "../../types/species-builder/species-builder";

export function createSpeciesBuilderBridgeAccess() {
  let bridge: SpeciesBuilderBridge | undefined;

  function requireBridge(): SpeciesBuilderBridge {
    if (!bridge) {
      throw new Error("Species Builder has not been connected to its Foundry bridge.");
    }

    return bridge;
  }

  const configuredBridge: SpeciesBuilderBridge = {
    loadRandomTalentSources: () => requireBridge().loadRandomTalentSources(),
    loadRuntimeSpecies: () => requireBridge().loadRuntimeSpecies(),
    loadSettings: () => requireBridge().loadSettings(),
    loadSpeciesTable: () => requireBridge().loadSpeciesTable(),
    loadValidationCatalog: (persistedDefinitionKeys) =>
      requireBridge().loadValidationCatalog(persistedDefinitionKeys),
    openItemSheet: (uuid) => requireBridge().openItemSheet(uuid),
    resolveItemDrop: (data, itemType) => requireBridge().resolveItemDrop(data, itemType),
    resolveJournalDrop: (data) => requireBridge().resolveJournalDrop(data),
    saveSettings: (settings, syncGeneratedDocuments) =>
      requireBridge().saveSettings(settings, syncGeneratedDocuments),
    saveSpeciesTable: (draft, registerInWfrp) =>
      requireBridge().saveSpeciesTable(draft, registerInWfrp),
  };

  function configure(nextBridge: SpeciesBuilderBridge): void {
    bridge = nextBridge;
  }

  return { configure, configuredBridge, requireBridge };
}
