import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

import { careers, species, subspecies } from "./shared";

export function createSkavenFamilyDefinition(): SpeciesBuilderDefinition {
  return species("skaven", "Skaven", [20, 20, 20, 20, 30, 25, 20, 20, 10, 10], {
    age: "1d10+5",
    careerTable: careers(
      "Thief",
      "Outlaw",
      "Scout",
      "Rat Catcher",
      "Smuggler",
      "Beggar",
      "Servant",
      "Messenger",
      "Spy",
      "Soldier",
    ),
    extra: 2,
    fate: 3,
    height: { die: "1d10", feet: 4, inches: 5 },
    includeInExtraSpecies: true,
    movement: 5,
    resilience: 0,
    skills: [
      "Athletics",
      "Bribery",
      "Dodge",
      "Gamble",
      "Language (Queekish)",
      "Lore (Skaven)",
      "Melee (Basic)",
      "Perception",
      "Ranged (Sling)",
      "Sleight of Hand",
      "Stealth (Underground)",
      "Stealth (Urban)",
    ],
    subspecies: createSkavenSubspecies(),
    talents: [
      "Night Vision",
      "Acute Sense (Smell)",
      "Snivel, Beneath Notice, Flee!",
      "Tunnel Rat, Enclosed Fighter",
    ],
    traits: [],
  });
}

