<script setup lang="ts">
import {
  hasValidationErrors,
  issuesForField,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../../validation-presentation";
import { WOUND_FORMULA_KEYWORDS } from "../../../../../../../../../functions/species-builder/wound-formula-keywords";

const props = defineProps<{
  formula: string | undefined;
  generatedTraitName: string | undefined;
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
}>();

const emit = defineEmits<{
  updateWoundFormula: [value: string];
}>();

function textAreaValue(event: Event): string {
  return event.target instanceof HTMLTextAreaElement ? event.target.value : "";
}

function formulaIssues(): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, "woundFormula");
}

function formulaMessages(): string[] {
  return uniqueIssueMessages(formulaIssues());
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">Wound Calculation</legend>
        <p class="dui-fieldset-label">
          Use <code>{Skill or Characteristic}</code> for a total value,
          <code>[Skill or Characteristic]</code> for its bonus, and
          <code>{Skill|Characteristic}</code> or <code>[Skill|Characteristic]</code> to base a skill
          on another characteristic. You can also use keywords such as <code>@tb</code>,
          <code>@scale</code>, and <code>@xp</code>.
        </p>
        <details class="dui-collapse dui-collapse-arrow">
          <summary class="dui-collapse-title">Formula keyword guide</summary>
          <div class="dui-collapse-content">
            <p>
              Keywords pull values from the current Actor during Wound calculation. Size uses
              <code>@size</code> as steps from Average and <code>@scale</code> as powers of two.
            </p>
            <div aria-label="Wound formula keywords">
              <code v-for="keyword in WOUND_FORMULA_KEYWORDS" :key="keyword" class="dui-badge">
                {{ keyword }}
              </code>
            </div>
          </div>
        </details>
        <label class="dui-label" for="species-wound-formula">Formula</label>
        <textarea
          id="species-wound-formula"
          :aria-describedby="formulaIssues().length ? 'species-wound-formula-errors' : undefined"
          :aria-invalid="hasValidationErrors(formulaIssues()) || undefined"
          class="dui-textarea app:w-full"
          :class="validationClass(formulaIssues(), 'dui-textarea-error', 'dui-textarea-warning')"
          :disabled="isDisabled"
          :value="formula ?? ''"
          placeholder="@sb * (1 + @sbMultiplier) + @tb * (2 + @tbMultiplier) + @wpb * (1 + @wpbMultiplier)"
          rows="4"
          @input="emit('updateWoundFormula', textAreaValue($event))"
        />
        <div v-if="formulaMessages().length" id="species-wound-formula-errors">
          <p
            v-for="message in formulaMessages()"
            :key="message"
            class="app:m-0 app:text-xs"
            :class="validationClass(formulaIssues(), 'app:text-error', 'app:text-warning')"
          >
            {{ message }}
          </p>
        </div>
        <p v-if="generatedTraitName" class="dui-alert dui-alert-info">
          Generated Trait item: {{ generatedTraitName }}
        </p>
      </fieldset>
    </div>
  </section>
</template>
