import type { useSpeciesBuilderEditor } from "../../../../state/species-builder/editor";

import { ref } from "vue";

type SpeciesBuilderEditor = ReturnType<typeof useSpeciesBuilderEditor>;

export function useSpeciesBuilderUnsafeSave(editor: SpeciesBuilderEditor) {
  const isConfirmationOpen = ref(false);

  function requestSave(): void {
    if (editor.requiresUnsafeSaveConfirmation.value) {
      isConfirmationOpen.value = true;
      return;
    }

    void editor.saveChanges();
  }

  function confirmSave(): void {
    isConfirmationOpen.value = false;
    void editor.saveChanges({ allowValidationErrors: true });
  }

  function closeConfirmation(): void {
    isConfirmationOpen.value = false;
  }

  return {
    closeConfirmation,
    confirmSave,
    isConfirmationOpen,
    requestSave,
  };
}
