import type { SpeciesBuilderValidationCatalog } from "../../../../types/species-builder/validation";

import { isRecord } from "../../../../shared/object-readers";

type RandomTalentSource = SpeciesBuilderValidationCatalog["randomTalentSources"][number];

export interface RuntimeGrantValidationContext {
  randomTalentSources: ReadonlyMap<string, RandomTalentSource>;
  skills: ReadonlySet<string>;
  talents: ReadonlySet<string>;
  traits: ReadonlySet<string>;
}

export interface RuntimeGrantValues {
  randomTalents: unknown;
  skills: unknown;
  talentReplacement: unknown;
  talents: unknown;
  traits: unknown;
}

export function addRuntimeGrantProblems(
  values: RuntimeGrantValues,
  context: RuntimeGrantValidationContext,
  errors: string[],
  warnings: string[],
): void {
  const randomTalentKeys = validateRandomTalentRecord(
    values.randomTalents,
    context.randomTalentSources,
    errors,
  );

  validateNamedArray(values.skills, "skills", context.skills, errors, warnings);
  validateTalentArray(values.talents, randomTalentKeys, context, errors, warnings);
  validateNamedArray(values.traits, "traits", context.traits, errors, warnings);
  validateTalentReplacements(values.talentReplacement, context.talents, warnings);
}

export function addRuntimeCareerReplacementProblems(
  source: unknown,
  careerGroups: ReadonlySet<string>,
  problems: string[],
): void {
  if (!source) {
    return;
  }

  if (!isRecord(source)) {
    problems.push("Career replacements are not an object");
    return;
  }

  for (const [rolled, replacements] of Object.entries(source)) {
    if (!careerGroups.has(rolled)) {
      problems.push(`Career replacement source ${label(rolled)} does not match exactly`);
    }

    if (!Array.isArray(replacements) || replacements.length === 0) {
      problems.push(`Career replacements for ${label(rolled)} must be a non-empty array`);
      continue;
    }

    for (const replacement of replacements) {
      if (typeof replacement !== "string" || !careerGroups.has(replacement.trim())) {
        problems.push(`Career replacement ${label(replacement)} does not match exactly`);
      }
    }
  }
}

function validateRandomTalentRecord(
  source: unknown,
  availableSources: ReadonlyMap<string, RandomTalentSource>,
  errors: string[],
): Set<string> {
  const effectiveSource = source || { talents: 0 };

  if (!isRecord(effectiveSource)) {
    errors.push("random Talents configuration is not an object");
    return new Set();
  }

  const keys = new Set(Object.keys(effectiveSource));

  for (const [key, count] of Object.entries(effectiveSource)) {
    if (!isNonNegativeIntegerLike(count)) {
      errors.push(`random Talent count for ${label(key)} is not a non-negative whole number`);
    }

    const table = availableSources.get(key);

    if (!table) {
      errors.push(`random Talent table is missing for ${label(key)}`);
    } else if (!table.readyForCharacterCreation) {
      errors.push(
        `random Talent table ${label(key)} is not ready: ${table.reason ?? "invalid results"}`,
      );
    }
  }

  return keys;
}

function validateNamedArray(
  source: unknown,
  field: "skills" | "traits",
  names: ReadonlySet<string>,
  errors: string[],
  warnings: string[],
): void {
  if (!Array.isArray(source)) {
    errors.push(`${field} must be an array of names`);
    return;
  }

  const invalid = source.filter(
    (entry) => typeof entry !== "string" || !names.has(itemBaseName(entry)),
  );

  if (invalid.length > 0) {
    warnings.push(`${field} do not match available Items exactly: ${uniqueLabels(invalid)}`);
  }
}

function validateTalentArray(
  source: unknown,
  randomTalentKeys: ReadonlySet<string>,
  context: RuntimeGrantValidationContext,
  errors: string[],
  warnings: string[],
): void {
  if (!Array.isArray(source)) {
    errors.push("talents must be an array of names or numeric random Talent counts");
    return;
  }

  for (const entry of source) {
    if (isNumericLike(entry)) {
      if (!isNonNegativeIntegerLike(entry)) {
        errors.push(`numeric Talent grant ${label(entry)} is not a non-negative whole number`);
      }
      requireConfiguredRandomSource("talents", randomTalentKeys, context, errors);
      continue;
    }

    if (typeof entry !== "string") {
      errors.push(`Talent grant ${label(entry)} is not a name or numeric count`);
      continue;
    }

    const choices = entry.includes(",") ? entry.split(",") : [entry];

    for (const choice of choices) {
      const name = choice.trim();
      const randomMatch = entry.includes(",") ? matchRandomChoice(name) : undefined;

      if (randomMatch) {
        requireConfiguredRandomSource(randomMatch.key, randomTalentKeys, context, errors);
      } else if (!context.talents.has(itemBaseName(name))) {
        warnings.push(`Talent ${label(name)} does not match an available Item exactly`);
      }
    }
  }
}

function requireConfiguredRandomSource(
  key: string,
  configuredKeys: ReadonlySet<string>,
  context: RuntimeGrantValidationContext,
  problems: string[],
): void {
  if (!configuredKeys.has(key)) {
    problems.push(`Talent grant uses random table ${label(key)} without configuring that key`);
    return;
  }

  const source = context.randomTalentSources.get(key);

  if (!source) {
    problems.push(`Talent grant uses missing random table ${label(key)}`);
  } else if (!source.readyForCharacterCreation) {
    problems.push(`Talent grant uses unready random table ${label(key)}`);
  }
}

function validateTalentReplacements(
  source: unknown,
  talentNames: ReadonlySet<string>,
  warnings: string[],
): void {
  if (!source) {
    return;
  }

  if (!isRecord(source)) {
    warnings.push("Talent replacements are not an object");
    return;
  }

  for (const [rolled, replacement] of Object.entries(source)) {
    if (!talentNames.has(itemBaseName(rolled))) {
      warnings.push(`Talent replacement source ${label(rolled)} does not match exactly`);
    }
    if (typeof replacement !== "string" || !talentNames.has(itemBaseName(replacement))) {
      warnings.push(`Talent replacement ${label(replacement)} does not match exactly`);
    }
  }
}

function matchRandomChoice(value: string): { key: string } | undefined {
  const match = /random\[(\d)\](?:\[?([a-zA-Z-_]+)\])?/iu.exec(value);

  return match ? { key: match[2] ?? "talents" } : undefined;
}

function isNumericLike(value: unknown): boolean {
  return (
    (typeof value === "number" && Number.isFinite(value)) ||
    (typeof value === "string" && value.trim() !== "" && Number.isFinite(Number(value)))
  );
}

function isNonNegativeIntegerLike(value: unknown): boolean {
  return isNumericLike(value) && Number.isInteger(Number(value)) && Number(value) >= 0;
}

function itemBaseName(value: string): string {
  return value.split("(")[0]?.trim() ?? "";
}

function uniqueLabels(values: unknown[]): string {
  return [...new Set(values.map(label))].join(", ");
}

function label(value: unknown): string {
  return `“${typeof value === "string" ? value.trim() || "(blank)" : String(value)}”`;
}
