<script setup lang="ts">
import { computed, ref } from "vue";

import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

import {
  parseSpeciesDefinitionImport,
  serializeSpeciesDefinitionExport,
} from "../../../../functions/species-builder/definition-portability";
import { createSpeciesConfigKey } from "../../../../functions/species-builder/config-keys";
import { useDialogFocusReturn } from "./dialog-focus";

const props = defineProps<{
  definition: SpeciesBuilderDefinition | undefined;
  buttonClass?: string;
  dialogHost?: HTMLElement;
  existingKeys: string[];
  isDisabled: boolean;
  isImportOnly: boolean;
}>();

const emit = defineEmits<{
  importDefinition: [definition: SpeciesBuilderDefinition];
}>();

const dialog = ref<HTMLDialogElement>();
const dialogFocus = useDialogFocusReturn();
const importError = ref("");
const importText = ref("");
const message = ref("");
const stagedDefinition = ref<SpeciesBuilderDefinition>();
const exportResult = computed(() => {
  if (!props.definition) {
    return { error: "Select a species before exporting.", text: "" };
  }

  try {
    return { error: "", text: serializeSpeciesDefinitionExport(props.definition) };
  } catch (error) {
    return {
      error: error instanceof Error ? error.message : "The selected species cannot be exported.",
      text: "",
    };
  }
});
const hasDuplicateKey = computed(
  () =>
    Boolean(stagedDefinition.value) &&
    props.existingKeys.includes(createSpeciesConfigKey(stagedDefinition.value?.key ?? "")),
);

function openDialog(): void {
  message.value = "";
  dialogFocus.capture();
  dialog.value?.showModal();
}

function close(): void {
  dialog.value?.close();
}

function handleDialogClosed(): void {
  importError.value = "";
  message.value = "";
  stagedDefinition.value = undefined;
  dialogFocus.restore();
}

function updateImportText(event: Event): void {
  importText.value = event.target instanceof HTMLTextAreaElement ? event.target.value : "";
  importError.value = "";
  message.value = "";
  stagedDefinition.value = undefined;
}

function validateImport(): void {
  if (props.isDisabled) {
    return;
  }

  const result = parseSpeciesDefinitionImport(importText.value);

  if (!result.ok) {
    importError.value = result.error;
    message.value = "";
    stagedDefinition.value = undefined;
    return;
  }

  importError.value = "";
  message.value = `Validated ${result.definition.name}. Review it before adding.`;
  stagedDefinition.value = result.definition;
}

async function loadImportFile(event: Event): Promise<void> {
  const input = event.target;

  if (!(input instanceof HTMLInputElement) || props.isDisabled) {
    return;
  }

  const file = input.files?.[0];

  if (!file) {
    return;
  }

  try {
    importText.value = await file.text();
    validateImport();
  } catch {
    importText.value = "";
    importError.value =
      "The selected file could not be read. Choose another JSON file or paste it.";
    message.value = "";
    stagedDefinition.value = undefined;
  } finally {
    input.value = "";
  }
}

async function copyExport(): Promise<void> {
  if (props.isDisabled) {
    return;
  }

  if (!exportResult.value.text || !navigator.clipboard) {
    message.value = "Clipboard access is unavailable. Select and copy the export text manually.";
    return;
  }

  try {
    await navigator.clipboard.writeText(exportResult.value.text);
    message.value = "Species export copied to the clipboard.";
  } catch {
    message.value = "Copy failed. Select and copy the export text manually.";
  }
}

function addImportedDefinition(): void {
  if (props.isDisabled || !stagedDefinition.value || hasDuplicateKey.value) {
    return;
  }

  emit("importDefinition", stagedDefinition.value);
  close();
}
</script>

<template>
  <button
    class="app:w-full app:whitespace-nowrap"
    :class="buttonClass"
    :disabled="isDisabled"
    type="button"
    @click="openDialog"
  >
    <i
      aria-hidden="true"
      :class="isImportOnly ? 'fa-solid fa-file-import' : 'fa-solid fa-arrow-right-arrow-left'"
    />
    {{ isImportOnly ? "Import Species" : "Import / Export" }}
  </button>

  <Teleport v-if="dialogHost" :to="dialogHost">
    <dialog
      ref="dialog"
      aria-labelledby="species-portability-title"
      class="dui-modal"
      @close="handleDialogClosed"
      @keydown.esc.stop.prevent="close"
      @keyup.esc.stop
    >
      <section class="dui-modal-box">
        <h2 id="species-portability-title">
          {{ isImportOnly ? "Import Species Definition" : "Transfer Species Definition" }}
        </h2>
        <p>
          Imports are staged here and never replace the current draft. Exported JSON contains only
          project-owned authoring data and names, without Foundry document links.
        </p>

        <div v-if="isImportOnly" class="dui-alert dui-alert-info" role="note">
          <i aria-hidden="true" class="fa-solid fa-lock" />
          <span>
            Installed species cannot be exported because their source package owns the definition.
            You can still import a separate custom species below.
          </span>
        </div>

        <fieldset v-else class="dui-fieldset">
          <legend class="dui-fieldset-legend">Export selected species</legend>
          <p v-if="exportResult.error" class="dui-alert dui-alert-warning" role="status">
            {{ exportResult.error }}
          </p>
          <textarea
            v-else
            aria-label="Species definition export JSON"
            class="dui-textarea"
            :disabled="isDisabled"
            readonly
            rows="10"
            :value="exportResult.text"
          />
          <button
            class="dui-btn"
            :disabled="isDisabled || !exportResult.text"
            type="button"
            @click="copyExport"
          >
            <i aria-hidden="true" class="fa-solid fa-copy" />
            Copy Export
          </button>
        </fieldset>

        <div v-if="!isImportOnly" class="dui-divider">Import</div>
        <fieldset class="dui-fieldset">
          <legend class="dui-fieldset-legend">Choose or paste a species export</legend>
          <input
            accept="application/json,.json"
            aria-label="Choose species definition JSON"
            class="dui-file-input"
            :disabled="isDisabled"
            type="file"
            @change="loadImportFile"
          />
          <textarea
            aria-label="Species definition import JSON"
            class="dui-textarea"
            :disabled="isDisabled"
            placeholder="Paste a Species Builder export here"
            rows="8"
            :value="importText"
            @input="updateImportText"
          />
          <button
            class="dui-btn"
            :disabled="isDisabled || !importText.trim()"
            type="button"
            @click="validateImport"
          >
            Validate Import
          </button>
        </fieldset>

        <p v-if="importError" class="dui-alert dui-alert-error" role="alert">
          <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
          <span>{{ importError }}</span>
        </p>
        <section v-else-if="stagedDefinition" class="dui-alert dui-alert-info">
          <i aria-hidden="true" class="fa-solid fa-eye" />
          <div>
            <strong>{{ stagedDefinition.name }}</strong>
            <p>Key: {{ stagedDefinition.key }}</p>
            <p>{{ stagedDefinition.subspecies?.length ?? 0 }} subspecies</p>
          </div>
        </section>
        <p v-if="hasDuplicateKey" class="dui-alert dui-alert-warning" role="alert">
          A species with key {{ stagedDefinition?.key }} already exists. Change the key in the
          import JSON and validate it again.
        </p>
        <p aria-live="polite">{{ message }}</p>

        <div class="dui-modal-action">
          <button
            class="dui-btn dui-btn-primary"
            :disabled="isDisabled || !stagedDefinition || hasDuplicateKey"
            type="button"
            @click="addImportedDefinition"
          >
            Add Imported Species
          </button>
          <button class="dui-btn dui-btn-ghost" type="button" @click="close">Close</button>
        </div>
      </section>
      <form class="dui-modal-backdrop" method="dialog">
        <button aria-label="Close transfer dialog" type="submit">Close</button>
      </form>
    </dialog>
  </Teleport>
</template>
