import type { SpeciesBuilderSettings } from "../../../types/species-builder/species-builder";
import type {
  SpeciesItemRecord,
  SpeciesItemTableData,
} from "../../../types/species-builder/species-item";
import { speciesItemToDefinition, speciesItemToSubspecies } from "./definitions";

export function buildSpeciesItemCatalog(
  items: SpeciesItemRecord[],
  tables: Map<string, SpeciesItemTableData> = new Map(),
): Pick<SpeciesBuilderSettings, "definitions" | "runtimeSpeciesExtensions"> {
  const roots = new Map(
    items
      .filter((item) => !hasParent(item))
      .map((item) => [item.uuid, speciesItemToDefinition(item, tables.get(item.uuid))]),
  );
  for (const item of items.filter(hasParent)) {
    const reference = item.system.subspeciesOf;
    const parent = items.find((candidate) =>
      reference.uuid ? candidate.uuid === reference.uuid : candidate.id === reference.id,
    );
    if (!parent)
      throw new Error(
        `${item.name}: parent Species Item is missing from the world. Import its parent before loading species.`,
      );
    if (hasParent(parent))
      throw new Error(
        `${item.name}: nested or cyclic subspecies cannot be represented by WFRP's current config.`,
      );
    const definition = roots.get(parent.uuid)!;
    const inheritedTables = { ...tables.get(parent.uuid), ...tables.get(item.uuid) };
    (definition.subspecies ??= []).push(speciesItemToSubspecies(item, parent, inheritedTables));
  }
  return { definitions: [...roots.values()], runtimeSpeciesExtensions: [] };
}

function hasParent(item: SpeciesItemRecord): boolean {
  return !!(item.system.subspeciesOf.uuid || item.system.subspeciesOf.id);
}
