import type {
  WfrpSpeciesConfig,
  WfrpSubspeciesConfigEntry,
} from "../../../types/species-builder/species-builder";

import { buildWfrpSpeciesConfig } from "../../../functions/species-builder/species-config";
import { isRecord } from "../../../shared/object-readers";
import { MODULE_ID } from "../../constants";
import { logInfo, logWarning } from "../../logging";
import { loadSpeciesItemSettings } from "./items/repository";

type WfrpConfigRecord = Record<string, unknown>;

const GENERATED_CONFIG_FIELDS = [
  "species",
  "speciesCharacteristics",
  "speciesSkills",
  "speciesTalents",
  "speciesRandomTalents",
  "speciesTalentReplacement",
  "speciesTraits",
  "speciesMovement",
  "speciesFate",
  "speciesRes",
  "speciesExtra",
  "speciesAge",
  "speciesHeight",
  "speciesCareerReplacements",
] as const;

export function applySpeciesItemConfig(settings = loadSpeciesItemSettings()): void {
  const wfrpConfig = game.wfrp4e?.config;

  if (!isRecord(wfrpConfig)) {
    logWarning(`${MODULE_ID} | WFRP config was unavailable; custom species were not applied.`);
    return;
  }

  const runtimeSpeciesKeys = new Set(
    isRecord(wfrpConfig["species"]) ? Object.keys(wfrpConfig["species"]) : [],
  );
  const duplicateKeys = new Set(
    settings.definitions
      .filter((definition, index, all) =>
        all.some((other, otherIndex) => index !== otherIndex && other.key === definition.key),
      )
      .map(({ key }) => key),
  );
  if (duplicateKeys.size)
    logWarning(`Duplicate Species Item keys were skipped: ${[...duplicateKeys].join(", ")}`);
  const applicableDefinitions = settings.definitions.filter(
    (definition) => !duplicateKeys.has(definition.key),
  );
  const generatedConfig = buildWfrpSpeciesConfig({
    ...settings,
    definitions: applicableDefinitions,
  });
  // Installed base species remain owned by their source; child Items still supply subspecies.
  for (const field of GENERATED_CONFIG_FIELDS) {
    for (const key of runtimeSpeciesKeys) delete generatedConfig[field][key];
  }
  generatedConfig.extraSpecies = generatedConfig.extraSpecies.filter(
    (key) => !runtimeSpeciesKeys.has(key),
  );

  mergeGeneratedConfig(wfrpConfig, generatedConfig);

  if (applicableDefinitions.length > 0) {
    logInfo(`${MODULE_ID} | Applied ${applicableDefinitions.length} custom species definition(s).`);
  }
}

function mergeGeneratedConfig(target: WfrpConfigRecord, generatedConfig: WfrpSpeciesConfig): void {
  for (const field of GENERATED_CONFIG_FIELDS) {
    mergeRecordField(target, field, generatedConfig[field]);
  }

  mergeExtraSpecies(target, generatedConfig.extraSpecies);
  mergeSubspecies(target, generatedConfig.subspecies);
}

function mergeRecordField(
  target: WfrpConfigRecord,
  field: (typeof GENERATED_CONFIG_FIELDS)[number],
  generatedValue: Record<string, unknown>,
): void {
  if (Object.keys(generatedValue).length === 0) {
    return;
  }

  const targetField = target[field];

  if (!isRecord(targetField)) {
    target[field] = { ...generatedValue };
    return;
  }

  Object.assign(targetField, generatedValue);
}

function mergeExtraSpecies(target: WfrpConfigRecord, extraSpecies: string[]): void {
  if (extraSpecies.length === 0) {
    return;
  }

  const targetExtraSpecies = Array.isArray(target["extraSpecies"]) ? target["extraSpecies"] : [];
  const merged = new Set<string>();

  for (const entry of targetExtraSpecies) {
    if (typeof entry === "string") {
      merged.add(entry);
    }
  }

  for (const entry of extraSpecies) {
    merged.add(entry);
  }

  target["extraSpecies"] = [...merged];
}

function mergeSubspecies(
  target: WfrpConfigRecord,
  subspecies: Record<string, Record<string, WfrpSubspeciesConfigEntry>>,
): void {
  if (Object.keys(subspecies).length === 0) {
    return;
  }

  const targetSubspecies = isRecord(target["subspecies"]) ? target["subspecies"] : {};

  for (const [speciesKey, speciesSubspecies] of Object.entries(subspecies)) {
    const targetSpeciesSubspecies = isRecord(targetSubspecies[speciesKey])
      ? targetSubspecies[speciesKey]
      : {};

    Object.assign(targetSpeciesSubspecies, speciesSubspecies);
    targetSubspecies[speciesKey] = targetSpeciesSubspecies;
  }

  target["subspecies"] = targetSubspecies;
}
