import type { Ref } from "vue";

import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
} from "../../types/species-builder/species-builder";

import { canEditSpeciesDefinitionBase } from "../../functions/species-builder/editing-definitions";
import { clonePlain } from "../../functions/species-builder/editor/draft";

interface SelectedDefinitionContext {
  definitions: Ref<SpeciesBuilderEditingDefinition[]>;
  message: Ref<string>;
  selectedIndex: Ref<number>;
}

export interface SelectedDefinitionUpdateOptions {
  allowRuntimeBase?: boolean;
}

export function updateSelectedDefinitionAtIndex(
  context: SelectedDefinitionContext,
  update: (definition: SpeciesBuilderDefinition) => SpeciesBuilderDefinition,
  options: SelectedDefinitionUpdateOptions = {},
): void {
  const definition = context.definitions.value[context.selectedIndex.value];

  if (!definition || (!options.allowRuntimeBase && !canEditSpeciesDefinitionBase(definition))) {
    return;
  }

  context.definitions.value = context.definitions.value.map((entry, index) => {
    if (index !== context.selectedIndex.value) {
      return entry;
    }

    const updated = update(clonePlain(definition));

    return {
      ...updated,
      origin: definition.origin,
      runtimeSubspeciesCount: definition.runtimeSubspeciesCount,
      ...(definition.runtimeUnavailable ? { runtimeUnavailable: true } : {}),
    };
  });
  context.message.value = "";
}
