import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";

import { formatLinkedItemName } from "../item-reference-names";
import { configuredRandomTalentKeys, validateTalentRows } from "./grant-talents";
import {
  createIssue,
  isKnownItem,
  type ValidationCatalogIndex,
  type ValidationIssueLocation,
} from "./shared";

export function validateDefinitionGrants(
  definitions: SpeciesBuilderDefinition[],
  catalog: ValidationCatalogIndex,
): SpeciesBuilderValidationIssue[] {
  const issues: SpeciesBuilderValidationIssue[] = [];

  definitions.forEach((definition, definitionIndex) => {
    validateNamedRows(
      linkedOrRawNames(definition.linkedSkills, definition.skills),
      "skills",
      "Skill",
      catalog.skills,
      definitionLocation(definitionIndex, "skills"),
      issues,
    );
    validateTalentRows(
      talentChoices(definition),
      "talents",
      definitionLocation(definitionIndex, "talents"),
      configuredRandomTalentKeys(definition.randomTalents),
      catalog,
      issues,
    );
    validateNamedRows(
      linkedOrRawNames(definition.linkedTraits, definition.traits),
      "traits",
      "Trait",
      catalog.traits,
      definitionLocation(definitionIndex, "traits"),
      issues,
    );

    (definition.subspecies ?? []).forEach((subspecies, subspeciesIndex) =>
      validateSubspeciesGrants(
        definition,
        subspecies,
        definitionIndex,
        subspeciesIndex,
        catalog,
        issues,
      ),
    );
  });

  return issues;
}

function validateSubspeciesGrants(
  definition: SpeciesBuilderDefinition,
  subspecies: SpeciesBuilderSubspeciesDefinition,
  definitionIndex: number,
  subspeciesIndex: number,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  validateNamedRows(
    subspecies.skillsAdded ?? [],
    "skillsAdded",
    "Skill",
    catalog.skills,
    subspeciesLocation(definitionIndex, subspeciesIndex, "skills"),
    issues,
  );
  validateTalentRows(
    (subspecies.talentsAdded ?? []).map(splitTalentChoices),
    "talentsAdded",
    subspeciesLocation(definitionIndex, subspeciesIndex, "talents"),
    configuredRandomTalentKeys(subspecies.randomTalents ?? definition.randomTalents),
    catalog,
    issues,
  );
  validateNamedRows(
    subspecies.traitsAdded ?? [],
    "traitsAdded",
    "Trait",
    catalog.traits,
    subspeciesLocation(definitionIndex, subspeciesIndex, "traits"),
    issues,
  );
}

function validateNamedRows(
  values: string[],
  field: string,
  label: string,
  knownNames: Set<string>,
  location: ValidationIssueLocation,
  issues: SpeciesBuilderValidationIssue[],
): void {
  values.forEach((value, rowIndex) => {
    const name = value.trim();
    const rowLocation = { ...location, field, rowIndex };

    if (!name) {
      issues.push(
        createIssue(rowLocation, "grant-blank", `${label} row ${rowIndex + 1} is blank.`),
      );
    } else if (!isKnownItem(name, knownNames)) {
      issues.push(
        createIssue(
          rowLocation,
          "grant-unresolved",
          `${label} “${name}” does not match an available WFRP ${label} Item.`,
        ),
      );
    }
  });
}

function linkedOrRawNames(
  linked: SpeciesBuilderLinkedItemName[] | undefined,
  raw: string[] | undefined,
): string[] {
  return linked?.length ? linked.map(formatLinkedItemName) : (raw ?? []);
}

function talentChoices(definition: SpeciesBuilderDefinition): string[][] {
  if (definition.linkedTalents?.length) {
    return definition.linkedTalents.map((grant) => grant.choices.map(formatLinkedItemName));
  }

  return (definition.talents ?? []).map(splitTalentChoices);
}

function splitTalentChoices(value: string): string[] {
  return value.split(",").map((choice) => choice.trim());
}

function definitionLocation(
  definitionIndex: number,
  section: "skills" | "talents" | "traits",
): ValidationIssueLocation {
  return { definitionIndex, scope: "definition", section };
}

function subspeciesLocation(
  definitionIndex: number,
  subspeciesIndex: number,
  section: "skills" | "talents" | "traits",
): ValidationIssueLocation {
  return { definitionIndex, scope: "subspecies", section, subspeciesIndex };
}
