<script setup lang="ts">
import { computed } from "vue";

import type {
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderTalentGrant,
} from "../../../../../../../../types/species-builder/species-builder";
import type { SpeciesBuilderArrayField } from "../../../../../../../../functions/species-builder/editor/field-values";

import DocumentDrop from "../../../../../../../components/DocumentDrop.vue";
import { useSpeciesBuilderStore } from "../../../../../../../../state/species-builder";
import { arrayFields } from "../support/field-definitions";
import {
  linkedListFieldForArrayField,
  linkedRowsForValues,
  type SpeciesBuilderLinkedListField,
  talentGrantsForValues,
} from "../../../../../../../../functions/species-builder/editor/linked-grants";
import { arrayFieldHelp } from "./array-field-help";
import type { ArrayFieldValues } from "./array-field-contracts";
import {
  issuesForField,
  issuesForFieldRow,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../validation-presentation";
import EditableLinkedItemRow from "./EditableLinkedItemRow.vue";

const props = defineProps<{
  fields?: SpeciesBuilderArrayField[];
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  values: ArrayFieldValues;
}>();

const store = useSpeciesBuilderStore();

const visibleArrayFields = computed(() =>
  arrayFields.filter((entry) => !props.fields || props.fields.includes(entry.field)),
);

function linkedRows(field: SpeciesBuilderLinkedListField): SpeciesBuilderLinkedItemName[] {
  return linkedRowsForValues(props.values[field], linkedValues(field));
}

function linkedValues(
  field: SpeciesBuilderLinkedListField,
): SpeciesBuilderLinkedItemName[] | undefined {
  return field === "skills" ? props.values.linkedSkills : props.values.linkedTraits;
}

function talentGrants(): SpeciesBuilderTalentGrant[] {
  return talentGrantsForValues(props.values.talents, props.values.linkedTalents);
}

function visibleEntryCount(field: SpeciesBuilderArrayField): number {
  if (field === "talents") {
    return talentGrants().length;
  }

  return linkedRows(field).length;
}

function fieldIssues(field: SpeciesBuilderArrayField): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, field);
}

function fieldMessages(field: SpeciesBuilderArrayField): string[] {
  return uniqueIssueMessages(fieldIssues(field));
}

function rowIssues(
  field: SpeciesBuilderArrayField,
  rowIndex: number,
): SpeciesBuilderValidationIssue[] {
  return issuesForFieldRow(props.issues, field, rowIndex);
}

function talentChoiceIssues(
  rowIndex: number,
  choiceIndex: number,
): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, "talents", rowIndex, choiceIndex);
}
</script>

<template>
  <div class="app:grid app:gap-3">
    <section
      v-for="entry in visibleArrayFields"
      :key="entry.field"
      class="dui-card dui-card-border dui-card-sm"
    >
      <div class="dui-card-body">
        <header class="app:flex app:items-start app:justify-between app:gap-4">
          <div>
            <h3 class="dui-card-title">{{ entry.label }}</h3>
            <p class="app:m-0">{{ arrayFieldHelp[entry.field] }}</p>
          </div>
          <div class="dui-card-actions app:items-center">
            <span class="dui-badge">{{ visibleEntryCount(entry.field) }}</span>
            <button
              v-if="entry.field !== 'talents'"
              class="dui-btn dui-btn-sm"
              :disabled="isDisabled"
              :title="`Add a ${entry.label.slice(0, -1)} row`"
              type="button"
              @click="store.addLinkedItem(linkedListFieldForArrayField(entry.field))"
            >
              <i aria-hidden="true" class="fa-solid fa-plus" />
              Add
            </button>
            <div v-else class="dui-join">
              <button
                class="dui-btn dui-btn-sm dui-join-item"
                :disabled="isDisabled"
                title="Add one guaranteed Talent"
                type="button"
                @click="store.addTalentGrant('single')"
              >
                <i aria-hidden="true" class="fa-solid fa-plus" />
                Talent
              </button>
              <button
                class="dui-btn dui-btn-sm dui-join-item"
                :disabled="isDisabled"
                title="Add a Talent choice set. WFRP stores this as one comma-separated Talent entry."
                type="button"
                @click="store.addTalentGrant('choice')"
              >
                <i aria-hidden="true" class="fa-solid fa-list-check" />
                Choice Set
              </button>
            </div>
          </div>
        </header>

        <DocumentDrop
          :description="`Drop a WFRP ${entry.label.slice(0, -1)} item to add it to this list.`"
          :disabled="isDisabled"
          :title="`Drop ${entry.label}`"
          variant="compact"
          @drop-data="(data) => store.appendArrayFieldDrop(entry.field, data)"
        />

        <div
          v-if="fieldMessages(entry.field).length"
          class="dui-alert"
          :class="validationClass(fieldIssues(entry.field), 'dui-alert-error', 'dui-alert-warning')"
          role="alert"
        >
          <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
          <div>
            <p
              v-for="message in fieldMessages(entry.field)"
              :key="message"
              class="app:m-0 app:text-xs"
            >
              {{ message }}
            </p>
          </div>
        </div>

        <ul v-if="entry.field !== 'talents' && linkedRows(entry.field).length > 0" class="dui-list">
          <EditableLinkedItemRow
            v-for="(item, index) in linkedRows(entry.field)"
            :key="`${entry.field}-${index}`"
            :drop-description="`Drop a WFRP ${entry.label.slice(0, -1)} item to link or replace this row.`"
            :drop-title="`Link ${entry.label.slice(0, -1)}`"
            :input-title="`${entry.label.slice(0, -1)} name used by WFRP item lookup`"
            :is-disabled="isDisabled"
            :issues="rowIssues(entry.field, index)"
            :remove-title="`Remove ${item.name}`"
            :value="item"
            @drop-data="
              (data) =>
                store.setLinkedItemDrop(linkedListFieldForArrayField(entry.field), index, data)
            "
            @open-item="(uuid) => store.openItemSheet(uuid)"
            @remove="store.removeLinkedItem(linkedListFieldForArrayField(entry.field), index)"
            @update-name="
              (value) =>
                store.renameLinkedItem(linkedListFieldForArrayField(entry.field), index, value)
            "
          />
        </ul>

        <ul v-else-if="entry.field === 'talents' && talentGrants().length > 0" class="dui-list">
          <li
            v-for="(grant, grantIndex) in talentGrants()"
            :key="`talent-${grantIndex}`"
            class="dui-list-row"
            :class="
              validationClass(
                rowIssues('talents', grantIndex),
                'app:border app:border-error',
                'app:border app:border-warning',
              )
            "
          >
            <span class="dui-badge dui-badge-ghost">Grant {{ grantIndex + 1 }}</span>
            <div class="dui-list-col-grow">
              <strong>
                {{ grant.choices.length > 1 ? "Talent Choice" : "Guaranteed Talent" }}
              </strong>
              <p v-if="grant.choices.length > 1">Choose one of these alternatives.</p>

              <ul class="dui-list">
                <EditableLinkedItemRow
                  v-for="(choice, choiceIndex) in grant.choices"
                  :key="`${grantIndex}-${choiceIndex}`"
                  drop-description="Drop a WFRP Talent item to link or replace this option."
                  drop-title="Link Talent"
                  :input-title="
                    grant.choices.length > 1
                      ? 'One Talent option offered for this choice set'
                      : 'Guaranteed Talent name'
                  "
                  :is-disabled="isDisabled"
                  :issues="talentChoiceIssues(grantIndex, choiceIndex)"
                  :remove-title="`Remove ${choice.name}`"
                  :value="choice"
                  @drop-data="(data) => store.setTalentChoiceDrop(grantIndex, choiceIndex, data)"
                  @open-item="(uuid) => store.openItemSheet(uuid)"
                  @remove="store.removeTalentChoice(grantIndex, choiceIndex)"
                  @update-name="(value) => store.renameTalentChoice(grantIndex, choiceIndex, value)"
                />
              </ul>
            </div>
            <div class="dui-join">
              <button
                class="dui-btn dui-btn-sm dui-join-item"
                :disabled="isDisabled"
                title="Add another alternative to this Talent choice"
                type="button"
                @click="store.addTalentChoice(grantIndex)"
              >
                <i aria-hidden="true" class="fa-solid fa-plus" />
                Choice
              </button>
              <button
                :disabled="isDisabled"
                title="Remove this Talent grant"
                class="dui-btn dui-btn-error dui-btn-sm dui-join-item"
                type="button"
                @click="store.removeTalentGrant(grantIndex)"
              >
                <i aria-hidden="true" class="fa-solid fa-trash" />
                Remove
              </button>
            </div>
          </li>
        </ul>

        <div v-else class="dui-alert" role="status">
          <i aria-hidden="true" class="fa-solid fa-circle-info" />
          <span>No {{ entry.label.toLowerCase() }} yet.</span>
        </div>
      </div>
    </section>
  </div>
</template>
