<script setup lang="ts">
import { computed } from "vue";

import type {
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderRandomTalentSource,
} from "../../../../../../../types/species-builder/species-builder";
import type { SpeciesBuilderDetailPanelEmits } from "./detail-panel-events";
import type { SpeciesBuilderEditorTab } from "./editor-tabs";
import type { RandomTableTab } from "./tabs/tables/random-table-events";
import type { SpeciesBuilderValidationIssue } from "../../../../../../../types/species-builder/validation";
import type { SpeciesBuilderValidationNavigationRequest } from "../../../../components/validation/species-builder-validation-summary";

import SpeciesBuilderDetailPanel from "./SpeciesBuilderDetailPanel.vue";
import { getSpeciesBuilderPageMeta } from "../../../../components/species-builder-navigation";

const props = defineProps<{
  activeEditorTab: SpeciesBuilderEditorTab;
  activeTableTab: RandomTableTab;
  definition: SpeciesBuilderEditingDefinition | undefined;
  isLoading: boolean;
  isSaving: boolean;
  issues: SpeciesBuilderValidationIssue[];
  randomTalentSources: SpeciesBuilderRandomTalentSource[];
  validationNavigationRequest?: SpeciesBuilderValidationNavigationRequest;
}>();

const emit = defineEmits<SpeciesBuilderDetailPanelEmits>();
const pageMeta = computed(() =>
  getSpeciesBuilderPageMeta("species", true, props.activeEditorTab, props.activeTableTab),
);
const showInstalledSpeciesNotice = computed(
  () =>
    props.activeEditorTab !== "subspecies" &&
    props.definition?.origin === "runtime" &&
    !props.definition.runtimeUnavailable,
);
const showUnavailableSpeciesNotice = computed(
  () => props.activeEditorTab !== "subspecies" && props.definition?.runtimeUnavailable,
);
</script>

<template>
  <section>
    <header class="app:mb-3 app:flex app:flex-col app:gap-2">
      <div class="app:flex app:flex-wrap app:items-center app:gap-2">
        <h2 class="dui-card-title">{{ pageMeta.label }}</h2>
        <span
          v-if="definition?.origin === 'runtime'"
          class="dui-badge dui-badge-sm"
          :class="definition.runtimeUnavailable ? 'dui-badge-warning' : 'dui-badge-ghost'"
        >
          <i
            aria-hidden="true"
            :class="
              definition.runtimeUnavailable
                ? 'fa-solid fa-triangle-exclamation'
                : 'fa-solid fa-lock'
            "
          />
          {{ definition.runtimeUnavailable ? "Unavailable source" : "Installed species" }}
        </span>
      </div>
      <p class="app:m-0">{{ pageMeta.description }}</p>
      <div v-if="showInstalledSpeciesNotice" class="dui-alert dui-alert-info" role="note">
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>
          This species comes from WFRP or an active module, so its setup is read-only. You can
          inspect every section and add editable custom variants from Subspecies.
        </span>
      </div>
      <div
        v-else-if="showUnavailableSpeciesNotice"
        class="dui-alert dui-alert-warning"
        role="alert"
      >
        <i aria-hidden="true" class="fa-solid fa-triangle-exclamation" />
        <span>
          This species source is no longer active. Its saved custom variants are preserved until the
          source returns.
        </span>
      </div>
    </header>

    <SpeciesBuilderDetailPanel
      v-if="definition"
      :active-editor-tab="activeEditorTab"
      :active-table-tab="activeTableTab"
      :definition="definition"
      :is-loading="isLoading"
      :is-saving="isSaving"
      :issues="issues"
      :random-talent-sources="randomTalentSources"
      :validation-navigation-request="validationNavigationRequest"
      @add-subspecies="emit('addSubspecies')"
      @career-replacement-choice-drop="
        (rowIndex, replacementIndex, data) =>
          emit('careerReplacementChoiceDrop', rowIndex, replacementIndex, data)
      "
      @career-replacement-rolled-drop="
        (rowIndex, data) => emit('careerReplacementRolledDrop', rowIndex, data)
      "
      @career-table-career-drop="(rowIndex, data) => emit('careerTableCareerDrop', rowIndex, data)"
      @career-table-journal-drop="
        (rowIndex, data) => emit('careerTableJournalDrop', rowIndex, data)
      "
      @delete-subspecies="(index) => emit('deleteSubspecies', index)"
      @open-item="(uuid) => emit('openItem', uuid)"
      @review-issues="emit('reviewIssues')"
      @save="emit('save')"
      @subspecies-talent-drop="(index, data) => emit('subspeciesTalentDrop', index, data)"
      @subspecies-career-table-career-drop="
        (index, rowIndex, data) => emit('subspeciesCareerTableCareerDrop', index, rowIndex, data)
      "
      @subspecies-career-table-journal-drop="
        (index, rowIndex, data) => emit('subspeciesCareerTableJournalDrop', index, rowIndex, data)
      "
      @subspecies-talent-replacement-replacement-drop="
        (index, rowIndex, data) =>
          emit('subspeciesTalentReplacementReplacementDrop', index, rowIndex, data)
      "
      @subspecies-talent-replacement-rolled-drop="
        (index, rowIndex, data) =>
          emit('subspeciesTalentReplacementRolledDrop', index, rowIndex, data)
      "
      @talent-replacement-replacement-drop="
        (rowIndex, data) => emit('talentReplacementReplacementDrop', rowIndex, data)
      "
      @talent-replacement-rolled-drop="
        (rowIndex, data) => emit('talentReplacementRolledDrop', rowIndex, data)
      "
      @update-boolean-field="(field, value) => emit('updateBooleanField', field, value)"
      @update-career-replacement-rows="(rows) => emit('updateCareerReplacementRows', rows)"
      @update-career-table-rows="(rows) => emit('updateCareerTableRows', rows)"
      @update-characteristic="(key, value) => emit('updateCharacteristic', key, value)"
      @update-height-field="(field, value) => emit('updateHeightField', field, value)"
      @update-number-field="(field, value) => emit('updateNumberField', field, value)"
      @update-string-field="(field, value) => emit('updateStringField', field, value)"
      @update-wound-formula="(value) => emit('updateWoundFormula', value)"
      @update-subspecies-array-field="
        (index, field, value) => emit('updateSubspeciesArrayField', index, field, value)
      "
      @update-subspecies-characteristic="
        (index, key, value) => emit('updateSubspeciesCharacteristic', index, key, value)
      "
      @update-subspecies-number-field="
        (index, field, value) => emit('updateSubspeciesNumberField', index, field, value)
      "
      @update-subspecies-string-field="
        (index, field, value) => emit('updateSubspeciesStringField', index, field, value)
      "
      @update-subspecies-career-table-rows="
        (index, rows) => emit('updateSubspeciesCareerTableRows', index, rows)
      "
      @update-subspecies-wound-formula="
        (index, value) => emit('updateSubspeciesWoundFormula', index, value)
      "
      @update-subspecies-talent-replacement-rows="
        (index, rows) => emit('updateSubspeciesTalentReplacementRows', index, rows)
      "
      @update-subspecies-text-map-field="
        (index, field, value) => emit('updateSubspeciesTextMapField', index, field, value)
      "
      @update-talent-replacement-rows="(rows) => emit('updateTalentReplacementRows', rows)"
      @update-text-map-field="(field, value) => emit('updateTextMapField', field, value)"
    />

    <section v-else role="status" class="dui-alert dui-alert-warning">No species selected.</section>
  </section>
</template>
