import type {
  SpeciesBuilderCareerTableDefinition,
  SpeciesBuilderDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../../types/species-builder/species-builder";

import { assignIfPresent } from "../../../../shared/assign-if-present";
import { isRecord } from "../../../../shared/object-readers";
import { type RuntimeSpeciesConfigSnapshot, runtimeConfigEntry } from "./config-snapshot";
import {
  assignChangedRuntimeNumber,
  changedRuntimeCharacteristics,
  mergeRuntimeRandomTalents,
  readRuntimeCharacteristics,
  readRuntimeHeight,
  readRuntimeNumber,
  readRuntimeNumberRecord,
  readRuntimeString,
  readRuntimeStringArray,
  readRuntimeStringArrayRecord,
  readRuntimeStringRecord,
  readRuntimeTalentValues,
  runtimeListDelta,
  runtimeRecordsEqual,
} from "./values";

export interface RuntimeSpeciesDefinitionContext {
  resolveCareerTable: (
    speciesKey: string,
    subspeciesKey: string | undefined,
    configuredColumn: unknown,
  ) => SpeciesBuilderCareerTableDefinition | undefined;
}

export function adaptRuntimeSpeciesDefinitions(
  snapshot: RuntimeSpeciesConfigSnapshot,
  context: RuntimeSpeciesDefinitionContext,
): SpeciesBuilderDefinition[] {
  const extraSpecies = new Set(snapshot.extraSpecies);

  return Object.entries(snapshot.records.species)
    .flatMap(([key, configuredName]) => {
      const speciesKey = key.trim();

      return speciesKey
        ? [
            adaptRuntimeSpeciesDefinition(
              snapshot,
              speciesKey,
              configuredName,
              extraSpecies,
              context,
            ),
          ]
        : [];
    })
    .sort(compareNamedDefinitions);
}

function adaptRuntimeSpeciesDefinition(
  snapshot: RuntimeSpeciesConfigSnapshot,
  key: string,
  configuredName: unknown,
  extraSpecies: ReadonlySet<string>,
  context: RuntimeSpeciesDefinitionContext,
): SpeciesBuilderDefinition {
  const definition: SpeciesBuilderDefinition = {
    includeInExtraSpecies: extraSpecies.has(key),
    key,
    name: readRuntimeString(configuredName) ?? key,
  };
  const talentValues = readRuntimeTalentValues(runtimeConfigEntry(snapshot, "speciesTalents", key));

  assignIfPresent(
    definition,
    "characteristics",
    readRuntimeCharacteristics(runtimeConfigEntry(snapshot, "speciesCharacteristics", key)),
  );
  assignIfPresent(
    definition,
    "skills",
    readRuntimeStringArray(runtimeConfigEntry(snapshot, "speciesSkills", key)),
  );
  assignIfPresent(definition, "talents", talentValues?.talents);
  assignIfPresent(
    definition,
    "randomTalents",
    mergeRuntimeRandomTalents(
      readRuntimeNumberRecord(runtimeConfigEntry(snapshot, "speciesRandomTalents", key)),
      talentValues?.randomTalentCount,
    ),
  );
  assignIfPresent(
    definition,
    "talentReplacements",
    readRuntimeStringRecord(runtimeConfigEntry(snapshot, "speciesTalentReplacement", key)),
  );
  assignIfPresent(
    definition,
    "traits",
    readRuntimeStringArray(runtimeConfigEntry(snapshot, "speciesTraits", key)),
  );
  assignBaseScalarFields(definition, snapshot, key);
  assignIfPresent(definition, "careerTable", context.resolveCareerTable(key, undefined, undefined));

  const subspecies = adaptRuntimeSubspecies(snapshot, definition, context);

  assignIfPresent(definition, "subspecies", subspecies.length > 0 ? subspecies : undefined);

  return definition;
}

function assignBaseScalarFields(
  definition: SpeciesBuilderDefinition,
  snapshot: RuntimeSpeciesConfigSnapshot,
  key: string,
): void {
  assignIfPresent(
    definition,
    "movement",
    readRuntimeNumber(runtimeConfigEntry(snapshot, "speciesMovement", key)),
  );
  assignIfPresent(
    definition,
    "fate",
    readRuntimeNumber(runtimeConfigEntry(snapshot, "speciesFate", key)),
  );
  assignIfPresent(
    definition,
    "resilience",
    readRuntimeNumber(runtimeConfigEntry(snapshot, "speciesRes", key)),
  );
  assignIfPresent(
    definition,
    "extra",
    readRuntimeNumber(runtimeConfigEntry(snapshot, "speciesExtra", key)),
  );
  assignIfPresent(
    definition,
    "age",
    readRuntimeString(runtimeConfigEntry(snapshot, "speciesAge", key)),
  );
  assignIfPresent(
    definition,
    "height",
    readRuntimeHeight(runtimeConfigEntry(snapshot, "speciesHeight", key)),
  );
  assignIfPresent(
    definition,
    "careerReplacements",
    readRuntimeStringArrayRecord(runtimeConfigEntry(snapshot, "speciesCareerReplacements", key)),
  );
}

function adaptRuntimeSubspecies(
  snapshot: RuntimeSpeciesConfigSnapshot,
  parent: SpeciesBuilderDefinition,
  context: RuntimeSpeciesDefinitionContext,
): SpeciesBuilderSubspeciesDefinition[] {
  const configured = runtimeConfigEntry(snapshot, "subspecies", parent.key);

  if (!isRecord(configured)) {
    return [];
  }

  return Object.entries(configured)
    .flatMap(([key, source]) =>
      key.trim() && isRecord(source)
        ? [adaptRuntimeSubspeciesDefinition(snapshot, parent, key.trim(), source, context)]
        : [],
    )
    .sort(compareNamedDefinitions);
}

function adaptRuntimeSubspeciesDefinition(
  snapshot: RuntimeSpeciesConfigSnapshot,
  parent: SpeciesBuilderDefinition,
  key: string,
  source: Record<string, unknown>,
  context: RuntimeSpeciesDefinitionContext,
): SpeciesBuilderSubspeciesDefinition {
  const definition: SpeciesBuilderSubspeciesDefinition = {
    key,
    name: readRuntimeString(source["name"]) ?? key,
  };
  const characteristics = readRuntimeCharacteristics(source["characteristics"]);

  if (characteristics) {
    assignIfPresent(
      definition,
      "characteristics",
      changedRuntimeCharacteristics(parent.characteristics, characteristics),
    );
  }

  assignSubspeciesListDeltas(definition, parent, source);
  assignSubspeciesRandomTalents(definition, parent, source);
  assignSubspeciesScalarDeltas(definition, parent, source);
  assignIfPresent(
    definition,
    "careerReplacements",
    readRuntimeStringArrayRecord(
      runtimeConfigEntry(snapshot, "speciesCareerReplacements", `${parent.key}-${key}`),
    ),
  );

  const talentReplacements = readRuntimeStringRecord(source["talentReplacement"]);

  if (!runtimeRecordsEqual(parent.talentReplacements, talentReplacements)) {
    assignIfPresent(definition, "talentReplacements", talentReplacements);
  }

  assignIfPresent(
    definition,
    "careerTable",
    context.resolveCareerTable(parent.key, key, source["careerTable"]),
  );

  return definition;
}

function assignSubspeciesListDeltas(
  definition: SpeciesBuilderSubspeciesDefinition,
  parent: SpeciesBuilderDefinition,
  source: Record<string, unknown>,
): void {
  assignListDelta(
    definition,
    "skills",
    parent.skills ?? [],
    readRuntimeStringArray(source["skills"]),
  );

  const talentValues = readRuntimeTalentValues(source["talents"]);

  assignListDelta(definition, "talents", parent.talents ?? [], talentValues?.talents);
  assignListDelta(
    definition,
    "traits",
    parent.traits ?? [],
    readRuntimeStringArray(source["speciesTraits"]),
  );
}

function assignListDelta(
  definition: SpeciesBuilderSubspeciesDefinition,
  field: "skills" | "talents" | "traits",
  parent: string[],
  child: string[] | undefined,
): void {
  if (!child) {
    return;
  }

  const delta = runtimeListDelta(parent, child);

  assignIfPresent(definition, `${field}Added`, delta.added);
  assignIfPresent(definition, `${field}Removed`, delta.removed);
}

function assignSubspeciesRandomTalents(
  definition: SpeciesBuilderSubspeciesDefinition,
  parent: SpeciesBuilderDefinition,
  source: Record<string, unknown>,
): void {
  const talentValues = readRuntimeTalentValues(source["talents"]);
  const configured = readRuntimeNumberRecord(source["randomTalents"]);
  const randomTalents = mergeRuntimeRandomTalents(
    configured,
    talentValues?.randomTalentCount,
    parent.randomTalents,
  );

  if (!runtimeRecordsEqual(parent.randomTalents, randomTalents)) {
    assignIfPresent(definition, "randomTalents", randomTalents);
  }
}

function assignSubspeciesScalarDeltas(
  definition: SpeciesBuilderSubspeciesDefinition,
  parent: SpeciesBuilderDefinition,
  source: Record<string, unknown>,
): void {
  assignChangedRuntimeNumber(definition, "movement", parent.movement, source["movement"]);
  assignChangedRuntimeNumber(definition, "fate", parent.fate, source["fate"]);
  assignChangedRuntimeNumber(definition, "resilience", parent.resilience, source["resilience"]);
  assignChangedRuntimeNumber(definition, "extra", parent.extra, source["extra"]);
}

function compareNamedDefinitions(
  left: Pick<SpeciesBuilderDefinition, "name">,
  right: Pick<SpeciesBuilderDefinition, "name">,
): number {
  return left.name.localeCompare(right.name);
}
