import { findWorldItemByNameAndType } from "../foundry/item-sources";

export async function findWfrpItemByNameAndType(
  name: string,
  types: string[],
): Promise<FoundryItemDocument | null> {
  // WFRP4e's utility lookup can resolve configured compendium/world data more
  // reliably than a plain world Item search, so it gets the first attempt.
  const utilityResult = await game.wfrp4e?.utility?.findItem?.(name, types);

  if (utilityResult) {
    return utilityResult;
  }

  return findWorldItemByNameAndType(name, types);
}
