import type { NpcTraitDraftEntry } from "../../../../../types/npc-builder";

import { assertFoundryItemType } from "../../../../foundry/document-guards";
import { parseDropData } from "../../../../foundry/drop-data";
import { readTraitConfig } from "./config";

export async function resolveTraitDrop(data: string): Promise<NpcTraitDraftEntry> {
  const dropData = parseDropData(data);

  if (dropData.type !== "Item" || !dropData.uuid) {
    throw new Error("Drop a Foundry Trait item here.");
  }

  const item = assertFoundryItemType(
    await fromUuid(dropData.uuid),
    "trait",
    "Drop a Foundry Trait item here.",
  );

  return {
    config: readTraitConfig(item),
    ignored: false,
    key: `custom:${item.uuid}`,
    name: item.name,
    source: "custom",
    sourceUuid: item.uuid,
  };
}
