import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSettings,
  SpeciesBuilderSubspeciesDefinition,
} from "../../types/species-builder/species-builder";

export interface SpeciesBuilderDefinitionPlan {
  definition: SpeciesBuilderDefinition;
  emitBaseDefinition: boolean;
  subspecies: SpeciesBuilderSubspeciesDefinition[];
}

export function buildSpeciesDefinitionPlans(
  settings: SpeciesBuilderSettings,
  runtimeParents: SpeciesBuilderDefinition[] = [],
): SpeciesBuilderDefinitionPlan[] {
  const runtimeParentsByKey = new Map(
    runtimeParents.map((definition) => [definition.key.trim(), definition]),
  );
  const customPlans = settings.definitions.flatMap((definition) => {
    if (runtimeParentsByKey.has(definition.key.trim())) {
      return [];
    }

    return [
      {
        definition,
        emitBaseDefinition: true,
        subspecies: definition.subspecies ?? [],
      },
    ];
  });
  const runtimeExtensionPlans = (settings.runtimeSpeciesExtensions ?? []).flatMap((extension) => {
    const parent = runtimeParentsByKey.get(extension.speciesKey.trim());

    if (!parent) {
      return [];
    }

    const externalSubspeciesKeys = new Set(
      (parent.subspecies ?? []).map((subspecies) => subspecies.key.trim()),
    );
    const authoredSubspecies = extension.subspecies.filter(
      (subspecies) => !externalSubspeciesKeys.has(subspecies.key.trim()),
    );

    return authoredSubspecies.length > 0
      ? [
          {
            definition: parent,
            emitBaseDefinition: false,
            subspecies: authoredSubspecies,
          },
        ]
      : [];
  });

  return [...customPlans, ...runtimeExtensionPlans];
}
