export interface SubspeciesTalentRow {
  name: string;
  source: "added" | "inherited";
}

export interface SubspeciesTalentInheritance {
  activeRows: SubspeciesTalentRow[];
  addedTalents: string[];
  removedParentTalents: string[];
  removedTalents: string[];
}

export interface SubspeciesTalentDeltaUpdate {
  field: "talentsAdded" | "talentsRemoved";
  value: string;
}

export function buildSubspeciesTalentInheritance(
  parentValues: string[],
  addedValues: string[] | undefined,
  removedValues: string[] | undefined,
): SubspeciesTalentInheritance {
  const parentTalents = uniqueTalentNames(parentValues);
  const addedTalents = uniqueTalentNames(addedValues);
  const removedTalents = uniqueTalentNames(removedValues);
  const inheritedRows: SubspeciesTalentRow[] = parentTalents
    .filter((talent) => !removedTalents.includes(talent))
    .map((name) => ({ name, source: "inherited" }));
  const addedRows: SubspeciesTalentRow[] = addedTalents
    .filter((talent) => !inheritedRows.some((row) => row.name === talent))
    .map((name) => ({ name, source: "added" }));

  return {
    activeRows: [...inheritedRows, ...addedRows],
    addedTalents,
    removedParentTalents: parentTalents.filter((talent) => removedTalents.includes(talent)),
    removedTalents,
  };
}

export function removeSubspeciesTalent(
  row: SubspeciesTalentRow,
  inheritance: SubspeciesTalentInheritance,
): SubspeciesTalentDeltaUpdate {
  return row.source === "added"
    ? {
        field: "talentsAdded",
        value: formatTalentDelta(inheritance.addedTalents.filter((talent) => talent !== row.name)),
      }
    : {
        field: "talentsRemoved",
        value: formatTalentDelta([...inheritance.removedTalents, row.name]),
      };
}

export function restoreSubspeciesTalent(
  name: string,
  inheritance: SubspeciesTalentInheritance,
): SubspeciesTalentDeltaUpdate {
  return {
    field: "talentsRemoved",
    value: formatTalentDelta(inheritance.removedTalents.filter((talent) => talent !== name)),
  };
}

export function uniqueTalentNames(values: string[] | undefined): string[] {
  const names: string[] = [];

  for (const value of values ?? []) {
    const name = value.trim();

    if (name && !names.includes(name)) {
      names.push(name);
    }
  }

  return names;
}

function formatTalentDelta(values: string[]): string {
  return uniqueTalentNames(values).join("\n");
}
