import type { useSpeciesBuilderEditor } from "../../../../../../../state/species-builder/editor";

type SpeciesBuilderEditor = ReturnType<typeof useSpeciesBuilderEditor>;

interface SpeciesBuilderEditorPageEventOptions {
  requestDeleteSubspecies: (index: number) => void;
  requestSave: () => void;
}

export function createSpeciesBuilderEditorPageEvents(
  editor: SpeciesBuilderEditor,
  options: SpeciesBuilderEditorPageEventOptions,
) {
  return {
    addSubspecies: editor.addSubspecies,
    careerReplacementChoiceDrop: editor.setCareerReplacementChoiceDrop,
    careerReplacementRolledDrop: editor.setCareerReplacementRolledDrop,
    careerTableCareerDrop: editor.setCareerTableCareerDrop,
    careerTableJournalDrop: editor.setCareerTableJournalDrop,
    deleteSubspecies: options.requestDeleteSubspecies,
    openItem: editor.openItemSheet,
    save: options.requestSave,
    subspeciesTalentDrop: editor.appendSubspeciesTalentDrop,
    subspeciesCareerTableCareerDrop: editor.setSubspeciesCareerTableCareerDrop,
    subspeciesCareerTableJournalDrop: editor.setSubspeciesCareerTableJournalDrop,
    subspeciesTalentReplacementReplacementDrop: (
      subspeciesIndex: number,
      rowIndex: number,
      data: string,
    ) => editor.setSubspeciesTalentReplacementDrop(subspeciesIndex, rowIndex, "replacement", data),
    subspeciesTalentReplacementRolledDrop: (
      subspeciesIndex: number,
      rowIndex: number,
      data: string,
    ) => editor.setSubspeciesTalentReplacementDrop(subspeciesIndex, rowIndex, "rolled", data),
    talentReplacementReplacementDrop: (rowIndex: number, data: string) =>
      editor.setTalentReplacementDrop(rowIndex, "replacement", data),
    talentReplacementRolledDrop: (rowIndex: number, data: string) =>
      editor.setTalentReplacementDrop(rowIndex, "rolled", data),
    updateBooleanField: editor.updateBooleanField,
    updateCareerReplacementRows: editor.updateCareerReplacementRows,
    updateCareerTableRows: editor.updateCareerTableRows,
    updateCharacteristic: editor.updateCharacteristic,
    updateHeightField: editor.updateHeightField,
    updateNumberField: editor.updateNumberField,
    updateStringField: editor.updateStringField,
    updateWoundFormula: editor.updateWoundFormula,
    updateSubspeciesArrayField: editor.updateSubspeciesArrayField,
    updateSubspeciesCharacteristic: editor.updateSubspeciesCharacteristic,
    updateSubspeciesNumberField: editor.updateSubspeciesNumberField,
    updateSubspeciesStringField: editor.updateSubspeciesStringField,
    updateSubspeciesWoundFormula: editor.updateSubspeciesWoundFormula,
    updateSubspeciesCareerTableRows: editor.updateSubspeciesCareerTableRows,
    updateSubspeciesTalentReplacementRows: editor.updateSubspeciesTalentReplacementRows,
    updateSubspeciesTextMapField: editor.updateSubspeciesTextMapField,
    updateTalentReplacementRows: editor.updateTalentReplacementRows,
    updateTextMapField: editor.updateTextMapField,
  };
}
