export interface AmbiguousSkillGrant {
  baseName: string;
  options: string[];
  originalName: string;
  specialization: string;
}

export interface ConcreteSkillGrant {
  baseName: string;
  originalName: string;
  specialization: string;
}

export interface SkillGrantOccurrence {
  occurrence: number;
  originalName: string;
  resolutionKey: string;
}

export function buildSkillGrantResolutionKey(
  careerUuid: string,
  originalName: string,
  occurrence: number,
): string {
  return `${careerUuid}:${normalizeSkillGrantText(originalName)}:${occurrence}`;
}

export function formatSpecializedSkillName(baseName: string, specialization: string): string {
  const trimmedBase = baseName.trim();
  const trimmedSpecialization = specialization.trim();

  return trimmedSpecialization ? `${trimmedBase} (${trimmedSpecialization})` : trimmedBase;
}

export function getConcreteSkillGrant(skillName: string): ConcreteSkillGrant | null {
  const match = /^(?<base>.+?)\s*\((?<specialization>[^)]+)\)\s*$/.exec(skillName.trim());

  if (!match?.groups) {
    return null;
  }

  const matchedBaseName = match.groups["base"]?.trim() ?? "";
  const specialization = match.groups["specialization"]?.trim() ?? "";

  if (!matchedBaseName || !specialization) {
    return null;
  }

  if (getAmbiguousSkillGrant(skillName)) {
    return null;
  }

  return {
    baseName: matchedBaseName,
    originalName: skillName,
    specialization,
  };
}

export function getAmbiguousSkillGrant(skillName: string): AmbiguousSkillGrant | null {
  const match = /^(?<base>.+?)\s*\((?<specialization>[^)]+)\)\s*$/.exec(skillName.trim());

  if (!match?.groups) {
    return null;
  }

  const baseName = match.groups["base"]?.trim() ?? "";
  const specialization = match.groups["specialization"]?.trim() ?? "";
  const options = parseSpecializationOptions(specialization);

  if (!baseName || !specialization) {
    return null;
  }

  if (!isAmbiguousSpecialization(specialization, options)) {
    return null;
  }

  return {
    baseName,
    options,
    originalName: skillName,
    specialization,
  };
}

export function getSkillGrantOccurrences(
  careerUuid: string,
  skillNames: string[],
): SkillGrantOccurrence[] {
  const occurrences = new Map<string, number>();

  return skillNames.map((originalName) => {
    const normalizedName = normalizeSkillGrantText(originalName);
    const occurrence = occurrences.get(normalizedName) ?? 0;

    occurrences.set(normalizedName, occurrence + 1);

    return {
      occurrence,
      originalName,
      resolutionKey: buildSkillGrantResolutionKey(careerUuid, originalName, occurrence),
    };
  });
}

export function normalizeSkillGrantText(value: string): string {
  return value.trim().replaceAll(/\s+/g, " ").toLocaleLowerCase();
}

function isAmbiguousSpecialization(specialization: string, options: string[]): boolean {
  const normalized = specialization.trim().toLocaleLowerCase();

  return normalized === "any" || options.length > 1;
}

function parseSpecializationOptions(specialization: string): string[] {
  return specialization
    .split(/\s+or\s+/i)
    .map((option) => option.trim())
    .filter(Boolean);
}
