import { computed, type Ref } from "vue";

import type {
  NpcBaseActorDraftData,
  NpcBuilderSettings,
  NpcCareerQueueEntry,
  NpcTrappingDraftEntry,
  NpcTrappingResolution,
} from "../../types/npc-builder";

import { normalizeQuantity } from "../../functions/npc-builder/draft-helpers";
import {
  createTrappingFallbackResolution,
  deriveNpcTrappings,
  selectTrappingCandidateResolution,
} from "../../functions/npc-builder/trappings/derive-trappings";

interface TrappingStoreSliceContext {
  baseActorDraftData: Ref<NpcBaseActorDraftData>;
  careers: Ref<NpcCareerQueueEntry[]>;
  customTrappings: Ref<NpcTrappingDraftEntry[]>;
  settings: Ref<NpcBuilderSettings>;
  trappingOverrides: Ref<Record<string, { ignored?: boolean; quantity?: number }>>;
  trappingResolutionOverrides: Ref<Record<string, NpcTrappingResolution>>;
}

export function createTrappingStoreSlice(context: TrappingStoreSliceContext) {
  const {
    baseActorDraftData,
    careers,
    customTrappings,
    settings,
    trappingOverrides,
    trappingResolutionOverrides,
  } = context;

  const trappings = computed<NpcTrappingDraftEntry[]>(() =>
    deriveNpcTrappings({
      baseActorDraftData: baseActorDraftData.value,
      careers: careers.value,
      customTrappings: customTrappings.value,
      settings: settings.value,
      trappingOverrides: trappingOverrides.value,
      trappingResolutionOverrides: trappingResolutionOverrides.value,
    }),
  );

  function addCustomTrapping(trapping: NpcTrappingDraftEntry): void {
    if (!customTrappings.value.some((entry) => entry.key === trapping.key)) {
      customTrappings.value.push(trapping);
    }
  }

  function removeCustomTrapping(key: string): void {
    customTrappings.value = customTrappings.value.filter((entry) => entry.key !== key);
    delete trappingOverrides.value[key];
    delete trappingResolutionOverrides.value[key];
  }

  function setTrappingIgnored(key: string, ignored: boolean): void {
    trappingOverrides.value[key] = {
      ...trappingOverrides.value[key],
      ignored,
    };
  }

  function setTrappingQuantity(key: string, quantity: number): void {
    trappingOverrides.value[key] = {
      ...trappingOverrides.value[key],
      quantity: normalizeQuantity(quantity),
    };
  }

  function selectTrappingResolutionCandidate(key: string, candidateUuid: string): void {
    const entry = trappings.value.find((trapping) => trapping.key === key);
    const resolution = entry ? selectTrappingCandidateResolution(entry, candidateUuid) : null;

    if (!resolution) {
      return;
    }

    trappingResolutionOverrides.value[key] = resolution;
  }

  function setTrappingFallback(key: string): void {
    const entry = trappings.value.find((trapping) => trapping.key === key);

    if (!entry) {
      return;
    }

    trappingResolutionOverrides.value[key] = createTrappingFallbackResolution(entry);
  }

  function setTrappingResolution(key: string, resolution: NpcTrappingResolution): void {
    trappingResolutionOverrides.value[key] = resolution;
  }

  return {
    addCustomTrapping,
    removeCustomTrapping,
    selectTrappingResolutionCandidate,
    setTrappingFallback,
    setTrappingIgnored,
    setTrappingQuantity,
    setTrappingResolution,
    trappings,
  };
}
