export interface SpeciesBuilderSavePolicyInput {
  hasLoadError: boolean;
  hasUnsavedChanges: boolean;
  isLoading: boolean;
  isSaving: boolean;
  validationErrorCount: number;
}

export interface SpeciesBuilderSavePolicy {
  canSave: boolean;
  requiresUnsafeSaveConfirmation: boolean;
}

export function getSpeciesBuilderSavePolicy(
  input: SpeciesBuilderSavePolicyInput,
): SpeciesBuilderSavePolicy {
  const canSave =
    !input.isLoading && !input.isSaving && !input.hasLoadError && input.hasUnsavedChanges;

  return {
    canSave,
    requiresUnsafeSaveConfirmation: canSave && input.validationErrorCount > 0,
  };
}
