import { readProperty } from "./path-resolver";
import { isObject } from "./utils";

export interface SummaryContext {
  maxDepth: number;
  maxEntries: number;
  seen: WeakSet<object>;
}

export function summarizeValue(value: unknown, context: SummaryContext): unknown {
  if (!isObject(value) && typeof value !== "function") {
    return summarizePrimitive(value);
  }

  if (typeof value === "function") {
    return summarizeFunction(value);
  }

  if (Array.isArray(value)) {
    return summarizeArray(value, context);
  }

  if (value instanceof Map) {
    return summarizeCollection(value, context);
  }

  return summarizeObject(value, context);
}

function summarizeArray(value: unknown[], context: SummaryContext): Record<string, unknown> {
  return {
    length: value.length,
    sample: value
      .slice(0, context.maxEntries)
      .map((entry) => summarizeValue(entry, nextContext(context))),
    type: "array",
  };
}

function summarizeCollection(
  value: Map<unknown, unknown>,
  context: SummaryContext,
): Record<string, unknown> {
  return {
    sample: [...value.entries()].slice(0, context.maxEntries).map(([key, entry]) => ({
      key: summarizeValue(key, nextContext(context)),
      value: summarizeValue(entry, nextContext(context)),
    })),
    size: value.size,
    type: "Map",
  };
}

function summarizeFunction(value: { name?: string }): Record<string, unknown> {
  return {
    name: value.name,
    type: "function",
  };
}

function summarizeObject(
  value: Record<string, unknown>,
  context: SummaryContext,
): Record<string, unknown> {
  // Foundry documents and collections are often cyclic. Keep the summary
  // bounded so debug probes can be logged safely in a live world.
  if (context.seen.has(value)) {
    return {
      type: "circular",
    };
  }

  context.seen.add(value);

  const keys = getObjectKeys(value, context.maxEntries);
  const constructor = readProperty(value, "constructor");
  const summary: Record<string, unknown> = {
    constructor:
      typeof constructor === "function" && constructor.name ? constructor.name : "Object",
    keys,
    type: "object",
  };

  for (const key of ["documentName", "id", "name", "type", "uuid"]) {
    const property = readProperty(value, key);

    if (typeof property === "string") {
      summary[key] = property;
    }
  }

  if (context.maxDepth <= 0) {
    return summary;
  }

  const properties: Record<string, unknown> = {};

  for (const key of keys) {
    properties[key] = summarizeValue(readProperty(value, key), nextContext(context));
  }

  summary["properties"] = properties;

  const toObject = readProperty(value, "toObject");

  if (typeof toObject === "function") {
    try {
      // Foundry document instances hide useful system data behind toObject().
      // Include a bounded source summary without requiring console access.
      summary["source"] = summarizeValue(toObject.call(value), nextContext(context));
    } catch (error) {
      summary["source"] = {
        error: error instanceof Error ? error.message : String(error),
        type: "error",
      };
    }
  }

  return summary;
}

function summarizePrimitive(value: unknown): Record<string, unknown> {
  if (typeof value === "string") {
    const sample = value.length > 120 ? `${value.slice(0, 120)}...` : value;

    return {
      length: value.length,
      sample,
      type: "string",
    };
  }

  const type = value === null ? "null" : typeof value;

  return {
    type,
    value,
  };
}

function getObjectKeys(value: object, maxEntries: number): string[] {
  return Object.keys(value).sort().slice(0, maxEntries);
}

function nextContext(context: SummaryContext): SummaryContext {
  return {
    maxDepth: context.maxDepth - 1,
    maxEntries: context.maxEntries,
    seen: context.seen,
  };
}
