import SpeciesItemApp from "../../../view/apps/species-item/SpeciesItemApp.vue";
import { MODULE_ID } from "../../constants";
import { VueApplicationMount } from "../vue-mount";
import { SPECIES_ITEM_TYPE } from "../species-builder/items/adapter";
import { createSpeciesItemSheetBridge } from "./bridge";

// Foundry only accepts DocumentSheetV2 subclasses in its sheet registry. Share the Vue mount
// with FoundryVueApplication while retaining the document ownership and sheet lifecycle.
export class SpeciesItemApplication extends foundry.applications.api.DocumentSheetV2 {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    tag: "div",
    classes: [MODULE_ID],
    position: { width: 760, height: 780 },
    window: { resizable: true, icon: "fa-solid fa-people-group" },
  };
  readonly #vue = new VueApplicationMount();

  protected override async _renderHTML(
    _context: foundry.applications.types.ApplicationRenderContext,
    _options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<HTMLElement> {
    return this.#vue.createRoot();
  }

  protected override _replaceHTML(
    root: HTMLElement,
    content: HTMLElement,
    _options: foundry.applications.types.ApplicationRenderOptions,
  ): void {
    this.#vue.mount(root, content, SpeciesItemApp, {
      uuid: this.document.uuid,
      editable: this.isEditable && game.user?.isGM === true,
      bridge: createSpeciesItemSheetBridge(this.document),
    });
  }

  protected override async _preClose(
    options: foundry.applications.types.ApplicationRenderOptions,
  ): Promise<void> {
    this.#vue.unmount();
    await super._preClose(options);
  }
}

export function registerSpeciesItemSheet(): void {
  foundry.applications.apps.DocumentSheetConfig.registerSheet(
    Item,
    MODULE_ID,
    SpeciesItemApplication,
    {
      types: [SPECIES_ITEM_TYPE],
      makeDefault: true,
      label: "Species Customizer",
    },
  );
}
