export function isSpeciesBuilderNavigationEntryCurrent(
  entry: SpeciesBuilderNavigationEntry,
  state: SpeciesBuilderNavigationState,
): boolean {
  if (entry.kind === "project") {
    return state.activeTab === entry.tab && (entry.tab !== "species" || !state.isEditorOpen);
  }

  if (!state.isEditorOpen || state.activeTab !== "species") {
    return false;
  }

  if (entry.kind === "editor") {
    return state.activeEditorTab === entry.tab;
  }

  return state.activeEditorTab === "tables" && state.activeTableTab === entry.tab;
}

export function isSpeciesBuilderNavigationEntryDisabled(
  entry: SpeciesBuilderNavigationEntry,
  state: SpeciesBuilderNavigationState,
): boolean {
  return state.isBusy || (entry.kind !== "project" && !state.hasSelectedDefinition);
}

export function getSpeciesBuilderNavigationValidationKey(
  entry: SpeciesBuilderNavigationEntry,
): SpeciesBuilderNavigationValidationKey | undefined {
  if (entry.kind === "project") {
    return entry.tab === "species" || entry.tab === "species-table" ? entry.tab : undefined;
  }

  return entry.tab;
}

export function buildSpeciesBuilderNavigationValidationCounts(
  issues: SpeciesBuilderValidationIssue[],
  selectedDefinitionIndex: number,
): SpeciesBuilderNavigationValidationCounts {
  const counts: SpeciesBuilderNavigationValidationCounts = {};

  for (const issue of issues) {
    if (issue.scope === "species-table") {
      incrementValidationCount(counts, "species-table", issue);
      continue;
    }

    incrementValidationCount(counts, "species", issue);

    if (issue.definitionIndex !== selectedDefinitionIndex) {
      continue;
    }

    incrementValidationCount(
      counts,
      issue.scope === "subspecies" ? "subspecies" : issue.section,
      issue,
    );
  }

  return counts;
}

function incrementValidationCount(
  counts: SpeciesBuilderNavigationValidationCounts,
  key: SpeciesBuilderNavigationValidationKey,
  issue: SpeciesBuilderValidationIssue,
): void {
  counts[key] = addValidationIssueToIndicator(counts[key], issue);
}

export function getSpeciesBuilderPageMeta(
  activeTab: SpeciesBuilderActiveTab,
  isEditorOpen: boolean,
  activeEditorTab: SpeciesBuilderEditorTab,
  activeTableTab: RandomTableTab,
): SpeciesBuilderPageMeta {
  if (activeTab === "settings") {
    return {
      description: "Control optional authoring tools and sample definitions.",
      label: "Settings",
    };
  }

  if (activeTab === "species-table") {
    return {
      description: "Configure the weighted world table WFRP uses to roll a character's species.",
      label: "Species Table",
    };
  }

  if (activeTab === "wfrp-config") {
    return {
      description: "Review the WFRP config generated from the current draft.",
      label: "WFRP Config",
    };
  }

  if (!isEditorOpen) {
    return {
      description: "Choose a species to edit or create a new definition.",
      label: "Custom Species",
    };
  }

  return activeEditorTab === "tables"
    ? tablePageMeta[activeTableTab]
    : editorPageMeta[activeEditorTab];
}
