import type {
  NpcBaseActorDraftData,
  NpcBuilderSettings,
  NpcCareerQueueEntry,
  NpcTrappingDraftEntry,
  NpcTrappingResolution,
} from "../../../types/npc-builder";

import {
  createFallbackTrappingResolution,
  createMatchedTrappingResolution,
  createUnresolvedTrappingResolution,
} from "../trapping-resolution";
import { normalizeName, normalizeQuantity } from "../draft-helpers";

export interface NpcTrappingDerivationInput {
  baseActorDraftData: NpcBaseActorDraftData;
  careers: NpcCareerQueueEntry[];
  customTrappings: NpcTrappingDraftEntry[];
  settings: NpcBuilderSettings;
  trappingOverrides: Record<string, { ignored?: boolean; quantity?: number }>;
  trappingResolutionOverrides: Record<string, NpcTrappingResolution>;
}

export function deriveNpcTrappings(input: NpcTrappingDerivationInput): NpcTrappingDraftEntry[] {
  const entries = new Map<string, NpcTrappingDraftEntry>();

  addBaseTrappings(entries, input);
  addCareerTrappings(entries, input);

  for (const trapping of input.customTrappings) {
    entries.set(trapping.key, { ...trapping });
  }

  return [...entries.values()]
    .map((entry) => applyTrappingOverrides(entry, input))
    .sort(compareTrappings);
}

export function selectTrappingCandidateResolution(
  entry: NpcTrappingDraftEntry,
  candidateUuid: string,
): NpcTrappingResolution | null {
  const candidate = entry.resolution.candidates.find((option) => option.uuid === candidateUuid);

  if (!candidate) {
    return null;
  }

  return {
    ...entry.resolution,
    selectedCandidateUuid: candidate.uuid,
    selectedItemType: candidate.itemType,
    selectedName: candidate.name,
    status: entry.resolution.status === "matched" ? "matched" : "ambiguous",
  };
}

export function createTrappingFallbackResolution(
  entry: NpcTrappingDraftEntry,
): NpcTrappingResolution {
  return {
    ...createFallbackTrappingResolution(entry.name, entry.itemType),
    candidates: entry.resolution.candidates,
    searchTerms: entry.resolution.searchTerms,
  };
}

function addBaseTrappings(
  entries: Map<string, NpcTrappingDraftEntry>,
  input: NpcTrappingDerivationInput,
): void {
  if (!input.settings.allowBaseActorTrappings) {
    return;
  }

  for (const trapping of input.baseActorDraftData.trappings) {
    const key = `base:${trapping.uuid || normalizeName(trapping.name)}`;

    entries.set(key, {
      ignored: false,
      itemType: trapping.itemType,
      key,
      name: trapping.name,
      quantity: trapping.quantity,
      resolution: createMatchedTrappingResolution({
        itemType: trapping.itemType,
        name: trapping.name,
        uuid: trapping.uuid,
      }),
      source: "base",
      sourceUuid: trapping.uuid,
    });
  }
}

function addCareerTrappings(
  entries: Map<string, NpcTrappingDraftEntry>,
  input: NpcTrappingDerivationInput,
): void {
  for (const career of input.careers) {
    for (const trappingName of career.grants.trappings) {
      const key = `career:${normalizeName(trappingName)}`;
      const existing = entries.get(key);

      if (existing) {
        existing.quantity += career.quantity;
        continue;
      }

      entries.set(key, {
        ignored: false,
        itemType: "trapping",
        key,
        name: trappingName,
        quantity: career.quantity,
        resolution:
          input.trappingResolutionOverrides[key] ??
          createUnresolvedTrappingResolution(trappingName),
        source: "career",
        sourceUuid: "",
      });
    }
  }
}

function applyTrappingOverrides(
  entry: NpcTrappingDraftEntry,
  input: NpcTrappingDerivationInput,
): NpcTrappingDraftEntry {
  const override = input.trappingOverrides[entry.key];

  return {
    ...entry,
    ignored: override?.ignored ?? entry.ignored,
    quantity: normalizeQuantity(override?.quantity ?? entry.quantity),
    resolution: input.trappingResolutionOverrides[entry.key] ?? entry.resolution,
  };
}

function compareTrappings(left: NpcTrappingDraftEntry, right: NpcTrappingDraftEntry): number {
  if (left.source !== right.source) {
    return left.source.localeCompare(right.source);
  }

  return left.name.localeCompare(right.name);
}
