<script setup lang="ts">
import type { SpeciesBuilderTalentReplacementRow } from "../../../../../../../../../../../types/species-builder/species-builder";

import {
  appendTalentReplacementRow,
  removeTalentReplacementRow,
  talentReplacementRowsFromRecord,
} from "../../../../../../../../../../../functions/species-builder/editor/replacements";
import LinkedItemDropField from "../../components/LinkedItemDropField.vue";
import TableEditorHeader from "../../components/TableEditorHeader.vue";
import {
  issuesForField,
  issuesForRow,
  issuesWithoutRow,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../../../../validation-presentation";

const props = defineProps<{
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  rows: SpeciesBuilderTalentReplacementRow[] | undefined;
  values: Record<string, string> | undefined;
}>();

const emit = defineEmits<{
  dropReplacement: [index: number, data: string];
  dropRolled: [index: number, data: string];
  openItem: [uuid: string];
  updateRows: [rows: SpeciesBuilderTalentReplacementRow[]];
}>();

function replacementRows(): SpeciesBuilderTalentReplacementRow[] {
  return props.rows?.length ? props.rows : talentReplacementRowsFromRecord(props.values);
}

function addRow(): void {
  emit("updateRows", appendTalentReplacementRow(replacementRows()));
}

function removeRow(index: number): void {
  emit("updateRows", removeTalentReplacementRow(replacementRows(), index));
}

function sectionMessages(): string[] {
  return uniqueIssueMessages(issuesWithoutRow(props.issues));
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <TableEditorHeader
        action-label="Add Rule"
        action-title="Add a rolled Talent and replacement Talent"
        :count="replacementRows().length"
        description="Offer a specific alternative when character creation rolls a Talent."
        :is-disabled="isDisabled"
        title="Talent Replacements"
        @add="addRow"
      />

      <div
        v-if="sectionMessages().length"
        class="dui-alert"
        :class="validationClass(issuesWithoutRow(issues), 'dui-alert-error', 'dui-alert-warning')"
        role="alert"
      >
        <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
        <div>
          <p v-for="message in sectionMessages()" :key="message" class="app:m-0 app:text-xs">
            {{ message }}
          </p>
        </div>
      </div>

      <ul v-if="replacementRows().length > 0" class="dui-list">
        <li
          v-for="(row, index) in replacementRows()"
          :key="`talent-replacement-${index}`"
          class="dui-list-row"
          :class="
            validationClass(
              issuesForRow(issues, index),
              'app:border app:border-error',
              'app:border app:border-warning',
            )
          "
        >
          <span class="dui-badge dui-badge-ghost">{{ index + 1 }}</span>
          <div class="dui-list-col-grow">
            <LinkedItemDropField
              description="Drop the Talent result that may be replaced."
              :is-disabled="isDisabled"
              :issues="issuesForField(issues, 'rolled', index)"
              label="Rolled Talent"
              title="Drop Rolled Talent"
              :value="row.rolled"
              @drop-data="(data) => emit('dropRolled', index, data)"
              @open-item="(uuid) => emit('openItem', uuid)"
            />
            <LinkedItemDropField
              description="Drop the Talent offered instead of the rolled Talent."
              :is-disabled="isDisabled"
              :issues="issuesForField(issues, 'replacement', index)"
              label="Replacement"
              title="Drop Replacement Talent"
              :value="row.replacement"
              @drop-data="(data) => emit('dropReplacement', index, data)"
              @open-item="(uuid) => emit('openItem', uuid)"
            />
          </div>
          <button
            :disabled="isDisabled"
            title="Remove this Talent replacement"
            class="dui-btn dui-btn-error dui-btn-sm"
            type="button"
            @click="removeRow(index)"
          >
            <i aria-hidden="true" class="fa-solid fa-trash" />
            Remove
          </button>
        </li>
      </ul>
      <div v-else class="dui-alert" role="status">
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>No Talent replacements.</span>
      </div>
    </div>
  </section>
</template>
