import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSettings,
  SpeciesBuilderSubspeciesDefinition,
} from "../../types/species-builder/species-builder";

import { buildSpeciesDefinitionPlans } from "./definition-plans";
import { createFamiliarCorrectionDefinition, FAMILIAR_NAME } from "./familiar-correction";
import { buildCompiledWoundFormulaScriptLines } from "./wound-formula/index";

const GENERATED_WOUND_FORMULA_EFFECT_FLAG = "generatedSpeciesWoundFormulaEffect";
export const GENERATED_WOUND_FORMULA_TRAIT_FLAG = "generatedSpeciesWoundFormulaTrait";

export interface SpeciesWoundFormulaTraitSpec {
  formula: string;
  name: string;
  ownerName: string;
  speciesKey: string;
  subspeciesKey?: string;
}

export interface WoundFormulaTraitSourceInput {
  flagScope: string;
  spec: SpeciesWoundFormulaTraitSpec;
}

export function buildSpeciesWoundFormulaTraitSpecs(
  settings: SpeciesBuilderSettings,
  runtimeParents: SpeciesBuilderDefinition[] = [],
): SpeciesWoundFormulaTraitSpec[] {
  const authoredSpecs = buildSpeciesDefinitionPlans(settings, runtimeParents).flatMap((plan) => [
    ...(plan.emitBaseDefinition ? buildSpeciesFormulaSpecs(plan.definition) : []),
    ...buildSubspeciesFormulaSpecs(plan.definition, plan.subspecies),
  ]);

  return [...authoredSpecs, ...buildFamiliarCorrectionFormulaSpecs(settings, runtimeParents)];
}

export function getSpeciesWoundFormulaTraitName(
  definition: Pick<SpeciesBuilderDefinition, "name">,
) {
  return `__${definition.name.trim()}__`;
}

export function getSubspeciesWoundFormulaTraitName(
  definition: Pick<SpeciesBuilderDefinition, "name">,
  subspecies: Pick<SpeciesBuilderSubspeciesDefinition, "name">,
) {
  return `__${definition.name.trim()} / ${subspecies.name.trim()}__`;
}

export function buildSpeciesWoundFormulaTraitSource({
  flagScope,
  spec,
}: WoundFormulaTraitSourceInput): Record<string, unknown> {
  return {
    effects: [buildSpeciesWoundFormulaEffectSource({ flagScope, spec })],
    flags: {
      [flagScope]: {
        [GENERATED_WOUND_FORMULA_TRAIT_FLAG]: {
          speciesKey: spec.speciesKey,
          subspeciesKey: spec.subspeciesKey ?? "",
        },
      },
    },
    img: "icons/svg/aura.svg",
    name: spec.name,
    system: {
      description: {
        value: buildTraitDescription(spec),
      },
    },
    type: "trait",
  };
}

function buildSpeciesWoundFormulaEffectSource({
  flagScope,
  spec,
}: WoundFormulaTraitSourceInput): Record<string, unknown> {
  return {
    changes: [],
    disabled: false,
    flags: {
      [flagScope]: {
        [GENERATED_WOUND_FORMULA_EFFECT_FLAG]: {
          speciesKey: spec.speciesKey,
          subspeciesKey: spec.subspeciesKey ?? "",
        },
      },
    },
    img: "icons/svg/aura.svg",
    name: `${spec.ownerName} Wound Formula`,
    system: {
      scriptData: [
        {
          label: `${spec.ownerName} Wound Formula Capture`,
          script: buildPreWoundCaptureScript(),
          trigger: "preWoundCalc",
        },
        {
          label: `${spec.ownerName} Wound Formula`,
          script: buildWoundCalculationScript(spec),
          trigger: "woundCalc",
        },
      ],
      transferData: {
        documentType: "Actor",
        type: "document",
      },
    },
    transfer: true,
  };
}

function buildPreWoundCaptureScript(): string {
  return [
    "// Generated by Drowsy's WFRP4e Customizers.",
    'const storageKey = "__wfrp4eCustomizerWoundFormulaArgs";',
    "const sourceId = this.item?.id || this.effect.id;",
    "this.actor[storageKey] ||= {};",
    "this.actor[storageKey][sourceId] = args;",
  ].join("\n");
}

function buildWoundCalculationScript(spec: SpeciesWoundFormulaTraitSpec): string {
  return [
    "// Generated by Drowsy's WFRP4e Customizers.",
    'const storageKey = "__wfrp4eCustomizerWoundFormulaArgs";',
    "const sourceId = this.item?.id || this.effect.id;",
    "const preWoundArgs = this.actor[storageKey][sourceId];",
    "const actor = this.actor;",
    "",
    ...buildCompiledWoundFormulaScriptLines(spec.formula),
  ].join("\n");
}

function buildTraitDescription(spec: SpeciesWoundFormulaTraitSpec): string {
  return [
    "<p>Generated by Drowsy's WFRP4e Customizers. This Trait applies a custom Species Builder wound formula.</p>",
    `<p>${escapeHtml(spec.formula)}</p>`,
  ].join("");
}

function buildSpeciesFormulaSpecs(
  definition: SpeciesBuilderDefinition,
): SpeciesWoundFormulaTraitSpec[] {
  if (!definition.woundFormula?.formula) {
    return [];
  }

  return [
    {
      formula: definition.woundFormula.formula,
      name: getSpeciesWoundFormulaTraitName(definition),
      ownerName: definition.name,
      speciesKey: definition.key,
    },
  ];
}

function buildSubspeciesFormulaSpecs(
  definition: SpeciesBuilderDefinition,
  subspeciesDefinitions: SpeciesBuilderSubspeciesDefinition[],
): SpeciesWoundFormulaTraitSpec[] {
  return subspeciesDefinitions.flatMap((subspecies) => {
    if (!subspecies.woundFormula?.formula) {
      return [];
    }

    return [
      {
        formula: subspecies.woundFormula.formula,
        name: getSubspeciesWoundFormulaTraitName(definition, subspecies),
        ownerName: `${definition.name} / ${subspecies.name}`,
        speciesKey: definition.key,
        subspeciesKey: subspecies.key,
      },
    ];
  });
}

function buildFamiliarCorrectionFormulaSpecs(
  settings: SpeciesBuilderSettings,
  runtimeParents: SpeciesBuilderDefinition[],
): SpeciesWoundFormulaTraitSpec[] {
  if (!settings.correctExistingWfrpSpecies) {
    return [];
  }

  const runtimeFamiliar = runtimeParents.find(
    (definition) => definition.name.trim() === FAMILIAR_NAME,
  );

  return runtimeFamiliar
    ? buildSpeciesFormulaSpecs(createFamiliarCorrectionDefinition(runtimeFamiliar.key))
    : [];
}

function escapeHtml(value: string): string {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}
