<script setup lang="ts">
import type { SpeciesBuilderLinkedItemName } from "../../../../../../../../types/species-builder/species-builder";

import { type SpeciesBuilderValidationIssue, validationClass } from "../validation-presentation";
import LinkedItemDropValue from "./LinkedItemDropValue.vue";

defineProps<{
  dropDescription: string;
  dropTitle: string;
  inputTitle: string;
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  removeTitle: string;
  value: SpeciesBuilderLinkedItemName;
}>();

const emit = defineEmits<{
  dropData: [data: string];
  openItem: [uuid: string];
  remove: [];
  updateName: [name: string];
}>();
</script>

<template>
  <li
    class="dui-list-row"
    :class="validationClass(issues, 'app:border app:border-error', 'app:border app:border-warning')"
  >
    <LinkedItemDropValue
      class="dui-list-col-grow"
      :description="dropDescription"
      :input-title="inputTitle"
      :is-disabled="isDisabled"
      :is-editable="true"
      :issues="issues"
      :title="dropTitle"
      :value="value"
      @drop-data="(data) => emit('dropData', data)"
      @open-item="(uuid) => emit('openItem', uuid)"
      @update-name="(name) => emit('updateName', name)"
    />

    <button
      :disabled="isDisabled"
      :title="removeTitle"
      class="dui-btn dui-btn-error dui-btn-sm"
      type="button"
      @click="emit('remove')"
    >
      <i aria-hidden="true" class="fa-solid fa-trash" />
      Remove
    </button>
  </li>
</template>
