import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderItemReference,
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderTalentGrant,
} from "../../../types/species-builder/species-builder";

import { formatItemReferenceName } from "../item-reference-names";
import { setOptionalField } from "./draft";
import {
  appendLinkedRow,
  appendTalentChoice,
  appendTalentGrant,
  linkedRowNames,
  linkedRowsForValues,
  removeLinkedRow,
  removeTalentChoice,
  removeTalentGrant,
  setLinkedRowItem,
  setLinkedRowName,
  setTalentChoiceItem,
  setTalentChoiceName,
  type SpeciesBuilderLinkedListField,
  type SpeciesBuilderTalentGrantKind,
  talentGrantNames,
  talentGrantsForValues,
} from "./linked-grants";
import { updateSubspeciesAtIndex } from "./subspecies-fields";

export function linkedRowsFromDefinition(
  definition: SpeciesBuilderDefinition,
  field: SpeciesBuilderLinkedListField,
): SpeciesBuilderLinkedItemName[] {
  const linkedRows = field === "skills" ? definition.linkedSkills : definition.linkedTraits;

  return linkedRowsForValues(definition[field], linkedRows);
}

export function talentRowsFromDefinition(
  definition: SpeciesBuilderDefinition,
): SpeciesBuilderTalentGrant[] {
  return talentGrantsForValues(definition.talents, definition.linkedTalents);
}

export function addLinkedItemRow(
  definition: SpeciesBuilderDefinition,
  field: SpeciesBuilderLinkedListField,
): SpeciesBuilderDefinition {
  return setLinkedRows(
    definition,
    field,
    appendLinkedRow(linkedRowsFromDefinition(definition, field), field),
  );
}

export function renameLinkedItemRow(
  definition: SpeciesBuilderDefinition,
  field: SpeciesBuilderLinkedListField,
  rowIndex: number,
  name: string,
): SpeciesBuilderDefinition {
  const rows = setLinkedRowName(linkedRowsFromDefinition(definition, field), rowIndex, name);

  return setLinkedRows(definition, field, rows);
}

export function removeLinkedItemRow(
  definition: SpeciesBuilderDefinition,
  field: SpeciesBuilderLinkedListField,
  rowIndex: number,
): SpeciesBuilderDefinition {
  const rows = removeLinkedRow(linkedRowsFromDefinition(definition, field), rowIndex);

  return setLinkedRows(definition, field, rows);
}

export function setLinkedItemRowReference(
  definition: SpeciesBuilderDefinition,
  field: SpeciesBuilderLinkedListField,
  rowIndex: number,
  item: SpeciesBuilderItemReference,
): SpeciesBuilderDefinition {
  const rows = setLinkedRowItem(linkedRowsFromDefinition(definition, field), rowIndex, item);

  return setLinkedRows(definition, field, rows);
}

export function addTalentGrant(
  definition: SpeciesBuilderDefinition,
  kind: SpeciesBuilderTalentGrantKind,
): SpeciesBuilderDefinition {
  return setTalentRows(definition, appendTalentGrant(talentRowsFromDefinition(definition), kind));
}

export function addTalentGrantChoice(
  definition: SpeciesBuilderDefinition,
  grantIndex: number,
): SpeciesBuilderDefinition {
  return setTalentRows(
    definition,
    appendTalentChoice(talentRowsFromDefinition(definition), grantIndex),
  );
}

export function renameTalentGrantChoice(
  definition: SpeciesBuilderDefinition,
  grantIndex: number,
  choiceIndex: number,
  name: string,
): SpeciesBuilderDefinition {
  const grants = setTalentChoiceName(
    talentRowsFromDefinition(definition),
    grantIndex,
    choiceIndex,
    name,
  );

  return setTalentRows(definition, grants);
}

export function removeTalentGrantRow(
  definition: SpeciesBuilderDefinition,
  grantIndex: number,
): SpeciesBuilderDefinition {
  return setTalentRows(
    definition,
    removeTalentGrant(talentRowsFromDefinition(definition), grantIndex),
  );
}

export function removeTalentGrantChoice(
  definition: SpeciesBuilderDefinition,
  grantIndex: number,
  choiceIndex: number,
): SpeciesBuilderDefinition {
  const grants = removeTalentChoice(talentRowsFromDefinition(definition), grantIndex, choiceIndex);

  return setTalentRows(definition, grants);
}

export function setTalentGrantChoiceReference(
  definition: SpeciesBuilderDefinition,
  grantIndex: number,
  choiceIndex: number,
  item: SpeciesBuilderItemReference,
): SpeciesBuilderDefinition {
  const grants = setTalentChoiceItem(
    talentRowsFromDefinition(definition),
    grantIndex,
    choiceIndex,
    item,
  );

  return setTalentRows(definition, grants);
}

export function appendDroppedGrant(
  definition: SpeciesBuilderDefinition,
  field: "skills" | "talents" | "traits",
  item: SpeciesBuilderItemReference,
): SpeciesBuilderDefinition {
  const name = formatItemReferenceName(item);

  if (field === "talents") {
    const grants = talentRowsFromDefinition(definition);

    return talentGrantNames(grants).includes(name)
      ? definition
      : setTalentRows(definition, [...grants, { choices: [{ item, name }] }]);
  }

  const rows = linkedRowsFromDefinition(definition, field);

  return linkedRowNames(rows).includes(name)
    ? definition
    : setLinkedRows(definition, field, [...rows, { item, name }]);
}

export function applySubspeciesTalentDrop(
  definition: SpeciesBuilderDefinition,
  subspeciesIndex: number,
  item: SpeciesBuilderItemReference,
): SpeciesBuilderDefinition {
  const name = formatItemReferenceName(item);
  const parentTalents = talentGrantNames(talentRowsFromDefinition(definition));

  return updateSubspeciesAtIndex(definition, subspeciesIndex, (subspecies) => {
    if (shouldRestoreSubspeciesParentTalentDrop(parentTalents, name)) {
      const withoutAdded = optionalArray(
        (subspecies.talentsAdded ?? []).filter((talent) => talent !== name),
      );
      const withoutRemoved = optionalArray(
        (subspecies.talentsRemoved ?? []).filter((talent) => talent !== name),
      );

      return setOptionalField(
        setOptionalField(subspecies, "talentsAdded", withoutAdded),
        "talentsRemoved",
        withoutRemoved,
      );
    }

    if ((subspecies.talentsAdded ?? []).includes(name)) {
      return subspecies;
    }

    return setOptionalField(subspecies, "talentsAdded", [...(subspecies.talentsAdded ?? []), name]);
  });
}

export function setLinkedRows(
  definition: SpeciesBuilderDefinition,
  field: SpeciesBuilderLinkedListField,
  rows: SpeciesBuilderLinkedItemName[],
): SpeciesBuilderDefinition {
  const linkedField = field === "skills" ? "linkedSkills" : "linkedTraits";
  const names = linkedRowNames(rows);
  const withLinkedRows = setOptionalField(
    definition,
    linkedField,
    rows.length > 0 ? rows : undefined,
  );

  return setOptionalField(withLinkedRows, field, names.length > 0 ? names : undefined);
}

export function setTalentRows(
  definition: SpeciesBuilderDefinition,
  rows: SpeciesBuilderTalentGrant[],
): SpeciesBuilderDefinition {
  const names = talentGrantNames(rows);
  const withLinkedRows = setOptionalField(
    definition,
    "linkedTalents",
    rows.length > 0 ? rows : undefined,
  );

  return setOptionalField(withLinkedRows, "talents", names.length > 0 ? names : undefined);
}

export function shouldRestoreSubspeciesParentTalentDrop(
  parentTalents: string[],
  droppedTalent: string,
): boolean {
  return parentTalents.includes(droppedTalent) && !/\([^()]*\)/.test(droppedTalent);
}

function optionalArray<TValue>(values: TValue[]): TValue[] | undefined {
  return values.length > 0 ? values : undefined;
}
