<script setup lang="ts">
import { computed, ref } from "vue";

import type { SpeciesBuilderActiveTab } from "./active-tab";

import {
  createAllExampleSpeciesPackage,
  createExampleSpeciesPackage,
  EXAMPLE_SPECIES_OPTIONS,
} from "../../../../functions/species-builder/example-species";
import { useSpeciesBuilderStore } from "../../../../state/species-builder";
import { summarizeValidationIssues } from "../components/validation/validation-presentation";
import SpeciesBuilderSettingsPanel from "./settings/SpeciesBuilderSettingsPanel.vue";
import SpeciesBuilderSpeciesTablePanel from "./species-table/SpeciesBuilderSpeciesTablePanel.vue";
import SpeciesBuilderOverview from "./species/pages/overview/SpeciesBuilderOverview.vue";
import WfrpConfigPanel from "./wfrp-config/WfrpConfigPanel.vue";

defineProps<{
  activeTab: SpeciesBuilderActiveTab;
  isDisabled: boolean;
}>();

const emit = defineEmits<{
  editSpecies: [index: number];
}>();

const editor = useSpeciesBuilderStore();
const selectedExampleSpeciesId = ref(EXAMPLE_SPECIES_OPTIONS[0]?.id ?? "");
const definitionValidationIndicators = computed(() =>
  editor.definitions.map((_, definitionIndex) =>
    summarizeValidationIssues(
      editor.validationIssues.filter((issue) => issue.definitionIndex === definitionIndex),
    ),
  ),
);
const speciesTableIssues = computed(() =>
  editor.validationIssues.filter((issue) => issue.scope === "species-table"),
);

function addBlankDefinition(): void {
  editor.addBlankDefinition();
  emit("editSpecies", editor.selectedIndex);
}

function addSelectedExampleSpecies(exampleId: string): void {
  const examplePackage = createExampleSpeciesPackage(exampleId);

  if (!examplePackage) {
    return;
  }

  editor.addExamplePackage(examplePackage);
  emit("editSpecies", editor.selectedIndex);
}

function addAllExampleSpecies(): void {
  editor.addExamplePackage(createAllExampleSpeciesPackage());
  emit("editSpecies", editor.selectedIndex);
}
</script>

<template>
  <section
    v-if="activeTab === 'settings'"
    id="species-builder-panel-settings"
    aria-label="Species Builder settings"
    role="region"
  >
    <SpeciesBuilderSettingsPanel
      :auto-register-species-table="editor.autoRegisterSpeciesTable"
      :correct-existing-wfrp-species="editor.correctExistingWfrpSpecies"
      :example-species-options="EXAMPLE_SPECIES_OPTIONS"
      :is-disabled="isDisabled"
      :selected-example-species-id="selectedExampleSpeciesId"
      :show-generated-config-tab="editor.showGeneratedConfigTab"
      :species-table="editor.speciesTable"
      @generate-all-example-species="addAllExampleSpecies"
      @generate-example-species="addSelectedExampleSpecies"
      @update-auto-register-species-table="editor.updateAutoRegisterSpeciesTable"
      @update-correct-existing-wfrp-species="editor.updateCorrectExistingWfrpSpecies"
      @update-selected-example-species-id="selectedExampleSpeciesId = $event"
      @update-show-generated-config-tab="editor.updateShowGeneratedConfigTab"
    />
  </section>

  <section
    v-else-if="activeTab === 'species-table'"
    id="species-builder-panel-species-table"
    aria-label="Random Species table"
    role="region"
  >
    <SpeciesBuilderSpeciesTablePanel
      :draft="editor.preparedSpeciesTable"
      :is-disabled="isDisabled"
      :is-validation-blocking="
        editor.blockingValidationIssues.some((issue) => issue.scope === 'species-table')
      "
      :issues="speciesTableIssues"
      :options="editor.speciesTableOptions"
      :summaries="editor.speciesTableSummaries"
      :validation-messages="editor.speciesTableValidationMessages"
      @add-row="editor.addSpeciesTableRow"
      @remove-row="editor.removeSpeciesTableRow"
      @update-row-key="editor.updateSpeciesTableRowKey"
      @update-row-weight="editor.updateSpeciesTableRowWeight"
    />
  </section>

  <section
    v-else-if="activeTab === 'wfrp-config'"
    id="species-builder-panel-wfrp-config"
    aria-label="Generated WFRP configuration"
    role="region"
  >
    <WfrpConfigPanel :generated-config-text="editor.generatedConfigText" />
  </section>

  <section v-else id="species-builder-panel-species" aria-label="Species definitions" role="region">
    <SpeciesBuilderOverview
      :definitions="editor.definitions"
      :is-disabled="isDisabled"
      :selected-index="editor.selectedIndex"
      :validation-indicators="definitionValidationIndicators"
      @add-species="addBlankDefinition"
      @edit-species="emit('editSpecies', $event)"
    />
  </section>
</template>
