import type {
  SpeciesBuilderCareerReplacementRow,
  SpeciesBuilderDefinition,
  SpeciesBuilderLinkedItemName,
  SpeciesBuilderSubspeciesDefinition,
  SpeciesBuilderTalentGrant,
  SpeciesBuilderTalentReplacementRow,
} from "../../../types/species-builder/species-builder";

import { isRecord } from "../../../shared/object-readers";
import { formatLinkedItemName } from "../item-reference-names";
import { linkedNamesFromRows, talentNamesFromGrants } from "../linked-grant-records";
import { validatePortableSpeciesDefinition } from "./validation";
import {
  careerReplacementRecordFromRows,
  talentReplacementRecordFromRows,
} from "../replacement-row-records";
import { normalizeSpeciesBuilderSettings } from "../species-settings-normalization";

export const SPECIES_DEFINITION_EXPORT_FORMAT = "wfrp4e-customizer-species-definition";
export const SPECIES_DEFINITION_EXPORT_VERSION = 1;

export interface SpeciesDefinitionExportPayload {
  definition: SpeciesBuilderDefinition;
  format: typeof SPECIES_DEFINITION_EXPORT_FORMAT;
  version: typeof SPECIES_DEFINITION_EXPORT_VERSION;
}

export type SpeciesDefinitionImportResult =
  | {
      definition: SpeciesBuilderDefinition;
      ok: true;
    }
  | {
      error: string;
      ok: false;
    };

export function serializeSpeciesDefinitionExport(definition: SpeciesBuilderDefinition): string {
  const normalized = normalizeDefinition(definition);

  if (!normalized.ok) {
    throw new Error(`Species definition cannot be exported: ${normalized.error}`);
  }

  const payload: SpeciesDefinitionExportPayload = {
    definition: createPortableDefinition(normalized.definition),
    format: SPECIES_DEFINITION_EXPORT_FORMAT,
    version: SPECIES_DEFINITION_EXPORT_VERSION,
  };

  return JSON.stringify(payload, null, 2);
}

export function parseSpeciesDefinitionImport(source: string): SpeciesDefinitionImportResult {
  let payload: unknown;

  try {
    payload = JSON.parse(source) as unknown;
  } catch (error) {
    const detail = error instanceof Error ? error.message : "Unknown JSON error.";

    return importError(`Import is not valid JSON: ${detail}`);
  }

  if (!isRecord(payload)) {
    return importError("Import payload must be a JSON object.");
  }

  const unsupportedPayloadField = Object.keys(payload).find(
    (field) => !["definition", "format", "version"].includes(field),
  );

  if (unsupportedPayloadField) {
    return importError(
      `${unsupportedPayloadField} is not supported by species definition export version 1.`,
    );
  }

  if (payload["format"] !== SPECIES_DEFINITION_EXPORT_FORMAT) {
    return importError(`Import payload format must be "${SPECIES_DEFINITION_EXPORT_FORMAT}".`);
  }

  if (payload["version"] !== SPECIES_DEFINITION_EXPORT_VERSION) {
    return importError(`Import payload version must be ${SPECIES_DEFINITION_EXPORT_VERSION}.`);
  }

  if (!("definition" in payload)) {
    return importError("Import payload must include a definition object.");
  }

  const validationError = validatePortableSpeciesDefinition(payload["definition"]);

  if (validationError) {
    return importError(validationError);
  }

  const normalized = normalizeDefinition(payload["definition"]);

  return normalized.ok
    ? {
        definition: createPortableDefinition(normalized.definition),
        ok: true,
      }
    : normalized;
}

function normalizeDefinition(value: unknown): SpeciesDefinitionImportResult {
  const validationError = validateDefinitionIdentity(value);

  if (validationError) {
    return importError(validationError);
  }

  const definition = normalizeSpeciesBuilderSettings({
    definitions: [value],
    showGeneratedConfigTab: false,
  }).definitions[0];

  return definition
    ? { definition, ok: true }
    : importError("definition could not be normalized as a Species Builder definition.");
}

function validateDefinitionIdentity(value: unknown): string {
  if (!isRecord(value)) {
    return "definition must be a JSON object.";
  }

  if (typeof value["key"] !== "string" || !value["key"].trim()) {
    return "definition.key must be a non-empty string.";
  }

  if (typeof value["name"] !== "string" || !value["name"].trim()) {
    return "definition.name must be a non-empty string.";
  }

  if ("includeInExtraSpecies" in value && typeof value["includeInExtraSpecies"] !== "boolean") {
    return "definition.includeInExtraSpecies must be a boolean.";
  }

  if ("subspecies" in value && !Array.isArray(value["subspecies"])) {
    return "definition.subspecies must be an array.";
  }

  const subspecies = (value["subspecies"] as unknown[] | undefined) ?? [];

  for (const [index, entry] of subspecies.entries()) {
    if (!isRecord(entry)) {
      return `definition.subspecies[${index}] must be a JSON object.`;
    }

    if (typeof entry["key"] !== "string" || !entry["key"].trim()) {
      return `definition.subspecies[${index}].key must be a non-empty string.`;
    }

    if (typeof entry["name"] !== "string" || !entry["name"].trim()) {
      return `definition.subspecies[${index}].name must be a non-empty string.`;
    }
  }

  return "";
}

function createPortableDefinition(definition: SpeciesBuilderDefinition): SpeciesBuilderDefinition {
  const portable: SpeciesBuilderDefinition = {
    ...definition,
    careerTable: portableCareerTable(definition.careerTable),
    subspecies: definition.subspecies?.map(createPortableSubspecies),
  };

  if (definition.linkedSkills) {
    portable.linkedSkills = definition.linkedSkills.map(portableLinkedName);
    portable.skills = linkedNamesFromRows(portable.linkedSkills);
  }

  if (definition.linkedTalents) {
    portable.linkedTalents = definition.linkedTalents.map(portableTalentGrant);
    portable.talents = talentNamesFromGrants(portable.linkedTalents);
  }

  if (definition.linkedTraits) {
    portable.linkedTraits = definition.linkedTraits.map(portableLinkedName);
    portable.traits = linkedNamesFromRows(portable.linkedTraits);
  }

  if (definition.talentReplacementRows) {
    portable.talentReplacementRows = definition.talentReplacementRows.map(
      portableTalentReplacementRow,
    );
    portable.talentReplacements = talentReplacementRecordFromRows(portable.talentReplacementRows);
  }

  if (definition.careerReplacementRows) {
    portable.careerReplacementRows = definition.careerReplacementRows.map(
      portableCareerReplacementRow,
    );
    portable.careerReplacements = careerReplacementRecordFromRows(portable.careerReplacementRows);
  }

  return portable;
}

function createPortableSubspecies(
  subspecies: SpeciesBuilderSubspeciesDefinition,
): SpeciesBuilderSubspeciesDefinition {
  const portable: SpeciesBuilderSubspeciesDefinition = {
    ...subspecies,
    careerTable: portableCareerTable(subspecies.careerTable),
  };

  if (subspecies.talentReplacementRows) {
    portable.talentReplacementRows = subspecies.talentReplacementRows.map(
      portableTalentReplacementRow,
    );
    portable.talentReplacements = talentReplacementRecordFromRows(portable.talentReplacementRows);
  }

  return portable;
}

function portableLinkedName(value: SpeciesBuilderLinkedItemName): SpeciesBuilderLinkedItemName {
  return {
    name: formatLinkedItemName(value),
  };
}

function portableTalentGrant(grant: SpeciesBuilderTalentGrant): SpeciesBuilderTalentGrant {
  return {
    choices: grant.choices.map(portableLinkedName),
  };
}

function portableTalentReplacementRow(
  row: SpeciesBuilderTalentReplacementRow,
): SpeciesBuilderTalentReplacementRow {
  return {
    replacement: portableLinkedName(row.replacement),
    rolled: portableLinkedName(row.rolled),
  };
}

function portableCareerReplacementRow(
  row: SpeciesBuilderCareerReplacementRow,
): SpeciesBuilderCareerReplacementRow {
  return {
    replacements: row.replacements.map(portableLinkedName),
    rolled: portableLinkedName(row.rolled),
  };
}

function portableCareerTable(
  careerTable: SpeciesBuilderDefinition["careerTable"],
): SpeciesBuilderDefinition["careerTable"] {
  return careerTable
    ? {
        rows: careerTable.rows.map((row) => ({ name: row.name })),
      }
    : undefined;
}

function importError(error: string): SpeciesDefinitionImportResult {
  return {
    error,
    ok: false,
  };
}
