import { isRecord } from "../../../../shared/object-readers";

export interface RuntimeTableReadiness {
  readyForCharacterCreation: boolean;
  reason?: string;
  requiresWorldTableImport?: boolean;
}

interface RuntimeTableResultTexts {
  reason?: string;
  texts: string[];
}

export function validateRandomTalentTable(
  source: unknown,
  talentBaseNames: ReadonlySet<string>,
): RuntimeTableReadiness {
  const resultTexts = readWfrpTableResultTexts(source);

  if (resultTexts.reason) {
    return notReady(resultTexts.reason);
  }

  const missing = resultTexts.texts.filter(
    (text) => !talentBaseNames.has(extractItemBaseName(text)),
  );

  return missing.length > 0
    ? notReady(
        `these result labels do not match Talent Items exactly: ${uniqueLabels(missing).join(", ")}`,
      )
    : ready();
}

export function validateCareerTable(
  source: unknown,
  careerGroupNames: ReadonlySet<string>,
): RuntimeTableReadiness {
  const resultTexts = readWfrpTableResultTexts(source);

  if (resultTexts.reason) {
    return notReady(resultTexts.reason);
  }

  const missing = resultTexts.texts.filter((text) => !careerGroupNames.has(text));

  return missing.length > 0
    ? notReady(
        `these result labels do not match tier-1 Career groups exactly: ${uniqueLabels(missing).join(", ")}`,
      )
    : ready();
}

export function readWfrpTableResultTexts(source: unknown): RuntimeTableResultTexts {
  if (!isRecord(source)) {
    return { reason: "the table could not be found", texts: [] };
  }

  // WFRP returns a columns array when one key resolves to a table-family selector.
  // An absent or undefined property is still an ordinary RollTable, matching rollTable's check.
  if (Array.isArray(source["columns"])) {
    return {
      reason: "the table key resolves to multiple columns instead of one RollTable",
      texts: [],
    };
  }

  const results = iterableValues(source["results"]);

  if (results.length === 0) {
    return { reason: "the table has no results", texts: [] };
  }

  const texts = results.map(readResultText);
  const unreadable = texts.filter((text) => !text);

  return unreadable.length > 0
    ? { reason: "one or more results have no usable WFRP result text", texts }
    : { texts };
}

export function extractWfrpTableResultText(chatText: string): string {
  const match = /\{(.+?)\}/u.exec(chatText);

  return match?.[1] ?? chatText;
}

function readResultText(source: unknown): string {
  if (!isRecord(source)) {
    return "";
  }

  // This mirrors Foundry 14's TableResult#getChatText without calling that deprecated API.
  // WFRP 9.6.3 still parses the visible label from this exact string shape.
  const chatText =
    source["type"] === "document" ? documentResultChatText(source) : source["description"];

  return typeof chatText === "string" ? extractWfrpTableResultText(chatText) : "";
}

function documentResultChatText(source: Record<string, unknown>): string {
  const documentUuid = source["documentUuid"];
  const name = source["name"];

  return typeof documentUuid === "string" && typeof name === "string"
    ? `@UUID[${documentUuid}]{${name}}`
    : "";
}

function iterableValues(source: unknown): unknown[] {
  if (Array.isArray(source)) {
    return source;
  }

  return isRecord(source) && Symbol.iterator in source ? [...source] : [];
}

function extractItemBaseName(value: string): string {
  return value.split("(")[0]?.trim() ?? "";
}

function uniqueLabels(values: string[]): string[] {
  return [...new Set(values.map((value) => value || "(blank result)"))];
}

function ready(): RuntimeTableReadiness {
  return { readyForCharacterCreation: true };
}

function notReady(reason: string): RuntimeTableReadiness {
  return { readyForCharacterCreation: false, reason };
}
