<script setup lang="ts">
import { computed, nextTick } from "vue";

import type { SpeciesBuilderActiveTab } from "../tabs/active-tab";
import type { SpeciesBuilderEditorTab } from "../tabs/species/pages/editor/editor-tabs";
import type { RandomTableTab } from "../tabs/species/pages/editor/tabs/tables/random-table-events";
import type { SpeciesBuilderNavigationEntry } from "./species-builder-navigation";
import type { SpeciesBuilderNavigationValidationCounts } from "./species-builder-navigation";
import type { SpeciesBuilderValidationIndicator } from "./validation/validation-presentation";

import {
  createSpeciesBuilderNavigationGroups,
  getSpeciesBuilderNavigationValidationKey,
  isSpeciesBuilderNavigationEntryCurrent,
  isSpeciesBuilderNavigationEntryDisabled,
} from "./species-builder-navigation";
import SpeciesBuilderValidationDot from "./SpeciesBuilderValidationDot.vue";

const props = defineProps<{
  activeEditorTab: SpeciesBuilderEditorTab;
  activeTableTab: RandomTableTab;
  activeTab: SpeciesBuilderActiveTab;
  hasSelectedDefinition: boolean;
  isBusy: boolean;
  isEditorOpen: boolean;
  showGeneratedConfigTab: boolean;
  validationCounts: SpeciesBuilderNavigationValidationCounts;
}>();

const emit = defineEmits<{
  selectEditorTab: [tab: SpeciesBuilderEditorTab];
  selectTableTab: [tab: RandomTableTab];
  selectTab: [tab: SpeciesBuilderActiveTab];
}>();

const navigationGroups = computed(() =>
  createSpeciesBuilderNavigationGroups(props.showGeneratedConfigTab),
);
const navigationState = computed(() => ({
  activeEditorTab: props.activeEditorTab,
  activeTableTab: props.activeTableTab,
  activeTab: props.activeTab,
  hasSelectedDefinition: props.hasSelectedDefinition,
  isBusy: props.isBusy,
  isEditorOpen: props.isEditorOpen,
}));

async function selectEntry(entry: SpeciesBuilderNavigationEntry, event: MouseEvent): Promise<void> {
  if (isSpeciesBuilderNavigationEntryDisabled(entry, navigationState.value)) {
    return;
  }

  const scrollContainer =
    event.currentTarget instanceof HTMLElement
      ? event.currentTarget.closest<HTMLElement>(".wfrp4e-customizer-apps-root")
      : null;

  if (entry.kind === "project") {
    emit("selectTab", entry.tab);
  } else if (entry.kind === "editor") {
    emit("selectEditorTab", entry.tab);
  } else {
    emit("selectTableTab", entry.tab);
  }

  await nextTick();
  scrollContainer?.scrollTo({ top: 0 });
}

function validationIndicator(
  entry: SpeciesBuilderNavigationEntry,
): SpeciesBuilderValidationIndicator | undefined {
  const key = getSpeciesBuilderNavigationValidationKey(entry);

  return key ? props.validationCounts[key] : undefined;
}
</script>

<template>
  <aside class="app:w-48 app:shrink-0">
    <nav aria-label="Species Builder sections" class="app:sticky app:top-20">
      <ul class="dui-menu dui-menu-sm app:w-full app:rounded-box app:bg-base-200">
        <template v-for="group in navigationGroups" :key="group.key">
          <li class="dui-menu-title">
            <span>{{ group.label }}</span>
          </li>
          <li v-for="entry in group.entries" :key="`${entry.kind}-${entry.tab}`">
            <button
              :aria-current="
                isSpeciesBuilderNavigationEntryCurrent(entry, navigationState) ? 'page' : undefined
              "
              :class="{
                'dui-menu-active': isSpeciesBuilderNavigationEntryCurrent(entry, navigationState),
              }"
              :disabled="isSpeciesBuilderNavigationEntryDisabled(entry, navigationState)"
              type="button"
              @click="selectEntry(entry, $event)"
            >
              <i aria-hidden="true" :class="entry.icon" />
              <span>{{ entry.label }}</span>
              <SpeciesBuilderValidationDot :indicator="validationIndicator(entry)" />
            </button>
          </li>
        </template>
      </ul>
    </nav>
  </aside>
</template>
