import { GENERATED_CAREER_TABLE_FLAG } from "../../../../functions/species-builder/career-tables";
import { readUnknownPath } from "../../../../shared/object-readers";
import { MODULE_ID } from "../../../constants";
import { readSpeciesItem } from "./adapter";
import { worldSpeciesItems } from "./repository";

export function managedSpeciesCareerTables(): FoundryRollTableDocument[] {
  const references = worldSpeciesItems().map((item) => readSpeciesItem(item).system.tables.career);
  return (game.tables?.contents ?? []).filter(
    (table) =>
      readUnknownPath(table.toObject(), [
        "flags",
        MODULE_ID,
        GENERATED_CAREER_TABLE_FLAG,
        "speciesItemBridge",
      ]) === true &&
      !references.some(
        (reference) =>
          reference.uuid === table.uuid || (!reference.uuid && reference.id === table.id),
      ),
  );
}
