import type {
  SpeciesBuilderCareerTableDefinition,
  SpeciesBuilderDefinition,
  SpeciesBuilderExamplePackage,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../../types/species-builder/species-builder";

type CharacteristicBonuses = [
  ws: number,
  bs: number,
  s: number,
  t: number,
  i: number,
  ag: number,
  dex: number,
  int: number,
  wp: number,
  fel: number,
];

type SpeciesFields = Omit<SpeciesBuilderDefinition, "characteristics" | "key" | "name">;

type SubspeciesFields = Omit<
  SpeciesBuilderSubspeciesDefinition,
  "characteristics" | "key" | "name"
>;

export function species(
  key: string,
  name: string,
  bonuses: CharacteristicBonuses,
  fields: SpeciesFields,
): SpeciesBuilderDefinition {
  return {
    characteristics: characteristics(...bonuses),
    key,
    name,
    ...fields,
  };
}

export function subspecies(
  key: string,
  name: string,
  bonuses?: CharacteristicBonuses,
  fields: SubspeciesFields = {},
): SpeciesBuilderSubspeciesDefinition {
  return {
    ...(bonuses ? { characteristics: characteristics(...bonuses) } : {}),
    key,
    name,
    ...fields,
  };
}

export function careers(...names: string[]): SpeciesBuilderCareerTableDefinition {
  return { rows: names.map((name) => ({ name })) };
}

export function definitionPackage(
  ...definitions: SpeciesBuilderDefinition[]
): SpeciesBuilderExamplePackage {
  return { definitions, runtimeSpeciesExtensions: [] };
}

export function characteristics(
  ws: number,
  bs: number,
  s: number,
  t: number,
  i: number,
  ag: number,
  dex: number,
  int: number,
  wp: number,
  fel: number,
): SpeciesBuilderDefinition["characteristics"] {
  return {
    ag: formula(ag),
    bs: formula(bs),
    dex: formula(dex),
    fel: formula(fel),
    i: formula(i),
    int: formula(int),
    s: formula(s),
    t: formula(t),
    wp: formula(wp),
    ws: formula(ws),
  };
}

function formula(bonus: number): string {
  return bonus === -1 ? "0" : `2d10+${bonus}`;
}
