<script setup lang="ts">
import type { NpcLowerCareerMode } from "../../../../../types/npc-builder";

import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  askForLinkedSkillSpecializations: boolean;
  lowerCareerMode: NpcLowerCareerMode;
}>();

const emit = defineEmits<{
  askForLinkedSkillSpecializationsChange: [value: boolean];
  lowerCareerModeChange: [mode: NpcLowerCareerMode];
}>();

function handleLowerCareerModeChange(event: Event): void {
  const select = event.target as HTMLSelectElement | null;
  const value = select?.value;

  if (value === "auto-add-all" || value === "never" || value === "prompt") {
    emit("lowerCareerModeChange", value);
  }
}

function handleLinkedSkillsChange(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("askForLinkedSkillSpecializationsChange", Boolean(input?.checked));
}
</script>

<template>
  <NpcBuilderSection title="Career Resolution">
    <fieldset class="dui-fieldset">
      <legend class="dui-fieldset-legend">Lower career handling</legend>
      <select
        aria-label="Lower career handling"
        class="dui-select dui-select-sm"
        :value="lowerCareerMode"
        @change="handleLowerCareerModeChange"
      >
        <option value="prompt">Prompt when candidates are found</option>
        <option value="auto-add-all">Automatically add all lower-tier matches</option>
        <option value="never">Only add dropped careers</option>
      </select>
    </fieldset>
    <label class="dui-label">
      <input
        class="dui-toggle dui-toggle-sm"
        :checked="askForLinkedSkillSpecializations"
        type="checkbox"
        @change="handleLinkedSkillsChange"
      />
      <span>Resolve linked career skill repeats separately</span>
    </label>
  </NpcBuilderSection>
</template>
