import type {
  NpcBaseActorDraftData,
  NpcBaseActorSummary,
  NpcBuilderSettings,
} from "../../../../types/npc-builder";

import { readStringPath } from "../../../../shared/object-readers";
import { assertFoundryActor } from "../../../foundry/document-guards";
import { parseDropData } from "../../../foundry/drop-data";
import { readCharacteristicAdvancements, readItemAdvancements } from "./advancements";
import { readActorOptionalTraits, readActorTraits } from "./traits";
import { readActorTrappings } from "./trappings";

export function listBaseActors(settings: NpcBuilderSettings): NpcBaseActorSummary[] {
  return game.actors.contents
    .filter((actor) => isActorInBaseFolder(actor, settings))
    .map(toActorSummary);
}

export async function loadBaseActorDraftData(
  baseActorUuid: string,
): Promise<NpcBaseActorDraftData> {
  const actor = assertFoundryActor(await fromUuid(baseActorUuid));

  return {
    advancements: [
      ...readCharacteristicAdvancements(actor),
      ...readItemAdvancements(actor, "skill"),
      ...readItemAdvancements(actor, "talent"),
    ],
    optionalTraits: readActorOptionalTraits(actor),
    traits: readActorTraits(actor),
    trappings: readActorTrappings(actor),
  };
}

export async function resolveActorDrop(data: string): Promise<NpcBaseActorSummary> {
  const dropData = parseDropData(data);

  if (dropData.type !== "Actor") {
    throw new Error("Drop a Foundry Actor here.");
  }

  let actorDocument: unknown = null;

  if (dropData.uuid) {
    actorDocument = await fromUuid(dropData.uuid);
  } else if (dropData.id) {
    actorDocument = game.actors.get(dropData.id);
  }

  const actor = assertFoundryActor(actorDocument);

  return toActorSummary(actor);
}

export function toActorSummary(actor: FoundryActorDocument): NpcBaseActorSummary {
  return {
    img: actor.img ?? "",
    name: actor.name,
    prototypeTokenImg: getActorPrototypeTokenImage(actor),
    species: getActorSpecies(actor),
    type: actor.type,
    uuid: actor.uuid,
  };
}

export function getActorSpecies(actor: FoundryActorDocument): string {
  return (
    readStringPath(actor.system, ["details", "species", "value"]) ||
    readStringPath(actor.system, ["details", "species"]) ||
    readStringPath(actor.system, ["details", "race", "value"]) ||
    readStringPath(actor.system, ["details", "ancestry", "value"])
  );
}

export function getActorPrototypeTokenImage(actor: FoundryActorDocument): string {
  return (
    readStringPath(actor, ["prototypeToken", "texture", "src"]) ||
    readStringPath(actor.toObject(), ["prototypeToken", "texture", "src"])
  );
}

function isActorInBaseFolder(actor: FoundryActorDocument, settings: NpcBuilderSettings): boolean {
  if (!settings.baseActorFolderUuid) {
    return true;
  }

  return actor.folder?.uuid === settings.baseActorFolderUuid;
}
