import { normalizeName } from "../../../../functions/npc-builder/draft-helpers";
import {
  getCompendiumIndexEntryUuid,
  isActorCompendiumPack,
  readCompendiumIndexEntries,
} from "../../../foundry/compendiums";

interface SpeciesActorMatch {
  actor: FoundryActorDocument;
  source: string;
}

interface CompendiumActorCandidate {
  name: string;
  source: string;
  uuid: string;
}

let compendiumActorCandidatesPromise: null | Promise<CompendiumActorCandidate[]> = null;

export async function findSpeciesActor(
  species: string,
  subjectActor: FoundryActorDocument,
  baseActorFolderUuid: string,
): Promise<null | SpeciesActorMatch> {
  const actors = game.actors.contents;
  const prioritizedActors = baseActorFolderUuid
    ? actors.filter((actor) => actor.folder?.uuid === baseActorFolderUuid)
    : [];
  const prioritizedMatch = findActorNameMatch(prioritizedActors, species);

  if (prioritizedMatch) {
    return {
      actor: prioritizedMatch,
      source: prioritizedMatch.folder?.name ?? "Configured NPC Base Actors folder",
    };
  }

  const worldMatch = findActorNameMatch(
    actors.filter((actor) => actor.uuid !== subjectActor.uuid),
    species,
  );

  if (worldMatch) {
    return { actor: worldMatch, source: "World Actors" };
  }

  const compendiumMatch = findCandidateNameMatch(await getCompendiumActorCandidates(), species);

  if (!compendiumMatch) {
    return null;
  }

  const actor = await fromUuid(compendiumMatch.uuid);

  if (!isActorDocument(actor)) {
    throw new Error(`The species Actor ${compendiumMatch.uuid} is no longer available.`);
  }

  return { actor, source: compendiumMatch.source };
}

function findActorNameMatch(
  actors: FoundryActorDocument[],
  species: string,
): FoundryActorDocument | null {
  return findNameMatch(actors, species, (actor) => actor.name);
}

function findCandidateNameMatch(
  actors: CompendiumActorCandidate[],
  species: string,
): CompendiumActorCandidate | null {
  return findNameMatch(actors, species, (actor) => actor.name);
}

function findNameMatch<T>(
  candidates: T[],
  species: string,
  getName: (candidate: T) => string,
): T | null {
  const trimmedSpecies = species.trim();
  const exactMatch = candidates.find((candidate) => getName(candidate).trim() === trimmedSpecies);

  return (
    exactMatch ??
    candidates.find((candidate) => normalizeName(getName(candidate)) === normalizeName(species)) ??
    null
  );
}

function getCompendiumActorCandidates(): Promise<CompendiumActorCandidate[]> {
  compendiumActorCandidatesPromise ??= buildCompendiumActorCandidates();

  return compendiumActorCandidatesPromise;
}

async function buildCompendiumActorCandidates(): Promise<CompendiumActorCandidate[]> {
  const candidates: CompendiumActorCandidate[] = [];

  for (const pack of game.packs ?? []) {
    if (!isActorCompendiumPack(pack) || !pack.getIndex) {
      continue;
    }

    const index = await pack.getIndex({ fields: ["name"] });

    for (const entry of readCompendiumIndexEntries(index)) {
      const uuid = getCompendiumIndexEntryUuid(pack, entry);

      if (entry.name && uuid) {
        candidates.push({
          name: entry.name,
          source: pack.title ?? pack.collection ?? "Actor Compendium",
          uuid,
        });
      }
    }
  }

  return candidates;
}

function isActorDocument(value: unknown): value is FoundryActorDocument {
  return (
    typeof value === "object" &&
    value !== null &&
    "documentName" in value &&
    value.documentName === "Actor"
  );
}
