<script setup lang="ts">
import { computed, onMounted, ref } from "vue";

import type {
  SpeciesBuilderBridge,
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
} from "../../../types/species-builder/species-builder";

import { createDefinitionsWithGeneratedKeys } from "../../../functions/species-builder/editor/draft";
import { useSpeciesBuilderEditor } from "../../../state/species-builder/editor";
import SpeciesBuilderStatus from "../species-builder/components/SpeciesBuilderStatus.vue";
import SpeciesDefinitionPortability from "../species-builder/components/SpeciesDefinitionPortability.vue";
import UnsafeSaveConfirmationSubView from "../species-builder/components/UnsafeSaveConfirmationSubView.vue";
import { useSpeciesBuilderUnsafeSave } from "../species-builder/components/unsafe-save";
import {
  summarizeValidationIssues,
  validationIndicatorLabel,
} from "../species-builder/components/validation/validation-presentation";
import { validationIssuesForSummary } from "../species-builder/components/validation/species-builder-validation-summary";
import SpeciesSuiteHeader from "./components/SpeciesSuiteHeader.vue";

const props = defineProps<{
  bridge: SpeciesBuilderBridge;
  onOpenConfigurator: () => void;
  onOpenIssues: (definitionIndex?: number) => void;
  onOpenSpecies: (definitionIndex: number) => void;
  onOpenSpeciesTable: () => void;
  onOpenWfrpConfig: () => void;
  onSettingsSaved?: () => void;
}>();
const editor = useSpeciesBuilderEditor(props.bridge, { onSettingsSaved: props.onSettingsSaved });
const unsafeSave = useSpeciesBuilderUnsafeSave(editor);
const filter = ref("");
const portabilityHost = ref<HTMLElement>();
const isBusy = computed(() => editor.isLoading.value || editor.isSaving.value);
const summaryIssues = computed(() => validationIssuesForSummary(editor.validationIssues.value));
const errorCount = computed(
  () => summaryIssues.value.filter((issue) => issue.severity === "error").length,
);
const warningCount = computed(() => summaryIssues.value.length - errorCount.value);
const definitionKeys = computed(() =>
  createDefinitionsWithGeneratedKeys(editor.definitions.value).map(({ key }) => key),
);
const visibleDefinitions = computed(() => {
  const query = filter.value.trim().toLocaleLowerCase();

  return editor.definitions.value
    .map((definition, index) => ({ definition, index }))
    .filter(
      ({ definition }) =>
        !query ||
        definition.name.toLocaleLowerCase().includes(query) ||
        definition.key.toLocaleLowerCase().includes(query),
    );
});

onMounted(() => void editor.ensureSettingsLoaded());

function definitionLabel(definition: SpeciesBuilderEditingDefinition): string {
  return definition.name.trim() || definition.key.trim() || "Untitled Species";
}

function sourceLabel(definition: SpeciesBuilderEditingDefinition): string {
  if (definition.runtimeUnavailable) return "Source unavailable";
  return definition.origin === "runtime" ? "Installed" : "Custom";
}

function definitionIndicator(index: number) {
  return summarizeValidationIssues(
    editor.validationIssues.value.filter((issue) => issue.definitionIndex === index),
  );
}

function addSpecies(): void {
  editor.addBlankDefinition();
  props.onOpenSpecies(editor.selectedIndex.value);
}

function importDefinition(definition: SpeciesBuilderDefinition): void {
  editor.addDefinition(definition);
  props.onOpenSpecies(editor.selectedIndex.value);
}

function stopFormControlKeyPropagation(event: KeyboardEvent): void {
  if (event.target instanceof HTMLInputElement) event.stopPropagation();
}
</script>

<template>
  <section
    class="app:flex app:min-h-full app:flex-col"
    :aria-busy="isBusy"
    @keydown="stopFormControlKeyPropagation"
    @keyup="stopFormControlKeyPropagation"
  >
    <SpeciesSuiteHeader
      :can-save="editor.canSave.value"
      :error-count="errorCount"
      :has-unsaved-changes="editor.hasUnsavedChanges.value"
      :is-busy="isBusy"
      :show-parent="false"
      title="Species"
      :warning-count="warningCount"
      @open-issues="onOpenIssues()"
      @reload="editor.loadSettings"
      @save="unsafeSave.requestSave"
    />

    <UnsafeSaveConfirmationSubView
      :is-open="unsafeSave.isConfirmationOpen.value"
      @close="unsafeSave.closeConfirmation"
      @confirm="unsafeSave.confirmSave"
    />

    <div ref="portabilityHost" />

    <main class="app:flex app:flex-1 app:flex-col app:gap-3 app:p-3">
      <SpeciesBuilderStatus
        :chargen-error-count="errorCount"
        :chargen-warning-count="warningCount"
        :load-error="editor.loadError.value || editor.saveError.value"
        :message="editor.message.value"
        :validation-message="editor.blockingSpeciesTableValidationMessages.value[0] ?? ''"
        @review-issues="onOpenIssues()"
      />

      <section class="app:flex app:flex-wrap app:items-center app:gap-2" aria-label="Species tools">
        <button
          class="dui-btn dui-btn-primary dui-btn-sm"
          :disabled="isBusy"
          type="button"
          @click="addSpecies"
        >
          <i aria-hidden="true" class="fa-solid fa-plus" />
          New Species
        </button>
        <SpeciesDefinitionPortability
          button-class="dui-btn dui-btn-sm"
          :definition="undefined"
          :dialog-host="portabilityHost"
          :existing-keys="definitionKeys"
          :is-disabled="isBusy"
          is-import-only
          @import-definition="importDefinition"
        />
        <button
          class="dui-btn dui-btn-sm"
          :disabled="isBusy"
          type="button"
          @click="onOpenSpeciesTable"
        >
          <i aria-hidden="true" class="fa-solid fa-dice-d20" />
          Species Table
        </button>
        <button
          class="dui-btn dui-btn-sm"
          :disabled="isBusy"
          type="button"
          @click="onOpenConfigurator"
        >
          <i aria-hidden="true" class="fa-solid fa-sliders" />
          Configurator
        </button>
        <button
          v-if="editor.showGeneratedConfigTab.value"
          class="dui-btn dui-btn-sm"
          :disabled="isBusy"
          type="button"
          @click="onOpenWfrpConfig"
        >
          <i aria-hidden="true" class="fa-solid fa-code" />
          WFRP Config
        </button>
      </section>

      <label v-if="editor.definitions.value.length" class="dui-input dui-input-sm app:w-full">
        <i aria-hidden="true" class="fa-solid fa-magnifying-glass" />
        <input v-model="filter" type="search" placeholder="Find a species by name or key" />
      </label>

      <div v-if="isBusy && !editor.isLoaded.value" class="dui-alert" role="status">
        <i aria-hidden="true" class="fa-solid fa-spinner fa-spin" />
        <span>Loading installed and custom species…</span>
      </div>

      <div
        v-else-if="editor.definitions.value.length === 0"
        class="dui-alert dui-alert-info"
        role="status"
      >
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>No species were found. Create a custom species to begin.</span>
      </div>

      <div v-else-if="visibleDefinitions.length === 0" class="dui-alert" role="status">
        <i aria-hidden="true" class="fa-solid fa-magnifying-glass" />
        <span>No species match “{{ filter.trim() }}”. Clear the search to see all species.</span>
      </div>

      <div
        v-else
        class="app:max-w-full app:overflow-x-auto app:rounded-box app:border app:border-base-300 app:bg-base-100"
      >
        <table class="dui-table dui-table-sm">
          <caption class="app:sr-only">
            Installed and custom WFRP species
          </caption>
          <thead>
            <tr>
              <th scope="col">Species</th>
              <th scope="col">Source</th>
              <th scope="col">Subspecies</th>
              <th scope="col">Validation</th>
              <th scope="col"><span class="app:sr-only">Open</span></th>
            </tr>
          </thead>
          <tbody>
            <tr
              v-for="entry in visibleDefinitions"
              :key="`${entry.definition.origin}-${entry.definition.key}-${entry.index}`"
            >
              <th scope="row">
                <button
                  class="dui-btn dui-btn-link dui-btn-sm app:h-auto app:justify-start app:p-0 app:text-left"
                  type="button"
                  @click="onOpenSpecies(entry.index)"
                >
                  <span>
                    <span class="app:block">{{ definitionLabel(entry.definition) }}</span>
                    <code class="app:block app:text-xs app:font-normal app:text-base-content/60">{{
                      entry.definition.key || "Key not set"
                    }}</code>
                  </span>
                </button>
              </th>
              <td>
                <span class="dui-badge dui-badge-ghost dui-badge-sm">
                  <i
                    aria-hidden="true"
                    :class="
                      entry.definition.origin === 'runtime' ? 'fa-solid fa-lock' : 'fa-solid fa-pen'
                    "
                  />
                  {{ sourceLabel(entry.definition) }}
                </span>
              </td>
              <td>{{ entry.definition.subspecies?.length ?? 0 }}</td>
              <td>
                <button
                  v-if="definitionIndicator(entry.index)"
                  class="dui-btn dui-btn-outline dui-btn-xs"
                  :class="
                    definitionIndicator(entry.index)?.severity === 'error'
                      ? 'dui-btn-error'
                      : 'dui-btn-warning'
                  "
                  :title="validationIndicatorLabel(definitionIndicator(entry.index))"
                  type="button"
                  @click="onOpenIssues(entry.index)"
                >
                  <i
                    aria-hidden="true"
                    :class="
                      definitionIndicator(entry.index)?.severity === 'error'
                        ? 'fa-solid fa-circle-exclamation'
                        : 'fa-solid fa-triangle-exclamation'
                    "
                  />
                  {{ definitionIndicator(entry.index)?.count }}
                  <span class="app:sr-only">{{
                    validationIndicatorLabel(definitionIndicator(entry.index))
                  }}</span>
                </button>
                <span v-else class="dui-badge dui-badge-success dui-badge-sm">
                  <i aria-hidden="true" class="fa-solid fa-check" />
                  Good
                </span>
              </td>
              <td>
                <button
                  class="dui-btn dui-btn-sm"
                  :disabled="isBusy"
                  type="button"
                  @click="onOpenSpecies(entry.index)"
                >
                  {{ entry.definition.origin === "runtime" ? "Inspect" : "Edit" }}
                  <i aria-hidden="true" class="fa-solid fa-arrow-up-right-from-square" />
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </main>
  </section>
</template>
