import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

import { careers, species, subspecies } from "./shared";

export function createBeastfiendDefinition(): SpeciesBuilderDefinition {
  return species("beastfiend", "Beastfiend", [30, 20, 30, 30, 30, 25, 15, 20, 35, 10], {
    age: "3d10+10",
    careerTable: careers("Hunter", "Mystic", "Outlaw", "Warrior", "Zealot"),
    extra: 1,
    fate: 1,
    height: { die: "1d10", feet: 6, inches: 0 },
    includeInExtraSpecies: true,
    movement: 4,
    resilience: 2,
    skills: [
      "Athletics",
      "Cool",
      "Endurance",
      "Intimidate",
      "Language (Dark Tongue)",
      "Lore (Chaos)",
      "Melee (Basic)",
      "Outdoor Survival",
      "Perception",
      "Pray",
      "Track",
    ],
    subspecies: createBeastfiendSubspecies(),
    talents: ["Hardy", "Night Vision", "Resistance (Chaos)", "Ruinous Mark"],
    traits: ["Armour (1)", "Corruption (Minor)", "Mutation", "Painless"],
  });
}

function createBeastfiendSubspecies() {
  return [
    subspecies("bloodborn", "Bloodborn Beastfiend", [45, 15, 35, 30, 40, 25, 15, 15, 45, 5], {
      careerTable: careers("Pit Fighter", "Soldier", "Warrior", "Zealot"),
      skillsAdded: ["Intimidate", "Melee (Two-Handed)"],
      talentsAdded: ["Berserk Charge", "Frenzy", "Furious Assault", "Very Strong"],
      traitsAdded: ["Armour (3)", "Champion", "Horns (4)"],
    }),
    subspecies("delightborn", "Delightborn Beastfiend", [40, 30, 25, 20, 45, 45, 25, 25, 40, 30], {
      careerTable: careers("Assassin", "Duellist", "Entertainer", "Spy", "Warrior"),
      skillsAdded: ["Charm", "Dodge", "Entertain (Any)", "Intuition"],
      talentsAdded: ["Attractive", "Combat Reflexes", "Lightning Reflexes", "Step Aside"],
      traitsAdded: ["Champion", "Distracting"],
    }),
    subspecies("plagueborn", "Plagueborn Beastfiend", [25, 15, 25, 45, 20, 15, 15, 20, 40, 10], {
      careerTable: careers("Flagellant", "Herbalist", "Physician", "Warrior", "Zealot"),
      skillsAdded: ["Heal", "Lore (Disease)", "Lore (Poison)"],
      talentsAdded: ["Hardy", "Resistance (Disease)", "Resistance (Poison)", "Very Resilient"],
      traitsAdded: ["Disease (Packer's Pox)", "Infected", "Regenerate"],
    }),
    subspecies("changeborn", "Changeborn Beastfiend", [25, 30, 20, 25, 35, 30, 25, 35, 40, 15], {
      careerTable: careers("Alchemist", "Mystic", "Scholar", "Witch", "Wizard"),
      skillsAdded: ["Channelling (Dhar)", "Language (Magick)", "Lore (Magic)"],
      talentsAdded: ["Aethyric Attunement", "Petty Magic", "Second Sight", "Savvy"],
      traitsAdded: ["Breath (Warpfire)", "Spellcaster (Tzeentch)"],
    }),
  ];
}

