<script setup lang="ts">
import { computed } from "vue";

import type {
  SpeciesBuilderExampleSpeciesOption,
  SpeciesBuilderSpeciesTableDraft,
} from "../../../../../types/species-builder/species-builder";

const emit = defineEmits<{
  generateAllExampleSpecies: [];
  generateExampleSpecies: [id: string];
  updateAutoRegisterSpeciesTable: [value: boolean];
  updateCorrectExistingWfrpSpecies: [value: boolean];
  updateSelectedExampleSpeciesId: [id: string];
  updateShowGeneratedConfigTab: [value: boolean];
}>();

const props = defineProps<{
  autoRegisterSpeciesTable: boolean;
  correctExistingWfrpSpecies: boolean;
  exampleSpeciesOptions: SpeciesBuilderExampleSpeciesOption[];
  isDisabled: boolean;
  selectedExampleSpeciesId: string;
  showGeneratedConfigTab: boolean;
  speciesTable: SpeciesBuilderSpeciesTableDraft;
}>();

const selectedExampleSpecies = computed(() =>
  props.exampleSpeciesOptions.find((option) => option.id === props.selectedExampleSpeciesId),
);

function checkboxValue(event: Event): boolean {
  return event.target instanceof HTMLInputElement && event.target.checked;
}

function selectValue(event: Event): string {
  return event.target instanceof HTMLSelectElement ? event.target.value : "";
}

function speciesTableStatus(): string {
  if (props.speciesTable.ownership === "external") {
    return props.speciesTable.isRegistered ? "External table active" : "External table";
  }

  if (props.speciesTable.ownership === "managed") {
    return props.speciesTable.isRegistered ? "Registered" : "Not registered";
  }

  return "No managed table yet";
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <header>
        <h2 class="dui-card-title">Species Builder Settings</h2>
        <p>Control optional tools and add sample definitions to the current draft.</p>
      </header>

      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">Generated config</legend>
        <p class="dui-fieldset-label">
          Expose the read-only WFRP config generated from the current draft.
        </p>
        <label class="dui-label">
          <input
            class="dui-checkbox"
            :checked="showGeneratedConfigTab"
            :disabled="isDisabled"
            type="checkbox"
            @change="emit('updateShowGeneratedConfigTab', checkboxValue($event))"
          />
          <span>Show WFRP config tab</span>
        </label>
      </fieldset>

      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">Installed WFRP species</legend>
        <label
          class="dui-label app:w-full app:items-start app:justify-between app:gap-3 app:whitespace-normal"
        >
          <span>
            <strong>Correct known species data</strong>
            <span class="app:block app:text-base-content/70">
              Fills known missing details and repairs malformed references in installed WFRP
              content. Badger, Cat, Crow, Fox, Owl, and Stoat remain Animal Familiar subspecies
              instead of also appearing as top-level species. Takes effect after reloading Foundry.
            </span>
          </span>
          <input
            class="dui-toggle dui-toggle-primary app:shrink-0"
            :checked="correctExistingWfrpSpecies"
            :disabled="isDisabled"
            type="checkbox"
            @change="emit('updateCorrectExistingWfrpSpecies', checkboxValue($event))"
          />
        </label>
      </fieldset>

      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">
          World Species Table
          <span class="dui-badge dui-badge-sm">{{ speciesTableStatus() }}</span>
        </legend>
        <label
          class="dui-label app:w-full app:items-start app:justify-between app:gap-3 app:whitespace-normal"
        >
          <span>
            <strong>Register managed table on save</strong>
            <span class="app:block app:text-base-content/70">
              When enabled, Save Changes points WFRP’s world Species table setting to the
              Builder-managed table. Turning this off stops future registration; it does not change
              or delete the table currently selected by WFRP.
            </span>
          </span>
          <input
            class="dui-toggle dui-toggle-primary app:shrink-0"
            :checked="autoRegisterSpeciesTable"
            :disabled="isDisabled"
            type="checkbox"
            @change="emit('updateAutoRegisterSpeciesTable', checkboxValue($event))"
          />
        </label>
      </fieldset>

      <div class="dui-divider">Sample Definitions</div>
      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">Example Species</legend>
        <p class="dui-fieldset-label">
          Add preconfigured species definitions matching sample species Journal material.
        </p>
        <label class="dui-label" for="species-builder-example">Sample definition</label>
        <select
          id="species-builder-example"
          class="dui-select"
          :disabled="isDisabled"
          :value="selectedExampleSpeciesId"
          @change="emit('updateSelectedExampleSpeciesId', selectValue($event))"
        >
          <option v-for="option in exampleSpeciesOptions" :key="option.id" :value="option.id">
            {{ option.label }}
          </option>
        </select>
        <p class="dui-fieldset-label">
          {{ selectedExampleSpecies?.description }}
        </p>
        <div class="dui-join">
          <button
            class="dui-btn dui-join-item"
            :disabled="isDisabled || !selectedExampleSpeciesId"
            type="button"
            @click="emit('generateExampleSpecies', selectedExampleSpeciesId)"
          >
            <i aria-hidden="true" class="fa-solid fa-scroll" />
            Generate Selected
          </button>
          <button
            class="dui-btn dui-join-item"
            :disabled="isDisabled || exampleSpeciesOptions.length === 0"
            type="button"
            @click="emit('generateAllExampleSpecies')"
          >
            <i aria-hidden="true" class="fa-solid fa-layer-group" />
            Generate All
          </button>
        </div>
      </fieldset>
    </div>
  </section>
</template>
