import type { NpcAdvancementDraftEntry } from "../../types/npc-builder";

import { getAmbiguousSkillGrant, normalizeSkillGrantText } from "./skill-specialization";

export interface MetadataRequestState {
  inFlightNames: string[];
  successfulNames: string[];
}

export function createMetadataRequestState(): MetadataRequestState {
  return {
    inFlightNames: [],
    successfulNames: [],
  };
}

export function getUnresolvedSkillCharacteristicNames(
  advancements: NpcAdvancementDraftEntry[],
): string[] {
  const names = new Set<string>();

  for (const advancement of advancements) {
    if (
      advancement.kind === "skill" &&
      !advancement.characteristicKey &&
      !getAmbiguousSkillGrant(advancement.name)
    ) {
      names.add(advancement.name);
    }
  }

  return [...names];
}

export function getUnresolvedTalentMaximumNames(
  advancements: NpcAdvancementDraftEntry[],
): string[] {
  const names = new Set<string>();

  for (const advancement of advancements) {
    if (advancement.kind === "talent" && !advancement.talentMaximumKey) {
      names.add(advancement.name);
    }
  }

  return [...names];
}

export function getMetadataNamesToRequest(names: string[], state: MetadataRequestState): string[] {
  const unavailableNames = new Set([...state.inFlightNames, ...state.successfulNames]);

  return names.filter((name) => {
    const normalizedName = normalizeSkillGrantText(name);

    if (unavailableNames.has(normalizedName)) {
      return false;
    }

    unavailableNames.add(normalizedName);
    return true;
  });
}

export function startMetadataRequest(
  state: MetadataRequestState,
  names: string[],
): MetadataRequestState {
  return {
    ...state,
    inFlightNames: uniqueNormalizedNames([...state.inFlightNames, ...names]),
  };
}

export function completeMetadataRequest(
  state: MetadataRequestState,
  names: string[],
): MetadataRequestState {
  const completedNames = new Set(uniqueNormalizedNames(names));

  return {
    inFlightNames: state.inFlightNames.filter((name) => !completedNames.has(name)),
    successfulNames: uniqueNormalizedNames([...state.successfulNames, ...completedNames]),
  };
}

export function failMetadataRequest(
  state: MetadataRequestState,
  names: string[],
): MetadataRequestState {
  const failedNames = new Set(uniqueNormalizedNames(names));

  return {
    ...state,
    inFlightNames: state.inFlightNames.filter((name) => !failedNames.has(name)),
  };
}

function uniqueNormalizedNames(names: Iterable<string>): string[] {
  return [...new Set([...names].map(normalizeSkillGrantText).filter(Boolean))];
}
