import type {
  SpeciesItemRecord,
  SpeciesItemReference,
  SpeciesItemTableData,
} from "../../../../types/species-builder/species-item";
import { careerTableFromDocument } from "../runtime-species/career-table";

export function resolveSpeciesItemTables(record: SpeciesItemRecord): SpeciesItemTableData {
  const data: SpeciesItemTableData = {};
  const talentTable = resolveTable(record.system.tables.talents);
  if (talentTable) {
    const key = talentTable.getFlag("wfrp4e", "key");
    if (typeof key !== "string" || !key.trim())
      throw new Error(`${record.name}: the random Talent table needs a WFRP table key.`);
    data.randomTalentKey = key;
  }
  const careerTable = resolveTable(record.system.tables.career);
  if (careerTable) {
    const definition = careerTableFromDocument(careerTable);
    if (!definition)
      throw new Error(`${record.name}: the referenced Career table has no usable rows.`);
    data.careerTable = definition;
  }
  return data;
}

function resolveTable(reference: SpeciesItemReference): FoundryRollTableDocument | undefined {
  if (!reference.uuid && !reference.id) return undefined;
  const table = game.tables?.contents.find((entry) =>
    reference.uuid ? entry.uuid === reference.uuid : entry.id === reference.id,
  );
  if (!table)
    throw new Error(
      `Import the referenced RollTable ${reference.name || reference.uuid || reference.id} into the world and relink it.`,
    );
  return table;
}
