<script setup lang="ts">
import { computed } from "vue";

const props = defineProps<{
  chargenErrorCount: number;
  chargenWarningCount: number;
  loadError: string;
  message: string;
  validationMessage: string;
}>();

const emit = defineEmits<{
  reviewIssues: [];
}>();

const chargenIssueCount = computed(() => props.chargenErrorCount + props.chargenWarningCount);
</script>

<template>
  <section aria-live="polite">
    <p v-if="loadError" role="alert" class="dui-alert dui-alert-error app:m-0">
      <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
      <span>{{ loadError }}</span>
    </p>
    <div
      v-else-if="chargenIssueCount > 0"
      role="alert"
      class="dui-alert app:m-0"
      :class="chargenErrorCount > 0 ? 'dui-alert-error' : 'dui-alert-warning'"
    >
      <i
        aria-hidden="true"
        class="fa-solid"
        :class="chargenErrorCount > 0 ? 'fa-circle-exclamation' : 'fa-triangle-exclamation'"
      />
      <span class="app:flex-1">
        <template v-if="chargenErrorCount > 0">
          {{ chargenErrorCount }} character-creation
          {{ chargenErrorCount === 1 ? "error affects" : "errors affect" }} species that can be
          rolled or selected.
        </template>
        <template v-if="chargenWarningCount > 0">
          {{ chargenWarningCount }} validation
          {{ chargenWarningCount === 1 ? "warning identifies" : "warnings identify" }} playable
          incomplete or inactive species data.
        </template>
      </span>
      <button class="dui-btn dui-btn-sm" type="button" @click="emit('reviewIssues')">
        Review {{ chargenIssueCount === 1 ? "Issue" : "Issues" }}
        <i aria-hidden="true" class="fa-solid fa-chevron-right" />
      </button>
    </div>
    <p v-else-if="validationMessage" role="alert" class="dui-alert dui-alert-error app:m-0">
      <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
      <span>{{ validationMessage }}</span>
    </p>
    <p v-else-if="message" class="dui-alert dui-alert-info app:m-0">
      <i aria-hidden="true" class="fa-solid fa-circle-info" />
      <span>{{ message }}</span>
    </p>
  </section>
</template>
