import type { NpcBaseTraitSummary } from "../../../../../types/npc-builder";

import { isTraitDisabled, isTraitSourceDisabled, readTraitConfig } from "./config";

export function readActorTraits(actor: FoundryActorDocument): NpcBaseTraitSummary[] {
  return (
    actor.items?.contents
      .filter((item) => item.type === "trait" && !isTraitDisabled(item))
      .map(toBaseTraitSummary) ?? []
  );
}

export function readActorOptionalTraits(actor: FoundryActorDocument): NpcBaseTraitSummary[] {
  return (
    actor.items?.contents
      .filter((item) => item.type === "trait" && isTraitDisabled(item))
      .map(toBaseTraitSummary) ?? []
  );
}

export function removeDisabledTraitSources(actorData: FoundryActorSource): void {
  if (!Array.isArray(actorData["items"])) {
    return;
  }

  actorData["items"] = actorData["items"].filter((item: unknown) => {
    if (typeof item !== "object" || item === null) {
      return true;
    }

    const itemSource = item as FoundryItemSource;

    return itemSource["type"] !== "trait" || !isTraitSourceDisabled(itemSource);
  });
}

function toBaseTraitSummary(item: FoundryItemDocument): NpcBaseTraitSummary {
  return {
    config: readTraitConfig(item),
    img: item.img ?? "",
    name: item.name,
    uuid: item.uuid,
  };
}
