import type { SpeciesBuilderValidationCatalog } from "../../../../types/species-builder/validation";
import type { RuntimeTableReadiness } from "./table-results";

import {
  isCharacteristicFormula,
  isSensibleDiceFormula,
} from "../../../../functions/species-builder/validation/shared";
import { isRecord } from "../../../../shared/object-readers";
import { WfrpCharacteristicKey } from "../../../../types/wfrp4e/characteristics";
import {
  addRuntimeCareerReplacementProblems,
  addRuntimeGrantProblems,
  type RuntimeGrantValidationContext,
  type RuntimeGrantValues,
} from "./runtime-grants";

export interface RuntimeSpeciesReadinessContext extends RuntimeGrantValidationContext {
  careerGroups: ReadonlySet<string>;
  validateCareerTable: (
    speciesKey: string,
    subspeciesKey: string | undefined,
    configuredColumn: unknown,
  ) => RuntimeTableReadiness;
}

const CHARACTERISTIC_KEYS = Object.values(WfrpCharacteristicKey);
const REQUIRED_STATS = [
  ["speciesMovement", "movement"],
  ["speciesFate", "fate"],
  ["speciesRes", "resilience"],
  ["speciesExtra", "extra points"],
] as const;

export function loadRuntimeSpecies(
  config: Record<string, unknown>,
  context: RuntimeSpeciesReadinessContext,
  persistedDefinitionKeys: string[] = [],
): SpeciesBuilderValidationCatalog["runtimeSpecies"] {
  const species = isRecord(config["species"]) ? config["species"] : {};
  const excludedKeys = new Set(persistedDefinitionKeys.map((key) => key.trim()).filter(Boolean));

  return Object.entries(species)
    .filter(([key]) => !excludedKeys.has(key))
    .map(([key, configuredName]) => {
      const name =
        typeof configuredName === "string" && configuredName.trim() ? configuredName.trim() : key;
      const problems = runtimeSpeciesProblems(config, key, configuredName, context);
      const result: SpeciesBuilderValidationCatalog["runtimeSpecies"][number] = {
        key,
        name,
        readyForCharacterCreation: problems.errors.length === 0,
      };

      if (problems.errors.length > 0) {
        result.errorReasons = problems.errors;
        result.reason = summarizeProblems(problems.errors);
      }
      if (problems.requiresWorldTableImport) {
        result.requiresWorldTableImport = true;
      }
      if (problems.warnings.length > 0) {
        result.warningReason = summarizeProblems(problems.warnings);
        result.warningReasons = problems.warnings;
      }

      return result;
    })
    .sort((left, right) => left.name.localeCompare(right.name));
}

function runtimeSpeciesProblems(
  config: Record<string, unknown>,
  key: string,
  configuredName: unknown,
  context: RuntimeSpeciesReadinessContext,
): RuntimeSpeciesProblems {
  const problems: RuntimeSpeciesProblems = {
    errors: [],
    requiresWorldTableImport: false,
    warnings: [],
  };

  if (!key.trim()) {
    problems.errors.push("species key is missing");
  }
  if (typeof configuredName !== "string" || !configuredName.trim()) {
    problems.errors.push("display name is missing");
  }

  const baseGrants = baseGrantValues(config, key);
  addRuntimeGrantProblems(baseGrants, context, problems.errors, problems.warnings);

  const baseCharacteristics = recordEntry(config, "speciesCharacteristics", key);
  addCharacteristicProblems(baseCharacteristics, problems.errors);
  addStatProblems(baseStatValues(config, key), problems.errors);
  addAgeHeightProblems(config, key, problems.warnings);
  addRuntimeCareerReplacementProblems(
    recordEntry(config, "speciesCareerReplacements", key),
    context.careerGroups,
    problems.warnings,
  );
  problems.requiresWorldTableImport ||= addCareerTableProblem(
    context.validateCareerTable(key, undefined, undefined),
    problems.errors,
  );
  addSubspeciesProblems(config, key, baseCharacteristics, baseGrants, context, problems);

  return problems;
}

interface RuntimeSpeciesProblems {
  errors: string[];
  requiresWorldTableImport: boolean;
  warnings: string[];
}

function summarizeProblems(problems: string[]): string {
  const first = problems[0] ?? "runtime configuration is incomplete";
  const additionalCount = problems.length - 1;

  return additionalCount > 0 ? `${first} (+${additionalCount} more)` : first;
}

function addSubspeciesProblems(
  config: Record<string, unknown>,
  speciesKey: string,
  baseCharacteristics: unknown,
  baseGrants: RuntimeGrantValues,
  context: RuntimeSpeciesReadinessContext,
  problems: RuntimeSpeciesProblems,
): void {
  const allSubspecies = config["subspecies"];
  const configured = isRecord(allSubspecies) ? allSubspecies[speciesKey] : undefined;

  if (!configured) {
    return;
  }
  if (!isRecord(configured)) {
    problems.errors.push("subspecies configuration is not an object");
    return;
  }

  for (const [subspeciesKey, source] of Object.entries(configured)) {
    const childProblems: RuntimeSpeciesProblems = {
      errors: [],
      requiresWorldTableImport: false,
      warnings: [],
    };

    if (!isRecord(source)) {
      problems.errors.push(`subspecies ${subspeciesKey} is not an object`);
      continue;
    }
    if (typeof source["name"] !== "string" || !source["name"].trim()) {
      childProblems.warnings.push("display name is missing");
    }

    addCharacteristicProblems(
      source["characteristics"] || baseCharacteristics,
      childProblems.errors,
    );
    addStatProblems(subspeciesStatValues(config, speciesKey, source), childProblems.errors);
    addRuntimeGrantProblems(
      effectiveSubspeciesGrants(source, baseGrants),
      context,
      childProblems.errors,
      childProblems.warnings,
    );
    addRuntimeCareerReplacementProblems(
      recordEntry(config, "speciesCareerReplacements", `${speciesKey}-${subspeciesKey}`),
      context.careerGroups,
      childProblems.warnings,
    );
    childProblems.requiresWorldTableImport ||= addCareerTableProblem(
      context.validateCareerTable(speciesKey, subspeciesKey, source["careerTable"]),
      childProblems.errors,
    );

    problems.errors.push(
      ...childProblems.errors.map((problem) => `subspecies ${subspeciesKey}: ${problem}`),
    );
    problems.warnings.push(
      ...childProblems.warnings.map((problem) => `subspecies ${subspeciesKey}: ${problem}`),
    );
    problems.requiresWorldTableImport ||= childProblems.requiresWorldTableImport;
  }
}

function addCharacteristicProblems(source: unknown, problems: string[]): void {
  if (!isRecord(source)) {
    problems.push("characteristic formulas are missing");
    return;
  }

  const invalid = CHARACTERISTIC_KEYS.filter((key) => {
    const formula = source[key];

    return typeof formula !== "string" || !isCharacteristicFormula(formula);
  });

  if (invalid.length > 0) {
    problems.push(`characteristic formulas are invalid or missing for ${invalid.join(", ")}`);
  }
}

function addStatProblems(values: Record<string, unknown>, problems: string[]): void {
  for (const [label, value] of Object.entries(values)) {
    if (!Number.isInteger(value) || Number(value) < 0) {
      problems.push(`${label} is missing or not a non-negative whole number`);
    }
  }
}

function addAgeHeightProblems(
  config: Record<string, unknown>,
  key: string,
  problems: string[],
): void {
  const age = recordEntry(config, "speciesAge", key);

  if (typeof age !== "string" || !isSensibleDiceFormula(age, false)) {
    problems.push("age formula is missing or invalid");
  }

  const height = recordEntry(config, "speciesHeight", key);

  if (
    !isRecord(height) ||
    typeof height["die"] !== "string" ||
    !isSensibleDiceFormula(height["die"], true) ||
    !isNonNegativeInteger(height["feet"]) ||
    !isNonNegativeInteger(height["inches"])
  ) {
    problems.push("height needs a valid die formula and non-negative whole feet and inches");
  }
}

function addCareerTableProblem(readiness: RuntimeTableReadiness, problems: string[]): boolean {
  if (!readiness.readyForCharacterCreation) {
    problems.push(readiness.reason ?? "Career table is not ready");
  }

  return Boolean(readiness.requiresWorldTableImport);
}

function baseGrantValues(config: Record<string, unknown>, key: string): RuntimeGrantValues {
  return {
    randomTalents: recordEntry(config, "speciesRandomTalents", key),
    skills: recordEntry(config, "speciesSkills", key),
    talentReplacement: recordEntry(config, "speciesTalentReplacement", key) || {},
    talents: recordEntry(config, "speciesTalents", key),
    traits: recordEntry(config, "speciesTraits", key) || [],
  };
}

function effectiveSubspeciesGrants(
  source: Record<string, unknown>,
  base: RuntimeGrantValues,
): RuntimeGrantValues {
  return {
    randomTalents: source["randomTalents"] || base.randomTalents,
    skills: source["skills"] || base.skills,
    talentReplacement: source["talentReplacement"] || base.talentReplacement,
    talents: source["talents"] || base.talents,
    traits: source["speciesTraits"] || base.traits,
  };
}

function baseStatValues(config: Record<string, unknown>, key: string): Record<string, unknown> {
  return Object.fromEntries(
    REQUIRED_STATS.map(([field, label]) => [label, recordEntry(config, field, key)]),
  );
}

function subspeciesStatValues(
  config: Record<string, unknown>,
  key: string,
  source: Record<string, unknown>,
): Record<string, unknown> {
  return Object.fromEntries(
    REQUIRED_STATS.map(([field, label]) => [
      label,
      source[subspeciesStatField(field)] ?? recordEntry(config, field, key),
    ]),
  );
}

function subspeciesStatField(field: (typeof REQUIRED_STATS)[number][0]): string {
  return field === "speciesRes" ? "resilience" : field.replace("species", "").toLowerCase();
}

function recordEntry(config: Record<string, unknown>, field: string, key: string): unknown {
  const record = config[field];

  return isRecord(record) ? record[key] : undefined;
}

function isNonNegativeInteger(value: unknown): boolean {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}
