import { isRecord } from "../../../shared/object-readers";
import { WfrpCharacteristicKey } from "../../../types/wfrp4e/characteristics";

export type ValueValidator = (value: unknown, path: string) => string;

type RecordValidator = (value: Record<string, unknown>, path: string) => string;

const CHARACTERISTIC_KEYS = new Set<string>(Object.values(WfrpCharacteristicKey));

export function validateCharacteristics(value: unknown, path: string): string {
  if (!isRecord(value)) {
    return `${path} must be a JSON object.`;
  }

  for (const [key, formula] of Object.entries(value)) {
    if (!CHARACTERISTIC_KEYS.has(key)) {
      return `${path}.${key} is not a supported WFRP characteristic.`;
    }

    const error = validateNonEmptyString(formula, `${path}.${key}`, "string formula");

    if (error) {
      return error;
    }
  }

  return "";
}

export function validateHeight(value: unknown, path: string): string {
  return validateObject(value, path, ["die", "feet", "inches"], (record, recordPath) =>
    validateFields(
      record,
      recordPath,
      [
        ["die", validateNonEmptyString],
        ["feet", validateFiniteNumber],
        ["inches", validateFiniteNumber],
      ],
      new Set(),
    ),
  );
}

export function validateWoundFormula(value: unknown, path: string): string {
  return validateObject(value, path, ["formula"], (record, recordPath) =>
    validateFields(
      record,
      recordPath,
      [
        [
          "formula",
          (entry, entryPath) => validateNonEmptyString(entry, entryPath, "string formula"),
        ],
      ],
      new Set(["formula"]),
    ),
  );
}

export function validateCareerTable(value: unknown, path: string): string {
  return validateObject(value, path, ["rows"], (record, recordPath) =>
    validateFields(record, recordPath, [["rows", validateCareerTableRows]], new Set(["rows"])),
  );
}

function validateCareerTableRows(value: unknown, path: string): string {
  return validateArray(value, path, (entry, entryPath) => validateLinkedItem(entry, entryPath));
}

export function validateLinkedItems(value: unknown, path: string): string {
  return validateArray(value, path, (entry, entryPath) => validateLinkedItem(entry, entryPath));
}

function validateLinkedItem(value: unknown, path: string): string {
  return validateObject(value, path, ["name"], (record, recordPath) =>
    validateFields(record, recordPath, [["name", validateNonEmptyString]], new Set(["name"])),
  );
}

export function validateTalentGrants(value: unknown, path: string): string {
  return validateArray(value, path, (entry, entryPath) =>
    validateObject(entry, entryPath, ["choices"], (record, recordPath) =>
      validateFields(
        record,
        recordPath,
        [["choices", (choices, choicesPath) => validateLinkedItemList(choices, choicesPath, true)]],
        new Set(["choices"]),
      ),
    ),
  );
}

export function validateTalentReplacementRows(value: unknown, path: string): string {
  return validateArray(value, path, (entry, entryPath) =>
    validateObject(entry, entryPath, ["replacement", "rolled"], (record, recordPath) =>
      validateFields(
        record,
        recordPath,
        [
          ["replacement", validateLinkedItem],
          ["rolled", validateLinkedItem],
        ],
        new Set(["replacement", "rolled"]),
      ),
    ),
  );
}

export function validateCareerReplacementRows(value: unknown, path: string): string {
  return validateArray(value, path, (entry, entryPath) =>
    validateObject(entry, entryPath, ["replacements", "rolled"], (record, recordPath) =>
      validateFields(
        record,
        recordPath,
        [
          ["replacements", (rows, rowsPath) => validateLinkedItemList(rows, rowsPath, true)],
          ["rolled", validateLinkedItem],
        ],
        new Set(["replacements", "rolled"]),
      ),
    ),
  );
}

function validateLinkedItemList(value: unknown, path: string, requireEntry: boolean): string {
  if (requireEntry && Array.isArray(value) && value.length === 0) {
    return `${path} must contain at least one entry.`;
  }

  return validateLinkedItems(value, path);
}

export function validateStringArray(value: unknown, path: string): string {
  return validateArray(value, path, validateNonEmptyString);
}

export function validateStringRecord(value: unknown, path: string): string {
  return validateKeyedRecord(value, path, validateNonEmptyString);
}

export function validateNumberRecord(value: unknown, path: string): string {
  return validateKeyedRecord(value, path, validateFiniteNumber);
}

export function validateStringArrayRecord(value: unknown, path: string): string {
  return validateKeyedRecord(value, path, validateStringArray);
}

function validateKeyedRecord(value: unknown, path: string, validator: ValueValidator): string {
  if (!isRecord(value)) {
    return `${path} must be a JSON object.`;
  }

  for (const [key, entry] of Object.entries(value)) {
    if (!key.trim()) {
      return `${path} must not contain an empty key.`;
    }

    const error = validator(entry, `${path}[${JSON.stringify(key)}]`);

    if (error) {
      return error;
    }
  }

  return "";
}

export function validateFields(
  value: Record<string, unknown>,
  path: string,
  validators: Array<[string, ValueValidator]>,
  requiredFields: Set<string>,
): string {
  for (const [field, validator] of validators) {
    if (!(field in value)) {
      if (requiredFields.has(field)) {
        return `${path}.${field} is required.`;
      }

      continue;
    }

    const error = validator(value[field], `${path}.${field}`);

    if (error) {
      return error;
    }
  }

  return "";
}

export function validateObject(
  value: unknown,
  path: string,
  allowedFields: readonly string[],
  validator: RecordValidator,
): string {
  if (!isRecord(value)) {
    return `${path} must be a JSON object.`;
  }

  const unsupportedField = Object.keys(value).find((field) => !allowedFields.includes(field));

  if (unsupportedField) {
    return `${path}.${unsupportedField} is not supported by species definition export version 1.`;
  }

  return validator(value, path);
}

export function validateArray(value: unknown, path: string, validator: ValueValidator): string {
  if (!Array.isArray(value)) {
    return `${path} must be an array.`;
  }

  for (const [index, entry] of value.entries()) {
    const error = validator(entry, `${path}[${index}]`);

    if (error) {
      return error;
    }
  }

  return "";
}

export function validateNonEmptyString(
  value: unknown,
  path: string,
  label = "non-empty string",
): string {
  return typeof value === "string" && value.trim() ? "" : `${path} must be a ${label}.`;
}

export function validateFiniteNumber(value: unknown, path: string): string {
  return typeof value === "number" && Number.isFinite(value)
    ? ""
    : `${path} must be a finite number.`;
}

export function validateBoolean(value: unknown, path: string): string {
  return typeof value === "boolean" ? "" : `${path} must be a boolean.`;
}
