<script setup lang="ts">
import { computed, onMounted, ref } from "vue";

import type { SpeciesBuilderBridge } from "../../../types/species-builder/species-builder";
import type { SpeciesBuilderEditorTab } from "../species-builder/tabs/species/pages/editor/editor-tabs";
import type { RandomTableTab } from "../species-builder/tabs/species/pages/editor/tabs/tables/random-table-events";

import { createDefinitionsWithGeneratedKeys } from "../../../functions/species-builder/editor/draft";
import { useSpeciesBuilderEditor } from "../../../state/species-builder/editor";
import DeleteConfirmationSubView from "../species-builder/components/DeleteConfirmationSubView.vue";
import SpeciesBuilderStatus from "../species-builder/components/SpeciesBuilderStatus.vue";
import SpeciesDefinitionPortability from "../species-builder/components/SpeciesDefinitionPortability.vue";
import UnsafeSaveConfirmationSubView from "../species-builder/components/UnsafeSaveConfirmationSubView.vue";
import { useSpeciesBuilderDeletion } from "../species-builder/components/deletion";
import { useSpeciesBuilderUnsafeSave } from "../species-builder/components/unsafe-save";
import {
  summarizeValidationIssues,
  validationIndicatorLabel,
} from "../species-builder/components/validation/validation-presentation";
import { createSpeciesBuilderEditorPageEvents } from "../species-builder/tabs/species/pages/editor/editor-page-events";
import SpeciesBuilderDetailPanel from "../species-builder/tabs/species/pages/editor/SpeciesBuilderDetailPanel.vue";
import SubspeciesSection from "../species-builder/tabs/species/pages/editor/tabs/subspecies/SubspeciesSection.vue";
import SpeciesSuiteHeader from "./components/SpeciesSuiteHeader.vue";

const props = defineProps<{
  bridge: SpeciesBuilderBridge;
  definitionIndex: number;
  initialTab: SpeciesBuilderEditorTab;
  initialTableTab: RandomTableTab;
  onOpenDirectory: () => void;
  onOpenIssues: () => void;
  onOpenSubspecies: (subspeciesIndex: number) => void;
  onOpenWoundFormula: () => void;
  onSettingsSaved?: () => void;
}>();
const editor = useSpeciesBuilderEditor(props.bridge, { onSettingsSaved: props.onSettingsSaved });
const activeTab = ref(props.initialTab);
const activeTableTab = ref(props.initialTableTab);
const portabilityHost = ref<HTMLElement>();
const unsafeSave = useSpeciesBuilderUnsafeSave(editor);
const deletion = useSpeciesBuilderDeletion({
  deleteDefinition: editor.deleteSelectedDefinition,
  deleteSubspecies: editor.deleteSubspecies,
  selectedDefinition: editor.selectedDefinition,
});
const definition = computed(() => editor.definitions.value[props.definitionIndex]);
const issues = computed(() =>
  editor.validationIssues.value.filter((issue) => issue.definitionIndex === props.definitionIndex),
);
const errorCount = computed(
  () => issues.value.filter((issue) => issue.severity === "error").length,
);
const warningCount = computed(() => issues.value.length - errorCount.value);
const isBusy = computed(() => editor.isLoading.value || editor.isSaving.value);
const definitionKeys = computed(() =>
  createDefinitionsWithGeneratedKeys(editor.definitions.value).map(({ key }) => key),
);
const subspeciesIndicators = computed(() =>
  (definition.value?.subspecies ?? []).map((_, index) =>
    summarizeValidationIssues(
      issues.value.filter(
        (issue) => issue.scope === "subspecies" && issue.subspeciesIndex === index,
      ),
    ),
  ),
);
const definitionTabs: Array<{ icon: string; label: string; tab: SpeciesBuilderEditorTab }> = [
  { icon: "fa-solid fa-id-card", label: "Details", tab: "details" },
  { icon: "fa-solid fa-chart-simple", label: "Attributes", tab: "attributes" },
  { icon: "fa-solid fa-heart-pulse", label: "Wounds", tab: "wounds" },
  { icon: "fa-solid fa-book-open", label: "Skills", tab: "skills" },
  { icon: "fa-solid fa-star", label: "Talents", tab: "talents" },
  { icon: "fa-solid fa-dna", label: "Traits", tab: "traits" },
  { icon: "fa-solid fa-code-branch", label: "Subspecies", tab: "subspecies" },
  { icon: "fa-solid fa-table", label: "Tables", tab: "tables" },
];
const tableTabs: Array<{ label: string; tab: RandomTableTab }> = [
  { label: "Careers", tab: "careerTable" },
  { label: "Random Talents", tab: "randomTalents" },
  { label: "Talent Swaps", tab: "talentReplacement" },
  { label: "Career Swaps", tab: "careerReplacement" },
];
const tableSections = new Set(tableTabs.map(({ tab }) => tab));
const editorEvents = {
  ...createSpeciesBuilderEditorPageEvents(editor, {
    requestDeleteSubspecies: deletion.requestDeleteSubspecies,
    requestSave: unsafeSave.requestSave,
  }),
  reviewIssues: props.onOpenIssues,
};

onMounted(async () => {
  await editor.ensureSettingsLoaded();
  editor.selectDefinition(props.definitionIndex);
});

function name(): string {
  return definition.value?.name.trim() || definition.value?.key.trim() || "Untitled Species";
}

function tabIndicator(tab: SpeciesBuilderEditorTab) {
  return summarizeValidationIssues(
    issues.value.filter((issue) => {
      if (tab === "subspecies") return issue.scope === "subspecies";
      if (tab === "tables") return tableSections.has(issue.section as RandomTableTab);
      return issue.scope === "definition" && issue.section === tab;
    }),
  );
}

function tableIndicator(tab: RandomTableTab) {
  return summarizeValidationIssues(issues.value.filter((issue) => issue.section === tab));
}

function addSubspecies(): void {
  const nextIndex = definition.value?.subspecies?.length ?? 0;
  editor.addSubspecies();
  props.onOpenSubspecies(nextIndex);
}

function confirmDelete(): void {
  deletion.confirmPendingDelete();
  props.onOpenDirectory();
}
</script>

<template>
  <section class="app:flex app:min-h-full app:flex-col" :aria-busy="isBusy">
    <SpeciesSuiteHeader
      :can-save="editor.canSave.value"
      :context="definition?.origin === 'runtime' ? 'Installed species' : 'Custom species'"
      :error-count="errorCount"
      :has-unsaved-changes="editor.hasUnsavedChanges.value"
      :is-busy="isBusy"
      :title="name()"
      :warning-count="warningCount"
      @open-issues="onOpenIssues"
      @open-parent="onOpenDirectory"
      @reload="editor.loadSettings"
      @save="unsafeSave.requestSave"
    />

    <DeleteConfirmationSubView
      :message="deletion.pendingDelete.value?.message"
      @close="deletion.pendingDelete.value = null"
      @confirm="confirmDelete"
    />
    <UnsafeSaveConfirmationSubView
      :is-open="unsafeSave.isConfirmationOpen.value"
      @close="unsafeSave.closeConfirmation"
      @confirm="unsafeSave.confirmSave"
    />
    <div ref="portabilityHost" />

    <main class="app:flex app:flex-1 app:flex-col app:gap-3 app:p-3">
      <SpeciesBuilderStatus
        :chargen-error-count="errorCount"
        :chargen-warning-count="warningCount"
        :load-error="editor.loadError.value || editor.saveError.value"
        :message="editor.message.value"
        validation-message=""
        @review-issues="onOpenIssues"
      />

      <div class="app:flex app:flex-wrap app:items-center app:gap-2">
        <SpeciesDefinitionPortability
          button-class="dui-btn dui-btn-sm"
          :definition="definition?.origin === 'custom' ? definition : undefined"
          :dialog-host="portabilityHost"
          :existing-keys="definitionKeys"
          :is-disabled="isBusy"
          :is-import-only="definition?.origin !== 'custom'"
          @import-definition="editor.addDefinition"
        />
        <button
          v-if="definition?.origin === 'custom'"
          class="dui-btn dui-btn-sm"
          :disabled="isBusy"
          type="button"
          @click="editor.duplicateSelectedDefinition"
        >
          <i aria-hidden="true" class="fa-solid fa-copy" />
          Duplicate
        </button>
        <button
          v-if="definition?.origin === 'custom'"
          class="dui-btn dui-btn-error dui-btn-outline dui-btn-sm"
          :disabled="isBusy"
          type="button"
          @click="deletion.requestDeleteDefinition"
        >
          <i aria-hidden="true" class="fa-solid fa-trash" />
          Delete
        </button>
      </div>

      <div class="app:max-w-full app:overflow-x-auto">
        <div
          aria-label="Species editor sections"
          class="dui-tabs dui-tabs-box app:min-w-max"
          role="tablist"
        >
          <button
            v-for="entry in definitionTabs"
            :key="entry.tab"
            class="dui-tab"
            :class="{ 'dui-tab-active': activeTab === entry.tab }"
            :disabled="isBusy"
            role="tab"
            type="button"
            @click="activeTab = entry.tab"
          >
            <i aria-hidden="true" :class="entry.icon" />
            {{ entry.label }}
            <span
              v-if="tabIndicator(entry.tab)"
              class="dui-status dui-status-sm"
              :class="
                tabIndicator(entry.tab)?.severity === 'error'
                  ? 'dui-status-error'
                  : 'dui-status-warning'
              "
              :title="validationIndicatorLabel(tabIndicator(entry.tab))"
            >
              <span class="app:sr-only">
                {{ validationIndicatorLabel(tabIndicator(entry.tab)) }}
              </span>
            </span>
          </button>
        </div>
      </div>

      <div
        v-if="activeTab === 'tables'"
        class="dui-tabs dui-tabs-border"
        role="tablist"
        aria-label="Species table sections"
      >
        <button
          v-for="entry in tableTabs"
          :key="entry.tab"
          class="dui-tab"
          :class="{ 'dui-tab-active': activeTableTab === entry.tab }"
          role="tab"
          type="button"
          @click="activeTableTab = entry.tab"
        >
          {{ entry.label }}
          <span
            v-if="tableIndicator(entry.tab)"
            class="dui-status dui-status-sm"
            :class="
              tableIndicator(entry.tab)?.severity === 'error'
                ? 'dui-status-error'
                : 'dui-status-warning'
            "
          />
        </button>
      </div>

      <div v-if="activeTab === 'wounds'" class="app:flex app:justify-end">
        <button class="dui-btn dui-btn-sm" type="button" @click="onOpenWoundFormula">
          <i aria-hidden="true" class="fa-solid fa-wand-magic-sparkles" />
          Open Formula Builder
        </button>
      </div>

      <SubspeciesSection
        v-if="definition && activeTab === 'subspecies'"
        :definition="definition"
        :is-loading="editor.isLoading.value"
        :is-saving="editor.isSaving.value"
        :validation-indicators="subspeciesIndicators"
        @add-subspecies="addSubspecies"
        @edit-subspecies="onOpenSubspecies"
      />
      <SpeciesBuilderDetailPanel
        v-else-if="definition"
        :active-editor-tab="activeTab"
        :active-table-tab="activeTableTab"
        :definition="definition"
        :is-loading="editor.isLoading.value"
        :is-saving="editor.isSaving.value"
        :issues="issues"
        :random-talent-sources="editor.randomTalentSources.value"
        v-on="editorEvents"
      />
      <div v-else class="dui-alert dui-alert-warning" role="status">
        <i aria-hidden="true" class="fa-solid fa-triangle-exclamation" />
        <span>This species is no longer available. Return to the Species List.</span>
      </div>
    </main>
  </section>
</template>
