<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from "vue";

import type {
  ActorPortraitApplyTarget,
  ActorPortraitGalleryBridge,
  ActorPortraitGalleryContext,
  PortraitCandidate,
} from "../../../types/portrait-gallery";

import { createPortraitFilterState } from "../../../state/portrait-gallery/filters";
import { createPortraitGalleryWorkflow } from "../../../state/portrait-gallery/workflow";
import PortraitGallery from "../../components/portrait-gallery/PortraitGallery.vue";

const props = defineProps<{
  bridge: ActorPortraitGalleryBridge;
  context: ActorPortraitGalleryContext;
}>();

const errorMessage = ref("");
const successMessage = ref("");
const applyingTarget = ref<ActorPortraitApplyTarget | null>(null);
const applyMenu = ref<HTMLElement | null>(null);
const selectedPortraitPath = ref(props.context.selectedPortraitPath);
const appliedPortraitPath = ref(props.context.currentPortraitPath);
const appliedTokenPath = ref(props.context.currentTokenPath);
let applyMenuOpenTimer: number | null = null;
let applyMenuCloseTimer: number | null = null;
const filterState = createPortraitFilterState();
const workflow = createPortraitGalleryWorkflow({
  activePortraitPath: selectedPortraitPath,
  baseSearchTerms: ref([...props.context.searchTerms]),
  errorMessage,
  excludeFullyTransparentImages: ref(props.context.excludeFullyTransparentImages),
  excludedReferenceImagePaths: ref([...props.context.excludedReferenceImagePaths]),
  filterState,
  hasSubject: ref(true),
  immediateCandidates: ref([...props.context.immediateCandidates]),
  includeCompendiumAssets: ref(props.context.includeCompendiumAssets),
  includeFilePickerAssets: ref(props.context.includeFilePickerAssets),
  pinnedPortraitPath: selectedPortraitPath,
  priorityFolderPaths: ref([...props.context.priorityFolderPaths]),
  provider: props.bridge,
  searchErrorMessage: "The portrait gallery could not finish searching Foundry images.",
  selectPortrait,
});
const canApplyPortrait = computed(
  () =>
    Boolean(selectedPortraitPath.value) && selectedPortraitPath.value !== appliedPortraitPath.value,
);
const canApplyToken = computed(
  () =>
    Boolean(selectedPortraitPath.value) && selectedPortraitPath.value !== appliedTokenPath.value,
);
const canApplyToBoth = computed(() => canApplyPortrait.value || canApplyToken.value);
const selectedLabel = computed(
  () => workflow.selectedPortraitCandidate.value?.label ?? "Selected portrait",
);

watch(selectedPortraitPath, () => {
  errorMessage.value = "";
  successMessage.value = "";
});

onBeforeUnmount(clearApplyMenuTimers);

function selectPortrait(candidate: PortraitCandidate): void {
  selectedPortraitPath.value = candidate.img;
}

async function applyPortrait(target: ActorPortraitApplyTarget): Promise<void> {
  if (!selectedPortraitPath.value || applyingTarget.value || !canApplyTarget(target)) {
    return;
  }

  closeApplyMenu();
  applyingTarget.value = target;
  errorMessage.value = "";
  successMessage.value = "";

  try {
    await props.bridge.applyActorPortrait(
      props.context.actorUuid,
      selectedPortraitPath.value,
      target,
    );

    if (target !== "token") {
      appliedPortraitPath.value = selectedPortraitPath.value;
    }

    if (target !== "portrait") {
      appliedTokenPath.value = selectedPortraitPath.value;
    }

    successMessage.value = getApplySuccessMessage(target);
  } catch (error) {
    errorMessage.value =
      error instanceof Error ? error.message : "The selected image could not be applied.";
  } finally {
    applyingTarget.value = null;
  }
}

function applyFromMenu(target: Exclude<ActorPortraitApplyTarget, "both">): void {
  closeApplyMenu();
  void applyPortrait(target);
}

function canApplyTarget(target: ActorPortraitApplyTarget): boolean {
  if (target === "portrait") {
    return canApplyPortrait.value;
  }

  if (target === "token") {
    return canApplyToken.value;
  }

  return canApplyToBoth.value;
}

function getApplySuccessMessage(target: ActorPortraitApplyTarget): string {
  if (target === "portrait") {
    return "Portrait updated.";
  }

  if (target === "token") {
    return "Prototype token updated.";
  }

  return "Portrait and token updated.";
}

function scheduleApplyMenuOpen(): void {
  clearApplyMenuTimers();
  applyMenuOpenTimer = window.setTimeout(openApplyMenu, 650);
}

function scheduleApplyMenuClose(): void {
  clearApplyMenuTimers();
  applyMenuCloseTimer = window.setTimeout(closeApplyMenu, 180);
}

function openApplyMenu(): void {
  clearApplyMenuTimers();

  if (applyMenu.value && !applyMenu.value.matches(":popover-open")) {
    applyMenu.value.showPopover();
  }
}

function closeApplyMenu(): void {
  clearApplyMenuTimers();

  if (applyMenu.value?.matches(":popover-open")) {
    applyMenu.value.hidePopover();
  }
}

function clearApplyMenuTimers(): void {
  if (applyMenuOpenTimer !== null) {
    window.clearTimeout(applyMenuOpenTimer);
    applyMenuOpenTimer = null;
  }

  if (applyMenuCloseTimer !== null) {
    window.clearTimeout(applyMenuCloseTimer);
    applyMenuCloseTimer = null;
  }
}
</script>

<template>
  <section class="app:flex app:h-full app:min-h-0 app:flex-col">
    <header
      class="dui-navbar app:sticky app:top-0 app:z-10 app:min-h-0 app:gap-2 app:bg-base-100 app:px-3 app:py-2 app:shadow-sm"
    >
      <div class="dui-navbar-start app:min-w-0 app:flex-1 app:gap-2">
        <h1 class="app:m-0 app:truncate app:text-lg app:font-semibold">{{ context.actorName }}</h1>
        <span v-if="successMessage" class="dui-badge dui-badge-success dui-badge-sm">
          {{ successMessage }}
        </span>
      </div>
      <div class="dui-navbar-end app:w-auto app:gap-2">
        <img
          v-if="selectedPortraitPath"
          :alt="`${selectedLabel} preview`"
          class="app:aspect-square app:w-10 app:rounded-box app:bg-base-300 app:object-cover"
          height="40"
          :src="selectedPortraitPath"
          width="40"
        />
        <div
          class="dui-join"
          @focusin="openApplyMenu"
          @focusout="scheduleApplyMenuClose"
          @pointerenter="scheduleApplyMenuOpen"
          @pointerleave="scheduleApplyMenuClose"
        >
          <button
            class="dui-btn dui-btn-primary dui-btn-sm dui-join-item"
            :disabled="!canApplyToBoth || Boolean(applyingTarget)"
            type="button"
            @click="applyPortrait('both')"
          >
            <i
              v-if="applyingTarget === 'both'"
              aria-hidden="true"
              class="fa-solid fa-spinner fa-spin"
            />
            <i v-else aria-hidden="true" class="fa-solid fa-layer-group" />
            {{ applyingTarget === "both" ? "Applying..." : "Apply to Both" }}
          </button>
          <button
            aria-label="More apply options"
            class="dui-btn dui-btn-primary dui-btn-sm dui-btn-square dui-join-item"
            :disabled="!selectedPortraitPath || Boolean(applyingTarget)"
            popovertarget="actor-portrait-apply-menu"
            style="anchor-name: --actor-portrait-apply-menu"
            type="button"
          >
            <i aria-hidden="true" class="fa-solid fa-chevron-down" />
          </button>
        </div>
        <ul
          id="actor-portrait-apply-menu"
          ref="applyMenu"
          class="dui-dropdown dui-dropdown-end dui-menu dui-menu-sm app:z-20 app:mt-1 app:w-52 app:rounded-box app:bg-base-100 app:p-2 app:shadow-lg"
          popover
          style="position-anchor: --actor-portrait-apply-menu"
          @focusin="openApplyMenu"
          @focusout="scheduleApplyMenuClose"
          @pointerenter="openApplyMenu"
          @pointerleave="scheduleApplyMenuClose"
        >
          <li>
            <button
              :disabled="!canApplyPortrait || Boolean(applyingTarget)"
              type="button"
              @click="applyFromMenu('portrait')"
            >
              <i aria-hidden="true" class="fa-solid fa-image" />
              Portrait only
            </button>
          </li>
          <li>
            <button
              :disabled="!canApplyToken || Boolean(applyingTarget)"
              type="button"
              @click="applyFromMenu('token')"
            >
              <i aria-hidden="true" class="fa-solid fa-circle" />
              Token only
            </button>
          </li>
        </ul>
      </div>
    </header>

    <main class="app:min-h-0 app:flex-1 app:p-2">
      <PortraitGallery
        class="app:h-full"
        empty-message="No portrait or token images are available for this Actor yet."
        :error-message="errorMessage"
        fill-height
        :is-loading="workflow.isLoadingPortraitCandidates.value"
        :options="workflow.portraitCandidates.value"
        :progress-label="workflow.portraitSearchProgressLabel.value"
        :progress-value="workflow.portraitSearchProgressValue.value"
        :search-terms="workflow.portraitSearchTerms.value"
        :selected-option-key="workflow.selectedPortraitCandidateKey.value"
        :tags="workflow.portraitFilterTags.value"
        @create-search-term="workflow.addPortraitSearchTerm"
        @filter-tag-section-change="workflow.setPortraitFilterTagSection"
        @select-portrait="workflow.selectPortrait"
      />
    </main>
  </section>
</template>
