import type { ComputedRef } from "vue";

import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderItemReference,
} from "../../types/species-builder/species-builder";

import {
  addLinkedItemRow,
  addTalentGrant as addTalentGrantToDefinition,
  addTalentGrantChoice,
  appendDroppedGrant,
  applySubspeciesTalentDrop,
  removeLinkedItemRow,
  removeTalentGrantChoice,
  removeTalentGrantRow,
  renameLinkedItemRow,
  renameTalentGrantChoice,
  setLinkedItemRowReference,
  setTalentGrantChoiceReference,
} from "../../functions/species-builder/editor/linked-definition";
import type {
  SpeciesBuilderLinkedListField,
  SpeciesBuilderTalentGrantKind,
} from "../../functions/species-builder/editor/linked-grants";

interface DefinitionLinkedGrantActions {
  updateSelectedDefinition: (
    update: (definition: SpeciesBuilderDefinition) => SpeciesBuilderDefinition,
  ) => void;
}

interface LinkedGrantSubspeciesActions {
  canEditSubspecies: (index: number) => boolean;
  updateDefinitionForSubspecies: (
    index: number,
    update: (definition: SpeciesBuilderDefinition) => SpeciesBuilderDefinition,
  ) => void;
}

interface LinkedGrantActionsContext {
  definitionActions: DefinitionLinkedGrantActions;
  resolveDroppedItem: (
    field: "skill" | "talent" | "trait",
    data: string,
  ) => Promise<SpeciesBuilderItemReference>;
  selectedDefinition: ComputedRef<SpeciesBuilderDefinition | undefined>;
  subspeciesActions: LinkedGrantSubspeciesActions;
}

const arrayFieldItemTypes = {
  skills: "skill",
  talents: "talent",
  traits: "trait",
} as const;

export function createSpeciesBuilderLinkedGrantActions(context: LinkedGrantActionsContext) {
  async function appendArrayFieldDrop(
    field: "skills" | "talents" | "traits",
    data: string,
  ): Promise<void> {
    const item = await context.resolveDroppedItem(arrayFieldItemTypes[field], data);

    updateDefinition((definition) => appendDroppedGrant(definition, field, item));
  }

  async function setLinkedItemDrop(
    field: SpeciesBuilderLinkedListField,
    index: number,
    data: string,
  ): Promise<void> {
    const item = await context.resolveDroppedItem(arrayFieldItemTypes[field], data);

    updateDefinition((definition) => setLinkedItemRowReference(definition, field, index, item));
  }

  async function setTalentChoiceDrop(
    grantIndex: number,
    choiceIndex: number,
    data: string,
  ): Promise<void> {
    const item = await context.resolveDroppedItem("talent", data);

    updateDefinition((definition) =>
      setTalentGrantChoiceReference(definition, grantIndex, choiceIndex, item),
    );
  }

  async function appendSubspeciesTalentDrop(index: number, data: string): Promise<void> {
    if (!context.subspeciesActions.canEditSubspecies(index)) {
      return;
    }

    const item = await context.resolveDroppedItem("talent", data);

    context.subspeciesActions.updateDefinitionForSubspecies(index, (definition) =>
      applySubspeciesTalentDrop(definition, index, item),
    );
  }

  function addLinkedItem(field: SpeciesBuilderLinkedListField): void {
    updateDefinition((definition) => addLinkedItemRow(definition, field));
  }

  function renameLinkedItem(
    field: SpeciesBuilderLinkedListField,
    index: number,
    name: string,
  ): void {
    updateDefinition((definition) => renameLinkedItemRow(definition, field, index, name));
  }

  function removeLinkedItem(field: SpeciesBuilderLinkedListField, index: number): void {
    updateDefinition((definition) => removeLinkedItemRow(definition, field, index));
  }

  function addTalentGrant(kind: SpeciesBuilderTalentGrantKind): void {
    updateDefinition((definition) => addTalentGrantToDefinition(definition, kind));
  }

  function addTalentChoice(grantIndex: number): void {
    updateDefinition((definition) => addTalentGrantChoice(definition, grantIndex));
  }

  function renameTalentChoice(grantIndex: number, choiceIndex: number, name: string): void {
    updateDefinition((definition) =>
      renameTalentGrantChoice(definition, grantIndex, choiceIndex, name),
    );
  }

  function removeTalentGrant(grantIndex: number): void {
    updateDefinition((definition) => removeTalentGrantRow(definition, grantIndex));
  }

  function removeTalentChoice(grantIndex: number, choiceIndex: number): void {
    updateDefinition((definition) => removeTalentGrantChoice(definition, grantIndex, choiceIndex));
  }

  function updateDefinition(
    update: (definition: SpeciesBuilderDefinition) => SpeciesBuilderDefinition,
  ): void {
    context.definitionActions.updateSelectedDefinition(update);
  }

  return {
    addLinkedItem,
    addTalentChoice,
    addTalentGrant,
    appendArrayFieldDrop,
    appendSubspeciesTalentDrop,
    removeLinkedItem,
    removeTalentChoice,
    removeTalentGrant,
    renameLinkedItem,
    renameTalentChoice,
    setLinkedItemDrop,
    setTalentChoiceDrop,
  };
}
