<script setup lang="ts">
import { nextTick, ref, watch } from "vue";

import { useDialogFocusReturn } from "./dialog-focus";

const props = defineProps<{
  isOpen: boolean;
}>();

const emit = defineEmits<{
  close: [];
  confirm: [];
}>();

const dialog = ref<HTMLDialogElement>();
const dialogFocus = useDialogFocusReturn();

function closeDialog(): void {
  dialog.value?.close();
}

function handleDialogClosed(): void {
  if (props.isOpen) {
    emit("close");
  }

  dialogFocus.restore();
}

watch(
  () => props.isOpen,
  async (isOpen) => {
    if (isOpen) {
      dialogFocus.capture();
      await nextTick();

      if (props.isOpen && !dialog.value?.open) {
        dialog.value?.showModal();
      }
    } else if (dialog.value?.open) {
      dialog.value.close();
    }
  },
  { flush: "post", immediate: true },
);
</script>

<template>
  <dialog
    ref="dialog"
    class="dui-modal"
    aria-describedby="species-builder-unsafe-save-message"
    aria-labelledby="species-builder-unsafe-save-title"
    @close="handleDialogClosed"
    @keydown.esc.stop.prevent="closeDialog"
    @keyup.esc.stop
  >
    <section v-if="isOpen" class="dui-modal-box">
      <h2 id="species-builder-unsafe-save-title">Save Despite Character-Creation Errors?</h2>
      <div
        id="species-builder-unsafe-save-message"
        class="dui-alert dui-alert-warning app:mt-3"
        role="alert"
      >
        <i aria-hidden="true" class="fa-solid fa-triangle-exclamation" />
        <span>
          These changes contain errors for species that can be rolled or selected. Saving is unsafe
          and may cause species selection or character creation to fail.
        </span>
      </div>
      <div class="dui-modal-action">
        <button class="dui-btn dui-btn-warning" type="button" @click="emit('confirm')">
          Save Anyway
        </button>
        <button autofocus class="dui-btn" type="button" @click="closeDialog">Cancel</button>
      </div>
    </section>
    <form class="dui-modal-backdrop" method="dialog">
      <button aria-label="Cancel unsafe save" type="submit">Close</button>
    </form>
  </dialog>
</template>
