<script setup lang="ts">
import type {
  PortraitCandidate,
  PortraitFilterSection,
  PortraitFilterTag,
} from "../../../types/portrait-gallery";

import {
  getPortraitCandidateAriaLabel,
  getPortraitCandidateSourceLabel,
  getPortraitCandidateTitle,
} from "../../../functions/portrait-gallery";
import PortraitFilterTags from "./PortraitFilterTags.vue";

const props = withDefaults(
  defineProps<{
    emptyMessage?: string;
    errorMessage?: string;
    fillHeight?: boolean;
    isLoading: boolean;
    options: PortraitCandidate[];
    progressLabel: string;
    progressValue: number;
    searchTerms: string[];
    selectedOptionKey: string;
    tags: PortraitFilterTag[];
  }>(),
  {
    emptyMessage: "No portraits are available yet.",
    errorMessage: "",
    fillHeight: false,
  },
);

const emit = defineEmits<{
  createSearchTerm: [value: string];
  filterTagSectionChange: [tag: PortraitFilterTag, section: PortraitFilterSection];
  selectPortrait: [candidate: PortraitCandidate];
}>();
</script>

<template>
  <section :aria-busy="isLoading" class="app:flex app:min-h-0 app:flex-col app:gap-2">
    <PortraitFilterTags
      :result-count="options.length"
      :tags="tags"
      @create-search-term="emit('createSearchTerm', $event)"
      @filter-tag-section-change="(tag, section) => emit('filterTagSectionChange', tag, section)"
    />

    <div v-if="errorMessage" class="dui-alert dui-alert-error app:min-h-0 app:py-2" role="alert">
      <i aria-hidden="true" class="fa-solid fa-triangle-exclamation" />
      <span>{{ errorMessage }}</span>
    </div>

    <div
      v-if="isLoading"
      aria-live="polite"
      class="dui-alert dui-alert-info app:min-h-0 app:gap-2 app:py-2"
      role="status"
    >
      <i aria-hidden="true" class="fa-solid fa-spinner fa-spin" />
      <div class="app:flex app:min-w-0 app:flex-1 app:items-center app:gap-2">
        <small class="app:shrink-0">{{ progressLabel || "Updating results..." }}</small>
        <progress
          aria-label="Portrait search progress"
          class="dui-progress app:min-w-24 app:flex-1"
          :value="progressValue"
          max="100"
        />
      </div>
    </div>
    <p
      v-else-if="searchTerms.length && !options.length"
      class="dui-alert dui-alert-warning app:min-h-0 app:py-2"
    >
      No portraits match the current filter tags.
    </p>

    <div
      v-if="options.length"
      class="app:pr-1"
      :class="
        fillHeight
          ? 'app:min-h-48 app:flex-1 app:overflow-y-auto'
          : 'app:max-h-[30rem] app:overflow-y-auto'
      "
    >
      <ul
        class="dui-list app:m-0 app:grid app:grid-cols-[repeat(auto-fill,minmax(8.5rem,1fr))] app:gap-3 app:p-0"
      >
        <li v-for="(candidate, index) in options" :key="candidate.key">
          <button
            :aria-label="getPortraitCandidateAriaLabel(candidate)"
            :aria-pressed="candidate.key === selectedOptionKey"
            class="dui-btn app:h-auto app:min-h-0 app:w-full app:flex-col app:items-stretch app:justify-start app:gap-2 app:overflow-hidden app:whitespace-normal app:p-2 app:text-left"
            :class="
              candidate.key === selectedOptionKey
                ? 'dui-btn-active dui-btn-outline'
                : 'dui-btn-ghost'
            "
            :title="getPortraitCandidateTitle(candidate)"
            type="button"
            @click="emit('selectPortrait', candidate)"
          >
            <img
              alt=""
              class="app:aspect-square app:w-full app:rounded-box app:bg-base-300 app:object-cover"
              height="192"
              :loading="index < 6 ? 'eager' : 'lazy'"
              :src="candidate.img"
              width="192"
            />
            <span class="app:flex app:flex-wrap app:items-center app:justify-between app:gap-1">
              <small>{{ getPortraitCandidateSourceLabel(candidate) }}</small>
              <span
                v-if="candidate.key === selectedOptionKey"
                class="dui-badge dui-badge-success dui-badge-sm"
              >
                Selected
              </span>
            </span>
            <strong class="app:text-sm">{{ candidate.label }}</strong>
          </button>
        </li>
      </ul>
    </div>
    <p v-else-if="!isLoading" class="dui-alert">{{ props.emptyMessage }}</p>
  </section>
</template>
