<script setup lang="ts">
import { computed, ref, useId } from "vue";

import {
  appendCareerTableRow,
  buildCareerTableCopySources,
  copyCareerTableRows,
  removeCareerTableRow,
  updateCareerTableRowAtIndex,
} from "../../../../../../../../../../../functions/species-builder/editor/career-table-rows";
import type { SpeciesBuilderCareerTableRow } from "../../../../../../../../../../../types/species-builder/species-builder";

import { useSpeciesBuilderStore } from "../../../../../../../../../../../state/species-builder";
import DocumentDrop from "../../../../../../../../../../components/DocumentDrop.vue";
import TableEditorHeader from "../../components/TableEditorHeader.vue";
import {
  hasValidationErrors,
  issuesForField,
  issuesForRow,
  issuesWithoutRow,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../../../../validation-presentation";

const props = defineProps<{
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  rows: SpeciesBuilderCareerTableRow[] | undefined;
}>();

const emit = defineEmits<{
  dropCareer: [rowIndex: number, data: string];
  dropJournal: [rowIndex: number, data: string];
  updateRows: [rows: SpeciesBuilderCareerTableRow[]];
}>();
const editor = useSpeciesBuilderStore();
const selectedCopySourceId = ref("");
const copySourceSelectId = useId();
const copySources = computed(() => buildCareerTableCopySources(editor.definitions, props.rows));
const selectedCopySource = computed(() =>
  copySources.value.find((source) => source.id === selectedCopySourceId.value),
);

function careerRows(): SpeciesBuilderCareerTableRow[] {
  return props.rows ?? [];
}

function addRow(): void {
  emit("updateRows", appendCareerTableRow(props.rows));
}

function copySelectedTable(): void {
  if (selectedCopySource.value) {
    emit("updateRows", copyCareerTableRows(selectedCopySource.value.rows));
  }
}

function removeRow(index: number): void {
  emit("updateRows", removeCareerTableRow(props.rows, index));
}

function updateRow(index: number, update: Partial<SpeciesBuilderCareerTableRow>): void {
  emit("updateRows", updateCareerTableRowAtIndex(props.rows, index, update));
}

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement ? event.target.value : "";
}

function nameIssues(rowIndex: number): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, "name", rowIndex);
}

function nameMessages(rowIndex: number): string[] {
  return uniqueIssueMessages(nameIssues(rowIndex));
}

function sectionMessages(): string[] {
  return uniqueIssueMessages(issuesWithoutRow(props.issues));
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <TableEditorHeader
        action-label="Add Career"
        action-title="Add a Career table row"
        :count="careerRows().length"
        description="Career group names are required for the normal character-generation roll. Journal links provide the result link; blank links use the generated fallback journal."
        :is-disabled="isDisabled"
        title="Career Table"
        @add="addRow"
      />
      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">Copy Existing Table</legend>
        <label class="dui-label" :for="copySourceSelectId">Source species</label>
        <div class="dui-join app:w-full">
          <select
            :id="copySourceSelectId"
            v-model="selectedCopySourceId"
            aria-label="Source species"
            class="dui-select dui-select-sm dui-join-item app:min-w-0 app:flex-1"
            :disabled="isDisabled || copySources.length === 0"
          >
            <option value="">
              {{ copySources.length > 0 ? "Select a species…" : "No species tables available" }}
            </option>
            <option v-for="source in copySources" :key="source.id" :value="source.id">
              {{ source.label }} ({{ source.rows.length }})
            </option>
          </select>
          <button
            class="dui-btn dui-btn-sm dui-join-item"
            :disabled="isDisabled || !selectedCopySource"
            title="Replace the current rows with a copy of the selected species table"
            type="button"
            @click="copySelectedTable"
          >
            <i aria-hidden="true" class="fa-solid fa-copy" />
            Copy Table
          </button>
        </div>
        <p class="dui-label">Copies its rows, ranges, weights, and journal links.</p>
      </fieldset>
      <div
        v-if="sectionMessages().length"
        class="dui-alert"
        :class="validationClass(issuesWithoutRow(issues), 'dui-alert-error', 'dui-alert-warning')"
        role="alert"
      >
        <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
        <div>
          <p v-for="message in sectionMessages()" :key="message" class="app:m-0 app:text-xs">
            {{ message }}
          </p>
        </div>
      </div>
      <ul v-if="careerRows().length > 0" class="dui-list">
        <li
          v-for="(row, index) in careerRows()"
          :key="index"
          class="dui-list-row"
          :class="
            validationClass(
              issuesForRow(issues, index),
              'app:border app:border-error',
              'app:border app:border-warning',
            )
          "
        >
          <span class="dui-badge dui-badge-ghost">{{ index + 1 }}</span>
          <div class="dui-list-col-grow">
            <div
              v-if="row.sourceRange || row.sourceWeight"
              class="app:flex app:flex-wrap app:gap-1"
            >
              <span v-if="row.sourceRange" class="dui-badge dui-badge-outline dui-badge-sm">
                Range {{ row.sourceRange[0] }}–{{ row.sourceRange[1] }}
              </span>
              <span v-if="row.sourceWeight" class="dui-badge dui-badge-ghost dui-badge-sm">
                Weight {{ row.sourceWeight }}
              </span>
            </div>
            <DocumentDrop
              description="Drop a WFRP Career item."
              :disabled="isDisabled"
              manual-entry-trigger="none"
              title="Career"
              variant="bare"
              @drop-data="(data) => emit('dropCareer', index, data)"
            >
              <fieldset class="dui-fieldset">
                <legend class="dui-fieldset-legend">Career Group</legend>
                <input
                  :aria-describedby="
                    nameIssues(index).length ? `career-table-name-${index}-errors` : undefined
                  "
                  :aria-invalid="hasValidationErrors(nameIssues(index)) || undefined"
                  class="dui-input"
                  :class="
                    validationClass(nameIssues(index), 'dui-input-error', 'dui-input-warning')
                  "
                  :disabled="isDisabled"
                  :value="row.name"
                  placeholder="Pit Fighter"
                  type="text"
                  @input="updateRow(index, { name: inputValue($event) })"
                />
                <div v-if="nameMessages(index).length" :id="`career-table-name-${index}-errors`">
                  <p
                    v-for="message in nameMessages(index)"
                    :key="message"
                    class="app:m-0 app:text-xs"
                    :class="
                      validationClass(nameIssues(index), 'app:text-error', 'app:text-warning')
                    "
                  >
                    {{ message }}
                  </p>
                </div>
              </fieldset>
            </DocumentDrop>
            <DocumentDrop
              description="Drop a Journal Entry or Journal Page."
              :disabled="isDisabled"
              manual-entry-trigger="button"
              title="Journal Link"
              variant="bare"
              @drop-data="(data) => emit('dropJournal', index, data)"
            >
              <fieldset class="dui-fieldset">
                <legend class="dui-fieldset-legend">Journal Entry/Page UUID</legend>
                <input
                  class="dui-input"
                  :disabled="isDisabled"
                  :value="row.journalUuid ?? ''"
                  placeholder="Compendium.package.journals.entry.JournalEntryPage.page"
                  type="text"
                  @input="updateRow(index, { journalUuid: inputValue($event) })"
                />
              </fieldset>
            </DocumentDrop>
          </div>
          <button
            class="dui-btn dui-btn-error dui-btn-sm"
            :disabled="isDisabled"
            type="button"
            @click="removeRow(index)"
          >
            <i aria-hidden="true" class="fa-solid fa-trash" />
            Remove
          </button>
        </li>
      </ul>
      <div v-else class="dui-alert" role="status">
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>No Career rows yet.</span>
      </div>
    </div>
  </section>
</template>
