import type { SpeciesBuilderDefinition } from "../../../../../types/species-builder/species-builder";
import type {
  SpeciesBuilderValidationIssue,
  SpeciesBuilderValidationSection,
} from "../../../../../types/species-builder/validation";
import type { SpeciesBuilderActiveTab } from "../../tabs/active-tab";
import type { SpeciesBuilderEditorTab } from "../../tabs/species/pages/editor/editor-tabs";
import type { SubspeciesEditorTab } from "../../tabs/species/pages/editor/tabs/subspecies/subspecies-editor-tabs";
import type { RandomTableTab } from "../../tabs/species/pages/editor/tabs/tables/random-table-events";

import { validationIssueSeverity } from "./validation-presentation";

export type SpeciesBuilderValidationDestination =
  | { kind: "project"; tab: Extract<SpeciesBuilderActiveTab, "species" | "species-table"> }
  | {
      definitionIndex: number;
      editorTab: SpeciesBuilderEditorTab;
      kind: "definition";
      tableTab?: RandomTableTab;
    }
  | {
      definitionIndex: number;
      kind: "subspecies";
      subspeciesIndex: number;
      subspeciesTab: SubspeciesEditorTab;
      tableTab?: RandomTableTab;
    };

export interface SpeciesBuilderValidationNavigationRequest {
  destination: SpeciesBuilderValidationDestination;
  sequence: number;
}

export interface SpeciesBuilderValidationSummaryItem {
  context: string;
  issue: SpeciesBuilderValidationIssue;
}

const TABLE_SECTIONS: RandomTableTab[] = [
  "careerTable",
  "randomTalents",
  "talentReplacement",
  "careerReplacement",
];

const SECTION_LABELS: Record<SpeciesBuilderValidationSection, string> = {
  "attributes": "Attributes",
  "careerReplacement": "Career Replacement",
  "careerTable": "Career Table",
  "details": "Details",
  "randomTalents": "Random Talents",
  "skills": "Skills",
  "species-table": "Species Table",
  "subspecies": "Subspecies",
  "talentReplacement": "Talent Replacement",
  "talents": "Talents",
  "traits": "Traits",
  "wounds": "Wounds",
};

export function validationIssuesForSummary(
  issues: SpeciesBuilderValidationIssue[],
): SpeciesBuilderValidationIssue[] {
  return issues.filter(
    (issue) =>
      issue.code !== "species-table-definition-not-ready" &&
      issue.code !== "species-table-runtime-not-ready",
  );
}

export function getSpeciesBuilderValidationDestination(
  issue: SpeciesBuilderValidationIssue,
): SpeciesBuilderValidationDestination {
  if (issue.scope === "species-table") {
    return { kind: "project", tab: "species-table" };
  }

  if (issue.definitionIndex === undefined) {
    return { kind: "project", tab: "species" };
  }

  if (issue.scope === "subspecies" && issue.subspeciesIndex !== undefined) {
    return {
      definitionIndex: issue.definitionIndex,
      kind: "subspecies",
      subspeciesIndex: issue.subspeciesIndex,
      subspeciesTab: getSubspeciesTab(issue.section),
      tableTab: isTableSection(issue.section) ? issue.section : undefined,
    };
  }

  if (isTableSection(issue.section)) {
    return {
      definitionIndex: issue.definitionIndex,
      editorTab: "tables",
      kind: "definition",
      tableTab: issue.section,
    };
  }

  return {
    definitionIndex: issue.definitionIndex,
    editorTab: getDefinitionTab(issue.section),
    kind: "definition",
  };
}

export function buildSpeciesBuilderValidationSummaryItems(
  issues: SpeciesBuilderValidationIssue[],
  definitions: SpeciesBuilderDefinition[],
): SpeciesBuilderValidationSummaryItem[] {
  return issues
    .map((issue, index) => ({ index, issue }))
    .sort(
      (left, right) =>
        validationSeverityRank(left.issue) - validationSeverityRank(right.issue) ||
        left.index - right.index,
    )
    .map(({ issue }) => ({ context: issueContext(issue, definitions), issue }));
}

export function getRequestedSubspeciesTabs(
  request: SpeciesBuilderValidationNavigationRequest | undefined,
  subspeciesIndex: number,
): { tab: SubspeciesEditorTab; tableTab?: RandomTableTab } | undefined {
  const destination = request?.destination;

  return destination?.kind === "subspecies" && destination.subspeciesIndex === subspeciesIndex
    ? { tab: destination.subspeciesTab, tableTab: destination.tableTab }
    : undefined;
}

function issueContext(
  issue: SpeciesBuilderValidationIssue,
  definitions: SpeciesBuilderDefinition[],
): string {
  if (issue.scope === "species-table") {
    return issue.rowIndex === undefined
      ? "Species Table"
      : `Species Table · Row ${issue.rowIndex + 1}`;
  }

  const definition = definitions[issue.definitionIndex ?? -1];
  const definitionName = entityName(definition, "Unknown Species");

  if (issue.scope !== "subspecies") {
    return `${definitionName} · ${SECTION_LABELS[issue.section]}`;
  }

  const subspecies = definition?.subspecies?.[issue.subspeciesIndex ?? -1];
  const subspeciesName = entityName(subspecies, "Unknown Subspecies");
  return `${definitionName} / ${subspeciesName} · ${subspeciesSectionLabel(issue.section)}`;
}

function entityName(entity: { key: string; name: string } | undefined, fallback: string): string {
  return entity?.name.trim() || entity?.key.trim() || fallback;
}

function getDefinitionTab(section: SpeciesBuilderValidationSection): SpeciesBuilderEditorTab {
  if (section === "subspecies") {
    return "subspecies";
  }

  if (section === "species-table" || isTableSection(section)) {
    return "details";
  }

  return section;
}

function getSubspeciesTab(section: SpeciesBuilderValidationSection): SubspeciesEditorTab {
  if (isTableSection(section)) {
    return "tables";
  }

  if (section === "skills" || section === "traits") {
    return "changes";
  }

  if (section === "talents" || section === "wounds") {
    return section;
  }

  return "details";
}

function subspeciesSectionLabel(section: SpeciesBuilderValidationSection): string {
  if (section === "subspecies" || section === "attributes" || section === "details") {
    return "Details";
  }

  if (section === "skills" || section === "traits") {
    return "Skills & Traits";
  }

  return SECTION_LABELS[section];
}

function isTableSection(section: SpeciesBuilderValidationSection): section is RandomTableTab {
  return TABLE_SECTIONS.includes(section as RandomTableTab);
}

function validationSeverityRank(issue: SpeciesBuilderValidationIssue): number {
  return validationIssueSeverity(issue) === "error" ? 0 : 1;
}
