import type {
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../../types/wfrp4e/characteristics";

import { clonePlain, parseSubspeciesTextMapField, setOptionalField } from "./draft";
import {
  normalizeCareerTableRows,
  normalizeEditableText,
  normalizeNumberInput,
  normalizeText,
  normalizeWoundFormulaInput,
  parseStringLines,
  type SpeciesBuilderSubspeciesArrayField,
  type SpeciesBuilderSubspeciesTextMapField,
} from "./field-values";

export function appendBlankSubspecies(
  definition: SpeciesBuilderDefinition,
): SpeciesBuilderDefinition {
  return {
    ...definition,
    subspecies: [
      ...(definition.subspecies ?? []),
      {
        key: "",
        name: "New Subspecies",
      },
    ],
  };
}

export function removeSubspecies(
  definition: SpeciesBuilderDefinition,
  index: number,
): SpeciesBuilderDefinition {
  const subspecies = (definition.subspecies ?? []).filter((_, entryIndex) => entryIndex !== index);

  return setOptionalField(definition, "subspecies", subspecies.length > 0 ? subspecies : undefined);
}

export function updateSubspeciesAtIndex(
  definition: SpeciesBuilderDefinition,
  index: number,
  update: (subspecies: SpeciesBuilderSubspeciesDefinition) => SpeciesBuilderSubspeciesDefinition,
): SpeciesBuilderDefinition {
  const subspecies = definition.subspecies ?? [];
  const entry = subspecies[index];

  if (!entry) {
    return definition;
  }

  return {
    ...definition,
    subspecies: subspecies.map((candidate, entryIndex) =>
      entryIndex === index ? update(clonePlain(entry)) : candidate,
    ),
  };
}

export function setSubspeciesStringField(
  subspecies: SpeciesBuilderSubspeciesDefinition,
  field: "key" | "name",
  value: string,
): SpeciesBuilderSubspeciesDefinition {
  return {
    ...subspecies,
    [field]: normalizeEditableText(value) ?? "",
  };
}

export function setSubspeciesNumberField(
  subspecies: SpeciesBuilderSubspeciesDefinition,
  field: "extra" | "fate" | "movement" | "resilience",
  value: string,
): SpeciesBuilderSubspeciesDefinition {
  return setOptionalField(subspecies, field, normalizeNumberInput(value));
}

export function setSubspeciesCharacteristic(
  subspecies: SpeciesBuilderSubspeciesDefinition,
  key: WfrpCharacteristicKey,
  value: string,
): SpeciesBuilderSubspeciesDefinition {
  const characteristics = subspecies.characteristics ? { ...subspecies.characteristics } : {};
  const formula = normalizeText(value);

  if (formula) {
    characteristics[key] = formula;
  } else {
    delete characteristics[key];
  }

  return setOptionalField(
    subspecies,
    "characteristics",
    Object.keys(characteristics).length > 0 ? characteristics : undefined,
  );
}

export function setSubspeciesArrayField(
  subspecies: SpeciesBuilderSubspeciesDefinition,
  field: SpeciesBuilderSubspeciesArrayField,
  value: string,
): SpeciesBuilderSubspeciesDefinition {
  return setOptionalField(subspecies, field, parseStringLines(value));
}

export function setSubspeciesTextMapField(
  subspecies: SpeciesBuilderSubspeciesDefinition,
  field: SpeciesBuilderSubspeciesTextMapField,
  value: string,
): SpeciesBuilderSubspeciesDefinition {
  return setOptionalField(subspecies, field, parseSubspeciesTextMapField(field, value));
}

export function setSubspeciesWoundFormula(
  subspecies: SpeciesBuilderSubspeciesDefinition,
  value: string,
): SpeciesBuilderSubspeciesDefinition {
  return setOptionalField(subspecies, "woundFormula", normalizeWoundFormulaInput(value));
}

export function setSubspeciesCareerTableRows(
  subspecies: SpeciesBuilderSubspeciesDefinition,
  rows: SpeciesBuilderCareerTableRow[],
): SpeciesBuilderSubspeciesDefinition {
  return setOptionalField(subspecies, "careerTable", normalizeCareerTableRows(rows));
}
