<script setup lang="ts">
import { nextTick, onBeforeUnmount, ref, useId, watch } from "vue";

const props = withDefaults(
  defineProps<{
    closeLabel?: string;
    open: boolean;
    title: string;
    wide?: boolean;
  }>(),
  {
    closeLabel: "Close",
    wide: false,
  },
);

const emit = defineEmits<{
  close: [];
}>();

const dialogElement = ref<HTMLDialogElement | null>(null);
const titleId = useId();

watch(
  () => props.open,
  async (isOpen) => {
    await nextTick();

    const dialog = dialogElement.value;

    if (isOpen && !dialog?.open) {
      dialog?.showModal();
      return;
    }

    if (!isOpen && dialog?.open) {
      dialog.close();
    }
  },
  { immediate: true },
);

onBeforeUnmount(() => {
  if (dialogElement.value?.open) {
    dialogElement.value.close();
  }
});
</script>

<template>
  <dialog
    ref="dialogElement"
    :aria-labelledby="titleId"
    aria-modal="true"
    class="dui-modal"
    @cancel.prevent="emit('close')"
  >
    <section class="dui-modal-box" :class="{ 'app:max-w-5xl': wide }">
      <h2 :id="titleId" class="dui-card-title">{{ title }}</h2>
      <slot />
      <div class="dui-modal-action">
        <button class="dui-btn" type="button" @click="emit('close')">{{ closeLabel }}</button>
      </div>
    </section>
  </dialog>
</template>
