import {
  buildCombinedProfileTraitSource,
  calculateCombinedProfile,
} from "../../../../../functions/npc-builder/combined-profile";
import { readNumberFromPaths } from "../../../../../shared/object-readers";
import { assertFoundryActor } from "../../../../foundry/document-guards";
import { MODULE_ID } from "../../../../constants";
import { applyCombinedProfileArmour } from "./armour";
import { readActorCombatProfile } from "./profile";
import { buildMountTraitSources } from "./trait-sources";

const TOKEN_SIZE_BY_ACTOR_SIZE: Record<string, number> = {
  avg: 1,
  enor: 3,
  lrg: 2,
  ltl: 0.5,
  mnst: 4,
  sml: 0.8,
  tiny: 0.3,
};

export async function applyCombinedProfile(
  actor: FoundryActorDocument,
  mountActorUuid: string,
): Promise<void> {
  const mount = assertFoundryActor(await fromUuid(mountActorUuid));

  if (actor.uuid === mount.uuid) {
    throw new Error("The rider and mount must be different Actors.");
  }

  const riderProfile = readActorCombatProfile(actor);
  const mountProfile = readActorCombatProfile(mount);
  const plan = calculateCombinedProfile(riderProfile, mountProfile);

  await actor.update(buildProfileUpdate(actor, plan));

  const traitSources = buildMountTraitSources(mount, plan);

  if (traitSources.length) {
    await actor.createEmbeddedDocuments("Item", traitSources);
  }

  await applyCombinedProfileArmour(actor, mount, mountProfile, plan);
  await actor.createEmbeddedDocuments("Item", [
    buildCombinedProfileTraitSource({
      flagScope: MODULE_ID,
      mount: mountProfile,
      plan,
      rider: riderProfile,
    }),
  ]);
  await actor.update({
    "system.status.wounds.max": plan.wounds,
    "system.status.wounds.value": plan.wounds,
  });
}

function buildProfileUpdate(
  actor: FoundryActorDocument,
  plan: ReturnType<typeof calculateCombinedProfile>,
): Record<string, unknown> {
  const size = TOKEN_SIZE_BY_ACTOR_SIZE[plan.size] ?? 1;

  return {
    "prototypeToken.height": size,
    "prototypeToken.width": size,
    "system.characteristics.i.modifier":
      readCharacteristicModifier(actor, "i") +
      plan.initiative -
      readCharacteristicValue(actor, "i"),
    "system.characteristics.t.modifier":
      readCharacteristicModifier(actor, "t") + plan.toughness - readCharacteristicValue(actor, "t"),
    "system.details.move.value": plan.movement,
  };
}

function readCharacteristicModifier(actor: FoundryActorDocument, key: string): number {
  return readNumberFromPaths(actor.system, [["characteristics", key, "modifier"]]);
}

function readCharacteristicValue(actor: FoundryActorDocument, key: string): number {
  return readNumberFromPaths(actor.system, [["characteristics", key, "value"]]);
}
