import type { Component } from "vue";

import SpeciesConfiguratorApp from "../../../view/apps/species-builder-suite/SpeciesConfiguratorApp.vue";
import { MODULE_ID } from "../../constants";
import { SpeciesSuiteApplication } from "./SpeciesSuiteApplication";

export class SpeciesConfiguratorApplication extends SpeciesSuiteApplication {
  static override DEFAULT_OPTIONS = {
    ...super.DEFAULT_OPTIONS,
    id: `${MODULE_ID}-species-configurator`,
    classes: [MODULE_ID, "wfrp4e-customizer-species-configurator"],
    position: { height: 680, width: 720 },
    window: {
      icon: "fa-solid fa-sliders",
      resizable: true,
      title: "Species Builder Configurator",
    },
  };

  constructor(
    private readonly openDirectory: () => void,
    private readonly openSpecies: (definitionIndex: number) => void,
  ) {
    super();
  }

  protected override getVueComponent(): Component {
    return SpeciesConfiguratorApp;
  }

  protected override getApplicationProps(): Record<string, unknown> {
    return { onOpenDirectory: this.openDirectory, onOpenSpecies: this.openSpecies };
  }
}
