import type { SpeciesBuilderValidationCatalog } from "../../../../types/species-builder/validation";

import { isRecord, readUnknownPath } from "../../../../shared/object-readers";
import {
  isItemCompendiumPack,
  isRollTableCompendiumPack,
  readCompendiumIndexEntries,
} from "../../../foundry/compendiums";
import {
  type RuntimeCareerTableCompendiumSource,
  validateRuntimeCareerTable,
} from "./career-table";
import { loadRuntimeSpecies } from "./runtime-species";
import { validateRandomTalentTable } from "./table-results";

type CatalogItemType = keyof SpeciesBuilderValidationCatalog["itemBaseNames"];
type RandomTalentSource = SpeciesBuilderValidationCatalog["randomTalentSources"][number];

const CATALOG_ITEM_TYPES = ["skill", "talent", "trait"] as const;
const ITEM_INDEX_FIELDS = ["name", "type", "system.careergroup.value", "system.level.value"];
const CAREER_TABLE_INDEX_FIELDS = ["name", "flags.wfrp4e.key", "flags.wfrp4e.column"];
interface CatalogAccumulator {
  careerGroups: Map<string, string>;
  itemNames: Record<CatalogItemType, Map<string, string>>;
}

export async function loadSpeciesBuilderValidationCatalog(
  persistedDefinitionKeys: string[] = [],
): Promise<SpeciesBuilderValidationCatalog> {
  const config = isRecord(game.wfrp4e?.config) ? game.wfrp4e.config : {};
  const accumulator: CatalogAccumulator = {
    careerGroups: new Map(),
    itemNames: { skill: new Map(), talent: new Map(), trait: new Map() },
  };

  for (const item of game.items?.contents ?? []) {
    indexCatalogItem(accumulator, item);
  }

  for (const pack of itemPacks()) {
    if (!pack.getIndex) {
      continue;
    }

    const index = await pack.getIndex({ fields: ITEM_INDEX_FIELDS });

    for (const entry of readCompendiumIndexEntries(index)) {
      indexCatalogItem(accumulator, entry);
    }
  }

  const careerTableCompendiumSources = await loadCareerTableCompendiumSources();
  const randomTalentSources = loadRandomTalentSources(config, accumulator.itemNames.talent);
  const careerGroups = new Set(accumulator.careerGroups.keys());

  return {
    careerGroupNames: sortedValues(accumulator.careerGroups),
    itemBaseNames: {
      skill: sortedValues(accumulator.itemNames.skill),
      talent: sortedValues(accumulator.itemNames.talent),
      trait: sortedValues(accumulator.itemNames.trait),
    },
    randomTalentSources,
    runtimeSpecies: loadRuntimeSpecies(
      config,
      {
        careerGroups,
        randomTalentSources: new Map(randomTalentSources.map((source) => [source.key, source])),
        skills: new Set(accumulator.itemNames.skill.keys()),
        talents: new Set(accumulator.itemNames.talent.keys()),
        traits: new Set(accumulator.itemNames.trait.keys()),
        validateCareerTable: (speciesKey, subspeciesKey, configuredColumn) =>
          validateRuntimeCareerTable(
            speciesKey,
            subspeciesKey,
            configuredColumn,
            careerGroups,
            careerTableCompendiumSources,
          ),
      },
      persistedDefinitionKeys,
    ),
  };
}

async function loadCareerTableCompendiumSources(): Promise<
  Map<string, RuntimeCareerTableCompendiumSource>
> {
  const sources = new Map<string, RuntimeCareerTableCompendiumSource>();

  for (const pack of (game.packs ?? []).filter(isRollTableCompendiumPack)) {
    if (!pack.getIndex) {
      continue;
    }

    const index = await pack.getIndex({ fields: CAREER_TABLE_INDEX_FIELDS });

    for (const entry of readCompendiumIndexEntries(index)) {
      const key = readUnknownPath(entry, ["flags", "wfrp4e", "key"]);
      const column = readUnknownPath(entry, ["flags", "wfrp4e", "column"]);

      if (
        key !== "career" ||
        typeof column !== "string" ||
        !column.trim() ||
        typeof entry.name !== "string"
      ) {
        continue;
      }

      const packTitle = pack.title?.trim() || pack.collection?.trim() || "its RollTable compendium";

      if (!sources.has(column.trim())) {
        sources.set(column.trim(), { name: entry.name.trim(), packTitle });
      }
    }
  }

  return sources;
}

function indexCatalogItem(accumulator: CatalogAccumulator, item: unknown): void {
  if (!isRecord(item) || typeof item["type"] !== "string" || typeof item["name"] !== "string") {
    return;
  }

  if (isCatalogItemType(item["type"])) {
    addName(accumulator.itemNames[item["type"]], baseItemName(item["name"]));
    return;
  }

  const level = Number(readUnknownPath(item, ["system", "level", "value"]));

  if (item["type"] !== "career" || level !== 1) {
    return;
  }

  const careerGroup = readUnknownPath(item, ["system", "careergroup", "value"]);

  if (typeof careerGroup === "string") {
    addName(accumulator.careerGroups, careerGroup);
  }
}

function itemPacks(): FoundryCompendiumCollection[] {
  const taggedPacks = game.wfrp4e?.tags?.getPacksWithTag?.([...CATALOG_ITEM_TYPES, "career"]);

  return taggedPacks
    ? [...new Set(taggedPacks)].filter(isItemCompendiumPack)
    : (game.packs ?? []).filter(isItemCompendiumPack);
}

function loadRandomTalentSources(
  config: Record<string, unknown>,
  talentNames: Map<string, string>,
): RandomTalentSource[] {
  const sources: RandomTalentSource[] = [];

  for (const key of randomTalentCandidates(config)) {
    const table = game.wfrp4e?.tables?.findTable?.(key);

    if (!table) {
      continue;
    }

    const readiness = validateRandomTalentTable(table, new Set(talentNames.keys()));

    sources.push(
      readiness.readyForCharacterCreation
        ? { key, readyForCharacterCreation: true }
        : { key, readyForCharacterCreation: false, reason: readiness.reason },
    );
  }

  return sources.sort((left, right) => left.key.localeCompare(right.key));
}

function randomTalentCandidates(config: Record<string, unknown>): string[] {
  const candidates = new Set<string>(["talents"]);

  for (const table of game.tables?.contents ?? []) {
    addString(candidates, table.getFlag("wfrp4e", "key"));
  }

  const tableSettings = game.settings.get("wfrp4e", "tableSettings");

  if (isRecord(tableSettings)) {
    Object.keys(tableSettings).forEach((key) => candidates.add(key));
  }

  addNestedRandomTalentKeys(config["speciesRandomTalents"], candidates);
  const subspecies = config["subspecies"];

  if (isRecord(subspecies)) {
    for (const subspeciesByKey of Object.values(subspecies)) {
      if (!isRecord(subspeciesByKey)) {
        continue;
      }

      for (const entry of Object.values(subspeciesByKey)) {
        if (isRecord(entry)) {
          addRandomTalentKeys(entry["randomTalents"], candidates);
        }
      }
    }
  }

  return [...candidates];
}

function addNestedRandomTalentKeys(source: unknown, target: Set<string>): void {
  if (isRecord(source)) {
    Object.values(source).forEach((entry) => addRandomTalentKeys(entry, target));
  }
}

function addRandomTalentKeys(source: unknown, target: Set<string>): void {
  if (isRecord(source)) {
    Object.keys(source).forEach((key) => target.add(key));
  }
}

function isCatalogItemType(value: string): value is CatalogItemType {
  return CATALOG_ITEM_TYPES.some((type) => type === value);
}

function baseItemName(name: string): string {
  return name.split("(", 1)[0]?.trim() ?? "";
}

function addName(target: Map<string, string>, name: string): void {
  const exactName = name.trim();

  if (exactName && !target.has(exactName)) {
    target.set(exactName, exactName);
  }
}

function addString(target: Set<string>, value: unknown): void {
  if (typeof value === "string" && value.trim()) {
    target.add(value.trim());
  }
}

function sortedValues(source: Map<string, string>): string[] {
  return [...source.values()].sort((left, right) => left.localeCompare(right));
}
