import { computed, ref, watch } from "vue";

import type {
  PortraitCandidate,
  PortraitFilterSection,
  PortraitFilterSource,
  PortraitFilterTag,
  PortraitSearchProgress,
  PortraitSearchProgressHandler,
} from "../../types/portrait-gallery";

import {
  doesPortraitCandidateMatchFilters,
  getPortraitSearchProgressLabel,
  getPortraitSearchProgressValue,
  getPortraitTermsInSection,
  listPortraitCandidateFilterSources,
  mergePortraitCandidateCollection,
  shouldSearchForPortraits,
} from "../../functions/portrait-gallery";
import type { PortraitGalleryWorkflowOptions } from "./workflow-options";

export function createPortraitGalleryWorkflow(options: PortraitGalleryWorkflowOptions) {
  const assetCandidates = ref<PortraitCandidate[]>([]);
  const filteredCandidates = ref<PortraitCandidate[] | null>(null);
  const isLoadingPortraitCandidates = ref(false);
  const portraitSearchProgress = ref<PortraitSearchProgress | null>(null);
  let activeLoadId = 0;

  const portraitSearchTerms = computed(() =>
    uniqueStrings([
      ...options.baseSearchTerms.value,
      ...options.filterState.customPortraitSearchTerms.value,
    ]),
  );
  const searchTerms = computed(() => getTermsInSection("search"));
  const mustIncludeTerms = computed(() => getTermsInSection("must-include"));
  const mustExcludeTerms = computed(() => getTermsInSection("must-exclude"));
  const activePortraitSearchTerms = computed(() =>
    uniqueStrings([...searchTerms.value, ...mustIncludeTerms.value]),
  );
  const allPortraitCandidates = computed(
    () =>
      filteredCandidates.value ??
      mergePortraitCandidateCollection({
        assetCandidates: assetCandidates.value,
        immediateCandidates: options.immediateCandidates.value,
        selectedPortraitPath: options.pinnedPortraitPath.value,
      }),
  );
  const filterSources = computed(() =>
    listPortraitCandidateFilterSources(allPortraitCandidates.value),
  );
  const portraitFilterTags = computed<PortraitFilterTag[]>(() => [
    ...portraitSearchTerms.value.flatMap(createTermTag),
    ...filterSources.value.map(createSourceTag),
  ]);
  const portraitCandidates = computed(() =>
    allPortraitCandidates.value.filter((candidate) =>
      doesPortraitCandidateMatchFilters(candidate, {
        mustExcludeSources: getSourcesInSection("must-exclude"),
        mustExcludeTerms: mustExcludeTerms.value,
        mustIncludeSources: getSourcesInSection("must-include"),
        mustIncludeTerms: mustIncludeTerms.value,
      }),
    ),
  );
  const selectedPortraitCandidate = computed(
    () =>
      portraitCandidates.value.find(
        (candidate) => candidate.img === options.activePortraitPath.value,
      ) ?? null,
  );
  const selectedPortraitCandidateKey = computed(() => selectedPortraitCandidate.value?.key ?? "");
  const portraitSearchProgressLabel = computed(() =>
    getPortraitSearchProgressLabel(portraitSearchProgress.value),
  );
  const portraitSearchProgressValue = computed(() =>
    getPortraitSearchProgressValue(portraitSearchProgress.value),
  );

  watch(
    portraitSearchTerms,
    (terms) => options.filterState.retainAvailablePortraitFilterTerms(terms),
    { immediate: true },
  );

  watch(
    () => [
      options.hasSubject.value,
      options.includeCompendiumAssets.value,
      options.includeFilePickerAssets.value,
      options.excludeFullyTransparentImages.value,
      options.excludedReferenceImagePaths.value.join("|"),
      options.priorityFolderPaths.value.join("|"),
      options.immediateCandidates.value.map(({ img }) => img).join("|"),
      options.baseSearchTerms.value.join("|"),
      options.filterState.customPortraitSearchTerms.value.join("|"),
      activePortraitSearchTerms.value.join("|"),
      mustExcludeTerms.value.join("|"),
    ],
    (_searchInputs, _previousSearchInputs, onCleanup) => {
      activeLoadId += 1;
      const refreshTimeout = setTimeout(() => void refreshPortraitCandidates(), 150);

      onCleanup(() => clearTimeout(refreshTimeout));
    },
    { immediate: true },
  );

  function setPortraitFilterTagSection(
    tag: PortraitFilterTag,
    section: PortraitFilterSection,
  ): void {
    if (tag.kind === "source") {
      options.filterState.setPortraitSourceTagSection(tag.value, section);
      return;
    }

    options.filterState.setPortraitTermSection(tag.value, section);
  }

  async function refreshPortraitCandidates(): Promise<void> {
    const loadId = activeLoadId + 1;
    activeLoadId = loadId;
    const hasSubject = options.hasSubject.value;
    const shouldDiscoverCandidates = shouldSearchForPortraits({
      hasEnabledSource:
        options.includeCompendiumAssets.value ||
        options.includeFilePickerAssets.value ||
        options.priorityFolderPaths.value.length > 0,
      hasSubject,
      searchTerms: activePortraitSearchTerms.value,
    });

    if (!hasSubject) {
      assetCandidates.value = [];
      filteredCandidates.value = [];
      isLoadingPortraitCandidates.value = false;
      portraitSearchProgress.value = null;
      return;
    }

    isLoadingPortraitCandidates.value = true;
    assetCandidates.value = [];
    filteredCandidates.value = null;
    portraitSearchProgress.value = {
      candidatesFound: 0,
      currentLocation: "Preparing portrait search",
      directoriesVisited: 0,
      maxDirectories: 0,
      phase: "world-documents",
    };

    try {
      const updateProgress: PortraitSearchProgressHandler = (progress) => {
        if (activeLoadId === loadId) {
          portraitSearchProgress.value = progress;
        }
      };
      const candidates = shouldDiscoverCandidates
        ? await options.provider.listPortraitCandidates(
            {
              includeCompendiumAssets: options.includeCompendiumAssets.value,
              includeFilePickerAssets: options.includeFilePickerAssets.value,
              mustExcludeTerms: mustExcludeTerms.value,
              mustIncludeTerms: mustIncludeTerms.value,
              priorityFolderPaths: options.priorityFolderPaths.value,
              searchTerms: activePortraitSearchTerms.value,
            },
            updateProgress,
          )
        : [];
      const mergedCandidates = mergePortraitCandidateCollection({
        assetCandidates: candidates,
        immediateCandidates: options.immediateCandidates.value,
        selectedPortraitPath: options.pinnedPortraitPath.value,
      });
      const includedCandidates = await options.provider.filterPortraitCandidates(
        mergedCandidates,
        {
          excludeFullyTransparentImages: options.excludeFullyTransparentImages.value,
          excludedReferenceImagePaths: options.excludedReferenceImagePaths.value,
        },
        updateProgress,
      );

      if (activeLoadId === loadId) {
        assetCandidates.value = candidates;
        filteredCandidates.value = includedCandidates;
      }
    } catch (error) {
      if (activeLoadId === loadId) {
        options.errorMessage.value =
          error instanceof Error ? error.message : options.searchErrorMessage;
      }
    } finally {
      if (activeLoadId === loadId) {
        isLoadingPortraitCandidates.value = false;
      }
    }
  }

  return {
    activePortraitSearchTerms,
    addPortraitSearchTerm: options.filterState.addCustomPortraitSearchTerm,
    isLoadingPortraitCandidates,
    portraitCandidates,
    portraitFilterTags,
    portraitSearchProgress,
    portraitSearchProgressLabel,
    portraitSearchProgressValue,
    portraitSearchTerms,
    selectedPortraitCandidate,
    selectedPortraitCandidateKey,
    selectPortrait: options.selectPortrait,
    setPortraitFilterTagSection,
  };

  function getTermsInSection(section: PortraitFilterSection): string[] {
    return getPortraitTermsInSection(
      portraitSearchTerms.value,
      options.filterState.portraitTermSections.value,
      section,
    );
  }

  function createTermTag(term: string): PortraitFilterTag[] {
    const section = options.filterState.portraitTermSections.value[term] ?? "search";

    return section === "removed"
      ? []
      : [{ canRemove: true, id: `term:${term}`, kind: "term", label: term, section, value: term }];
  }

  function createSourceTag(source: PortraitFilterSource): PortraitFilterTag {
    return {
      canRemove: false,
      id: `source:${source.value}`,
      kind: "source",
      label: `Sourced From ${source.label}`,
      section: options.filterState.portraitSourceTagSections.value[source.value] ?? "search",
      value: source.value,
    };
  }

  function getSourcesInSection(section: PortraitFilterSection): string[] {
    return filterSources.value
      .filter(
        (source) =>
          (options.filterState.portraitSourceTagSections.value[source.value] ?? "search") ===
          section,
      )
      .map((source) => source.value);
  }
}

function uniqueStrings<Value>(values: Value[]): Value[] {
  return [...new Set(values)];
}
