<script setup lang="ts">
import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderHeightDefinition,
} from "../../../../../../../../../types/species-builder/species-builder";

import { getSuggestedSpeciesKey } from "../../../../species-key-suggestions";
import {
  hasValidationErrors,
  issuesForField,
  sectionIssues,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../../validation-presentation";
import AgeHeightFields from "./AgeHeightFields.vue";

const props = defineProps<{
  definition: SpeciesBuilderDefinition;
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
}>();

const emit = defineEmits<{
  updateBooleanField: [field: "includeInExtraSpecies", value: boolean];
  updateHeightField: [field: keyof SpeciesBuilderHeightDefinition, value: string];
  updateStringField: [field: "age" | "key" | "name", value: string];
  reviewIssues: [];
}>();

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement ? event.target.value : "";
}

function checkboxValue(event: Event): boolean {
  return event.target instanceof HTMLInputElement && event.target.checked;
}

function fieldIssues(field: "key" | "name"): SpeciesBuilderValidationIssue[] {
  return issuesForField(props.issues, field);
}

function fieldMessages(field: "key" | "name"): string[] {
  return uniqueIssueMessages(fieldIssues(field));
}

function generalIssues(): SpeciesBuilderValidationIssue[] {
  return sectionIssues(props.issues);
}
</script>

<template>
  <section class="app:grid app:gap-3">
    <div
      v-if="generalIssues().length"
      class="dui-alert"
      :class="validationClass(generalIssues(), 'dui-alert-error', 'dui-alert-warning')"
      role="alert"
    >
      <i
        aria-hidden="true"
        class="fa-solid"
        :class="
          hasValidationErrors(generalIssues()) ? 'fa-circle-exclamation' : 'fa-triangle-exclamation'
        "
      />
      <div class="app:flex-1">
        <p
          v-for="message in uniqueIssueMessages(generalIssues()).slice(0, 1)"
          :key="message"
          class="app:m-0 app:text-xs"
        >
          {{ message }}
          <template v-if="uniqueIssueMessages(generalIssues()).length > 1">
            (+{{ uniqueIssueMessages(generalIssues()).length - 1 }} more)
          </template>
        </p>
      </div>
      <button class="dui-btn dui-btn-sm" type="button" @click="emit('reviewIssues')">
        Review Species Issues
        <i aria-hidden="true" class="fa-solid fa-chevron-right" />
      </button>
    </div>
    <div class="app:flex app:flex-wrap app:gap-3">
      <section class="dui-card dui-card-border dui-card-sm app:min-w-64 app:flex-1">
        <div class="dui-card-body">
          <fieldset class="dui-fieldset">
            <legend class="dui-fieldset-legend">Identity</legend>
            <p class="dui-fieldset-label">
              The name is shown to users. The key identifies this species in generated WFRP config.
            </p>
            <label class="dui-label" for="species-name">Name</label>
            <input
              id="species-name"
              :aria-describedby="fieldIssues('name').length ? 'species-name-errors' : undefined"
              :aria-invalid="hasValidationErrors(fieldIssues('name')) || undefined"
              class="dui-input dui-input-sm app:w-full"
              :class="validationClass(fieldIssues('name'), 'dui-input-error', 'dui-input-warning')"
              :disabled="isDisabled"
              :value="definition.name"
              type="text"
              @input="emit('updateStringField', 'name', inputValue($event))"
            />
            <div v-if="fieldMessages('name').length" id="species-name-errors">
              <p
                v-for="message in fieldMessages('name')"
                :key="message"
                class="app:m-0 app:text-xs"
                :class="validationClass(fieldIssues('name'), 'app:text-error', 'app:text-warning')"
              >
                {{ message }}
              </p>
            </div>

            <label class="dui-label" for="species-key">Key</label>
            <input
              id="species-key"
              :aria-describedby="fieldIssues('key').length ? 'species-key-errors' : undefined"
              :aria-invalid="hasValidationErrors(fieldIssues('key')) || undefined"
              class="dui-input dui-input-sm app:w-full"
              :class="validationClass(fieldIssues('key'), 'dui-input-error', 'dui-input-warning')"
              :disabled="isDisabled"
              :placeholder="getSuggestedSpeciesKey(definition)"
              :value="definition.key"
              type="text"
              @input="emit('updateStringField', 'key', inputValue($event))"
            />
            <div v-if="fieldMessages('key').length" id="species-key-errors">
              <p
                v-for="message in fieldMessages('key')"
                :key="message"
                class="app:m-0 app:text-xs"
                :class="validationClass(fieldIssues('key'), 'app:text-error', 'app:text-warning')"
              >
                {{ message }}
              </p>
            </div>
          </fieldset>
        </div>
      </section>

      <section class="dui-card dui-card-border dui-card-sm app:min-w-64 app:flex-1">
        <div class="dui-card-body">
          <fieldset class="dui-fieldset">
            <legend class="dui-fieldset-legend">WFRP Availability</legend>
            <p class="dui-fieldset-label">
              Choose whether character creation lists this custom species.
            </p>
            <label class="dui-label">
              <input
                class="dui-checkbox"
                :checked="definition.includeInExtraSpecies"
                :disabled="isDisabled"
                type="checkbox"
                @change="emit('updateBooleanField', 'includeInExtraSpecies', checkboxValue($event))"
              />
              <span>Show in WFRP extra species options</span>
            </label>
          </fieldset>
        </div>
      </section>
    </div>

    <section class="dui-card dui-card-border dui-card-sm">
      <div class="dui-card-body">
        <h3 class="dui-card-title">Character Creation</h3>
        <AgeHeightFields
          :definition="definition"
          :is-disabled="isDisabled"
          :issues="issues"
          @update-height-field="(field, value) => emit('updateHeightField', field, value)"
          @update-string-field="(field, value) => emit('updateStringField', field, value)"
        />
      </div>
    </section>
  </section>
</template>
