import type {
  NpcMagicGrant,
  NpcMagicGrantKind,
  NpcMagicGrantSource,
  NpcMagicLoreCategory,
  NpcMagicLoreOption,
} from "../../types/npc-builder";

const parentheticalTextPattern = /\(([^)]+)\)/;
export const EIGHT_WIND_MAGIC_LORE_KEYS = [
  "beasts",
  "death",
  "fire",
  "heavens",
  "metal",
  "life",
  "light",
  "shadow",
] as const;
export const DARK_MAGIC_LORE_KEYS = [
  "daemonology",
  "necromancy",
  "nurgle",
  "slaanesh",
  "tzeentch",
  "undivided",
] as const;

export function parseMagicGrantName(
  name: string,
  source: NpcMagicGrantSource,
): NpcMagicGrant | null {
  const trimmedName = name.trim();
  const lowerName = trimmedName.toLocaleLowerCase();

  if (lowerName === "petty magic") {
    return createGrant({
      kind: "petty-magic",
      rawLore: "Petty Magic",
      source,
      sourceName: trimmedName,
    });
  }

  if (lowerName.startsWith("arcane magic")) {
    return createGrant({
      kind: "arcane-magic",
      rawLore: readParentheticalText(trimmedName),
      source,
      sourceName: trimmedName,
    });
  }

  if (lowerName.startsWith("spellcaster")) {
    return createGrant({
      kind: "spellcaster",
      rawLore: readParentheticalText(trimmedName),
      source,
      sourceName: trimmedName,
    });
  }

  return null;
}

export function normalizeMagicLoreText(lore: string): string {
  return lore
    .trim()
    .replace(/^any\s+/i, "")
    .replace(/^arcane\s+lore\s+of\s+/i, "")
    .replace(/^arcane\s+lore$/i, "")
    .replace(/^lore\s+of\s+/i, "")
    .replaceAll(/\s+/g, " ")
    .toLocaleLowerCase();
}

export function createMagicGrantResolutionKey(options: {
  kind: NpcMagicGrantKind;
  rawLore: string;
  source: NpcMagicGrantSource;
  sourceName: string;
}): string {
  return `${options.source}:${options.kind}:${options.sourceName}:${options.rawLore}`;
}

export function resolveMagicGrantLore(grant: NpcMagicGrant, lore: string): NpcMagicGrant {
  return {
    ...grant,
    isAmbiguous: false,
    normalizedLore: normalizeMagicLoreText(lore),
    rawLore: lore.trim(),
  };
}

export function getMagicLoreCategory(key: string): NpcMagicLoreCategory {
  const normalizedKey = normalizeMagicLoreText(key);

  if (normalizedKey === "petty") {
    return "petty";
  }

  if ((EIGHT_WIND_MAGIC_LORE_KEYS as readonly string[]).includes(normalizedKey)) {
    return "eight-wind";
  }

  if ((DARK_MAGIC_LORE_KEYS as readonly string[]).includes(normalizedKey)) {
    return "dark";
  }

  return "other";
}

export function getMagicLoreOptionsForGrant(
  grant: NpcMagicGrant,
  options: NpcMagicLoreOption[],
): NpcMagicLoreOption[] {
  if (grant.kind === "petty-magic") {
    return options.filter((option) => option.category === "petty");
  }

  const lowerLore = grant.rawLore.trim().toLocaleLowerCase();

  if (lowerLore.includes("dark")) {
    return options.filter((option) => option.category === "dark");
  }

  if (lowerLore.includes("eight winds")) {
    return options.filter((option) => option.category === "eight-wind");
  }

  return options.filter((option) => option.category !== "petty");
}

export function isAmbiguousMagicLoreText(lore: string): boolean {
  const normalized = lore.trim().toLocaleLowerCase();

  return !normalized || normalized === "any" || normalized.includes("any ");
}

function createGrant(options: {
  kind: NpcMagicGrantKind;
  rawLore: string;
  source: NpcMagicGrantSource;
  sourceName: string;
}): NpcMagicGrant {
  const rawLore = options.rawLore.trim();

  return {
    isAmbiguous: isAmbiguousMagicLoreText(rawLore),
    kind: options.kind,
    normalizedLore: normalizeMagicLoreText(rawLore),
    rawLore,
    resolutionKey: createMagicGrantResolutionKey({
      kind: options.kind,
      rawLore,
      source: options.source,
      sourceName: options.sourceName,
    }),
    source: options.source,
    sourceName: options.sourceName,
  };
}

function readParentheticalText(name: string): string {
  return parentheticalTextPattern.exec(name)?.[1]?.trim() ?? "";
}
