<script setup lang="ts">
import type {
  NpcAdvancementDraftEntry,
  NpcEstimatedXpBreakdown,
} from "../../../../../types/npc-builder";

import {
  formatSources,
  getAdvancementTotal,
  getAdvancementXp,
  needsSkillSpecialization,
} from "./advancement-display";
import AdvancementRowTailActions from "./AdvancementRowTailActions.vue";
import NpcBuilderSection from "../NpcBuilderSection.vue";

defineProps<{
  entries: NpcAdvancementDraftEntry[];
  estimatedNpcXp?: NpcEstimatedXpBreakdown;
  manualAdvanceCount?: number;
  sectionNumber: string;
  showSkillSpecializationBadges?: boolean;
  title: string;
}>();

const emit = defineEmits<{
  adjustCurrent: [advancement: NpcAdvancementDraftEntry, direction: -1 | 1];
  removeCustom: [advancement: NpcAdvancementDraftEntry];
  resetAll: [];
  resetCurrent: [advancement: NpcAdvancementDraftEntry];
  totalChange: [advancement: NpcAdvancementDraftEntry, total: number];
}>();

function handleTotalInput(advancement: NpcAdvancementDraftEntry, event: Event): void {
  const input = event.target as HTMLInputElement | null;

  if (input) {
    emit("totalChange", advancement, Number(input.value));
  }
}
</script>

<template>
  <NpcBuilderSection :number="sectionNumber" :title="title">
    <div v-if="manualAdvanceCount" class="dui-card-actions">
      <span>{{ manualAdvanceCount }} manual edits</span>
      <button class="dui-btn dui-btn-sm" type="button" @click="emit('resetAll')">
        Reset All Advances
      </button>
    </div>
    <div v-if="estimatedNpcXp" class="dui-alert dui-alert-info">
      <strong>Estimated NPC XP {{ estimatedNpcXp.total }}</strong>
      <span>{{ estimatedNpcXp.characteristics }} characteristics</span>
      <span>{{ estimatedNpcXp.skills }} skills</span>
      <span>{{ estimatedNpcXp.talents }} talents</span>
    </div>
    <ul class="dui-list">
      <li v-for="entry in entries" :key="`${entry.kind}:${entry.name}`" class="dui-list-row">
        <div class="dui-list-col-grow">
          <strong>{{ entry.name }}</strong>
          <span v-if="entry.current !== entry.careerValue" class="dui-badge dui-badge-info">
            Manual edit
          </span>
          <span
            v-if="showSkillSpecializationBadges && needsSkillSpecialization(entry.name)"
            class="dui-badge dui-badge-warning"
          >
            Needs specialization
          </span>
          <span>
            Base {{ entry.baseValue }} · Advances {{ entry.current }} · XP
            {{ getAdvancementXp(entry) }}
          </span>
          <small>Sources: {{ formatSources(entry) }}</small>
        </div>
        <div class="dui-join">
          <button
            class="dui-join-item dui-btn dui-btn-sm"
            :disabled="getAdvancementTotal(entry) <= entry.minimumTotal"
            title="Decrease by 5"
            type="button"
            @click="emit('adjustCurrent', entry, -1)"
          >
            -5
          </button>
          <input
            class="dui-join-item dui-input dui-input-sm"
            :aria-label="`Total ${entry.name}`"
            :value="getAdvancementTotal(entry)"
            min="0"
            type="number"
            @input="handleTotalInput(entry, $event)"
          />
          <button
            class="dui-join-item dui-btn dui-btn-sm"
            title="Increase by 5"
            type="button"
            @click="emit('adjustCurrent', entry, 1)"
          >
            +5
          </button>
          <AdvancementRowTailActions
            :entry="entry"
            @remove-custom="emit('removeCustom', entry)"
            @reset-current="emit('resetCurrent', entry)"
          />
        </div>
      </li>
    </ul>
    <p v-if="!entries.length" class="dui-alert">No {{ title.toLowerCase() }} to advance yet.</p>
  </NpcBuilderSection>
</template>
