<script setup lang="ts">
import { computed, onMounted } from "vue";

import type { SpeciesBuilderBridge } from "../../../types/species-builder/species-builder";
import type { SubspeciesEditorTab } from "../species-builder/tabs/species/pages/editor/tabs/subspecies/subspecies-editor-tabs";
import type { RandomTableTab } from "../species-builder/tabs/species/pages/editor/tabs/tables/random-table-events";

import {
  talentGrantNames,
  talentGrantsForValues,
} from "../../../functions/species-builder/editor/linked-grants";
import { getSubspeciesWoundFormulaTraitName } from "../../../functions/species-builder/wound-formula-traits";
import { useSpeciesBuilderEditor } from "../../../state/species-builder/editor";
import DeleteConfirmationSubView from "../species-builder/components/DeleteConfirmationSubView.vue";
import SpeciesBuilderStatus from "../species-builder/components/SpeciesBuilderStatus.vue";
import UnsafeSaveConfirmationSubView from "../species-builder/components/UnsafeSaveConfirmationSubView.vue";
import { useSpeciesBuilderDeletion } from "../species-builder/components/deletion";
import { useSpeciesBuilderUnsafeSave } from "../species-builder/components/unsafe-save";
import SubspeciesEditorSubView from "../species-builder/tabs/species/pages/editor/tabs/subspecies/SubspeciesEditorSubView.vue";
import SpeciesSuiteHeader from "./components/SpeciesSuiteHeader.vue";

const props = defineProps<{
  bridge: SpeciesBuilderBridge;
  definitionIndex: number;
  initialTab: SubspeciesEditorTab;
  initialTableTab: RandomTableTab;
  onOpenIssues: () => void;
  onOpenParent: () => void;
  onOpenWoundFormula: () => void;
  onSettingsSaved?: () => void;
  subspeciesIndex: number;
}>();
const editor = useSpeciesBuilderEditor(props.bridge, { onSettingsSaved: props.onSettingsSaved });
const unsafeSave = useSpeciesBuilderUnsafeSave(editor);
const deletion = useSpeciesBuilderDeletion({
  deleteDefinition: editor.deleteSelectedDefinition,
  deleteSubspecies: editor.deleteSubspecies,
  selectedDefinition: editor.selectedDefinition,
});
const definition = computed(() => editor.definitions.value[props.definitionIndex]);
const subspecies = computed(() => definition.value?.subspecies?.[props.subspeciesIndex]);
const issues = computed(() =>
  editor.validationIssues.value.filter(
    (issue) =>
      issue.definitionIndex === props.definitionIndex &&
      issue.scope === "subspecies" &&
      issue.subspeciesIndex === props.subspeciesIndex,
  ),
);
const errorCount = computed(
  () => issues.value.filter((issue) => issue.severity === "error").length,
);
const warningCount = computed(() => issues.value.length - errorCount.value);
const isBusy = computed(() => editor.isLoading.value || editor.isSaving.value);
const isReadOnly = computed(
  () =>
    definition.value?.origin === "runtime" &&
    props.subspeciesIndex < (definition.value?.runtimeSubspeciesCount ?? 0),
);
const parentTalents = computed(() =>
  talentGrantNames(
    talentGrantsForValues(definition.value?.talents, definition.value?.linkedTalents),
  ),
);
const woundFormulaTraitName = computed(() => {
  const parent = definition.value;
  const child = subspecies.value;
  return parent && child ? getSubspeciesWoundFormulaTraitName(parent, child) : "";
});

onMounted(async () => {
  await editor.ensureSettingsLoaded();
  editor.selectDefinition(props.definitionIndex);
});

function name(): string {
  return subspecies.value?.name.trim() || subspecies.value?.key.trim() || "Untitled Subspecies";
}

function parentName(): string {
  return definition.value?.name.trim() || definition.value?.key.trim() || "Parent Species";
}

function confirmDelete(): void {
  deletion.confirmPendingDelete();
  props.onOpenParent();
}
</script>

<template>
  <section class="app:flex app:min-h-full app:flex-col" :aria-busy="isBusy">
    <SpeciesSuiteHeader
      :can-save="editor.canSave.value"
      :context="`${parentName()} / ${name()}`"
      :error-count="errorCount"
      :has-unsaved-changes="editor.hasUnsavedChanges.value"
      :is-busy="isBusy"
      :parent-label="parentName()"
      :title="name()"
      :warning-count="warningCount"
      @open-issues="onOpenIssues"
      @open-parent="onOpenParent"
      @reload="editor.loadSettings"
      @save="unsafeSave.requestSave"
    />

    <DeleteConfirmationSubView
      :message="deletion.pendingDelete.value?.message"
      @close="deletion.pendingDelete.value = null"
      @confirm="confirmDelete"
    />
    <UnsafeSaveConfirmationSubView
      :is-open="unsafeSave.isConfirmationOpen.value"
      @close="unsafeSave.closeConfirmation"
      @confirm="unsafeSave.confirmSave"
    />

    <main class="app:flex app:flex-1 app:flex-col app:gap-3 app:p-3">
      <SpeciesBuilderStatus
        :chargen-error-count="errorCount"
        :chargen-warning-count="warningCount"
        :load-error="editor.loadError.value || editor.saveError.value"
        :message="editor.message.value"
        validation-message=""
        @review-issues="onOpenIssues"
      />

      <div v-if="!isReadOnly && subspecies" class="app:flex app:justify-end">
        <button
          class="dui-btn dui-btn-error dui-btn-outline dui-btn-sm"
          :disabled="isBusy"
          type="button"
          @click="deletion.requestDeleteSubspecies(subspeciesIndex)"
        >
          <i aria-hidden="true" class="fa-solid fa-trash" />
          Delete Subspecies
        </button>
      </div>

      <SubspeciesEditorSubView
        v-if="definition && subspecies"
        :index="subspeciesIndex"
        :initial-tab="initialTab"
        :initial-table-tab="initialTableTab"
        :is-loading="editor.isLoading.value"
        is-open
        :is-read-only="isReadOnly"
        :is-saving="editor.isSaving.value"
        :issues="issues"
        :parent-definition="definition"
        :parent-talents="parentTalents"
        :random-talent-sources="editor.randomTalentSources.value"
        standalone
        :subspecies="subspecies"
        :wound-formula-trait-name="woundFormulaTraitName"
        @career-table-career-drop="editor.setSubspeciesCareerTableCareerDrop"
        @career-table-journal-drop="editor.setSubspeciesCareerTableJournalDrop"
        @close="onOpenParent"
        @delete="deletion.requestDeleteSubspecies"
        @open-item="editor.openItemSheet"
        @open-wound-formula="onOpenWoundFormula"
        @save="unsafeSave.requestSave"
        @talent-drop="editor.appendSubspeciesTalentDrop"
        @talent-replacement-replacement-drop="
          (entryIndex, rowIndex, data) =>
            editor.setSubspeciesTalentReplacementDrop(entryIndex, rowIndex, 'replacement', data)
        "
        @talent-replacement-rolled-drop="
          (entryIndex, rowIndex, data) =>
            editor.setSubspeciesTalentReplacementDrop(entryIndex, rowIndex, 'rolled', data)
        "
        @update-array-field="editor.updateSubspeciesArrayField"
        @update-career-table-rows="editor.updateSubspeciesCareerTableRows"
        @update-characteristic="editor.updateSubspeciesCharacteristic"
        @update-number-field="editor.updateSubspeciesNumberField"
        @update-string-field="editor.updateSubspeciesStringField"
        @update-talent-replacement-rows="editor.updateSubspeciesTalentReplacementRows"
        @update-text-map-field="editor.updateSubspeciesTextMapField"
        @update-wound-formula="editor.updateSubspeciesWoundFormula"
      />

      <div v-else class="dui-alert dui-alert-warning" role="status">
        <i aria-hidden="true" class="fa-solid fa-triangle-exclamation" />
        <span>This subspecies is no longer available. Return to {{ parentName() }}.</span>
      </div>
    </main>
  </section>
</template>
