import type { SpeciesItemEffect } from "../../../types/species-builder/species-item";
import { isRecord } from "../../../shared/object-readers";

export function readSpeciesEffects(item: FoundryItemDocument): SpeciesItemEffect[] {
  return (item.effects?.contents ?? []).map((effect) => {
    const source = effect.toObject();
    const system = isRecord(source["system"]) ? source["system"] : {};
    const transfer = isRecord(system["transferData"]) ? system["transferData"] : {};
    return {
      id: effect.id,
      name: effect.name,
      disabled: source["disabled"] === true,
      temporary: effect.isTemporary === true,
      type: typeof transfer["type"] === "string" ? transfer["type"] : "",
    };
  });
}

export async function editSpeciesEffect(
  item: FoundryItemDocument,
  action: "create" | "edit" | "toggle" | "delete",
  id?: string,
): Promise<void> {
  if (!game.user?.isGM) throw new Error("Only a GM can edit Species effects.");
  if (action === "create") {
    if (!item.createEmbeddedDocuments) throw new Error("This Item cannot create effects.");
    await item.createEmbeddedDocuments("ActiveEffect", [
      { name: "New Effect", img: "icons/svg/aura.svg" },
    ]);
    return;
  }
  const effect = item.effects?.contents.find((entry) => entry.id === id);
  if (!effect) throw new Error("The effect no longer exists. Reload the Item.");
  if (action === "edit") effect.sheet?.render(true);
  else if (action === "toggle")
    await effect.update({ disabled: effect.toObject()["disabled"] !== true });
  else if (item.deleteEmbeddedDocuments)
    await item.deleteEmbeddedDocuments("ActiveEffect", [effect.id]);
}

export function chooseSpeciesImage(current: string, selected: (path: string) => void): void {
  new foundry.applications.apps.FilePicker.implementation({
    type: "image",
    current,
    callback: selected,
  }).render(true);
}
