import type { SpeciesBuilderRandomTalentSource } from "../../../types/species-builder/species-builder";

import { isRecord } from "../../../shared/object-readers";

const DEFAULT_TALENT_SOURCE: SpeciesBuilderRandomTalentSource = {
  key: "talents",
  label: "Talents - Character Creation",
};

export function loadRandomTalentSources(): SpeciesBuilderRandomTalentSource[] {
  const sourcesByKey = new Map<string, SpeciesBuilderRandomTalentSource>();

  sourcesByKey.set(DEFAULT_TALENT_SOURCE.key, DEFAULT_TALENT_SOURCE);

  for (const table of game.tables?.contents ?? []) {
    const key = table.getFlag("wfrp4e", "key");

    if (typeof key !== "string" || !key.trim()) {
      continue;
    }

    const label = getRandomTalentSourceLabel(key, table);
    sourcesByKey.set(key, { key, label });
  }

  return [...sourcesByKey.values()].sort(compareRandomTalentSources);
}

function getRandomTalentSourceLabel(key: string, table: FoundryRollTableDocument): string {
  const wfrpTable = game.wfrp4e?.tables?.findTable?.(key);
  const label =
    isRecord(wfrpTable) && typeof wfrpTable["name"] === "string" ? wfrpTable["name"] : table.name;

  return label.trim() || key;
}

function compareRandomTalentSources(
  left: SpeciesBuilderRandomTalentSource,
  right: SpeciesBuilderRandomTalentSource,
): number {
  if (left.key === DEFAULT_TALENT_SOURCE.key) {
    return -1;
  }

  if (right.key === DEFAULT_TALENT_SOURCE.key) {
    return 1;
  }

  return left.label.localeCompare(right.label);
}
