<script setup lang="ts">
import { computed } from "vue";

import type { SpeciesBuilderDefinition } from "../../../../types/species-builder/species-builder";

import { getSuggestedSpeciesKey } from "../tabs/species/species-key-suggestions";

const props = defineProps<{
  canSave: boolean;
  definition?: SpeciesBuilderDefinition;
  entityKey?: string;
  entityName?: string;
  hasUnsavedChanges: boolean;
  hasValidationErrors: boolean;
  hasValidationWarnings: boolean;
  isLoading: boolean;
  isSaving: boolean;
  loadError: string;
}>();

const emit = defineEmits<{
  save: [];
}>();

const definitionName = computed(
  () =>
    props.entityName?.trim() ||
    props.definition?.name.trim() ||
    props.definition?.key.trim() ||
    (props.definition ? "Untitled Species" : "Species Builder"),
);
const definitionKey = computed(() => {
  if (props.entityKey?.trim()) {
    return props.entityKey.trim();
  }

  if (!props.definition) {
    return "";
  }

  return props.definition.key.trim() || getSuggestedSpeciesKey(props.definition);
});
const status = computed(() => {
  if (props.isLoading) {
    return {
      label: "Reloading species data...",
      statusClass: "dui-status-info",
    };
  }

  if (props.loadError) {
    return {
      label: "Error: review the message in the editor",
      statusClass: "dui-status-error",
    };
  }

  if (props.isSaving) {
    return {
      label: "Saving changes...",
      statusClass: "dui-status-info",
    };
  }

  if (props.hasValidationErrors && props.hasUnsavedChanges) {
    return {
      label: "Unsaved changes; saving requires confirmation",
      statusClass: "dui-status-error",
    };
  }

  if (props.hasValidationErrors) {
    return {
      label: "Saved; character-creation errors remain",
      statusClass: "dui-status-error",
    };
  }

  if (props.hasValidationWarnings) {
    return {
      label: props.hasUnsavedChanges
        ? "Unsaved changes; validation warnings remain"
        : "Saved; validation warnings remain",
      statusClass: "dui-status-warning",
    };
  }

  if (props.hasUnsavedChanges) {
    return {
      label: "Unsaved changes",
      statusClass: "dui-status-warning",
    };
  }

  return {
    label: "All changes saved",
    statusClass: "dui-status-success",
  };
});
</script>

<template>
  <footer
    aria-label="Current species and save state"
    class="dui-footer dui-footer-horizontal app:sticky app:bottom-0 app:z-10 app:items-center app:justify-between app:gap-3 app:bg-base-200 app:px-3 app:py-2"
  >
    <div class="app:flex app:min-w-0 app:items-center app:gap-2">
      <span aria-hidden="true" class="dui-status" :class="status.statusClass" />
      <strong>{{ definitionName }}</strong>
      <span v-if="definitionKey" class="dui-badge dui-badge-ghost">{{ definitionKey }}</span>
      <span aria-atomic="true" aria-live="polite" role="status">{{ status.label }}</span>
    </div>

    <button
      class="dui-btn dui-btn-primary dui-btn-sm"
      :disabled="!canSave"
      type="button"
      @click="emit('save')"
    >
      <i aria-hidden="true" class="fa-solid fa-floppy-disk" />
      {{ isSaving ? "Saving..." : "Save Changes" }}
    </button>
  </footer>
</template>
