import type { ComputedRef, Ref } from "vue";

import type {
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderExamplePackage,
  SpeciesBuilderHeightDefinition,
} from "../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../types/wfrp4e/characteristics";

import {
  copySpeciesDefinition,
  createBlankSpeciesDefinition,
  setSpeciesArrayField,
  setSpeciesCareerTableRows,
  setSpeciesCharacteristic,
  setSpeciesHeightField,
  setSpeciesNumberField,
  setSpeciesStringField,
  setSpeciesTextMapField,
  setSpeciesWoundFormula,
} from "../../functions/species-builder/editor/definition-fields";
import {
  canEditSpeciesDefinitionBase,
  createCustomEditingDefinition,
  mergeSpeciesBuilderExamplePackage,
} from "../../functions/species-builder/editing-definitions";
import type {
  SpeciesBuilderArrayField,
  SpeciesBuilderTextMapField,
} from "../../functions/species-builder/editor/field-values";
import { updateSelectedDefinitionAtIndex } from "./selected-definition";

interface SpeciesBuilderActionContext {
  definitions: Ref<SpeciesBuilderEditingDefinition[]>;
  message: Ref<string>;
  selectedDefinition: ComputedRef<SpeciesBuilderEditingDefinition | undefined>;
  selectedIndex: Ref<number>;
}

export function createSpeciesBuilderDefinitionActions(context: SpeciesBuilderActionContext) {
  function addBlankDefinition(): void {
    addDefinition(createBlankSpeciesDefinition());
  }

  function duplicateSelectedDefinition(): void {
    const definition = context.selectedDefinition.value;

    if (canEditSpeciesDefinitionBase(definition)) {
      addDefinition(copySpeciesDefinition(definition, context.definitions.value));
    }
  }

  function addDefinition(definition: SpeciesBuilderDefinition): void {
    addDefinitions([definition]);
  }

  function addDefinitions(definitions: SpeciesBuilderDefinition[]): void {
    if (definitions.length === 0) {
      return;
    }

    const additions = definitions.map(createCustomEditingDefinition);
    const firstRuntimeIndex = context.definitions.value.findIndex(
      (definition) => definition.origin === "runtime",
    );
    const insertionIndex =
      firstRuntimeIndex < 0 ? context.definitions.value.length : firstRuntimeIndex;
    context.definitions.value = [
      ...context.definitions.value.slice(0, insertionIndex),
      ...additions,
      ...context.definitions.value.slice(insertionIndex),
    ];
    context.selectedIndex.value = insertionIndex + additions.length - 1;
    context.message.value = "";
  }

  function addExamplePackage(examplePackage: SpeciesBuilderExamplePackage): void {
    const result = mergeSpeciesBuilderExamplePackage(context.definitions.value, examplePackage);

    if (result.selectedIndex < 0) {
      return;
    }

    context.definitions.value = result.definitions;
    context.selectedIndex.value = result.selectedIndex;
    context.message.value = "";
  }

  function deleteSelectedDefinition(): void {
    if (!canEditSpeciesDefinitionBase(context.selectedDefinition.value)) {
      return;
    }

    context.definitions.value = context.definitions.value.filter(
      (_, index) => index !== context.selectedIndex.value,
    );
    context.selectedIndex.value =
      context.definitions.value.length === 0
        ? -1
        : Math.min(context.selectedIndex.value, context.definitions.value.length - 1);
    context.message.value = "";
  }

  function selectDefinition(index: number): void {
    context.selectedIndex.value = index;
  }

  function updateStringField(field: "age" | "key" | "name", value: string): void {
    updateSelectedDefinition((definition) => setSpeciesStringField(definition, field, value));
  }

  function updateBooleanField(field: "includeInExtraSpecies", value: boolean): void {
    updateSelectedDefinition((definition) => ({ ...definition, [field]: value }));
  }

  function updateNumberField(
    field: "extra" | "fate" | "movement" | "resilience",
    value: string,
  ): void {
    updateSelectedDefinition((definition) => setSpeciesNumberField(definition, field, value));
  }

  function updateHeightField(field: keyof SpeciesBuilderHeightDefinition, value: string): void {
    updateSelectedDefinition((definition) => setSpeciesHeightField(definition, field, value));
  }

  function updateCharacteristic(key: WfrpCharacteristicKey, value: string): void {
    updateSelectedDefinition((definition) => setSpeciesCharacteristic(definition, key, value));
  }

  function updateArrayField(field: SpeciesBuilderArrayField, value: string): void {
    updateSelectedDefinition((definition) => setSpeciesArrayField(definition, field, value));
  }

  function updateTextMapField(field: SpeciesBuilderTextMapField, value: string): void {
    updateSelectedDefinition((definition) => setSpeciesTextMapField(definition, field, value));
  }

  function updateWoundFormula(value: string): void {
    updateSelectedDefinition((definition) => setSpeciesWoundFormula(definition, value));
  }

  function updateCareerTableRows(rows: SpeciesBuilderCareerTableRow[]): void {
    updateSelectedDefinition((definition) => setSpeciesCareerTableRows(definition, rows));
  }

  function updateSelectedDefinition(
    update: (definition: SpeciesBuilderDefinition) => SpeciesBuilderDefinition,
  ): void {
    updateSelectedDefinitionAtIndex(context, update);
  }

  return {
    addBlankDefinition,
    addDefinition,
    addDefinitions,
    addExamplePackage,
    deleteSelectedDefinition,
    duplicateSelectedDefinition,
    selectDefinition,
    updateArrayField,
    updateBooleanField,
    updateCareerTableRows,
    updateCharacteristic,
    updateHeightField,
    updateNumberField,
    updateStringField,
    updateSelectedDefinition,
    updateTextMapField,
    updateWoundFormula,
  };
}
