import type { DebugShapeProbeConfig } from "../../../types/module/debug-shape-inspector";

import { MODULE_ID } from "../../constants";
import { logWarning } from "../../logging";
import {
  DEFAULT_MAX_DEPTH,
  DEFAULT_MAX_ENTRIES,
  HASH_PROBE_PARAM,
  HASH_PROBE_PRESET_PARAM,
  MAX_DEPTH_LIMIT,
  MAX_ENTRIES_LIMIT,
  STORAGE_KEY,
} from "./constants";
import { probePresets } from "./presets";
import { clampInteger, readLocalStorageItem } from "./utils";

export function hasUrlProbeRequest(): boolean {
  return (
    window.location.href.includes(HASH_PROBE_PARAM) ||
    window.location.href.includes(HASH_PROBE_PRESET_PARAM)
  );
}

export function normalizeProbe(probe: DebugShapeProbeConfig): DebugShapeProbeConfig {
  const normalized: DebugShapeProbeConfig = {
    hook: probe.hook ?? "ready",
    maxDepth: clampInteger(probe.maxDepth, DEFAULT_MAX_DEPTH, MAX_DEPTH_LIMIT),
    maxEntries: clampInteger(probe.maxEntries, DEFAULT_MAX_ENTRIES, MAX_ENTRIES_LIMIT),
    path: probe.path.trim(),
  };

  if (probe.label) {
    normalized.label = probe.label;
  }

  return normalized;
}

export function readConfiguredProbes(): DebugShapeProbeConfig[] {
  return [...readStoredProbes(), ...readHashProbes()].map(normalizeProbe);
}

function readStoredProbes(): DebugShapeProbeConfig[] {
  const stored = readLocalStorageItem(STORAGE_KEY);

  if (!stored) {
    return [];
  }

  try {
    const parsed: unknown = JSON.parse(stored);

    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed.filter(isDebugShapeProbeConfig).map(normalizeProbe);
  } catch {
    return [];
  }
}

function readHashProbes(): DebugShapeProbeConfig[] {
  const probes: DebugShapeProbeConfig[] = [];
  const paramsList = [
    new URLSearchParams(window.location.search),
    new URLSearchParams(window.location.hash.replace(/^#/, "")),
  ];

  for (const params of paramsList) {
    const preset = params.get(HASH_PROBE_PRESET_PARAM);
    const configuredProbes = params.get(HASH_PROBE_PARAM);

    if (preset) {
      probes.push(...(probePresets[preset] ?? []));
    }

    if (configuredProbes) {
      probes.push(...parseUrlProbeConfig(configuredProbes));
    }
  }

  if (window.location.href.includes(`${HASH_PROBE_PRESET_PARAM}=npc-builder`) && !probes.length) {
    probes.push(...(probePresets["npc-builder"] ?? []));
  }

  return probes;
}

function parseUrlProbeConfig(configuredProbes: string): DebugShapeProbeConfig[] {
  try {
    const parsed: unknown = JSON.parse(decodeURIComponent(configuredProbes));

    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed.filter(isDebugShapeProbeConfig);
  } catch (error) {
    logWarning(`${MODULE_ID} | Could not parse URL shape probes.`, error);
    return [];
  }
}

function isDebugShapeProbeConfig(probe: unknown): probe is DebugShapeProbeConfig {
  if (typeof probe !== "object" || probe === null) {
    return false;
  }

  return "path" in probe && typeof probe.path === "string";
}
