<script setup lang="ts">
import type {
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderRandomTalentSource,
  SpeciesBuilderSubspeciesDefinition,
  SpeciesBuilderTalentReplacementRow,
} from "../../../../../../../../../types/species-builder/species-builder";
import type { WfrpCharacteristicKey } from "../../../../../../../../../types/wfrp4e/characteristics";
import type { SpeciesBuilderStatField } from "../../support/field-definitions";
import type { SpeciesBuilderValidationIssue } from "../../../../../../../../../types/species-builder/validation";
import type { SpeciesBuilderValidationNavigationRequest } from "../../../../../../components/validation/species-builder-validation-summary";
import type {
  SpeciesBuilderSubspeciesArrayField,
  SpeciesBuilderSubspeciesTextMapField,
} from "../../../../../../../../../functions/species-builder/editor/field-values";

import SubspeciesEditorSubView from "./SubspeciesEditorSubView.vue";

defineProps<{
  index: number;
  isLoading: boolean;
  isOpen: boolean;
  isReadOnly: boolean;
  isSaving: boolean;
  issues: SpeciesBuilderValidationIssue[];
  parentDefinition: SpeciesBuilderEditingDefinition;
  parentTalents: string[];
  randomTalentSources: SpeciesBuilderRandomTalentSource[];
  subspecies: SpeciesBuilderSubspeciesDefinition | undefined;
  validationNavigationRequest?: SpeciesBuilderValidationNavigationRequest;
  woundFormulaTraitName: string;
}>();

const emit = defineEmits<{
  close: [];
  deleteSubspecies: [index: number];
  openItem: [uuid: string];
  save: [];
  subspeciesCareerTableCareerDrop: [index: number, rowIndex: number, data: string];
  subspeciesCareerTableJournalDrop: [index: number, rowIndex: number, data: string];
  subspeciesTalentDrop: [index: number, data: string];
  subspeciesTalentReplacementReplacementDrop: [index: number, rowIndex: number, data: string];
  subspeciesTalentReplacementRolledDrop: [index: number, rowIndex: number, data: string];
  updateSubspeciesArrayField: [
    index: number,
    field: SpeciesBuilderSubspeciesArrayField,
    value: string,
  ];
  updateSubspeciesCharacteristic: [index: number, key: WfrpCharacteristicKey, value: string];
  updateSubspeciesNumberField: [index: number, field: SpeciesBuilderStatField, value: string];
  updateSubspeciesStringField: [index: number, field: "key" | "name", value: string];
  updateSubspeciesCareerTableRows: [index: number, rows: SpeciesBuilderCareerTableRow[]];
  updateSubspeciesWoundFormula: [index: number, value: string];
  updateSubspeciesTalentReplacementRows: [
    index: number,
    rows: SpeciesBuilderTalentReplacementRow[],
  ];
  updateSubspeciesTextMapField: [
    index: number,
    field: SpeciesBuilderSubspeciesTextMapField,
    value: string,
  ];
}>();

function deleteAndClose(index: number): void {
  emit("deleteSubspecies", index);
  emit("close");
}
</script>

<template>
  <SubspeciesEditorSubView
    :index="index"
    :is-loading="isLoading"
    :is-open="isOpen"
    :is-read-only="isReadOnly"
    :is-saving="isSaving"
    :issues="issues"
    :parent-definition="parentDefinition"
    :parent-talents="parentTalents"
    :random-talent-sources="randomTalentSources"
    :subspecies="subspecies"
    :validation-navigation-request="validationNavigationRequest"
    :wound-formula-trait-name="woundFormulaTraitName"
    @close="emit('close')"
    @delete="deleteAndClose"
    @open-item="(uuid) => emit('openItem', uuid)"
    @save="emit('save')"
    @career-table-career-drop="
      (entryIndex, rowIndex, data) =>
        emit('subspeciesCareerTableCareerDrop', entryIndex, rowIndex, data)
    "
    @career-table-journal-drop="
      (entryIndex, rowIndex, data) =>
        emit('subspeciesCareerTableJournalDrop', entryIndex, rowIndex, data)
    "
    @talent-drop="(entryIndex, data) => emit('subspeciesTalentDrop', entryIndex, data)"
    @talent-replacement-replacement-drop="
      (entryIndex, rowIndex, data) =>
        emit('subspeciesTalentReplacementReplacementDrop', entryIndex, rowIndex, data)
    "
    @talent-replacement-rolled-drop="
      (entryIndex, rowIndex, data) =>
        emit('subspeciesTalentReplacementRolledDrop', entryIndex, rowIndex, data)
    "
    @update-array-field="
      (entryIndex, field, value) => emit('updateSubspeciesArrayField', entryIndex, field, value)
    "
    @update-characteristic="
      (entryIndex, key, value) => emit('updateSubspeciesCharacteristic', entryIndex, key, value)
    "
    @update-number-field="
      (entryIndex, field, value) => emit('updateSubspeciesNumberField', entryIndex, field, value)
    "
    @update-string-field="
      (entryIndex, field, value) => emit('updateSubspeciesStringField', entryIndex, field, value)
    "
    @update-career-table-rows="
      (entryIndex, rows) => emit('updateSubspeciesCareerTableRows', entryIndex, rows)
    "
    @update-wound-formula="
      (entryIndex, value) => emit('updateSubspeciesWoundFormula', entryIndex, value)
    "
    @update-talent-replacement-rows="
      (entryIndex, rows) => emit('updateSubspeciesTalentReplacementRows', entryIndex, rows)
    "
    @update-text-map-field="
      (entryIndex, field, value) => emit('updateSubspeciesTextMapField', entryIndex, field, value)
    "
  />
</template>
