<script setup lang="ts">
import type {
  NpcBaseActorSummary,
  NpcCareerQueueEntry,
  NpcEstimatedXpBreakdown,
  NpcPortraitCandidate,
  NpcPortraitSearchProgress,
} from "../../../../../types/npc-builder";
import type { BuildGrantTotals } from "./types";

import BuildPreviewPanel from "./BuildPreviewPanel.vue";
import BuildSummaryDetails from "./BuildSummaryDetails.vue";
import NpcBuilderSection from "../NpcBuilderSection.vue";
import PortraitPicker from "./PortraitPicker.vue";

defineProps<{
  actorName: string;
  advancementCount: number;
  buildPreviewStatus: string;
  buildPreviewWarnings: string[];
  careerItemCount: number;
  compactPortraitCandidates: NpcPortraitCandidate[];
  editedAdvanceCount: number;
  estimatedNpcXp: NpcEstimatedXpBreakdown;
  fallbackTrappingCount: number;
  finalActorName: string;
  finalCareer: NpcCareerQueueEntry | null;
  finalPortraitPath: string;
  grantTotals: BuildGrantTotals;
  hiddenPortraitCandidateCount: number;
  ignoredTrappingCount: number;
  isLoadingPortraitCandidates: boolean;
  portraitCandidates: NpcPortraitCandidate[];
  portraitSearchProgress: NpcPortraitSearchProgress | null;
  portraitSearchProgressLabel: string;
  portraitSearchProgressValue: number;
  selectedBaseActor: NpcBaseActorSummary | null;
  selectedPortraitCandidate: NpcPortraitCandidate | null;
  selectedPortraitCandidateKey: string;
  selectedSpellCount: number;
  suggestedActorName: string;
  traitCount: number;
  visibleTrappingCount: number;
}>();

const emit = defineEmits<{
  actorNameChange: [value: string];
  openPortraitGallery: [];
  selectPortrait: [candidate: NpcPortraitCandidate];
}>();

function handleActorNameInput(event: Event): void {
  const input = event.target as HTMLInputElement | null;

  emit("actorNameChange", input?.value ?? "");
}
</script>

<template>
  <aside
    class="app:grid app:gap-3 md:app:sticky md:app:top-28 md:app:max-h-[calc(100vh-10rem)] md:app:self-start md:app:overflow-y-auto"
  >
    <NpcBuilderSection
      description="The generated Actor identity stays visible while Build NPC controls change."
      title="Preview"
    >
      <PortraitPicker
        :compact-portrait-candidates="compactPortraitCandidates"
        :final-career="finalCareer"
        :final-portrait-path="finalPortraitPath"
        :hidden-portrait-candidate-count="hiddenPortraitCandidateCount"
        :is-loading-portrait-candidates="isLoadingPortraitCandidates"
        :portrait-candidates="portraitCandidates"
        :portrait-search-progress="portraitSearchProgress"
        :portrait-search-progress-label="portraitSearchProgressLabel"
        :portrait-search-progress-value="portraitSearchProgressValue"
        :selected-portrait-candidate="selectedPortraitCandidate"
        :selected-portrait-candidate-key="selectedPortraitCandidateKey"
        @open-gallery="emit('openPortraitGallery')"
        @select-portrait="emit('selectPortrait', $event)"
      />

      <fieldset class="dui-fieldset">
        <legend class="dui-fieldset-legend">NPC name</legend>
        <input
          aria-label="NPC name"
          class="dui-input dui-input-sm"
          :placeholder="suggestedActorName"
          :value="actorName"
          type="text"
          @input="handleActorNameInput"
        />
      </fieldset>
    </NpcBuilderSection>

    <div class="app:hidden md:app:grid md:app:gap-3">
      <BuildPreviewPanel
        :advancement-count="advancementCount"
        :build-preview-status="buildPreviewStatus"
        :build-preview-warnings="buildPreviewWarnings"
        :edited-advance-count="editedAdvanceCount"
        :estimated-npc-xp="estimatedNpcXp"
        :fallback-trapping-count="fallbackTrappingCount"
        :ignored-trapping-count="ignoredTrappingCount"
        :selected-spell-count="selectedSpellCount"
        :trait-count="traitCount"
        :visible-trapping-count="visibleTrappingCount"
      />

      <details class="dui-collapse dui-collapse-arrow dui-card-border">
        <summary class="dui-collapse-title">Complete build details</summary>
        <div class="dui-collapse-content">
          <BuildSummaryDetails
            :advancement-count="advancementCount"
            :base-actor-name="selectedBaseActor?.name ?? 'Not selected'"
            :career-item-count="careerItemCount"
            :estimated-npc-xp-total="estimatedNpcXp.total"
            :final-actor-name="finalActorName"
            :final-career-name="finalCareer?.name ?? 'Not queued'"
            :grant-totals="grantTotals"
            :selected-spell-count="selectedSpellCount"
            :trait-count="traitCount"
            :visible-trapping-count="visibleTrappingCount"
          />
        </div>
      </details>
    </div>
  </aside>
</template>
