<script setup lang="ts">
import { computed } from "vue";

import type { SpeciesBuilderSubspeciesDefinition } from "../../../../../../../../../types/species-builder/species-builder";
import type { SpeciesBuilderSubspeciesArrayField } from "../../../../../../../../../functions/species-builder/editor/field-values";
import type { SpeciesBuilderValidationIssue } from "../../../../../../../../../types/species-builder/validation";

import {
  buildSubspeciesTalentInheritance,
  removeSubspeciesTalent,
  restoreSubspeciesTalent,
  type SubspeciesTalentDeltaUpdate,
  type SubspeciesTalentRow,
} from "../../../../../../../../../functions/species-builder/editor/subspecies-talents";
import DocumentDrop from "../../../../../../../../components/DocumentDrop.vue";
import {
  issuesForFieldRow,
  uniqueIssueMessages,
  validationClass,
} from "../../validation-presentation";

const props = defineProps<{
  index: number;
  isDisabled: boolean;
  issues: SpeciesBuilderValidationIssue[];
  parentTalents: string[];
  subspecies: SpeciesBuilderSubspeciesDefinition;
}>();

const emit = defineEmits<{
  talentDrop: [index: number, data: string];
  updateArrayField: [index: number, field: SpeciesBuilderSubspeciesArrayField, value: string];
}>();

const inheritance = computed(() =>
  buildSubspeciesTalentInheritance(
    props.parentTalents,
    props.subspecies.talentsAdded,
    props.subspecies.talentsRemoved,
  ),
);
const issueMessages = computed(() => uniqueIssueMessages(props.issues));

function removeTalent(row: SubspeciesTalentRow): void {
  emitTalentDelta(removeSubspeciesTalent(row, inheritance.value));
}

function restoreTalent(name: string): void {
  emitTalentDelta(restoreSubspeciesTalent(name, inheritance.value));
}

function emitTalentDelta(update: SubspeciesTalentDeltaUpdate): void {
  emit("updateArrayField", props.index, update.field, update.value);
}

function talentIssues(row: SubspeciesTalentRow): SpeciesBuilderValidationIssue[] {
  if (row.source !== "added") {
    return [];
  }

  const addedRowIndex = props.subspecies.talentsAdded?.findIndex(
    (talent) => talent.trim() === row.name,
  );

  return addedRowIndex === undefined || addedRowIndex < 0
    ? []
    : issuesForFieldRow(props.issues, "talentsAdded", addedRowIndex);
}

function talentIssueMessages(row: SubspeciesTalentRow): string[] {
  return uniqueIssueMessages(talentIssues(row));
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <h3 class="dui-card-title">Talent Inheritance</h3>
      <p>
        Parent Talents are shown here as the subspecies Talent list. Removing an inherited Talent
        records it as removed; dropping a new Talent records it as added.
      </p>
      <div
        v-if="issueMessages.length"
        class="dui-alert"
        :class="validationClass(issues, 'dui-alert-error', 'dui-alert-warning')"
        role="alert"
      >
        <i aria-hidden="true" class="fa-solid fa-circle-exclamation" />
        <div>
          <p v-for="message in issueMessages" :key="message" class="app:m-0 app:text-xs">
            {{ message }}
          </p>
        </div>
      </div>
      <DocumentDrop
        description="Drop a WFRP Talent item to add it to this subspecies."
        :disabled="isDisabled"
        title="Drop Added Talent"
        variant="compact"
        @drop-data="(data) => emit('talentDrop', index, data)"
      />
      <ul v-if="inheritance.activeRows.length > 0" class="dui-list">
        <li
          v-for="row in inheritance.activeRows"
          :key="`${row.source}-${row.name}`"
          class="dui-list-row"
          :class="
            validationClass(
              talentIssues(row),
              'app:border app:border-error',
              'app:border app:border-warning',
            )
          "
        >
          <div class="dui-list-col-grow">
            <strong>{{ row.name }}</strong>
            <span class="dui-badge">{{ row.source === "inherited" ? "Inherited" : "Added" }}</span>
            <p
              v-for="message in talentIssueMessages(row)"
              :key="message"
              class="app:m-0 app:text-xs"
              :class="validationClass(talentIssues(row), 'app:text-error', 'app:text-warning')"
            >
              {{ message }}
            </p>
          </div>
          <button
            :disabled="isDisabled"
            class="dui-btn dui-btn-error dui-btn-sm"
            :title="`Remove ${row.name}`"
            type="button"
            @click="removeTalent(row)"
          >
            <i aria-hidden="true" class="fa-solid fa-trash" />
            Remove
          </button>
        </li>
      </ul>
      <div v-else class="dui-alert" role="status">
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>No Talents in the compiled list.</span>
      </div>

      <div v-if="inheritance.removedParentTalents.length > 0">
        <h4>Removed Parent Talents</h4>
        <div class="dui-card-actions">
          <button
            v-for="talent in inheritance.removedParentTalents"
            :key="talent"
            class="dui-btn dui-btn-sm"
            :disabled="isDisabled"
            :title="`Restore ${talent}`"
            type="button"
            @click="restoreTalent(talent)"
          >
            <i aria-hidden="true" class="fa-solid fa-rotate-left" />
            {{ talent }}
          </button>
        </div>
      </div>
    </div>
  </section>
</template>
