import type {
  NpcAdvancementDraftEntry,
  NpcEstimatedXpBreakdown,
  NpcXpActorProfile,
  NpcXpNamedValue,
} from "../../types/npc-builder";
import {
  WFRP_CHARACTERISTIC_KEY_BY_NAME,
  WFRP_CHARACTERISTIC_NAMES,
} from "../../types/wfrp4e/characteristics";

import { normalizeName } from "./draft-helpers";

export const WFRP_XP_COSTS = {
  characteristic: [25, 30, 40, 50, 70, 90, 120, 150, 190, 230, 280, 330, 390, 450, 520],
  skill: [10, 15, 20, 30, 40, 60, 80, 110, 140, 180, 220, 270, 320, 380, 440],
} as const;

export function calculateEstimatedNpcXp(
  advancements: NpcAdvancementDraftEntry[],
): NpcEstimatedXpBreakdown {
  const baseline: NpcXpActorProfile = {
    characteristics: {},
    skills: [],
    talents: [],
  };
  const npc: NpcXpActorProfile = {
    characteristics: {},
    skills: [],
    talents: [],
  };

  for (const advancement of advancements) {
    const baselineValue = getAdvancementBaselineValue(advancement);
    const finalValue = baselineValue + advancement.current;

    if (advancement.kind === "characteristic") {
      const key = WFRP_CHARACTERISTIC_KEY_BY_NAME[normalizeName(advancement.name)];

      if (key) {
        baseline.characteristics[key] = baselineValue;
        npc.characteristics[key] = finalValue;
      }
    } else if (advancement.kind === "skill") {
      baseline.skills.push({ name: advancement.name, value: baselineValue });
      npc.skills.push({ name: advancement.name, value: finalValue });
    } else {
      baseline.talents.push({ name: advancement.name, value: baselineValue });
      npc.talents.push({ name: advancement.name, value: finalValue });
    }
  }

  return calculateNpcXpFromBaseDelta(npc, baseline);
}

export function calculateNpcXpFromBaseDelta(
  npc: NpcXpActorProfile,
  base: NpcXpActorProfile,
): NpcEstimatedXpBreakdown {
  const characteristics = calculateCharacteristicDeltaXp(npc, base);
  const skills = calculateNamedValueDeltaXp(npc.skills, base.skills, WFRP_XP_COSTS.skill);
  const talents = calculateTalentDeltaXp(npc.talents, base.talents);

  return {
    characteristics,
    skills,
    talents,
    total: characteristics + skills + talents,
  };
}

export function calculateAdvancementXp(
  advancement: Pick<NpcAdvancementDraftEntry, "current" | "kind">,
): number {
  const positiveDelta = Math.max(0, Math.floor(advancement.current));

  if (advancement.kind === "talent") {
    return calculateTalentXp(positiveDelta);
  }

  const costTable =
    advancement.kind === "characteristic" ? WFRP_XP_COSTS.characteristic : WFRP_XP_COSTS.skill;

  return calculateAdvanceTableXp(positiveDelta, costTable);
}

export function calculateAdvanceTableXp(advances: number, costTable: readonly number[]): number {
  const purchasedAdvances = Math.max(0, Math.floor(advances));
  let total = 0;

  for (let index = 0; index < purchasedAdvances; index += 1) {
    const costIndex = Math.min(Math.floor(index / 5), costTable.length - 1);

    total += costTable[costIndex] ?? 0;
  }

  return total;
}

export function calculateTalentXp(ranks: number, startingRanks = 0): number {
  const purchasedRanks = Math.max(0, Math.floor(ranks));
  const baseRanks = Math.max(0, Math.floor(startingRanks));
  let total = 0;

  for (let index = 0; index < purchasedRanks; index += 1) {
    total += (baseRanks + index + 1) * 100;
  }

  return total;
}

function calculateCharacteristicDeltaXp(
  npc: NpcXpActorProfile,
  species: NpcXpActorProfile,
): number {
  let total = 0;

  for (const key of Object.keys(WFRP_CHARACTERISTIC_NAMES)) {
    const characteristicKey = key as keyof NpcXpActorProfile["characteristics"];
    const delta = getPositiveDelta(
      npc.characteristics[characteristicKey] ?? 0,
      species.characteristics[characteristicKey] ?? 0,
    );

    total += calculateAdvanceTableXp(delta, WFRP_XP_COSTS.characteristic);
  }

  return total;
}

function calculateNamedValueDeltaXp(
  npcValues: NpcXpNamedValue[],
  speciesValues: NpcXpNamedValue[],
  costTable: readonly number[],
): number {
  const npcByName = aggregateNamedValues(npcValues);
  const speciesByName = aggregateNamedValues(speciesValues);
  let total = 0;

  for (const [name, npcValue] of npcByName) {
    const delta = getPositiveDelta(npcValue, speciesByName.get(name) ?? 0);

    total += calculateAdvanceTableXp(delta, costTable);
  }

  return total;
}

function calculateTalentDeltaXp(
  npcTalents: NpcXpNamedValue[],
  speciesTalents: NpcXpNamedValue[],
): number {
  const npcByName = aggregateNamedValues(npcTalents);
  const speciesByName = aggregateNamedValues(speciesTalents);
  let total = 0;

  for (const [name, npcRanks] of npcByName) {
    const rankDelta = getPositiveDelta(npcRanks, speciesByName.get(name) ?? 0);

    total += calculateTalentXp(rankDelta);
  }

  return total;
}

function aggregateNamedValues(values: NpcXpNamedValue[]): Map<string, number> {
  const totals = new Map<string, number>();

  for (const entry of values) {
    const name = normalizeName(entry.name);
    const value = Math.floor(entry.value);

    if (name) {
      totals.set(name, (totals.get(name) ?? 0) + value);
    }
  }

  return totals;
}

function getPositiveDelta(value: number, baseline: number): number {
  return Math.max(0, Math.floor(value) - Math.floor(baseline));
}

function getAdvancementBaselineValue(advancement: NpcAdvancementDraftEntry): number {
  if (advancement.kind === "characteristic") {
    return Math.floor(advancement.baseValue);
  }

  if (advancement.kind === "skill") {
    return Math.floor(advancement.baseAdvances + (advancement.baseModifier ?? 0));
  }

  return Math.floor(advancement.baseAdvances);
}
