import type {
  SpeciesBuilderCareerTableRow,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderItemReference,
} from "../../../types/species-builder/species-builder";

export interface SpeciesBuilderCareerTableCopySource {
  id: string;
  label: string;
  rows: SpeciesBuilderCareerTableRow[];
}

export function buildCareerTableCopySources(
  definitions: SpeciesBuilderEditingDefinition[],
  currentRows: SpeciesBuilderCareerTableRow[] | undefined,
): SpeciesBuilderCareerTableCopySource[] {
  return definitions.flatMap((definition, definitionIndex) => {
    const rows = definition.careerTable?.rows;

    if (!rows?.length || rows === currentRows) {
      return [];
    }

    return [
      {
        id: `definition-${definitionIndex}`,
        label: definition.name.trim() || definition.key.trim() || `Species ${definitionIndex + 1}`,
        rows,
      },
    ];
  });
}

export function copyCareerTableRows(
  rows: SpeciesBuilderCareerTableRow[],
): SpeciesBuilderCareerTableRow[] {
  return rows.map((row) => {
    const copy = { ...row };

    if (row.sourceRange) {
      copy.sourceRange = [...row.sourceRange];
    }

    return copy;
  });
}

export function appendCareerTableRow(
  rows: SpeciesBuilderCareerTableRow[] | undefined,
): SpeciesBuilderCareerTableRow[] {
  return [...(rows ?? []), { name: "" }];
}

export function removeCareerTableRow(
  rows: SpeciesBuilderCareerTableRow[] | undefined,
  rowIndex: number,
): SpeciesBuilderCareerTableRow[] {
  return (rows ?? []).filter((_, index) => index !== rowIndex);
}

export function updateCareerTableRowAtIndex(
  rows: SpeciesBuilderCareerTableRow[] | undefined,
  rowIndex: number,
  update: Partial<SpeciesBuilderCareerTableRow>,
): SpeciesBuilderCareerTableRow[] {
  return (rows ?? []).map((row, index) =>
    index === rowIndex ? updateCareerTableRow(row, update) : row,
  );
}

export function setCareerTableRowCareer(
  rows: SpeciesBuilderCareerTableRow[] | undefined,
  rowIndex: number,
  career: SpeciesBuilderItemReference,
): SpeciesBuilderCareerTableRow[] {
  const update: Partial<SpeciesBuilderCareerTableRow> = { name: career.name };

  if (career.careerJournalUuid) {
    update.journalUuid = career.careerJournalUuid;
  }

  return updateCareerTableRowAtIndex(rows, rowIndex, update);
}

export function setCareerTableRowJournal(
  rows: SpeciesBuilderCareerTableRow[] | undefined,
  rowIndex: number,
  journalUuid: string,
): SpeciesBuilderCareerTableRow[] {
  return updateCareerTableRowAtIndex(rows, rowIndex, { journalUuid });
}

function updateCareerTableRow(
  row: SpeciesBuilderCareerTableRow,
  update: Partial<SpeciesBuilderCareerTableRow>,
): SpeciesBuilderCareerTableRow {
  const updated = { ...row, ...update };

  if (!updated.journalUuid) {
    delete updated.journalUuid;
  }

  return updated;
}
