import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
} from "../../../types/species-builder/species-builder";
import type {
  SpeciesBuilderValidationCatalog,
  SpeciesBuilderValidationIssue,
} from "../../../types/species-builder/validation";

import { createSpeciesConfigKey } from "../config-keys";
import { createIssue, normalizeLookupName, type ValidationIssueLocation } from "./shared";

export function validateDefinitionIdentities(
  definitions: SpeciesBuilderDefinition[],
  catalog: SpeciesBuilderValidationCatalog,
): SpeciesBuilderValidationIssue[] {
  const issues: SpeciesBuilderValidationIssue[] = [];
  const runtimeNames = new Set(
    catalog.runtimeSpecies.map((species) => normalizeLookupName(species.name)).filter(Boolean),
  );
  const runtimeKeys = new Set(
    catalog.runtimeSpecies.map((species) => species.key.trim()).filter(Boolean),
  );
  const keyCounts = countKeys(definitions.map(definitionIdentityKey));
  const nameCounts = countNormalized(definitions.map((definition) => definition.name));

  definitions.forEach((definition, definitionIndex) => {
    validateSpeciesIdentity(
      definition,
      definitionIndex,
      keyCounts,
      nameCounts,
      runtimeKeys,
      runtimeNames,
      issues,
    );
    validateSubspeciesIdentities(definition, definitionIndex, issues);
  });

  return issues;
}

function validateSpeciesIdentity(
  definition: SpeciesBuilderDefinition,
  definitionIndex: number,
  keyCounts: Map<string, number>,
  nameCounts: Map<string, number>,
  runtimeKeys: Set<string>,
  runtimeNames: Set<string>,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const location = definitionLocation(definitionIndex);
  const key = definitionIdentityKey(definition);
  const name = definition.name.trim();

  if (!key) {
    issues.push(
      createIssue({ ...location, field: "key" }, "species-key-required", "Enter a species key."),
    );
  } else if ((keyCounts.get(key) ?? 0) > 1) {
    issues.push(
      createIssue(
        { ...location, field: "key" },
        "species-key-duplicate",
        `Species key “${key}” is used more than once.`,
      ),
    );
  } else if (runtimeKeys.has(key)) {
    issues.push(
      createIssue(
        { ...location, field: "key" },
        "species-key-runtime-collision",
        `Species key “${key}” is already used by an external WFRP species.`,
      ),
    );
  }

  if (!name) {
    issues.push(
      createIssue({ ...location, field: "name" }, "species-name-required", "Enter a species name."),
    );
    return;
  }

  const normalizedName = normalizeLookupName(name);

  if ((nameCounts.get(normalizedName) ?? 0) > 1 || runtimeNames.has(normalizedName)) {
    issues.push(
      createIssue(
        { ...location, field: "name" },
        "species-name-duplicate",
        `Species name “${name}” must be unique because WFRP identifies table results by name.`,
      ),
    );
  }
  if (/[{}]/u.test(name)) {
    issues.push(
      createIssue(
        { ...location, field: "name" },
        "species-name-unsafe",
        "Species names cannot contain { or }; WFRP parses the name from a UUID-link label.",
      ),
    );
  }
}

function validateSubspeciesIdentities(
  definition: SpeciesBuilderDefinition,
  definitionIndex: number,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const entries = definition.subspecies ?? [];
  const keyCounts = countKeys(
    entries.map((entry, index) => subspeciesIdentityKey(definition, entry.key, index)),
  );
  const nameCounts = countNormalized(entries.map((entry) => entry.name));

  entries.forEach((subspecies, subspeciesIndex) => {
    const location = subspeciesLocation(definitionIndex, subspeciesIndex);
    const key = subspeciesIdentityKey(definition, subspecies.key, subspeciesIndex);
    const name = subspecies.name.trim();

    if (!key) {
      issues.push(
        createIssue(
          { ...location, field: "key" },
          "subspecies-key-required",
          "Enter a subspecies key.",
        ),
      );
    } else if ((keyCounts.get(key) ?? 0) > 1) {
      issues.push(
        createIssue(
          { ...location, field: "key" },
          "subspecies-key-duplicate",
          `Subspecies key “${key}” is used more than once for this species.`,
        ),
      );
    }
    if (!name) {
      issues.push(
        createIssue(
          { ...location, field: "name" },
          "subspecies-name-required",
          "Enter a subspecies name.",
        ),
      );
    } else if ((nameCounts.get(normalizeLookupName(name)) ?? 0) > 1) {
      issues.push(
        createIssue(
          { ...location, field: "name" },
          "subspecies-name-duplicate",
          `Subspecies name “${name}” is used more than once for this species.`,
        ),
      );
    }
  });
}

function definitionLocation(definitionIndex: number): ValidationIssueLocation {
  return { definitionIndex, scope: "definition", section: "details" };
}

function subspeciesLocation(
  definitionIndex: number,
  subspeciesIndex: number,
): ValidationIssueLocation {
  return { definitionIndex, scope: "subspecies", section: "subspecies", subspeciesIndex };
}

function countNormalized(values: string[]): Map<string, number> {
  const counts = new Map<string, number>();

  for (const value of values) {
    const normalized = normalizeLookupName(value);

    if (normalized) {
      counts.set(normalized, (counts.get(normalized) ?? 0) + 1);
    }
  }

  return counts;
}

function countKeys(values: string[]): Map<string, number> {
  const counts = new Map<string, number>();

  for (const value of values) {
    const key = value.trim();

    if (key) {
      counts.set(key, (counts.get(key) ?? 0) + 1);
    }
  }

  return counts;
}

function definitionIdentityKey(definition: SpeciesBuilderDefinition): string {
  return isRuntimeDefinition(definition)
    ? definition.key.trim()
    : createSpeciesConfigKey(definition.key);
}

function subspeciesIdentityKey(
  definition: SpeciesBuilderDefinition,
  key: string,
  index: number,
): string {
  return isRuntimeDefinition(definition) && index < definition.runtimeSubspeciesCount
    ? key.trim()
    : createSpeciesConfigKey(key);
}

function isRuntimeDefinition(
  definition: SpeciesBuilderDefinition,
): definition is SpeciesBuilderEditingDefinition {
  return "origin" in definition && definition.origin === "runtime";
}
