import type {
  PortraitCandidate,
  PortraitSearchAvailability,
  PortraitSearchProgressHandler,
} from "../../../types/portrait-gallery";
import type { DigDownFileSearchCache, DigDownFuzzyGet, PortraitSearchState } from "./types";

import {
  addPortraitCandidate,
  doesCandidateMatchStateFilters,
  emitPortraitSearchProgress,
  getPortraitAssetLabel,
  isPortraitAssetPath,
  isRecord,
  isStringArrayRecord,
} from "./candidate-utils";

const digDownModuleId = "fuzzy-foundry";
const digDownMinimumMatchScore = 0.3;

export function collectDigDownPortraitCandidates(
  state: PortraitSearchState,
  onProgress: PortraitSearchProgressHandler | undefined,
): void {
  const availability = getPortraitSearchAvailability();

  emitPortraitSearchProgress(onProgress, state, {
    currentLocation: getDigDownSearchProgressLabel(availability),
    maxDirectories: 0,
    phase: "filesystem",
  });

  if (!availability.digDownActive || !availability.digDownCacheReady) {
    return;
  }

  const cache = getDigDownFileSearchCache();

  if (!cache?._fileIndexCache || !cache.fs) {
    return;
  }

  for (const filename of getDigDownMatchedFilenames(cache, state.searchTerms)) {
    collectDigDownFilenameCandidates(state, cache, filename);
  }

  emitPortraitSearchProgress(onProgress, state, {
    currentLocation: "Dig Down file cache search complete",
    maxDirectories: 0,
    phase: "filesystem",
  });
}

export function getPortraitSearchAvailability(): PortraitSearchAvailability {
  const digDownActive = game.modules.get(digDownModuleId)?.active === true;
  const digDownDeepFileSearchEnabled = isDigDownDeepFileSearchEnabled();
  const digDownCache = getDigDownFileSearchCache();
  const digDownIndexedFileCount = Object.values(digDownCache?._fileIndexCache ?? {}).reduce(
    (total, paths) => total + paths.length,
    0,
  );

  return {
    digDownActive,
    digDownCacheReady: Boolean(digDownCache?._fileIndexCache && digDownCache.fs),
    digDownDeepFileSearchEnabled,
    digDownIndexedFileCount,
  };
}

function isDigDownDeepFileSearchEnabled(): boolean {
  try {
    return game.settings.get(digDownModuleId, "deepFile") === true;
  } catch {
    return false;
  }
}

function getDigDownSearchProgressLabel(availability: PortraitSearchAvailability): string {
  if (!availability.digDownActive) {
    return "Dig Down is not active";
  }

  if (!availability.digDownDeepFileSearchEnabled) {
    return "Dig Down Deep File Search is disabled";
  }

  if (!availability.digDownCacheReady) {
    return "Waiting for Dig Down file cache";
  }

  return `Dig Down file cache (${availability.digDownIndexedFileCount} files)`;
}

function getDigDownMatchedFilenames(
  cache: DigDownFileSearchCache,
  searchTerms: string[],
): string[] {
  const matchedFilenames = new Set<string>();
  const filenames = Object.keys(cache._fileIndexCache ?? {});

  for (const searchTerm of searchTerms) {
    const normalizedSearchTerm = searchTerm.toLocaleLowerCase();

    for (const filename of filenames) {
      if (filename.toLocaleLowerCase().includes(normalizedSearchTerm)) {
        matchedFilenames.add(filename);
      }
    }

    const fuzzyMatches = cache.fs?.get(searchTerm, [], digDownMinimumMatchScore) ?? [];

    for (const [, filename] of fuzzyMatches) {
      matchedFilenames.add(filename);
    }
  }

  return [...matchedFilenames].sort((left, right) =>
    left.toLocaleLowerCase().localeCompare(right.toLocaleLowerCase()),
  );
}

function collectDigDownFilenameCandidates(
  state: PortraitSearchState,
  cache: DigDownFileSearchCache,
  filename: string,
): void {
  const paths = cache._fileIndexCache?.[filename] ?? [];

  for (const path of paths) {
    if (!isPortraitAssetPath(path)) {
      continue;
    }

    const candidate: PortraitCandidate = {
      img: path,
      key: `foundry-asset:${path}`,
      label: getPortraitAssetLabel(path, "Dig Down"),
      source: "foundry-asset",
      sourceGroup: "dig-down",
      sourceLabel: "Dig Down",
    };

    if (doesCandidateMatchStateFilters(candidate, state)) {
      addPortraitCandidate(state, candidate);
    }
  }
}

/*
 * Dig Down does not expose a documented module API. Its deep search cache is
 * created at canvas.deepSearchCache and indexes by filename, which is exactly
 * the granularity we want for portrait suggestions. We intentionally read that
 * cache instead of recursively browsing FilePicker sources ourselves.
 */
function getDigDownFileSearchCache(): DigDownFileSearchCache | null {
  const maybeCache = canvas.deepSearchCache;

  if (!isRecord(maybeCache)) {
    return null;
  }

  const fileIndexCache = maybeCache["_fileIndexCache"];
  const fuzzySet = maybeCache["fs"];
  const cache: DigDownFileSearchCache = {};

  if (isStringArrayRecord(fileIndexCache)) {
    cache._fileIndexCache = fileIndexCache;
  }

  if (isRecord(fuzzySet) && typeof fuzzySet["get"] === "function") {
    cache.fs = {
      get: fuzzySet["get"].bind(fuzzySet) as DigDownFuzzyGet,
    };
  }

  return cache;
}
