import type {
  SpeciesItemDraft,
  SpeciesItemSheetBridge,
} from "../../../types/species-builder/species-item";
import { isRecord } from "../../../shared/object-readers";
import { readSpeciesItem } from "../species-builder/items/adapter";
import { updateSpeciesItem } from "../species-builder/items/repository";

import { chooseSpeciesImage, editSpeciesEffect, readSpeciesEffects } from "./editing";
import { speciesNotesEditors } from "./notes";

export function createSpeciesItemSheetBridge(item: FoundryItemDocument): SpeciesItemSheetBridge {
  let snapshot = "";
  const notes = speciesNotesEditors();
  const load = (): SpeciesItemDraft => {
    const record = readSpeciesItem(item);
    snapshot = JSON.stringify(item.toObject());
    return { name: record.name, img: record.img, system: record.system };
  };
  return {
    isGM: game.user?.isGM === true,
    flushNotes: notes.flush,
    editNotes: notes.edit,
    async openReference(uuid) {
      const document = await fromUuid(uuid);
      const sheet = isRecord(document) ? document["sheet"] : undefined;
      if (isRecord(sheet) && typeof sheet["render"] === "function")
        sheet["render"].call(sheet, true);
      else throw new Error("The referenced document could not be opened.");
    },
    effects: () => readSpeciesEffects(item),
    effectAction: (action, id) => editSpeciesEffect(item, action, id),
    chooseImage: chooseSpeciesImage,
    mountNotes: notes.mount,
    load,
    async save(draft) {
      if (snapshot !== JSON.stringify(item.toObject()))
        throw new Error("This Item changed in another window. Reload its sheet before saving.");
      await updateSpeciesItem(item, draft);
      return load();
    },
    async resolveDrop(data) {
      const payload: unknown = JSON.parse(data);
      const uuid = isRecord(payload) ? payload["uuid"] : undefined;
      if (typeof uuid !== "string")
        throw new Error("Drop a Species, Skill, Talent, or RollTable document.");
      const document = await fromUuid(uuid);
      if (
        !isRecord(document) ||
        typeof document["uuid"] !== "string" ||
        typeof document["id"] !== "string" ||
        typeof document["name"] !== "string"
      )
        throw new Error("The dropped document could not be resolved.");
      return {
        type: document["documentName"] === "RollTable" ? "RollTable" : String(document["type"]),
        reference: { uuid: document["uuid"], id: document["id"], name: document["name"] },
      };
    },
  };
}
