import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderExamplePackage,
  SpeciesBuilderRuntimeSpeciesExtension,
} from "../../types/species-builder/species-builder";

import { clonePlain } from "./editor/draft";

export interface SpeciesBuilderPersistedDefinitions {
  definitions: SpeciesBuilderDefinition[];
  runtimeSpeciesExtensions: SpeciesBuilderRuntimeSpeciesExtension[];
}

export interface SpeciesBuilderExampleMergeResult {
  definitions: SpeciesBuilderEditingDefinition[];
  selectedIndex: number;
}

export function mergeSpeciesBuilderExamplePackage(
  existing: SpeciesBuilderEditingDefinition[],
  examplePackage: SpeciesBuilderExamplePackage,
): SpeciesBuilderExampleMergeResult {
  const additions = examplePackage.definitions.map(createCustomEditingDefinition);
  const firstRuntimeIndex = existing.findIndex((definition) => definition.origin === "runtime");
  const insertionIndex = firstRuntimeIndex < 0 ? existing.length : firstRuntimeIndex;
  const definitions = [
    ...existing.slice(0, insertionIndex),
    ...additions,
    ...existing.slice(insertionIndex),
  ];
  let selectedIndex = additions.length > 0 ? insertionIndex + additions.length - 1 : -1;

  for (const extension of examplePackage.runtimeSpeciesExtensions) {
    const key = runtimeIdentityKey(extension.speciesKey);
    const runtimeIndex = definitions.findIndex(
      (definition) => definition.origin === "runtime" && runtimeIdentityKey(definition.key) === key,
    );

    if (runtimeIndex >= 0) {
      const definition = definitions[runtimeIndex];

      if (definition) {
        definitions[runtimeIndex] = {
          ...definition,
          subspecies: optionalSubspecies([
            ...(definition.subspecies ?? []),
            ...clonePlain(extension.subspecies),
          ]),
        };
        selectedIndex = runtimeIndex;
      }
      continue;
    }

    definitions.push({
      includeInExtraSpecies: false,
      key: extension.speciesKey,
      name: extension.speciesName,
      origin: "runtime",
      runtimeSubspeciesCount: 0,
      runtimeUnavailable: true,
      subspecies: optionalSubspecies(clonePlain(extension.subspecies)),
    });
    selectedIndex = definitions.length - 1;
  }

  return { definitions, selectedIndex };
}

export function composeSpeciesBuilderEditingDefinitions(
  customDefinitions: SpeciesBuilderDefinition[],
  runtimeDefinitions: SpeciesBuilderDefinition[],
  extensions: SpeciesBuilderRuntimeSpeciesExtension[],
): SpeciesBuilderEditingDefinition[] {
  const custom = customDefinitions.map(createCustomEditingDefinition);
  const extensionsByKey = groupExtensionsByKey(extensions);
  const representedRuntimeKeys = new Set<string>();
  const runtime = runtimeDefinitions.flatMap((definition) => {
    const key = runtimeIdentityKey(definition.key);

    if (!key || representedRuntimeKeys.has(key)) {
      return [];
    }

    representedRuntimeKeys.add(key);
    const runtimeSubspecies = clonePlain(definition.subspecies ?? []);
    const authoredSubspecies = extensionsByKey
      .get(key)
      ?.flatMap((extension) => clonePlain(extension.subspecies));

    return [
      {
        ...clonePlain(definition),
        origin: "runtime" as const,
        runtimeSubspeciesCount: runtimeSubspecies.length,
        subspecies: optionalSubspecies([...runtimeSubspecies, ...(authoredSubspecies ?? [])]),
      },
    ];
  });
  const unavailable = [...extensionsByKey.entries()].flatMap(([key, entries]) => {
    if (representedRuntimeKeys.has(key)) {
      return [];
    }

    const first = entries[0];

    if (!first) {
      return [];
    }

    return [
      {
        includeInExtraSpecies: false,
        key: first.speciesKey,
        name: first.speciesName,
        origin: "runtime" as const,
        runtimeSubspeciesCount: 0,
        runtimeUnavailable: true,
        subspecies: optionalSubspecies(
          entries.flatMap((extension) => clonePlain(extension.subspecies)),
        ),
      },
    ];
  });

  return [...custom, ...runtime, ...unavailable];
}

export function splitSpeciesBuilderEditingDefinitions(
  editingDefinitions: SpeciesBuilderEditingDefinition[],
): SpeciesBuilderPersistedDefinitions {
  const definitions: SpeciesBuilderDefinition[] = [];
  const runtimeSpeciesExtensions: SpeciesBuilderRuntimeSpeciesExtension[] = [];

  for (const editingDefinition of editingDefinitions) {
    if (editingDefinition.origin === "custom") {
      definitions.push(stripEditingMetadata(editingDefinition));
      continue;
    }

    const subspecies = clonePlain(
      (editingDefinition.subspecies ?? []).slice(editingDefinition.runtimeSubspeciesCount),
    );

    if (subspecies.length > 0) {
      runtimeSpeciesExtensions.push({
        speciesKey: editingDefinition.key,
        speciesName: editingDefinition.name,
        subspecies,
      });
    }
  }

  return { definitions, runtimeSpeciesExtensions };
}

export function createCustomEditingDefinition(
  definition: SpeciesBuilderDefinition,
): SpeciesBuilderEditingDefinition {
  return {
    ...stripEditingMetadata(definition),
    origin: "custom",
    runtimeSubspeciesCount: 0,
  };
}

export function canEditSpeciesDefinitionBase(
  definition: SpeciesBuilderEditingDefinition | undefined,
): boolean {
  return definition?.origin === "custom";
}

export function canEditSpeciesSubspecies(
  definition: SpeciesBuilderEditingDefinition | undefined,
  subspeciesIndex: number,
): boolean {
  return (
    definition !== undefined &&
    subspeciesIndex >= 0 &&
    (definition.origin === "custom" || subspeciesIndex >= definition.runtimeSubspeciesCount)
  );
}

function stripEditingMetadata(
  definition: SpeciesBuilderDefinition | SpeciesBuilderEditingDefinition,
): SpeciesBuilderDefinition {
  const copy = clonePlain(definition) as SpeciesBuilderDefinition &
    Partial<SpeciesBuilderEditingDefinition>;

  delete copy.origin;
  delete copy.runtimeSubspeciesCount;
  delete copy.runtimeUnavailable;

  return copy;
}

function groupExtensionsByKey(
  extensions: SpeciesBuilderRuntimeSpeciesExtension[],
): Map<string, SpeciesBuilderRuntimeSpeciesExtension[]> {
  const grouped = new Map<string, SpeciesBuilderRuntimeSpeciesExtension[]>();

  for (const extension of extensions) {
    const key = runtimeIdentityKey(extension.speciesKey);

    if (!key) {
      continue;
    }

    grouped.set(key, [...(grouped.get(key) ?? []), extension]);
  }

  return grouped;
}

function runtimeIdentityKey(value: string): string {
  return value.trim();
}

function optionalSubspecies<T>(entries: T[]): T[] | undefined {
  return entries.length > 0 ? entries : undefined;
}
