<script setup lang="ts">
import { computed } from "vue";

import type {
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../../../../../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIndicator } from "../../../../../../components/validation/validation-presentation";

import SpeciesBuilderEntityRow from "../../../../components/SpeciesBuilderEntityRow.vue";
import { getSuggestedSubspeciesKey } from "../../../../species-key-suggestions";

const props = defineProps<{
  definition: SpeciesBuilderEditingDefinition;
  isLoading: boolean;
  isSaving: boolean;
  validationIndicators: Array<SpeciesBuilderValidationIndicator | undefined>;
}>();

const emit = defineEmits<{
  addSubspecies: [];
  editSubspecies: [index: number];
}>();

const subspecies = computed(() => props.definition.subspecies ?? []);
const runtimeSubspecies = computed(() =>
  subspecies.value.slice(0, props.definition.runtimeSubspeciesCount),
);
const customSubspecies = computed(() =>
  subspecies.value.slice(props.definition.runtimeSubspeciesCount),
);
const canAddSubspecies = computed(
  () => !props.isLoading && !props.isSaving && !props.definition.runtimeUnavailable,
);

function subspeciesLabel(entry: SpeciesBuilderSubspeciesDefinition): string {
  return entry.name.trim() || entry.key.trim() || "Untitled Subspecies";
}

function subspeciesKeyLabel(entry: SpeciesBuilderSubspeciesDefinition): string {
  return entry.key.trim() || getSuggestedSubspeciesKey(entry);
}
</script>

<template>
  <section class="dui-card dui-card-border dui-card-sm">
    <div class="dui-card-body">
      <header class="app:flex app:items-start app:justify-between app:gap-4">
        <div>
          <h3 class="dui-card-title">Subspecies</h3>
          <p class="app:m-0">Variants inherit this species and store only their changes.</p>
        </div>
        <div class="dui-card-actions app:items-center">
          <button
            class="dui-btn dui-btn-primary dui-btn-sm"
            :disabled="!canAddSubspecies"
            type="button"
            @click="emit('addSubspecies')"
          >
            <i aria-hidden="true" class="fa-solid fa-plus" />
            New Subspecies
          </button>
        </div>
      </header>

      <div
        v-if="definition.origin === 'runtime' && !definition.runtimeUnavailable"
        class="dui-alert dui-alert-info"
        role="note"
      >
        <i aria-hidden="true" class="fa-solid fa-lock" />
        <span>
          Installed variants are read-only. New subspecies are saved by this module without changing
          the installed parent species.
        </span>
      </div>

      <div v-if="definition.runtimeUnavailable" class="dui-alert dui-alert-warning" role="alert">
        <i aria-hidden="true" class="fa-solid fa-triangle-exclamation" />
        <span>
          The installed parent species is currently unavailable. Saved custom variants are being
          preserved, but new variants cannot be added until the source returns.
        </span>
      </div>

      <section v-if="definition.origin === 'runtime'" aria-labelledby="custom-variants-heading">
        <header class="app:flex app:items-center app:justify-between app:gap-2">
          <div>
            <h4 id="custom-variants-heading" class="dui-card-title">Custom Additions</h4>
            <p class="app:m-0">Editable variants owned by this world.</p>
          </div>
          <span class="dui-badge dui-badge-sm">{{ customSubspecies.length }}</span>
        </header>
        <div v-if="customSubspecies.length === 0" class="dui-alert" role="status">
          <i aria-hidden="true" class="fa-solid fa-circle-info" />
          <span>No custom variants yet. Add one without altering the installed species.</span>
        </div>
        <ul v-else class="dui-list">
          <SpeciesBuilderEntityRow
            v-for="(entry, relativeIndex) in customSubspecies"
            :key="`custom-${entry.key}-${relativeIndex}`"
            action-label="Edit"
            :entry-key="subspeciesKeyLabel(entry)"
            icon-class="fa-solid fa-user-plus"
            :is-disabled="isLoading || isSaving"
            :title="subspeciesLabel(entry)"
            :validation-indicator="
              validationIndicators[relativeIndex + definition.runtimeSubspeciesCount]
            "
            @open="emit('editSubspecies', relativeIndex + definition.runtimeSubspeciesCount)"
          />
        </ul>
      </section>

      <section v-if="runtimeSubspecies.length > 0" aria-labelledby="installed-variants-heading">
        <header class="app:flex app:items-center app:justify-between app:gap-2">
          <div>
            <h4 id="installed-variants-heading" class="dui-card-title">Installed Variants</h4>
            <p class="app:m-0">Provided by WFRP or an active module.</p>
          </div>
          <span class="dui-badge dui-badge-ghost dui-badge-sm">
            {{ runtimeSubspecies.length }}
          </span>
        </header>
        <ul class="dui-list">
          <SpeciesBuilderEntityRow
            v-for="(entry, index) in runtimeSubspecies"
            :key="`runtime-${entry.key}-${index}`"
            action-label="View setup"
            edit-icon-class="fa-solid fa-eye"
            :entry-key="subspeciesKeyLabel(entry)"
            icon-class="fa-solid fa-book-open"
            :is-disabled="isLoading || isSaving"
            is-read-only
            :title="subspeciesLabel(entry)"
            :validation-indicator="validationIndicators[index]"
            @open="emit('editSubspecies', index)"
          />
        </ul>
      </section>

      <div
        v-if="definition.origin === 'custom' && subspecies.length === 0"
        class="dui-alert"
        role="status"
      >
        <i aria-hidden="true" class="fa-solid fa-circle-info" />
        <span>No subspecies yet.</span>
      </div>
      <ul v-else-if="definition.origin === 'custom'" class="dui-list">
        <SpeciesBuilderEntityRow
          v-for="(entry, index) in subspecies"
          :key="`${entry.key}-${index}`"
          action-label="Edit"
          :entry-key="subspeciesKeyLabel(entry)"
          icon-class="fa-solid fa-user-group"
          :is-disabled="isLoading || isSaving"
          :title="subspeciesLabel(entry)"
          :validation-indicator="validationIndicators[index]"
          @open="emit('editSubspecies', index)"
        />
      </ul>
    </div>
  </section>
</template>
