import type { Ref } from "vue";

import type { SpeciesBuilderDefinition } from "../../../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../../../../types/species-builder/validation";
import type { SpeciesBuilderActiveTab } from "../../tabs/active-tab";
import type { SpeciesBuilderEditorTab } from "../../tabs/species/pages/editor/editor-tabs";
import type { RandomTableTab } from "../../tabs/species/pages/editor/tabs/tables/random-table-events";

import { computed, nextTick, ref } from "vue";
import {
  getSpeciesBuilderValidationDestination,
  type SpeciesBuilderValidationNavigationRequest,
  validationIssuesForSummary,
} from "./species-builder-validation-summary";

interface SpeciesBuilderValidationSummaryContext {
  definitions: Readonly<Ref<SpeciesBuilderDefinition[]>>;
  issues: Readonly<Ref<SpeciesBuilderValidationIssue[]>>;
  openEditorTab: (tab: SpeciesBuilderEditorTab) => void;
  openTableTab: (tab: RandomTableTab) => void;
  selectDefinition: (index: number) => void;
  selectProjectTab: (tab: SpeciesBuilderActiveTab) => void;
}

export function useSpeciesBuilderValidationSummary(
  context: SpeciesBuilderValidationSummaryContext,
) {
  const isOpen = ref(false);
  const navigationRequest = ref<SpeciesBuilderValidationNavigationRequest>();
  const definitionFilter = ref<number>();
  const summaryIssues = computed(() => {
    const issues = validationIssuesForSummary(context.issues.value);

    return definitionFilter.value === undefined
      ? issues
      : issues.filter((issue) => issue.definitionIndex === definitionFilter.value);
  });
  let sequence = 0;

  function open(): void {
    definitionFilter.value = undefined;
    showSummary();
  }

  function openForDefinition(definitionIndex: number): void {
    definitionFilter.value = definitionIndex;
    showSummary();
  }

  function showSummary(): void {
    if (summaryIssues.value.length > 0) {
      isOpen.value = true;
    }
  }

  function close(): void {
    isOpen.value = false;
  }

  async function selectIssue(issue: SpeciesBuilderValidationIssue): Promise<void> {
    const destination = getSpeciesBuilderValidationDestination(issue);

    close();
    navigationRequest.value = undefined;

    if (destination.kind === "project") {
      context.selectProjectTab(destination.tab);
      return;
    }

    context.selectDefinition(destination.definitionIndex);

    if (destination.kind === "definition") {
      if (destination.tableTab) {
        context.openTableTab(destination.tableTab);
      } else {
        context.openEditorTab(destination.editorTab);
      }

      return;
    }

    context.openEditorTab("subspecies");
    await nextTick();
    navigationRequest.value = { destination, sequence: ++sequence };
  }

  return {
    close,
    isOpen,
    navigationRequest,
    open,
    openForDefinition,
    selectIssue,
    summaryIssues,
  };
}
