<script setup lang="ts">
import type { SpeciesBuilderValidationIssue } from "../../../../../../../../../types/species-builder/validation";
import type { SubspeciesEditorTab } from "./subspecies-editor-tabs";

import {
  summarizeValidationIssues,
  validationIndicatorLabel,
} from "../../../../../../components/validation/validation-presentation";
import { SUBSPECIES_EDITOR_TABS, subspeciesIssuesForTab } from "./subspecies-editor-tabs";

const props = defineProps<{
  activeTab: SubspeciesEditorTab;
  isBusy: boolean;
  issues: SpeciesBuilderValidationIssue[];
}>();

const emit = defineEmits<{
  select: [tab: SubspeciesEditorTab];
}>();

function validationIndicatorForTab(tab: SubspeciesEditorTab) {
  return summarizeValidationIssues(subspeciesIssuesForTab(props.issues, tab));
}
</script>

<template>
  <div aria-label="Edit subspecies section" class="dui-tabs dui-tabs-border" role="tablist">
    <button
      v-for="entry in SUBSPECIES_EDITOR_TABS"
      :id="`subspecies-editor-tab-${entry.tab}`"
      :key="entry.tab"
      :aria-controls="`subspecies-editor-panel-${entry.tab}`"
      :aria-selected="activeTab === entry.tab"
      :autofocus="entry.tab === activeTab"
      class="dui-tab"
      :class="{ 'dui-tab-active': activeTab === entry.tab }"
      :disabled="isBusy"
      role="tab"
      type="button"
      @click="emit('select', entry.tab)"
    >
      {{ entry.label }}
      <span
        v-if="validationIndicatorForTab(entry.tab)"
        class="dui-status dui-status-sm"
        :class="
          validationIndicatorForTab(entry.tab)?.severity === 'error'
            ? 'dui-status-error'
            : 'dui-status-warning'
        "
        :title="validationIndicatorLabel(validationIndicatorForTab(entry.tab))"
      >
        <span class="app:sr-only">
          {{ validationIndicatorLabel(validationIndicatorForTab(entry.tab)) }}
        </span>
      </span>
    </button>
  </div>
</template>
