import type {
  SpeciesBuilderCareerTableDefinition,
  SpeciesBuilderDefinition,
} from "../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";

import { createIssue, type ValidationCatalogIndex, type ValidationIssueLocation } from "./shared";

export function validateCareerTables(
  definitions: SpeciesBuilderDefinition[],
  catalog: ValidationCatalogIndex,
): SpeciesBuilderValidationIssue[] {
  const issues: SpeciesBuilderValidationIssue[] = [];

  definitions.forEach((definition, definitionIndex) => {
    validateCareerTable(
      definition.careerTable,
      definitionLocation(definitionIndex),
      true,
      catalog,
      issues,
    );

    (definition.subspecies ?? []).forEach((subspecies, subspeciesIndex) => {
      if (subspecies.careerTable !== undefined) {
        validateCareerTable(
          subspecies.careerTable,
          subspeciesLocation(definitionIndex, subspeciesIndex),
          true,
          catalog,
          issues,
        );
      }
    });
  });

  return issues;
}

function validateCareerTable(
  table: SpeciesBuilderCareerTableDefinition | undefined,
  location: ValidationIssueLocation,
  required: boolean,
  catalog: ValidationCatalogIndex,
  issues: SpeciesBuilderValidationIssue[],
): void {
  if (!table || table.rows.length === 0) {
    if (required) {
      issues.push(
        createIssue(
          location,
          "career-table-required",
          "Add at least one Career group so character creation can roll a Career.",
        ),
      );
    }
    return;
  }

  table.rows.forEach((row, rowIndex) => {
    const name = row.name.trim();
    const rowLocation = { ...location, field: "name", rowIndex };

    if (!name) {
      issues.push(
        createIssue(
          rowLocation,
          "career-table-row-blank",
          `Career Table row ${rowIndex + 1} needs a Career group name.`,
        ),
      );
    } else if (!catalog.careerGroups.has(name)) {
      issues.push(
        createIssue(
          rowLocation,
          "career-table-career-missing",
          `Career group “${name}” does not match an available WFRP Career group.`,
        ),
      );
    }
  });
}

function definitionLocation(definitionIndex: number): ValidationIssueLocation {
  return { definitionIndex, scope: "definition", section: "careerTable" };
}

function subspeciesLocation(
  definitionIndex: number,
  subspeciesIndex: number,
): ValidationIssueLocation {
  return { definitionIndex, scope: "subspecies", section: "careerTable", subspeciesIndex };
}
