<script setup lang="ts">
withDefaults(
  defineProps<{
    canSave?: boolean;
    context?: string;
    errorCount?: number;
    hasUnsavedChanges?: boolean;
    isBusy: boolean;
    parentLabel?: string;
    showIssues?: boolean;
    showParent?: boolean;
    showReload?: boolean;
    showSave?: boolean;
    title: string;
    warningCount?: number;
  }>(),
  {
    canSave: false,
    context: "",
    errorCount: 0,
    hasUnsavedChanges: false,
    parentLabel: "Species List",
    showIssues: true,
    showParent: true,
    showReload: true,
    showSave: true,
    warningCount: 0,
  },
);

defineEmits<{
  openIssues: [];
  openParent: [];
  reload: [];
  save: [];
}>();
</script>

<template>
  <header
    class="dui-navbar app:sticky app:top-0 app:z-20 app:border-b app:border-base-300 app:bg-base-200 app:px-3"
  >
    <div class="dui-navbar-start app:min-w-0 app:flex-1">
      <div class="app:min-w-0">
        <nav
          v-if="showParent || context"
          aria-label="Current location"
          class="dui-breadcrumbs app:py-0 app:text-xs"
        >
          <ul>
            <li v-if="showParent">
              <button
                class="dui-btn dui-btn-link dui-btn-xs"
                type="button"
                @click="$emit('openParent')"
              >
                {{ parentLabel }}
              </button>
            </li>
            <li v-if="context">
              <span aria-current="page">{{ context }}</span>
            </li>
          </ul>
        </nav>
        <div class="app:flex app:min-w-0 app:flex-wrap app:items-center app:gap-2">
          <h1 class="app:m-0 app:truncate app:text-lg app:leading-tight">{{ title }}</h1>
          <span v-if="hasUnsavedChanges" class="dui-badge dui-badge-warning dui-badge-sm">
            Unsaved
          </span>
        </div>
      </div>
    </div>

    <div class="dui-navbar-end app:flex-wrap app:gap-1">
      <button
        v-if="showIssues && errorCount + warningCount > 0"
        class="dui-btn dui-btn-outline dui-btn-sm"
        type="button"
        @click="$emit('openIssues')"
      >
        <i aria-hidden="true" class="fa-solid fa-triangle-exclamation" />
        Issues
        <span class="dui-badge dui-badge-sm">{{ errorCount + warningCount }}</span>
      </button>
      <button
        v-if="showReload"
        class="dui-btn dui-btn-ghost dui-btn-sm"
        :disabled="isBusy"
        type="button"
        @click="$emit('reload')"
      >
        <i aria-hidden="true" class="fa-solid fa-rotate-right" />
        Reload
      </button>
      <button
        v-if="showSave"
        class="dui-btn dui-btn-primary dui-btn-sm"
        :disabled="!canSave"
        type="button"
        @click="$emit('save')"
      >
        <i aria-hidden="true" class="fa-solid fa-floppy-disk" />
        {{ isBusy ? "Working…" : "Save Changes" }}
      </button>
    </div>
  </header>
</template>
