<script setup lang="ts">
import { computed, onMounted } from "vue";

import type { SpeciesBuilderBridge } from "../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";

import { useSpeciesBuilderEditor } from "../../../state/species-builder/editor";
import {
  buildSpeciesBuilderValidationSummaryItems,
  validationIssuesForSummary,
} from "../species-builder/components/validation/species-builder-validation-summary";
import SpeciesSuiteHeader from "./components/SpeciesSuiteHeader.vue";

const props = defineProps<{
  bridge: SpeciesBuilderBridge;
  definitionIndex?: number;
  onOpenDirectory: () => void;
  onSelectIssue: (issue: SpeciesBuilderValidationIssue) => void;
  onSettingsSaved?: () => void;
}>();
const editor = useSpeciesBuilderEditor(props.bridge, { onSettingsSaved: props.onSettingsSaved });
const scopedIssues = computed(() =>
  validationIssuesForSummary(editor.validationIssues.value).filter(
    (issue) =>
      props.definitionIndex === undefined || issue.definitionIndex === props.definitionIndex,
  ),
);
const items = computed(() =>
  buildSpeciesBuilderValidationSummaryItems(scopedIssues.value, editor.definitions.value),
);
const errorCount = computed(
  () => scopedIssues.value.filter((issue) => issue.severity === "error").length,
);
const warningCount = computed(() => scopedIssues.value.length - errorCount.value);
const isBusy = computed(() => editor.isLoading.value || editor.isSaving.value);
const definitionName = computed(() => {
  const definition = editor.definitions.value[props.definitionIndex ?? -1];
  return definition?.name.trim() || definition?.key.trim();
});

onMounted(() => void editor.ensureSettingsLoaded());
</script>

<template>
  <section class="app:flex app:min-h-full app:flex-col" :aria-busy="isBusy">
    <SpeciesSuiteHeader
      :context="definitionName ? `${definitionName} validation` : 'All validation'"
      :error-count="errorCount"
      :is-busy="isBusy"
      :show-issues="false"
      :show-save="false"
      :title="definitionName ? `${definitionName} Issues` : 'Species Issues'"
      :warning-count="warningCount"
      @open-parent="onOpenDirectory"
      @reload="editor.loadSettings"
    />

    <main class="app:flex app:flex-1 app:flex-col app:gap-3 app:p-3">
      <div
        class="dui-alert"
        :class="errorCount > 0 ? 'dui-alert-error' : 'dui-alert-warning'"
        role="status"
      >
        <i
          aria-hidden="true"
          :class="
            errorCount > 0 ? 'fa-solid fa-circle-exclamation' : 'fa-solid fa-triangle-exclamation'
          "
        />
        <span>
          Errors identify data that blocks character creation. Warnings identify playable but
          incomplete data. Every issue below opens its exact editor.
        </span>
      </div>

      <div v-if="items.length === 0" class="dui-alert dui-alert-success" role="status">
        <i aria-hidden="true" class="fa-solid fa-check" />
        <span>{{ definitionName || "All species" }} currently has no validation issues.</span>
      </div>

      <ul v-else class="dui-list app:gap-1">
        <li
          v-for="(item, index) in items"
          :key="`${item.issue.code}-${index}`"
          class="dui-list-row app:p-0"
        >
          <button
            class="dui-btn dui-btn-outline app:h-auto app:w-full app:justify-start app:whitespace-normal app:p-3 app:text-left"
            :class="item.issue.severity === 'error' ? 'dui-btn-error' : 'dui-btn-warning'"
            type="button"
            @click="onSelectIssue(item.issue)"
          >
            <i
              aria-hidden="true"
              :class="
                item.issue.severity === 'error'
                  ? 'fa-solid fa-circle-exclamation'
                  : 'fa-solid fa-triangle-exclamation'
              "
            />
            <span class="app:flex app:min-w-0 app:flex-1 app:flex-col app:items-start">
              <strong>{{ item.context }}</strong>
              <span>{{ item.issue.message }}</span>
            </span>
            <i aria-hidden="true" class="fa-solid fa-arrow-up-right-from-square" />
          </button>
        </li>
      </ul>
    </main>
  </section>
</template>
