import type {
  SpeciesBuilderDefinition,
  SpeciesBuilderSubspeciesDefinition,
} from "../../../types/species-builder/species-builder";
import type { SpeciesBuilderValidationIssue } from "../../../types/species-builder/validation";
import {
  WFRP_CHARACTERISTIC_NAMES,
  type WfrpCharacteristicKey,
} from "../../../types/wfrp4e/characteristics";

import { compileWoundFormula } from "../wound-formula/compiler";
import {
  createIssue,
  isCharacteristicFormula,
  isNonNegativeInteger,
  isSensibleDiceFormula,
  type ValidationIssueLocation,
} from "./shared";

const CHARACTERISTIC_KEYS = Object.keys(WFRP_CHARACTERISTIC_NAMES) as WfrpCharacteristicKey[];
const REQUIRED_STATS = ["movement", "fate", "resilience", "extra"] as const;

export function validateDefinitionFields(
  definitions: SpeciesBuilderDefinition[],
): SpeciesBuilderValidationIssue[] {
  const issues: SpeciesBuilderValidationIssue[] = [];

  definitions.forEach((definition, definitionIndex) => {
    const location = definitionLocation(definitionIndex);

    validateCharacteristics(definition.characteristics, location, true, issues);
    validateStats(definition, location, true, issues);
    validateAgeAndHeight(definition, location, issues);
    validateWoundFormula(definition.woundFormula?.formula, location, issues);
    validateSubspecies(definition, definitionIndex, issues);
  });

  return issues;
}

function validateCharacteristics(
  characteristics: SpeciesBuilderDefinition["characteristics"],
  location: ValidationIssueLocation,
  requireAll: boolean,
  issues: SpeciesBuilderValidationIssue[],
): void {
  for (const key of CHARACTERISTIC_KEYS) {
    const formula = characteristics?.[key]?.trim() ?? "";
    const field = `characteristics.${key}`;

    if (!formula && requireAll) {
      issues.push(
        createIssue(
          { ...location, field, section: "attributes" },
          "characteristic-required",
          `${WFRP_CHARACTERISTIC_NAMES[key]} needs a roll formula.`,
        ),
      );
    } else if (formula && !isCharacteristicFormula(formula)) {
      issues.push(
        createIssue(
          { ...location, field, section: "attributes" },
          "characteristic-formula-invalid",
          `${WFRP_CHARACTERISTIC_NAMES[key]} needs a valid WFRP roll formula, such as 0, d10, or 2d10+20.`,
        ),
      );
    }
  }
}

function validateStats(
  definition: SpeciesBuilderDefinition | SpeciesBuilderSubspeciesDefinition,
  location: ValidationIssueLocation,
  required: boolean,
  issues: SpeciesBuilderValidationIssue[],
): void {
  for (const field of REQUIRED_STATS) {
    const value = definition[field];

    if (value === undefined && required) {
      issues.push(
        createIssue(
          { ...location, field, section: "attributes" },
          "stat-required",
          `${statLabel(field)} is required for character creation.`,
        ),
      );
    } else if (value !== undefined && !isNonNegativeInteger(value)) {
      issues.push(
        createIssue(
          { ...location, field, section: "attributes" },
          "stat-invalid",
          `${statLabel(field)} must be a non-negative whole number.`,
        ),
      );
    }
  }
}

function validateAgeAndHeight(
  definition: SpeciesBuilderDefinition,
  location: ValidationIssueLocation,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const age = definition.age?.trim() ?? "";

  if (!age) {
    issues.push(
      createIssue({ ...location, field: "age" }, "age-required", "Enter an age roll formula."),
    );
  } else if (!isSensibleDiceFormula(age, false)) {
    issues.push(
      createIssue(
        { ...location, field: "age" },
        "age-formula-invalid",
        "Age must use whole numbers and dice joined by + or -, such as 15+1d10.",
      ),
    );
  }

  const height = definition.height;

  if (!height) {
    for (const field of ["die", "feet", "inches"] as const) {
      issues.push(
        createIssue(
          { ...location, field: `height.${field}` },
          "height-required",
          `Height ${field} is required for character creation.`,
        ),
      );
    }
    return;
  }

  if (!height.die?.trim() || !isSensibleDiceFormula(height.die, true)) {
    issues.push(
      createIssue(
        { ...location, field: "height.die" },
        "height-die-invalid",
        "Height die must be a valid dice formula, such as 1d10.",
      ),
    );
  }
  validateHeightNumber(height.feet, "feet", location, issues);
  validateHeightNumber(height.inches, "inches", location, issues);
}

function validateHeightNumber(
  value: number | undefined,
  field: "feet" | "inches",
  location: ValidationIssueLocation,
  issues: SpeciesBuilderValidationIssue[],
): void {
  if (!isNonNegativeInteger(value)) {
    issues.push(
      createIssue(
        { ...location, field: `height.${field}` },
        `height-${field}-invalid`,
        `Height ${field} must be a non-negative whole number.`,
      ),
    );
  }
}

function validateWoundFormula(
  formula: string | undefined,
  location: ValidationIssueLocation,
  issues: SpeciesBuilderValidationIssue[],
): void {
  if (formula === undefined) {
    return;
  }

  try {
    if (!formula.trim() || !hasBalancedDelimiters(formula)) {
      throw new Error("The formula is blank or has unmatched brackets.");
    }
    compileWoundFormula(formula);
  } catch (error) {
    const detail = error instanceof Error ? error.message : "The formula could not be compiled.";
    issues.push(
      createIssue(
        { ...location, field: "woundFormula", section: "wounds" },
        "wound-formula-invalid",
        `Wound formula is invalid: ${detail}`,
      ),
    );
  }
}

function validateSubspecies(
  definition: SpeciesBuilderDefinition,
  definitionIndex: number,
  issues: SpeciesBuilderValidationIssue[],
): void {
  const entries = definition.subspecies ?? [];

  entries.forEach((subspecies, subspeciesIndex) => {
    const location = subspeciesLocation(definitionIndex, subspeciesIndex);

    if (subspecies.characteristics) {
      validateCharacteristics(
        { ...definition.characteristics, ...subspecies.characteristics },
        location,
        true,
        issues,
      );
    }
    validateStats(subspecies, location, false, issues);
    validateWoundFormula(subspecies.woundFormula?.formula, location, issues);
  });
}

function definitionLocation(definitionIndex: number): ValidationIssueLocation {
  return { definitionIndex, scope: "definition", section: "details" };
}

function subspeciesLocation(
  definitionIndex: number,
  subspeciesIndex: number,
): ValidationIssueLocation {
  return { definitionIndex, scope: "subspecies", section: "subspecies", subspeciesIndex };
}

function statLabel(field: (typeof REQUIRED_STATS)[number]): string {
  return field.charAt(0).toLocaleUpperCase() + field.slice(1);
}

function hasBalancedDelimiters(value: string): boolean {
  return (
    pairsAreBalanced(value, "{", "}") &&
    pairsAreBalanced(value, "[", "]") &&
    pairsAreBalanced(value, "(", ")")
  );
}

function pairsAreBalanced(value: string, open: string, close: string): boolean {
  let depth = 0;

  for (const character of value) {
    if (character === open) {
      depth += 1;
    } else if (character === close) {
      depth -= 1;
    }
    if (depth < 0) {
      return false;
    }
  }

  return depth === 0;
}
