import type { ComputedRef, Ref } from "vue";

import type {
  SpeciesBuilderBridge,
  SpeciesBuilderDefinition,
  SpeciesBuilderEditingDefinition,
  SpeciesBuilderSettings,
  SpeciesBuilderSpeciesTableDraft,
  SpeciesBuilderSpeciesTableLoad,
} from "../../types/species-builder/species-builder";
import type { SpeciesBuilderSaveOptions } from "./save-state";

import { composeSpeciesBuilderEditingDefinitions } from "../../functions/species-builder/editing-definitions";
import { snapshotSettings, getErrorMessage } from "../../functions/species-builder/editor/draft";
import { snapshotSpeciesTable } from "../../functions/species-builder/world-table";
import { snapshotDefinitionSettings } from "./save-state";

interface SpeciesBuilderSaveActionContext {
  autoRegisterSpeciesTable: Ref<boolean>;
  canSave: ComputedRef<boolean>;
  correctionSettingHasUnsavedChanges: ComputedRef<boolean>;
  correctExistingWfrpSpecies: Ref<boolean>;
  definitions: Ref<SpeciesBuilderEditingDefinition[]>;
  definitionsHaveUnsavedChanges: ComputedRef<boolean>;
  hydrateSpeciesTable: (load: SpeciesBuilderSpeciesTableLoad) => void;
  isSaving: Ref<boolean>;
  loadError: Ref<string>;
  message: Ref<string>;
  normalizedSettings: ComputedRef<SpeciesBuilderSettings>;
  preparedSpeciesTable: ComputedRef<SpeciesBuilderSpeciesTableDraft>;
  requireBridge: () => SpeciesBuilderBridge;
  requiresUnsafeSaveConfirmation: ComputedRef<boolean>;
  runtimeDefinitions: Ref<SpeciesBuilderDefinition[]>;
  savedDefinitionsSnapshot: Ref<string>;
  savedCorrectExistingWfrpSpecies: Ref<boolean>;
  savedSettingsSnapshot: Ref<string>;
  savedSpeciesTableSnapshot: Ref<string>;
  saveError: Ref<string>;
  selectedIndex: Ref<number>;
  settingsHaveUnsavedChanges: ComputedRef<boolean>;
  showGeneratedConfigTab: Ref<boolean>;
  speciesTableWillSave: ComputedRef<boolean>;
}

export function createSpeciesBuilderSaveActions(context: SpeciesBuilderSaveActionContext) {
  async function saveChanges(options: SpeciesBuilderSaveOptions = {}): Promise<boolean> {
    if (
      !context.canSave.value ||
      (context.requiresUnsafeSaveConfirmation.value && !options.allowValidationErrors)
    ) {
      return false;
    }

    context.isSaving.value = true;
    context.loadError.value = "";
    context.saveError.value = "";
    context.message.value = "";
    const shouldSaveSettings = context.settingsHaveUnsavedChanges.value;
    const shouldSaveSpeciesTable = context.speciesTableWillSave.value;
    let requiresReload = false;
    const postSaveErrors: string[] = [];

    try {
      if (shouldSaveSettings) {
        const syncGeneratedDocuments =
          context.definitionsHaveUnsavedChanges.value ||
          context.correctionSettingHasUnsavedChanges.value;
        const outcome = await context
          .requireBridge()
          .saveSettings(context.normalizedSettings.value, syncGeneratedDocuments);
        const saved = outcome.settings;
        context.autoRegisterSpeciesTable.value = saved.autoRegisterSpeciesTable;
        context.correctExistingWfrpSpecies.value = saved.correctExistingWfrpSpecies;
        context.definitions.value = composeSpeciesBuilderEditingDefinitions(
          saved.definitions,
          context.runtimeDefinitions.value,
          saved.runtimeSpeciesExtensions,
        );
        context.showGeneratedConfigTab.value = saved.showGeneratedConfigTab;
        context.selectedIndex.value =
          context.definitions.value.length > 0
            ? Math.min(context.selectedIndex.value, context.definitions.value.length - 1)
            : -1;
        context.savedSettingsSnapshot.value = snapshotSettings(context.normalizedSettings.value);
        context.savedDefinitionsSnapshot.value = snapshotDefinitionSettings(
          context.normalizedSettings.value,
        );
        context.savedCorrectExistingWfrpSpecies.value = saved.correctExistingWfrpSpecies;
        requiresReload = false;

        if (outcome.syncError) {
          postSaveErrors.push(outcome.syncError);
        }
      }

      if (shouldSaveSpeciesTable) {
        const savedTable = await context
          .requireBridge()
          .saveSpeciesTable(
            context.preparedSpeciesTable.value,
            context.autoRegisterSpeciesTable.value,
          );
        context.hydrateSpeciesTable(savedTable);
        context.savedSpeciesTableSnapshot.value = snapshotSpeciesTable(savedTable.draft);

        if (savedTable.registrationError) {
          postSaveErrors.push(savedTable.registrationError);
        }
      }

      describeSaveOutcome(context, postSaveErrors, requiresReload, shouldSaveSpeciesTable);
      return requiresReload;
    } catch (error) {
      context.saveError.value = getErrorMessage(error);
      return requiresReload;
    } finally {
      context.isSaving.value = false;
    }
  }

  return { saveChanges };
}

function describeSaveOutcome(
  context: SpeciesBuilderSaveActionContext,
  postSaveErrors: string[],
  requiresReload: boolean,
  savedSpeciesTable: boolean,
): void {
  if (postSaveErrors.length > 0) {
    context.saveError.value = postSaveErrors.join(" ");
  } else if (requiresReload) {
    context.message.value =
      "Saved. Refresh Foundry before using changed species in character generation.";
  } else if (savedSpeciesTable) {
    context.message.value = "Saved the world Species table.";
  } else {
    context.message.value =
      "Saved the legacy Builder draft. Species Items supply character-generation config.";
  }
}
