<script setup lang="ts">
import type { SpeciesBuilderLinkedItemName } from "../../../../../../../../types/species-builder/species-builder";

import DocumentDrop from "../../../../../../../components/DocumentDrop.vue";
import {
  hasValidationErrors,
  type SpeciesBuilderValidationIssue,
  uniqueIssueMessages,
  validationClass,
} from "../validation-presentation";

const props = defineProps<{
  description: string;
  inputTitle?: string;
  isDisabled: boolean;
  isEditable: boolean;
  issues: SpeciesBuilderValidationIssue[];
  title: string;
  value: SpeciesBuilderLinkedItemName;
}>();

const emit = defineEmits<{
  dropData: [data: string];
  openItem: [uuid: string];
  updateName: [name: string];
}>();

function inputValue(event: Event): string {
  return event.target instanceof HTMLInputElement ? event.target.value : "";
}

function issueMessages(): string[] {
  return uniqueIssueMessages(props.issues);
}
</script>

<template>
  <DocumentDrop
    :description="description"
    :disabled="isDisabled"
    :documents="value.item ? [value.item] : []"
    :documents-clickable="!isDisabled"
    empty-document-label="No item selected."
    manual-entry-trigger="button"
    :show-documents="Boolean(value.item?.uuid)"
    :title="title"
    variant="bare"
    @document-clicked="(document) => emit('openItem', document.uuid)"
    @drop-data="(data) => emit('dropData', data)"
  >
    <input
      v-if="!value.item?.uuid && isEditable"
      :aria-invalid="hasValidationErrors(issues) || undefined"
      class="dui-input"
      :class="validationClass(issues, 'dui-input-error', 'dui-input-warning')"
      :disabled="isDisabled"
      :title="inputTitle"
      :value="value.name"
      type="text"
      @input="emit('updateName', inputValue($event))"
    />

    <div
      v-else-if="value.name"
      class="dui-alert"
      :class="validationClass(issues, 'dui-alert-error', 'dui-alert-warning') ?? 'dui-alert-info'"
    >
      <strong>{{ value.name }}</strong>
      <span>Stored by name. Drop the matching Item to link its sheet.</span>
    </div>

    <div
      v-else
      class="dui-alert"
      :class="validationClass(issues, 'dui-alert-error', 'dui-alert-warning')"
    >
      <i aria-hidden="true" class="fa-solid fa-arrow-down" />
      <span>No item selected.</span>
    </div>

    <div v-if="issueMessages().length" class="app:grid app:gap-1" role="alert">
      <p
        v-for="message in issueMessages()"
        :key="message"
        class="app:m-0 app:text-xs"
        :class="validationClass(issues, 'app:text-error', 'app:text-warning')"
      >
        {{ message }}
      </p>
    </div>
  </DocumentDrop>
</template>
