export const NpcActorSizeKey = {
  Average: "avg",
  Enormous: "enor",
  Large: "lrg",
  Little: "ltl",
  Monstrous: "mnst",
  Small: "sml",
  Tiny: "tiny",
} as const;

export type NpcActorSizeKey = (typeof NpcActorSizeKey)[keyof typeof NpcActorSizeKey];

export interface NpcMountTraitSummary {
  damage: boolean;
  fixedDamage: number | null;
  name: string;
  specification: string;
  uuid: string;
}

export interface NpcActorCombatProfile {
  characteristics: {
    initiative: number;
    strength: number;
    strengthBonus: number;
    toughness: number;
  };
  img: string;
  movement: number;
  name: string;
  size: NpcActorSizeKey;
  traits: NpcMountTraitSummary[];
  uuid: string;
  wounds: number;
}

export interface NpcCombinedProfilePlan {
  chargeStrengthBonus: number;
  initiative: number;
  movement: number;
  size: NpcActorSizeKey;
  strength: number;
  toughness: number;
  traits: NpcMountTraitContribution[];
  wounds: number;
}

export interface NpcMountTraitContribution {
  fixedDamage: number | null;
  included: boolean;
  name: string;
  outputName: string;
  reason: string;
  sourceUuid: string;
}
