import type { NpcCareerGrants } from "../../types/npc-builder";

import { isRecord, readUnknownPath, toStringList } from "../../shared/object-readers";
import {
  isWfrpCharacteristicKey,
  WFRP_CHARACTERISTIC_KEY_BY_NAME,
  WFRP_CHARACTERISTIC_NAMES,
} from "../../types/wfrp4e/characteristics";

export function extractCareerGrants(systemData: unknown): NpcCareerGrants {
  // WFRP4e Career grant fields have appeared both as direct arrays and as
  // `{ value: ... }` fields in observed data, so each grant kind checks both.
  return {
    characteristics: readCharacteristics(systemData),
    skills: readSkillList(systemData),
    talents: readStringListFromPaths(systemData, [["talents", "value"], ["talents"]]),
    trappings: readStringListFromPaths(systemData, [["trappings", "value"], ["trappings"]]),
  };
}

function readCharacteristics(source: unknown): string[] {
  const pathList = readStringListFromPaths(source, [
    ["characteristics", "value"],
    ["characteristics"],
  ]);

  if (pathList.length) {
    return pathList.map(normalizeCharacteristic);
  }

  const characteristics = readUnknownPath(source, ["characteristics"]);

  if (!isRecord(characteristics)) {
    return [];
  }

  const grantedCharacteristics: string[] = [];

  for (const [key, value] of Object.entries(characteristics)) {
    if (value) {
      grantedCharacteristics.push(normalizeCharacteristic(key));
    }
  }

  return uniqueSorted(grantedCharacteristics);
}

function readSkillList(source: unknown): string[] {
  return readStringListFromPaths(source, [["skills", "value"], ["skills"]], {
    preserveDuplicates: true,
  });
}

function normalizeCharacteristic(value: string): string {
  const key = value.trim().toLocaleLowerCase();

  if (isWfrpCharacteristicKey(key)) {
    return WFRP_CHARACTERISTIC_NAMES[key];
  }

  const characteristicKey = WFRP_CHARACTERISTIC_KEY_BY_NAME[key];

  return characteristicKey ? WFRP_CHARACTERISTIC_NAMES[characteristicKey] : value.trim();
}

function readStringListFromPaths(
  source: unknown,
  paths: string[][],
  options: {
    preserveDuplicates?: boolean;
  } = {},
): string[] {
  for (const path of paths) {
    const list = toStringList(readUnknownPath(source, path));

    if (list.length) {
      return options.preserveDuplicates ? cleanStringList(list) : uniqueSorted(list);
    }
  }

  return [];
}

function cleanStringList(values: string[]): string[] {
  return values.map((value) => value.trim()).filter(Boolean);
}

function uniqueSorted(values: string[]): string[] {
  return [...new Set(cleanStringList(values))].sort((left, right) => left.localeCompare(right));
}
